def _start_download_queue_cleanup_scheduler():
    """Start background scheduler for download queue cleanup based on config settings."""
    global download_queue_cleanup_scheduler

    with download_queue_cleanup_scheduler_lock:
        existing_thread = download_queue_cleanup_scheduler.get("thread")
        if existing_thread and hasattr(existing_thread, "is_alive") and existing_thread.is_alive():
            download_queue_cleanup_scheduler["running"] = True
            return

        stop_event = threading.Event()
        download_queue_cleanup_scheduler["stop_event"] = stop_event

        def cleanup_worker():
            try:
                import time as time_module
                from download_monitor_enhancements import cleanup_download_queue

                # Let app startup settle before first cleanup cycle.
                time_module.sleep(10)

                while not stop_event.is_set():
                    try:
                        cfg = get_config() or {}
                        features_cfg = cfg.get("features", {}) if isinstance(cfg, dict) else {}
                        cleanup_cfg = features_cfg.get("download_queue_cleanup_scheduler", {}) if isinstance(features_cfg, dict) else {}

                        enabled = bool(cleanup_cfg.get("enabled", True))
                        interval_minutes = int(cleanup_cfg.get("interval_minutes", 60))
                        if interval_minutes < 5:
                            interval_minutes = 5

                        interval_seconds = interval_minutes * 60

                        if enabled:
                            stats = cleanup_download_queue()
                            if isinstance(stats, dict) and not stats.get("error"):
                                removed = int(stats.get("deleted_duplicates", 0)) + int(stats.get("deleted_album_tracks", 0))
                                if removed > 0:
                                    logging.info(
                                        "[QUEUE_CLEANUP_SCHEDULER] Removed %s duplicate/finished queue items (albums=%s)",
                                        removed,
                                        stats.get("completed_albums", 0),
                                    )
                        else:
                            logging.debug("[QUEUE_CLEANUP_SCHEDULER] Disabled via config")

                        if stop_event.wait(timeout=interval_seconds):
                            break
                    except Exception as loop_err:
                        logging.error(f"[QUEUE_CLEANUP_SCHEDULER] Worker loop error: {loop_err}")
                        if stop_event.wait(timeout=60):
                            break

                logging.info("[QUEUE_CLEANUP_SCHEDULER] Stopped")
            except Exception as worker_err:
                logging.error(f"[QUEUE_CLEANUP_SCHEDULER] Fatal worker error: {worker_err}")
            finally:
                with download_queue_cleanup_scheduler_lock:
                    download_queue_cleanup_scheduler["running"] = False

        thread = threading.Thread(target=cleanup_worker, daemon=True, name="queue-cleanup-scheduler")
        thread.start()
        download_queue_cleanup_scheduler["thread"] = thread
        download_queue_cleanup_scheduler["running"] = True
        logging.info("[QUEUE_CLEANUP_SCHEDULER] Started")


def _write_progress_file(path: str, scan_type: str, is_running: bool, extra: dict | None = None):
    """Persist minimal scan progress state so the dashboard can show status."""
    try:
        payload = {"is_running": is_running, "scan_type": scan_type}
        if extra:
            payload.update(extra)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(payload, f)
    except Exception as e:
        logging.debug(f"Failed to write progress file {path}: {e}")


def _write_progress_with_current_artist(path: str, scan_type: str, is_running: bool, extra: dict | None = None):
    """
    Write progress file while preserving current_artist from existing file.
    This ensures resume functionality works even after scan completion.
    
    Args:
        path: Path to progress file
        scan_type: Type of scan (e.g., 'navidrome_scan', 'popularity_scan')
        is_running: Whether scan is currently running
        extra: Additional data to include in progress file
    """
    # Try to preserve current_artist from existing progress file
    current_artist = None
    try:
        with open(path, 'r') as f:
            existing_progress = json.load(f)
            current_artist = existing_progress.get('current_artist')
    except (FileNotFoundError, json.JSONDecodeError, KeyError):
        pass  # File doesn't exist or is invalid, that's okay
    
    # Add current_artist to extra data if it exists
    if current_artist:
        if extra is None:
            extra = {}
        extra['current_artist'] = current_artist
    
    # Write the progress file with preserved current_artist
    _write_progress_file(path, scan_type, is_running, extra)


def _log_scan_session_complete(scan_type: str, artist_count: int = 0):
    """Log a scan-session completion entry to scan_history so the dashboard Recent Scans panel
    shows a timestamped row for the overall scan, not just per-album rows."""
    try:
        from scan_history import log_album_scan
        # Use _SCAN_SESSION_ as artist marker so the frontend can render it specially
        label = scan_type
        log_album_scan('_SCAN_SESSION_', label, scan_type, artist_count, 'completed', source='session_complete')
    except Exception as _e:
        logging.debug(f"_log_scan_session_complete({scan_type}): {_e}")


def _is_stop_requested_from_progress(path: str) -> bool:
    """Return True when a progress file indicates a user-requested stop."""
    try:
        if not os.path.exists(path):
            return False
        with open(path, "r", encoding="utf-8") as f:
            state = json.load(f)
        if state.get("stop_requested") is True:
            return True
        return (state.get("status") == "stopped") and (not bool(state.get("is_running", False)))
    except Exception:
        return False


def _request_scan_stop(path: str, scan_type: str):
    """Persist a cooperative stop request for thread-based scans."""
    payload = {}
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                payload = json.load(f)
    except Exception:
        payload = {}

    payload.update({
        "is_running": False,
        "scan_type": scan_type,
        "status": "stopped",
        "stop_requested": True,
        "stopped_at": datetime.now().isoformat()
    })
    _write_progress_file(path, scan_type, False, payload)


def _resolve_downloads_monitor_dir(cfg: dict | None = None) -> str:
    """Resolve downloads scan folder based on configuration.
    
    Respects user's configured downloads.folder path directly.
    Falls back to environment variable or default /downloads/Music.
    """
    cfg = cfg or {}
    downloads_cfg = cfg.get("downloads", {}) if isinstance(cfg, dict) else {}
    
    # Try configured folder first
    configured = downloads_cfg.get("folder")
    if configured and configured.strip():
        return os.path.normpath(configured.strip())
    
    # Fall back to environment variable
    env_dir = os.environ.get("DOWNLOADS_DIR")
    if env_dir and env_dir.strip():
        return os.path.normpath(env_dir.strip())
    
    # Default fallback
    return "/downloads/Music"


def _is_process_alive(proc):
    """Helper to check if a process/thread is alive"""
    if proc is None:
        return False
    if isinstance(proc, dict):
        thread = proc.get('thread')
        if thread is None:
            return False
        if hasattr(thread, 'is_alive'):
            return thread.is_alive()
        if hasattr(thread, 'poll'):
            return thread.poll() is None
        return False
    if hasattr(proc, 'is_alive'):
        return proc.is_alive()
    if hasattr(proc, 'poll'):
        return proc.poll() is None
    return False


def _validate_and_cleanup_progress_file(progress_file: str, process_ref=None, max_age_hours: int = 2):
    """
    Validate a progress file and clean it up if it's stale.
    
    Returns the progress data if valid, None if stale/invalid.
    
    Args:
        progress_file: Path to the progress file
        process_ref: Optional process/thread reference to check if actually running
        max_age_hours: Maximum age in hours before considering a running scan as stuck
    """
    if not os.path.exists(progress_file):
        return None
    
    try:
        with open(progress_file, 'r') as f:
            progress = json.load(f)
        
        # If scan says it's not running, return as-is
        if not progress.get("is_running", False):
            return progress
        
        # If we have a process reference, verify it's actually alive using helper
        if process_ref is not None:
            is_alive = _is_process_alive(process_ref)
            
            # If process is dead but file says running, clean it up
            if not is_alive:
                logging.warning(f"Progress file {progress_file} says running but process is dead - cleaning up")
                progress["is_running"] = False
                progress["status"] = "error"
                with open(progress_file, 'w') as f:
                    json.dump(progress, f)
                return progress
        
        # Check file modification time to detect truly stuck scans
        file_mtime = os.path.getmtime(progress_file)
        current_time = time.time()
        age_hours = (current_time - file_mtime) / 3600
        
        if age_hours > max_age_hours:
            logging.warning(f"Progress file {progress_file} is {age_hours:.1f} hours old - assuming stuck scan, cleaning up")
            progress["is_running"] = False
            progress["status"] = "timeout"
            with open(progress_file, 'w') as f:
                json.dump(progress, f)
            return progress
        
        return progress
    except Exception as e:
        logging.error(f"Error validating progress file {progress_file}: {e}")
        return None


def _monitor_process_for_progress(proc: subprocess.Popen, progress_path: str, scan_type: str):
    """Wait for a subprocess and mark its progress file as complete."""
    try:
        # Capture output while process runs
        output_lines = []
        if proc.stdout:
            for line in iter(proc.stdout.readline, ''):
                if not line:
                    break
                line = line.strip()
                if line:
                    output_lines.append(line)
                    logging.info(f"[{scan_type}] {line}")
        
        # Wait for process to complete
        returncode = proc.wait()
        
        # Capture any remaining output
        if proc.stdout:
            remaining = proc.stdout.read()
            if remaining:
                for line in remaining.strip().split('\n'):
                    if line.strip():
                        output_lines.append(line.strip())
                        logging.info(f"[{scan_type}] {line.strip()}")
        
        # Mark as complete with error info if failed
        result = {
            "exit_code": returncode,
            "completed_at": datetime.now().isoformat()
        }
        
        if returncode != 0:
            error_msg = f"Process exited with code {returncode}"
            if output_lines:
                # Include last few lines of output as error context
                result["error"] = error_msg
                result["output_tail"] = output_lines[-10:]
            logging.error(f"{scan_type} failed: {error_msg}")
            if output_lines:
                logging.error(f"Last output lines: {output_lines[-5:]}")
        else:
            logging.info(f"{scan_type} completed successfully")
        
        _write_progress_file(progress_path, scan_type, False, result)
    except Exception as e:
        logging.error(f"Progress monitor failed for {scan_type}: {e}", exc_info=True)
        _write_progress_file(progress_path, scan_type, False, {
            "exit_code": -1,
            "error": str(e)
        })


def _start_boot_navidrome_import():
    """Start a Navidrome metadata-only import in the background on startup.

    Uses force=False so it only fills missing metadata, and sets the
    SPTNR_SKIP_SINGLES flag so rating/single detection cannot run during this pass.
    
    Resumes from the last scanned artist if available, otherwise starts from the beginning.
    """
    global scan_process_navidrome

    # Avoid duplicate launches if already running
    if scan_process_navidrome and isinstance(scan_process_navidrome, dict):
        t = scan_process_navidrome.get("thread")
        if t and t.is_alive():
            logging.info("Navidrome import already running; boot kickoff skipped")
            return

    def run_import():
        os.environ["SPTNR_SKIP_SINGLES"] = "1"
        progress_path = os.path.join(os.path.dirname(DB_PATH), "navidrome_scan_progress.json")
        checkpoint_path = os.path.join(os.path.dirname(DB_PATH), "navidrome_scan_checkpoint.json")
        
        try:
            logging.info("[BOOT] Starting Navidrome import-only scan (missing-only)")
            _write_progress_file(progress_path, "navidrome_scan", True, {"status": "starting", "source": "boot"})

            # Warm local artist records from album metadata first.
            # This does not fetch track payloads; it only syncs album artists.
            try:
                _sync_new_navidrome_album_artists_fast(trigger_source="boot_pre_import")
            except Exception as pre_sync_err:
                logging.warning(f"[BOOT] Album-artist pre-sync failed before import: {pre_sync_err}")
            
            artist_map = build_artist_index()
            artists = list(artist_map.items())
            total = len(artists)
            
            # Check if we have a checkpoint from a previous scan
            start_idx = 0
            last_scanned_artist = None
            if os.path.exists(checkpoint_path):
                try:
                    with open(checkpoint_path, 'r') as f:
                        checkpoint = json.load(f)
                        last_scanned_artist = checkpoint.get("last_scanned_artist")
                        if last_scanned_artist:
                            # Find the index of the last scanned artist
                            for idx, (artist_name, _) in enumerate(artists):
                                if artist_name == last_scanned_artist:
                                    start_idx = idx + 1  # Start from the next artist
                                    logging.info(f"[BOOT] Resuming Navidrome scan from artist index {start_idx} (after '{last_scanned_artist}')")
                                    break
                except Exception as e:
                    logging.warning(f"[BOOT] Error reading checkpoint: {e}, starting from beginning")
            
            # Scan remaining artists
            for idx in range(start_idx, total):
                artist_name, info = artists[idx]
                scan_artist_to_db(artist_name, info.get("id"), verbose=False, force=False, processed_artists=idx+1, total_artists=total)
                
                # Update checkpoint with the last scanned artist
                try:
                    with open(checkpoint_path, 'w') as f:
                        json.dump({"last_scanned_artist": artist_name}, f)
                except Exception as e:
                    logging.warning(f"[BOOT] Error saving checkpoint: {e}")
            
            # Clear checkpoint when scan completes
            if os.path.exists(checkpoint_path):
                os.remove(checkpoint_path)
            
            _write_progress_file(progress_path, "navidrome_scan", False, {"status": "complete", "exit_code": 0, "source": "boot"})
            logging.info("[BOOT] Navidrome import-only scan completed")
            _mark_navidrome_first_full_import_complete(scan_source="boot")
            _sync_new_navidrome_album_artists_fast(trigger_source="boot_post_import")
            _maybe_start_post_navidrome_mp3_import(trigger_source="boot_post_import")
        except Exception as e:
            logging.error(f"[BOOT] Error in Navidrome import-only scan: {e}", exc_info=True)
            _write_progress_file(progress_path, "navidrome_scan", False, {"status": "error", "error": str(e), "exit_code": 1, "source": "boot"})
        finally:
            os.environ.pop("SPTNR_SKIP_SINGLES", None)
            scan_process_navidrome = None

    thread = threading.Thread(target=run_import, daemon=True)
    thread.start()
    scan_process_navidrome = {"thread": thread, "type": "navidrome_boot"}
    logging.info("Boot Navidrome import thread started")


# --- Daily scheduled task globals ---
_daily_scheduler_thread = None
_daily_scheduler_stop = None
_startup_leader_lock_conn = None
_startup_leader_lock_file_fd = None


def _acquire_startup_leader_lock() -> bool:
    """Acquire a cross-process lock so only one worker starts background schedulers.

    In production we run under gunicorn with multiple workers. Without a leader lock,
    each worker starts the same periodic jobs, creating contention and request stalls.
    """
    global _startup_leader_lock_conn, _startup_leader_lock_file_fd

    # PostgreSQL path: advisory lock tied to this connection's lifetime.
    try:
        conn = get_db()
        if _is_postgres_connection(conn):
            cursor = conn.cursor()
            lock_key = 915317499  # app-specific startup leader lock
            cursor.execute("SELECT pg_try_advisory_lock(%s) AS acquired", (lock_key,))
            row = cursor.fetchone()
            acquired = bool(_row_get(row, 'acquired', 0))

            if acquired:
                _startup_leader_lock_conn = conn  # keep alive to hold lock
                logging.info("[BOOT] Startup leader lock acquired in this worker")
                return True

            conn.close()
            logging.debug("[BOOT] Startup leader lock already held by another worker")
            return False

        # Not PostgreSQL; close and continue to file-lock fallback.
        conn.close()
    except Exception as lock_err:
        logging.debug(f"[BOOT] PostgreSQL leader lock unavailable: {lock_err}")

    # Fallback for SQLite/non-PG: best-effort lock file.
    try:
        lock_path = "/tmp/sptnr_startup_leader.lock"
        _startup_leader_lock_file_fd = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        os.write(_startup_leader_lock_file_fd, str(os.getpid()).encode("ascii", "ignore"))
        logging.info("[BOOT] Startup lock file acquired in this worker")
        return True
    except FileExistsError:
        logging.debug("[BOOT] Startup lock file already exists; skipping background schedulers")
        return False
    except Exception as lock_file_err:
        # Fail-open for environments where lock file cannot be created.
        logging.warning(f"[BOOT] Could not create startup lock file, enabling schedulers here: {lock_file_err}")
        return True


def _start_daily_scheduler():
    """Start a background thread that runs daily maintenance tasks once per day.

    Tasks:
    1. Scan Navidrome for new album artists not yet in the local database and import them.
    2. Scan every album artist in the catalogue for missing releases and add them to the
       missing_releases table.

    The scheduler respects any in-progress scan by waiting rather than starting a
    conflicting operation.
    """
    global _daily_scheduler_thread, _daily_scheduler_stop

    if _daily_scheduler_thread and _daily_scheduler_thread.is_alive():
        logging.debug("Daily scheduler already running; skipping duplicate start")
        return

    _daily_scheduler_stop = threading.Event()

    def _daily_worker():
        # Interval is configurable via ``features.daily_scheduler_interval_hours`` in config.yaml.
        # Defaults to 24 hours.
        try:
            cfg = get_config()
            interval_hours = float(
                cfg.get("features", {}).get("daily_scheduler_interval_hours", 24)
            )
        except Exception:
            interval_hours = 24
        INTERVAL_SECONDS = int(interval_hours * 3600)
        logging.info(f"[DAILY] Daily scheduler started (interval: {interval_hours}h)")

        while not _daily_scheduler_stop.is_set():
            # Wait for the full interval (interruptible by stop event)
            if _daily_scheduler_stop.wait(timeout=INTERVAL_SECONDS):
                break  # Stop requested

            try:
                _run_daily_new_artist_import()
            except Exception as exc:
                logging.error(f"[DAILY] Error in daily new-artist import: {exc}", exc_info=True)

            try:
                _run_daily_missing_releases_scan()
            except Exception as exc:
                logging.error(f"[DAILY] Error in daily missing-releases scan: {exc}", exc_info=True)

            try:
                _run_monday_listenbrainz_rss_sync()
            except Exception as exc:
                logging.error(f"[DAILY] Error in ListenBrainz Monday sync: {exc}", exc_info=True)

            try:
                _run_daily_5am_lb_rematch()
            except Exception as exc:
                logging.error(f"[DAILY] Error in LB 5am rematch: {exc}", exc_info=True)

            try:
                _run_daily_musicbrainz_collection_release_refresh()
            except Exception as exc:
                logging.error(f"[DAILY] Error in MusicBrainz daily release refresh: {exc}", exc_info=True)

        logging.info("[DAILY] Daily scheduler stopped")

    _daily_scheduler_thread = threading.Thread(target=_daily_worker, daemon=True, name="daily-scheduler")
    _daily_scheduler_thread.start()
    logging.info("[DAILY] Daily scheduler thread started (tasks run every 24 hours)")


@app.route("/api/queue/<queue_id>/requeue", methods=["POST"])
def api_queue_requeue_item(queue_id):
    """Re-queue a single unmatched or failed item back to queued status."""
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        cursor.execute(
            f"SELECT id, status, artist, title, file_path FROM download_queue WHERE id = {placeholder}",
            (queue_id,)
        )
        item = cursor.fetchone()

        if not item:
            conn.close()
            return jsonify({"error": "Queue item not found"}), 404

        current_status = item['status'] if hasattr(item, 'keys') else item[1]
        if current_status not in ['unmatched', 'failed', 'completed']:
            conn.close()
            return jsonify({"error": f"Cannot re-queue item with status '{current_status}'"}), 400

        update_sql = f"""
            UPDATE download_queue
            SET status = {placeholder},
                failure_reason = NULL,
                retry_count = 0,
                updated_at = CURRENT_TIMESTAMP
        """
        update_params = ['queued']

        if current_status == 'unmatched':
            update_sql += ", file_path = NULL"

        update_sql += f" WHERE id = {placeholder}"
        update_params.append(queue_id)
        cursor.execute(update_sql, tuple(update_params))

        if cursor.rowcount == 0:
            conn.close()
            return jsonify({"error": "Failed to re-queue item"}), 500

        conn.commit()
        item_artist = item['artist'] if hasattr(item, 'keys') else item[2]
        item_title = item['title'] if hasattr(item, 'keys') else item[3]
        conn.close()

        logging.info(f"[QUEUE] Re-queued item {queue_id} ({item_artist} - {item_title}) from '{current_status}' back to 'queued'")
        return jsonify({"success": True, "queue_id": queue_id, "message": f"Item re-queued: {item_artist} - {item_title}"})

    except Exception as e:
        logging.error(f"Error re-queuing item {queue_id}: {e}")
        return jsonify({"error": str(e)}), 400


@app.route("/api/queue/requeue-all-unmatched", methods=["POST"])
def api_queue_requeue_all_unmatched():
    """Re-queue all unmatched items back to queued status."""
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        cursor.execute(
            f"""UPDATE download_queue
                SET status = {placeholder},
                    failure_reason = NULL,
                    retry_count = 0,
                    file_path = NULL,
                    updated_at = CURRENT_TIMESTAMP
                WHERE status = {placeholder}""",
            ('queued', 'unmatched'),
        )
        requeued = cursor.rowcount
        conn.commit()
        conn.close()

        logging.info(f"[QUEUE] Re-queued {requeued} unmatched item(s) back to 'queued' status")
        return jsonify({"success": True, "requeued": requeued, "message": f"Re-queued {requeued} unmatched item(s) for retry"})

    except Exception as e:
        logging.error(f"Error re-queuing all unmatched: {e}")
        return jsonify({"error": str(e)}), 400

def _run_monday_listenbrainz_rss_sync():
    """Run ListenBrainz RSS playlist sync once per week (Monday morning) for configured users."""
    now = datetime.now()
    if now.weekday() != 0 or now.hour < 6:
        return
    cfg = get_config()
    users = cfg.get("navidrome_users", []) or []
    if not users:
        return
    conn = get_db()
    try:
        _ensure_listenbrainz_playlist_tables(conn)
        cursor = conn.cursor()
        placeholder = get_placeholder(conn)
        week_key = f"{now.isocalendar().year}-W{now.isocalendar().week:02d}"
        for user_cfg in users:
            app_user = (user_cfg.get("user") or "").strip()
            lb_token = (user_cfg.get("listenbrainz_user_token") or "").strip()
            lb_username = (user_cfg.get("listenbrainz_username") or app_user).strip()
            if not app_user or not lb_username:
                continue
            cursor.execute(
                f"SELECT last_synced_week FROM listenbrainz_playlist_scheduler_state WHERE username = {placeholder}",
                (app_user,),
            )
            row = cursor.fetchone()
            last_week = row.get("last_synced_week") if isinstance(row, dict) else (row[0] if row else None)
            if last_week == week_key:
                continue
            result = _sync_listenbrainz_rss_playlists_for_user(
                app_username=app_user,
                listenbrainz_username=lb_username,
                lb_token=lb_token,
                enqueue_missing=True,
                write_m3u=True,
            )
            if not result.get("success"):
                logging.warning(f"[LB_RSS] Monday sync failed for {app_user}: {result.get('error')}")
                continue
            now_iso = datetime.now().isoformat()
            cursor.execute("""
                INSERT INTO listenbrainz_playlist_scheduler_state (username, last_synced_week, last_synced_at)
                VALUES (%s, %s, %s)
                ON CONFLICT (username) DO UPDATE
                SET last_synced_week = EXCLUDED.last_synced_week,
                    last_synced_at = EXCLUDED.last_synced_at""",
                (app_user, week_key, now_iso))
        conn.commit()
    finally:
        conn.close()


def _run_daily_5am_lb_rematch():
    """Every morning at 5am, re-check missing LB playlist tracks against the library
    and update M3U playlists if new matches are found."""
    now = datetime.now()
    if now.hour != 5:
        return
    cfg = get_config()
    users = cfg.get("navidrome_users", []) or []
    if not users:
        return
    conn = get_db()
    try:
        _ensure_listenbrainz_playlist_tables(conn)
        cursor = conn.cursor()
        placeholder = get_placeholder(conn)
        for user_cfg in users:
            app_user = (user_cfg.get("user") or "").strip()
            lb_username = (user_cfg.get("listenbrainz_username") or app_user).strip()
            if not app_user:
                continue
            # Avoid running twice in the same hour
            cursor.execute(
                f"SELECT last_rematch_at FROM listenbrainz_playlist_scheduler_state WHERE username = {placeholder}",
                (app_user,),
            )
            row = cursor.fetchone()
            last_rematch = row.get("last_rematch_at") if isinstance(row, dict) else (row[0] if row else None)
            if last_rematch:
                try:
                    from datetime import datetime as _dt
                    last_dt = _dt.fromisoformat(last_rematch)
                    if (now - last_dt).total_seconds() < 3600:
                        continue
                except Exception:
                    pass
            newly_matched = _rematch_missing_lb_playlist_tracks(conn, app_user)
            if newly_matched > 0:
                logging.info(f"[LB_REMATCH] {newly_matched} new track(s) matched for {app_user}; refreshing M3U files")
                # Rewrite M3U for all playlists
                for key in LISTENBRAINZ_PLAYLIST_SPECS.keys():
                    playlist_name, rows = _load_playlist_rows(conn, app_user, key)
                    file_paths = [r.get("file_path") for r in rows if r.get("file_path")]
                    try:
                        _write_m3u_playlist(playlist_name, file_paths)
                    except Exception as exc:
                        logging.warning(f"[LB_REMATCH] M3U write failed for {key}: {exc}")
            now_iso = datetime.now().isoformat()
            cursor.execute("""
                INSERT INTO listenbrainz_playlist_scheduler_state (username, last_rematch_at)
                VALUES (%s, %s)
                ON CONFLICT (username) DO UPDATE SET last_rematch_at = EXCLUDED.last_rematch_at""",
                (app_user, now_iso))
        conn.commit()
    except Exception as exc:
        logging.error(f"[LB_REMATCH] Daily rematch error: {exc}", exc_info=True)
    finally:
        conn.close()


def _parse_musicbrainz_release_date(raw_date: str) -> str | None:
    """Normalize MusicBrainz release dates to YYYY-MM-DD for storage/filtering."""
    if not raw_date:
        return None
    value = str(raw_date).strip()
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
        return value
    if re.fullmatch(r"\d{4}-\d{2}", value):
        return f"{value}-01"
    if re.fullmatch(r"\d{4}", value):
        return f"{value}-01-01"
    return None


def _run_daily_musicbrainz_collection_release_refresh():
    """
    Refresh upcoming/recent releases from MusicBrainz for artists in the collection.

    This augments Wikipedia-based sources with direct MusicBrainz release-group data,
    then upserts results into `upcoming_releases` so the dashboard can show newly
    announced and recently released entries with queue actions.
    """
    cfg = get_config() or {}
    features = cfg.get("features", {}) if isinstance(cfg, dict) else {}

    if not bool(features.get("daily_musicbrainz_release_scan_enabled", True)):
        return

    try:
        lookback_days = int(features.get("daily_musicbrainz_release_lookback_days", 42) or 42)
    except Exception:
        lookback_days = 42
    try:
        lookahead_days = int(features.get("daily_musicbrainz_release_lookahead_days", 28) or 28)
    except Exception:
        lookahead_days = 28
    try:
        max_artists = int(features.get("daily_musicbrainz_release_max_artists", 500) or 500)
    except Exception:
        max_artists = 500
    try:
        per_artist_limit = int(features.get("daily_musicbrainz_release_per_artist_limit", 100) or 100)
    except Exception:
        per_artist_limit = 100

    lookback_days = max(1, min(lookback_days, 365))
    lookahead_days = max(1, min(lookahead_days, 365))
    max_artists = max(1, min(max_artists, 5000))
    per_artist_limit = max(10, min(per_artist_limit, 250))

    today = datetime.now().date()
    min_date = today - timedelta(days=lookback_days)
    max_date = today + timedelta(days=lookahead_days)

    conn = get_db()
    try:
        _ensure_upcoming_releases_schema(conn)
        placeholder = "%s"
        cursor = conn.cursor()

        cursor.execute(f"""
            SELECT DISTINCT COALESCE(NULLIF(album_artist, ''), artist) AS artist_name
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) IS NOT NULL
              AND COALESCE(NULLIF(album_artist, ''), artist) <> ''
            ORDER BY LOWER(COALESCE(NULLIF(album_artist, ''), artist))
            LIMIT {placeholder}
        """, (max_artists,))
        artist_rows = cursor.fetchall() or []

        artists = []
        for row in artist_rows:
            artist_name = _row_get(row, "artist_name", 0)
            if artist_name:
                artists.append(str(artist_name).strip())

        if not artists:
            logging.info("[UPCOMING_MB_DAILY] No collection artists found; skipping MusicBrainz refresh")
            return

        inserted = 0
        updated = 0
        scanned_artists = 0

        for artist_name in artists:
            scanned_artists += 1
            release_groups = _fetch_musicbrainz_releases(artist_name, limit=per_artist_limit)
            for rg in release_groups:
                parsed_date = _parse_musicbrainz_release_date(rg.get("first_release_date"))
                if not parsed_date:
                    continue

                try:
                    release_dt = datetime.strptime(parsed_date, "%Y-%m-%d").date()
                except ValueError:
                    continue

                if release_dt < min_date or release_dt > max_date:
                    continue

                album_name = (rg.get("title") or "").strip()
                if not album_name:
                    continue

                release_year = int(parsed_date[:4]) if len(parsed_date) >= 4 and parsed_date[:4].isdigit() else None
                release_group_mbid = (rg.get("id") or "").strip() or None

                cursor.execute(
                    f"""
                    INSERT INTO upcoming_releases (
                        artist_name,
                        album_name,
                        release_date,
                        release_year,
                        source,
                        artist_in_collection,
                        album_in_collection,
                        is_new_release,
                        notes,
                        release_group_mbid,
                        mbid_match_status,
                        mbid_source,
                        mbid_confidence,
                        mbid_match_score,
                        mbid_last_checked_at,
                        mbid_manual_override,
                        updated_at
                    )
                    VALUES (
                        {placeholder}, {placeholder}, {placeholder}, {placeholder},
                        {placeholder}, {placeholder}, {placeholder}, {placeholder},
                        {placeholder}, {placeholder}, {placeholder}, {placeholder},
                        {placeholder}, {placeholder}, {placeholder}, {placeholder},
                        CURRENT_TIMESTAMP
                    )
                    ON CONFLICT (artist_name, album_name, release_date) DO UPDATE SET
                        source = EXCLUDED.source,
                        artist_in_collection = EXCLUDED.artist_in_collection,
                        release_year = EXCLUDED.release_year,
                        release_group_mbid = COALESCE(EXCLUDED.release_group_mbid, upcoming_releases.release_group_mbid),
                        mbid_match_status = CASE
                            WHEN COALESCE(upcoming_releases.mbid_manual_override, FALSE) THEN upcoming_releases.mbid_match_status
                            ELSE EXCLUDED.mbid_match_status
                        END,
                        mbid_source = CASE
                            WHEN COALESCE(upcoming_releases.mbid_manual_override, FALSE) THEN upcoming_releases.mbid_source
                            ELSE EXCLUDED.mbid_source
                        END,
                        mbid_confidence = CASE
                            WHEN COALESCE(upcoming_releases.mbid_manual_override, FALSE) THEN upcoming_releases.mbid_confidence
                            ELSE EXCLUDED.mbid_confidence
                        END,
                        mbid_match_score = CASE
                            WHEN COALESCE(upcoming_releases.mbid_manual_override, FALSE) THEN upcoming_releases.mbid_match_score
                            ELSE EXCLUDED.mbid_match_score
                        END,
                        mbid_last_checked_at = CASE
                            WHEN COALESCE(upcoming_releases.mbid_manual_override, FALSE) THEN upcoming_releases.mbid_last_checked_at
                            ELSE EXCLUDED.mbid_last_checked_at
                        END,
                        updated_at = CURRENT_TIMESTAMP
                    """,
                    (
                        artist_name,
                        album_name,
                        parsed_date,
                        release_year,
                        "MusicBrainz Daily Collection",
                        True,
                        False,
                        True,
                        "Added by daily MusicBrainz artist scan",
                        release_group_mbid,
                        "matched" if release_group_mbid else "unmatched",
                        "musicbrainz_daily_scan",
                        "high" if release_group_mbid else None,
                        1.0 if release_group_mbid else None,
                        datetime.now().isoformat(),
                        False,
                    ),
                )

                if cursor.rowcount == 1:
                    inserted += 1
                else:
                    updated += 1

            try:
                singles_queued = _auto_queue_collection_artist_singles_from_release_groups(artist_name, release_groups)
                if singles_queued:
                    logging.info(
                        "[AUTO-QUEUE] Queued %s current-year single(s) for collection artist '%s'",
                        singles_queued,
                        artist_name,
                    )
            except Exception as auto_queue_err:
                logging.warning(
                    "[AUTO-QUEUE] Error auto-queuing singles for '%s': %s",
                    artist_name,
                    auto_queue_err,
                )

            # Respect MusicBrainz API pacing
            time.sleep(1.0)

        conn.commit()
        logging.info(
            "[UPCOMING_MB_DAILY] Refresh complete: artists=%s inserted=%s updated=%s window=%s..%s",
            scanned_artists,
            inserted,
            updated,
            min_date.isoformat(),
            max_date.isoformat(),
        )
    except Exception as exc:
        try:
            conn.rollback()
        except Exception:
            pass
        logging.error(f"[UPCOMING_MB_DAILY] Refresh failed: {exc}", exc_info=True)
    finally:
        conn.close()


def _ensure_upcoming_releases_schema(conn):
    from wikipedia_releases_scraper import WikipediaReleaseScraper

    scraper = WikipediaReleaseScraper(db_path=DB_PATH)
    scraper.ensure_schema(conn)
    return scraper


def _upcoming_release_checked_today(last_checked_at):
    if not last_checked_at:
        return False

    today_key = datetime.now().date().isoformat()
    return str(last_checked_at).startswith(today_key)


def _select_best_upcoming_release_match(candidates):
    if not candidates:
        return None, "unmatched"

    best = candidates[0]
    best_score = float(best.get("match_score") or 0.0)
    second_score = float(candidates[1].get("match_score") or 0.0) if len(candidates) > 1 else 0.0

    if best_score < 0.75:
        return None, "unmatched"

    if second_score and abs(best_score - second_score) < 0.03 and best_score < 0.92:
        return None, "ambiguous"

    return best, "matched"


def _update_upcoming_release_match_record(
    conn,
    release_id,
    *,
    release_group_mbid=None,
    status="unmatched",
    source=None,
    confidence=None,
    match_score=None,
    manual_override=False,
):
    placeholder = "%s"
    cursor = conn.cursor()
    cursor.execute(
        f"""
        UPDATE upcoming_releases
        SET release_group_mbid = {placeholder},
            mbid_match_status = {placeholder},
            mbid_source = {placeholder},
            mbid_confidence = {placeholder},
            mbid_match_score = {placeholder},
            mbid_last_checked_at = {placeholder},
            mbid_manual_override = {placeholder},
            updated_at = CURRENT_TIMESTAMP
        WHERE id = {placeholder}
        """,
        (
            release_group_mbid,
            status,
            source,
            confidence,
            match_score,
            datetime.now().isoformat(),
            bool(manual_override),
            release_id,
        ),
    )
    conn.commit()


def _match_upcoming_release(release_id, manual_release_group_mbid=None, manual_source=None):
    conn = get_db()
    try:
        _ensure_upcoming_releases_schema(conn)
        placeholder = "%s"
        cursor = conn.cursor()
        cursor.execute(
            f"SELECT * FROM upcoming_releases WHERE id = {placeholder}",
            (release_id,),
        )
        row = cursor.fetchone()
        if not row:
            return {"success": False, "error": "Upcoming release not found"}, 404

        artist_name = (_row_get(row, "artist_name", 1, "") or "").strip()
        album_name = (_row_get(row, "album_name", 2, "") or "").strip()
        if not artist_name or not album_name:
            return {"success": False, "error": "Upcoming release is missing artist or album information"}, 400

        if manual_release_group_mbid:
            _update_upcoming_release_match_record(
                conn,
                release_id,
                release_group_mbid=manual_release_group_mbid,
                status="matched",
                source=manual_source or "manual_selection",
                confidence="manual",
                match_score=1.0,
                manual_override=True,
            )
            return {
                "success": True,
                "release_id": release_id,
                "release_group_mbid": manual_release_group_mbid,
                "match_status": "matched",
                "manual_override": True,
            }, 200

        candidates = _search_musicbrainz_releasegroup_matches(artist_name, album_name, limit=10)
        selected, status = _select_best_upcoming_release_match(candidates)

        if not selected:
            _update_upcoming_release_match_record(
                conn,
                release_id,
                release_group_mbid=None,
                status=status,
                source="musicbrainz_auto",
                confidence=None,
                match_score=float(candidates[0].get("match_score") or 0.0) if candidates else None,
                manual_override=False,
            )
            return {
                "success": False,
                "release_id": release_id,
                "match_status": status,
                "candidates": candidates[:5],
            }, 200

        _update_upcoming_release_match_record(
            conn,
            release_id,
            release_group_mbid=selected.get("id"),
            status="matched",
            source="musicbrainz_auto",
            confidence=selected.get("confidence"),
            match_score=selected.get("match_score"),
            manual_override=False,
        )
        return {
            "success": True,
            "release_id": release_id,
            "release_group_mbid": selected.get("id"),
            "match_status": "matched",
            "confidence": selected.get("confidence"),
            "match_score": selected.get("match_score"),
            "candidate": selected,
        }, 200
    finally:
        conn.close()


def _run_daily_1am_upcoming_release_match():
    now = datetime.now()
    if now.hour != 1:
        return

    conn = get_db()
    try:
        _ensure_upcoming_releases_schema(conn)
        placeholder = "%s"
        cursor = conn.cursor()
        cursor.execute(
            f"""
            SELECT id, mbid_last_checked_at
            FROM upcoming_releases
            WHERE COALESCE(mbid_manual_override, FALSE) = FALSE
              AND (release_date IS NULL OR release_date >= {placeholder})
            ORDER BY release_date ASC, artist_name ASC, album_name ASC
            """,
            (now.date().isoformat(),),
        )
        rows = cursor.fetchall() or []
    finally:
        conn.close()

    pending_ids = []
    for row in rows:
        release_id = _row_get(row, "id", 0)
        last_checked_at = _row_get(row, "mbid_last_checked_at", 1)
        if release_id and not _upcoming_release_checked_today(last_checked_at):
            pending_ids.append(int(release_id))

    if not pending_ids:
        return

    matched = 0
    unresolved = 0
    for release_id in pending_ids:
        try:
            result, _ = _match_upcoming_release(release_id)
            if result.get("success"):
                matched += 1
            else:
                unresolved += 1
        except Exception as match_err:
            unresolved += 1
            logging.warning(f"[UPCOMING_MATCH] Release {release_id} auto-match failed: {match_err}")

    logging.info(
        "[UPCOMING_MATCH] 1am auto-match complete: checked=%s matched=%s unresolved=%s",
        len(pending_ids),
        matched,
        unresolved,
    )


def _start_upcoming_release_match_scheduler():
    """Start a lightweight scheduler that performs upcoming-release MBID matching at 1am."""
    global upcoming_release_match_scheduler

    with upcoming_release_match_scheduler_lock:
        existing_thread = upcoming_release_match_scheduler.get("thread")
        if existing_thread and hasattr(existing_thread, "is_alive") and existing_thread.is_alive():
            upcoming_release_match_scheduler["running"] = True
            return

        stop_event = threading.Event()
        upcoming_release_match_scheduler["stop_event"] = stop_event

        def scheduler_worker():
            try:
                time.sleep(15)
                interval_seconds = 10 * 60
                while not stop_event.is_set():
                    try:
                        _run_daily_1am_upcoming_release_match()
                    except Exception as loop_err:
                        logging.error(f"[UPCOMING_MATCH] Scheduler loop error: {loop_err}")

                    if stop_event.wait(timeout=interval_seconds):
                        break
            finally:
                with upcoming_release_match_scheduler_lock:
                    upcoming_release_match_scheduler["running"] = False

        thread = threading.Thread(target=scheduler_worker, daemon=True, name="upcoming-release-match-scheduler")
        thread.start()
        upcoming_release_match_scheduler["thread"] = thread
        upcoming_release_match_scheduler["running"] = True
        logging.info("[UPCOMING_MATCH] Scheduler started (checks every 10 minutes, runs matching at 1am)")


def _run_daily_new_artist_import():
    """Import new Navidrome album artists that are not yet in the local database.

    Queries Navidrome for all artists, then checks the local tracks table for any
    artist that hasn't been imported yet and triggers a metadata-only import for
    each new artist found.
    """
    global scan_process_navidrome

    logging.info("[DAILY] Checking Navidrome for new artists not yet in database...")

    # Skip if a Navidrome scan is already running
    if scan_process_navidrome and isinstance(scan_process_navidrome, dict):
        t = scan_process_navidrome.get("thread")
        if t and t.is_alive():
            logging.info("[DAILY] Navidrome scan already running; skipping new-artist import")
            return

    try:
        cfg = get_config()
        nav_users = cfg.get("navidrome_users", []) or []
        if not nav_users:
            nav_cfg = cfg.get("navidrome", {}) or {}
            if nav_cfg.get("base_url"):
                nav_users = [nav_cfg]

        if not nav_users:
            logging.debug("[DAILY] No Navidrome configuration found; skipping new-artist import")
            return

        from api_clients.navidrome import NavidromeClient  # type: ignore

        all_nav_artists: set = set()
        for user_cfg in nav_users:
            try:
                client = NavidromeClient(
                    base_url=user_cfg.get("base_url", ""),
                    username=user_cfg.get("user", ""),
                    password=user_cfg.get("pass", ""),
                )
                for artist in (client.get_artists() or []):
                    name = (artist.get("name") or "").strip()
                    if name:
                        all_nav_artists.add(name)
            except Exception as exc:
                logging.warning(f"[DAILY] Failed to fetch artists from Navidrome: {exc}")

        if not all_nav_artists:
            logging.debug("[DAILY] No artists returned from Navidrome")
            return

        # Get existing album artists from local database
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        cursor.execute(
            "SELECT DISTINCT LOWER(COALESCE(NULLIF(album_artist, ''), artist)) FROM tracks "
            "WHERE COALESCE(NULLIF(album_artist, ''), artist) IS NOT NULL"
        )
        local_artists = {row[0] for row in (cursor.fetchall() or []) if row and row[0]}
        conn.close()

        new_artists = [a for a in all_nav_artists if a.lower() not in local_artists]

        if not new_artists:
            logging.info("[DAILY] No new Navidrome artists found; database is up to date")
            return

        logging.info(f"[DAILY] Found {len(new_artists)} new artist(s) to import from Navidrome")

        # Use existing boot import infrastructure – scan each new artist
        def run_new_artist_import():
            global scan_process_navidrome
            # SPTNR_SKIP_SINGLES=1 prevents the popularity/single-detection pipeline
            # from running during this metadata-only import pass.  Without this flag,
            # scan_artist_to_db would also trigger expensive Last.fm/Spotify lookups
            # for each track.  The daily scheduler handles popularity separately.
            os.environ["SPTNR_SKIP_SINGLES"] = "1"
            try:
                artist_map = build_artist_index()
                for artist_name in new_artists:
                    info = artist_map.get(artist_name, {})
                    artist_id = info.get("id") if isinstance(info, dict) else None
                    logging.info(f"[DAILY] Importing new artist: {artist_name}")
                    scan_artist_to_db(artist_name, artist_id, verbose=False, force=False)
                logging.info(f"[DAILY] New artist import complete ({len(new_artists)} artist(s))")
            except Exception as exc:
                logging.error(f"[DAILY] Error importing new artists: {exc}", exc_info=True)
            finally:
                os.environ.pop("SPTNR_SKIP_SINGLES", None)
                scan_process_navidrome = None

        t = threading.Thread(target=run_new_artist_import, daemon=True, name="daily-new-artist-import")
        t.start()
        scan_process_navidrome = {"thread": t, "type": "daily_new_artist"}

    except Exception as exc:
        logging.error(f"[DAILY] _run_daily_new_artist_import error: {exc}", exc_info=True)


def _sync_new_navidrome_album_artists_fast(trigger_source: str = "unknown"):
    """Create missing album-artist records from Navidrome without scanning tracks."""
    try:
        from helpers.scan_helpers import pre_import_sync_album_artists

        result = pre_import_sync_album_artists()
        if not isinstance(result, dict):
            logging.info(f"[NAV_SYNC:{trigger_source}] pre-sync returned unexpected result type")
            return {"success": False, "error": "Unexpected result type"}

        if result.get("success"):
            logging.info(
                f"[NAV_SYNC:{trigger_source}] album-artist sync complete: "
                f"new={result.get('new_artists_created', 0)}, "
                f"unique={result.get('unique_album_artists', 0)}, "
                f"existing={result.get('existing_artists', 0)}, "
                f"elapsed_ms={result.get('sync_time_ms', 0)}"
            )
        else:
            logging.warning(
                f"[NAV_SYNC:{trigger_source}] album-artist sync failed: "
                f"{result.get('error', 'unknown error')}"
            )
        return result
    except Exception as exc:
        logging.error(f"[NAV_SYNC:{trigger_source}] unexpected error during album-artist sync: {exc}", exc_info=True)
        return {"success": False, "error": str(exc)}


def _has_valid_local_track_paths_for_mp3_import(sample_size: int = 120):
    """Quickly validate that Navidrome-imported track paths resolve on this host."""
    conn = None
    try:
        conn = get_db()
        if _is_postgres_connection(conn):
            cursor = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
            placeholder = "%s"
        else:
            cursor = conn.cursor()
            placeholder = "?"
        placeholder = "%s"

        cursor.execute(
            f"""
            SELECT file_path
            FROM tracks
            WHERE file_path IS NOT NULL
              AND file_path <> ''
              AND file_path NOT LIKE '__queued_for_download__%'
            ORDER BY id DESC
            LIMIT {placeholder}
            """,
            (sample_size,)
        )
        rows = cursor.fetchall() or []

        if not rows:
            return False, "No track file paths available in DB"

        checked = 0
        existing = 0
        for row in rows:
            file_path = (row.get("file_path") if isinstance(row, dict) else row[0]) or ""
            file_path = str(file_path).strip()
            if not file_path:
                continue

            checked += 1
            if os.path.exists(file_path):
                existing += 1

        if checked == 0:
            return False, "No usable file paths to validate"
        if existing == 0:
            return False, f"0/{checked} sampled file paths exist on this host"

        return True, f"{existing}/{checked} sampled file paths exist"
    except Exception as exc:
        return False, f"Path validation error: {exc}"
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _maybe_start_post_navidrome_mp3_import(trigger_source: str = "unknown"):
    """Run MP3 import after Navidrome sync only when local file paths are valid."""
    global scan_process_mp3_import

    try:
        is_running = False
        if scan_process_mp3_import is not None:
            try:
                if hasattr(scan_process_mp3_import, "is_alive"):
                    is_running = scan_process_mp3_import.is_alive()
                elif hasattr(scan_process_mp3_import, "poll"):
                    is_running = scan_process_mp3_import.poll() is None
            except Exception:
                is_running = False

        if is_running:
            log_unified(f"[NAV_SYNC:{trigger_source}] Skipping post-sync MP3 import: a MP3 import scan is already running")
            return {"success": False, "skipped": True, "reason": "mp3_import_running"}

        valid_paths, detail = _has_valid_local_track_paths_for_mp3_import()
        if not valid_paths:
            warning_msg = (
                "Incorrect file path being given, please go into Navidrome under "
                "User Settings > Players, search for popularr and enable Report Real Path"
            )
            log_unified(f"[NAV_SYNC:{trigger_source}] {warning_msg} ({detail})")
            logging.warning(f"[NAV_SYNC:{trigger_source}] Post-sync MP3 import skipped: {detail}")
            return {"success": False, "skipped": True, "reason": "invalid_paths", "detail": detail}

        from scan_mp3_import import MP3ImportScanner

        scanner = MP3ImportScanner(directory=None, dry_run=False, verbose=True, mode="database")

        def run_scan():
            global scan_process_mp3_import
            try:
                results = scanner.scan()
                logging.info(f"[NAV_SYNC:{trigger_source}] Post-sync MP3 import completed: {results}")
                log_unified(f"[NAV_SYNC:{trigger_source}] Post-sync MP3 import completed")
            except Exception as exc:
                logging.error(f"[NAV_SYNC:{trigger_source}] Post-sync MP3 import failed: {exc}", exc_info=True)
                log_unified(f"[NAV_SYNC:{trigger_source}] Post-sync MP3 import failed: {exc}")
            finally:
                scan_process_mp3_import = None

        scan_thread = threading.Thread(target=run_scan, daemon=True, name=f"mp3-import-post-nav-{trigger_source}")
        scan_thread.start()
        scan_process_mp3_import = scan_thread
        log_unified(f"[NAV_SYNC:{trigger_source}] Post-sync MP3 import started")
        return {"success": True, "started": True}
    except Exception as exc:
        logging.error(f"[NAV_SYNC:{trigger_source}] Unable to start post-sync MP3 import: {exc}", exc_info=True)
        log_unified(f"[NAV_SYNC:{trigger_source}] Unable to start post-sync MP3 import: {exc}")
        return {"success": False, "error": str(exc)}


def _navidrome_first_full_import_marker_path() -> str:
    return os.path.join(os.path.dirname(DB_PATH), "navidrome_first_full_import_done.json")


def _mark_navidrome_first_full_import_complete(scan_source: str = "unknown"):
    """Persist a marker after the first successful full Navidrome import."""
    marker_path = _navidrome_first_full_import_marker_path()
    if os.path.exists(marker_path):
        return
    try:
        payload = {
            "completed_at": datetime.utcnow().isoformat() + "Z",
            "source": scan_source,
        }
        with open(marker_path, "w", encoding="utf-8") as f:
            json.dump(payload, f)
        logging.info(f"[NAV_INCREMENTAL] First full Navidrome import marker created ({scan_source})")
        log_unified("[NAV_INCREMENTAL] First full Navidrome import complete; 15-minute incremental checks enabled")
    except Exception as exc:
        logging.warning(f"[NAV_INCREMENTAL] Could not write first-import marker: {exc}")


def _has_completed_first_navidrome_import(auto_repair: bool = True) -> bool:
    """Return True once the first successful full Navidrome import is known.

    The marker file is the primary source of truth. If it is missing after a restart,
    recover it from a completed Navidrome progress file or from an already-imported
    library in the database so the dashboard does not re-lock scan controls.
    """
    marker_path = _navidrome_first_full_import_marker_path()
    if os.path.exists(marker_path):
        return True

    progress_path = os.path.join(os.path.dirname(DB_PATH), "navidrome_scan_progress.json")
    try:
        if os.path.exists(progress_path):
            with open(progress_path, "r", encoding="utf-8") as pf:
                state = json.load(pf)
            if state.get("status") == "complete" and int(state.get("exit_code", 0)) == 0:
                if auto_repair:
                    _mark_navidrome_first_full_import_complete(scan_source="progress_file_detected")
                return True
    except Exception as progress_err:
        logging.debug(f"[NAV_INCREMENTAL] Could not inspect Navidrome progress file: {progress_err}")

    conn = None
    try:
        conn = get_db()
        cursor = conn.cursor()
        cursor.execute("SELECT COUNT(*) FROM tracks")
        row = cursor.fetchone()
        track_count = row[0] if isinstance(row, (list, tuple)) else (row.get('count') if hasattr(row, 'get') else row)
        if int(track_count or 0) > 0:
            if auto_repair:
                _mark_navidrome_first_full_import_complete(scan_source="database_detected")
            return True
    except Exception as db_err:
        logging.debug(f"[NAV_INCREMENTAL] Could not infer first import from database state: {db_err}")
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass

    return False


def _is_scan_currently_running(proc_ref) -> bool:
    if proc_ref is None:
        return False
    try:
        if isinstance(proc_ref, dict):
            t = proc_ref.get("thread")
            return bool(t and hasattr(t, "is_alive") and t.is_alive())
        if hasattr(proc_ref, "is_alive"):
            return bool(proc_ref.is_alive())
        if hasattr(proc_ref, "poll"):
            return proc_ref.poll() is None
    except Exception:
        return False
    return False


def _scan_new_navidrome_files_since_last_import(max_newest_albums: int = 80):
    """Detect likely new files from newest Navidrome albums and import missing artists/tracks."""
    from api_clients.navidrome import NavidromeClient

    cfg = get_config() or {}
    nav_users = cfg.get("navidrome_users", []) or []
    if not nav_users:
        nav_cfg = cfg.get("navidrome", {}) or {}
        if nav_cfg.get("base_url"):
            nav_users = [nav_cfg]

    if not nav_users:
        return {"success": False, "error": "No Navidrome configuration"}

    conn = None
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        artists_to_rescan = {}
        candidate_tracks = 0
        missing_track_count = 0

        for user_cfg in nav_users:
            client = NavidromeClient(
                base_url=user_cfg.get("base_url", ""),
                username=user_cfg.get("user", ""),
                password=user_cfg.get("pass", ""),
            )

            try:
                url = f"{client.base_url}/rest/getAlbumList2.view"
                params = client._build_params(type="newest", size=max_newest_albums)
                response = client.session.get(url, params=params, timeout=20)
                response.raise_for_status()
                newest_albums = response.json().get("subsonic-response", {}).get("albumList2", {}).get("album", []) or []
            except Exception as exc:
                logging.warning(f"[NAV_INCREMENTAL] Failed newest-album fetch for {user_cfg.get('base_url', '')}: {exc}")
                continue

            for album in newest_albums:
                album_id = album.get("id")
                if not album_id:
                    continue

                album_data = client.fetch_album_tracks(album_id)
                tracks = album_data.get("tracks", []) if isinstance(album_data, dict) else []
                if not tracks:
                    continue

                artist_name = (album_data.get("artist") if isinstance(album_data, dict) else None) or album.get("artist") or ""
                artist_id = (album_data.get("artistId") if isinstance(album_data, dict) else None) or album.get("artistId")

                track_ids = [str(t.get("id")) for t in tracks if t.get("id")]
                candidate_tracks += len(track_ids)
                if not track_ids:
                    continue

                placeholders = ", ".join([placeholder] * len(track_ids))
                cursor.execute(f"SELECT id FROM tracks WHERE id IN ({placeholders})", tuple(track_ids))
                existing_ids = set()
                for row in (cursor.fetchall() or []):
                    if isinstance(row, dict):
                        row_id = row.get("id")
                    elif hasattr(row, "keys"):
                        row_id = row["id"]
                    else:
                        row_id = row[0] if row else None
                    if row_id:
                        existing_ids.add(str(row_id))

                missing_in_db = [tid for tid in track_ids if tid not in existing_ids]
                if missing_in_db and artist_name and artist_id:
                    missing_track_count += len(missing_in_db)
                    artists_to_rescan[artist_name] = artist_id

        if not artists_to_rescan:
            return {
                "success": True,
                "rescanned_artists": 0,
                "missing_tracks_detected": 0,
                "candidate_tracks_checked": candidate_tracks,
            }

        for artist_name, artist_id in artists_to_rescan.items():
            try:
                scan_artist_to_db(artist_name, artist_id, verbose=False, force=False)
            except Exception as exc:
                logging.warning(f"[NAV_INCREMENTAL] Artist rescan failed for {artist_name}: {exc}")

        return {
            "success": True,
            "rescanned_artists": len(artists_to_rescan),
            "missing_tracks_detected": missing_track_count,
            "candidate_tracks_checked": candidate_tracks,
        }
    except Exception as exc:
        return {"success": False, "error": str(exc)}
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


def _start_navidrome_incremental_scheduler():
    """Start 15-minute incremental Navidrome sync checks after first full import."""
    global navidrome_incremental_scheduler

    with navidrome_incremental_scheduler_lock:
        existing_thread = navidrome_incremental_scheduler.get("thread")
        if existing_thread and hasattr(existing_thread, "is_alive") and existing_thread.is_alive():
            navidrome_incremental_scheduler["running"] = True
            return

        stop_event = threading.Event()
        navidrome_incremental_scheduler["stop_event"] = stop_event

        def scheduler_worker():
            try:
                time.sleep(20)
                interval_seconds = 15 * 60

                while not stop_event.is_set():
                    marker_path = _navidrome_first_full_import_marker_path()
                    if not os.path.exists(marker_path):
                        try:
                            progress_path = os.path.join(os.path.dirname(DB_PATH), "navidrome_scan_progress.json")
                            if os.path.exists(progress_path):
                                with open(progress_path, "r", encoding="utf-8") as pf:
                                    state = json.load(pf)
                                if state.get("status") == "complete" and int(state.get("exit_code", 0)) == 0:
                                    _mark_navidrome_first_full_import_complete(scan_source="progress_file_detected")
                        except Exception:
                            pass

                        if stop_event.wait(timeout=interval_seconds):
                            break
                        continue

                    # Don't run incremental checks during active long scans.
                    if _is_scan_currently_running(scan_process_navidrome) or _is_scan_currently_running(scan_process_combined):
                        if stop_event.wait(timeout=120):
                            break
                        continue

                    result = _scan_new_navidrome_files_since_last_import()
                    if result.get("success"):
                        if result.get("missing_tracks_detected", 0) > 0:
                            log_unified(
                                f"[NAV_INCREMENTAL] Imported missing tracks from new files: "
                                f"tracks={result.get('missing_tracks_detected', 0)}, "
                                f"artists={result.get('rescanned_artists', 0)}"
                            )
                        else:
                            logging.info(
                                "[NAV_INCREMENTAL] No new files detected (checked=%s)",
                                result.get("candidate_tracks_checked", 0),
                            )
                    else:
                        logging.warning(f"[NAV_INCREMENTAL] Incremental check failed: {result.get('error', 'unknown error')}")

                    if stop_event.wait(timeout=interval_seconds):
                        break
            except Exception as worker_exc:
                logging.error(f"[NAV_INCREMENTAL] Scheduler worker error: {worker_exc}")
            finally:
                with navidrome_incremental_scheduler_lock:
                    navidrome_incremental_scheduler["running"] = False

        thread = threading.Thread(target=scheduler_worker, daemon=True, name="navidrome-incremental-scheduler")
        thread.start()
        navidrome_incremental_scheduler["thread"] = thread
        navidrome_incremental_scheduler["running"] = True
        logging.info("[NAV_INCREMENTAL] Scheduler started (interval=15m, waits for first full import marker)")


def _run_daily_missing_releases_scan():
    """Check every album artist in the catalogue for missing releases.

    Delegates to the existing ``api_scan_all_missing_releases`` background
    logic by calling it within a Flask application context so that it can
    access ``request`` and other Flask globals safely.
    """
    global scan_process_missing_releases

    logging.info("[DAILY] Starting daily missing-releases scan...")

    # Skip if already running
    if scan_process_missing_releases and isinstance(scan_process_missing_releases, dict):
        t = scan_process_missing_releases.get("thread")
        if t and t.is_alive():
            logging.info("[DAILY] Missing-releases scan already running; skipping daily trigger")
            return

    try:
        with app.test_request_context("/api/artist/scan-all-missing-releases"):
            api_scan_all_missing_releases()
    except Exception as exc:
        logging.error(f"[DAILY] _run_daily_missing_releases_scan error: {exc}", exc_info=True)


def _read_yaml(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            content = f.read()
            return yaml.safe_load(content) or {}, content
    except FileNotFoundError:
        return {}, ""
    except yaml.YAMLError:
        return {}, ""


