# Initialize auto-boot import setting from config
def _get_auto_boot_import_setting():
    """Read auto boot Navidrome scan setting from config, with env var override."""
    # Environment variable takes precedence if set to disable
    if os.environ.get("SPTNR_DISABLE_BOOT_ND_IMPORT") == "1":
        return False
    
    # Read from config file
    try:
        cfg = get_config()
        features = cfg.get("features", {})
        return features.get("auto_boot_navidrome_scan", False)
    except (FileNotFoundError, yaml.YAMLError, KeyError, AttributeError) as e:
        logging.debug(f"Unable to read auto_boot_navidrome_scan from config: {e}")
        return False  # Default to disabled if config can't be read

AUTO_BOOT_ND_IMPORT = _get_auto_boot_import_setting()


def _start_boot_album_artist_sync_only():
    """Run a lightweight album-artist sync at boot without scanning track payloads."""

    def _worker():
        try:
            logging.info("[BOOT] Starting album-list artist sync (metadata-only)")
            _sync_new_navidrome_album_artists_fast(trigger_source="boot_init")
            logging.info("[BOOT] Album-list artist sync complete")
        except Exception as exc:
            logging.error(f"[BOOT] Album-list artist sync failed: {exc}", exc_info=True)

    threading.Thread(target=_worker, daemon=True, name="boot-album-artist-sync").start()


def _schedule_configured_startup_scan_launch():
    """Launch configured scan set after reboot when enabled in feature settings."""
    def _resolve_startup_scan_mode(scan_type, force_enabled, restart_requested):
        mode = "force" if force_enabled else "all"
        effective_restart = restart_requested
        resume_artist = None

        if scan_type not in {"navidrome", "popularity", "combined"}:
            return mode, effective_restart, resume_artist

        try:
            from scan_resume import should_resume_scan

            should_resume, resume_artist = should_resume_scan(scan_type)
            if should_resume:
                mode = "resume_force" if force_enabled else "resume"
                effective_restart = False
        except Exception as resume_err:
            logging.warning(f"[BOOT] Could not evaluate resume state for {scan_type}: {resume_err}")

        return mode, effective_restart, resume_artist

    def _worker():
        try:
            # Delay until module routes are fully loaded.
            # Keep this short by default so scans become visible quickly after reboot.
            delay_raw = os.environ.get("SPTNR_STARTUP_SCAN_DELAY_SECONDS", "3")
            try:
                startup_delay_seconds = int(delay_raw)
            except Exception:
                startup_delay_seconds = 3
            startup_delay_seconds = max(0, min(startup_delay_seconds, 300))
            time.sleep(startup_delay_seconds)

            cfg = get_config() or {}
            features = cfg.get("features", {}) if isinstance(cfg, dict) else {}
            if not bool(features.get("launch_on_startup", False)):
                return

            if not _has_completed_first_navidrome_import(auto_repair=True):
                logging.info("[BOOT] Startup scan launch is locked until first full Navidrome import completes")
                return

            scan_type = str(features.get("startup_scan_type", "navidrome") or "navidrome").strip().lower()
            restart = bool(features.get("startup_scan_restart", False))
            force_enabled = bool(features.get("force", False))

            mapping = {
                "navidrome": ("scan_navidrome", "/scan/navidrome"),
                "metadata": ("scan_mp3_import", "/scan/mp3-import"),
                "popularity": ("scan_popularity_route", "/scan/popularity"),
                "mood": ("scan_mood", "/scan/mood"),
                "combined": ("scan_combined", "/scan/combined"),
            }
            handler_name, base_path = mapping.get(scan_type, ("scan_navidrome", "/scan/navidrome"))
            mode, effective_restart, resume_artist = _resolve_startup_scan_mode(scan_type, force_enabled, restart)

            params = []
            if scan_type != "metadata":
                params.append(f"mode={mode}")
            if scan_type in {"navidrome", "popularity", "mood", "combined"}:
                params.append("restart=1" if effective_restart else "restart=0")

            request_path = base_path + (("?" + "&".join(params)) if params else "")
            handler = globals().get(handler_name)
            if not callable(handler):
                logging.warning(f"[BOOT] Startup scan launch skipped: handler '{handler_name}' not available")
                return

            if resume_artist:
                log_unified(f"[BOOT] Launch on startup: resuming {scan_type} from {resume_artist}")

            log_unified(
                f"[BOOT] Launch on startup: starting {scan_type} "
                f"({mode}, {'restart' if effective_restart else 'normal'})"
            )
            with app.test_request_context(request_path, method="POST"):
                handler()
        except Exception as exc:
            logging.error(f"[BOOT] Startup scan launch failed: {exc}", exc_info=True)

    threading.Thread(target=_worker, daemon=True, name="startup-scan-launch").start()


def _find_queue_processor_process():
    """Return an active queue_processor process if present, else None."""
    try:
        import psutil  # type: ignore
        for proc in psutil.process_iter(['pid', 'cmdline']):
            try:
                cmdline = proc.info.get('cmdline') or []
                if cmdline and 'queue_processor.py' in ' '.join(cmdline):
                    return proc
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                continue
    except Exception:
        return None
    return None


def _start_queue_processor_if_needed(force_restart: bool = False) -> bool:
    """Start queue_processor.py immediately unless it's already running.

    Returns True when a new process was started.
    """
    managed_externally = str(os.environ.get("SPTNR_QUEUE_PROCESSOR_MANAGED_EXTERNALLY", "0")).strip().lower()
    if managed_externally in {"1", "true", "yes", "on"}:
        logging.info("[QUEUE_PROCESSOR] External queue processor management enabled; skipping app-managed start")
        return False

    existing = _find_queue_processor_process()
    if existing and not force_restart:
        return False

    if existing and force_restart:
        try:
            existing.terminate()
            try:
                existing.wait(timeout=5)
            except Exception:
                existing.kill()
        except Exception as stop_err:
            logging.warning(f"[QUEUE_PROCESSOR] Could not stop existing process before restart: {stop_err}")

    try:
        cfg = get_config() or {}
        features = cfg.get("features", {}) if isinstance(cfg, dict) else {}
        interval = int(features.get("queue_processor_interval_seconds", 30) or 30)
        if interval < 5:
            interval = 5
    except Exception:
        interval = 30

    app_dir = os.path.dirname(os.path.abspath(__file__))
    python_bin = sys.executable or "python"

    subprocess.Popen(
        [python_bin, "queue_processor.py", str(interval)],
        cwd=app_dir,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        start_new_session=True,
    )
    logging.info(f"[QUEUE_PROCESSOR] Started queue_processor.py with interval={interval}s")
    return True

def _auto_resume_interrupted_scans():
    """Resume any scans that were actively running when the server last stopped.

    This runs unconditionally at boot (regardless of the ``launch_on_startup``
    feature flag) but is skipped when ``launch_on_startup`` is enabled because
    ``_schedule_configured_startup_scan_launch`` already handles the resume path
    in that case.  For each supported scan type we check whether a progress file
    exists with ``is_running=True`` and a ``last_updated`` timestamp younger
    than 24 hours.  When such a file is found the scan is restarted in resume
    mode so that it continues from where it left off.
    """
    def _worker():
        try:
            delay_raw = os.environ.get("SPTNR_STARTUP_SCAN_DELAY_SECONDS", "3")
            try:
                startup_delay_seconds = int(delay_raw)
            except Exception:
                startup_delay_seconds = 3
            startup_delay_seconds = max(0, min(startup_delay_seconds, 300))
            time.sleep(startup_delay_seconds)

            # Skip: _schedule_configured_startup_scan_launch handles the resume
            # path when launch_on_startup is enabled, so we avoid a double-start.
            try:
                cfg = get_config() or {}
                features = cfg.get("features", {}) if isinstance(cfg, dict) else {}
                if bool(features.get("launch_on_startup", False)):
                    return
            except Exception:
                pass

            from scan_resume import detect_interrupted_scan

            resumable = [
                ("navidrome", "scan_navidrome", "/scan/navidrome"),
                ("popularity", "scan_popularity_route", "/scan/popularity"),
                ("combined", "scan_combined", "/scan/combined"),
            ]

            for scan_type, handler_name, base_path in resumable:
                try:
                    progress = detect_interrupted_scan(scan_type)
                    if not progress:
                        continue

                    resume_artist = progress.get("current_artist")
                    handler = globals().get(handler_name)
                    if not callable(handler):
                        logging.warning(
                            f"[BOOT_RESUME] Handler '{handler_name}' not found; skipping auto-resume for {scan_type}"
                        )
                        continue

                    params = "mode=resume&restart=0"
                    request_path = base_path + "?" + params
                    log_unified(
                        f"[BOOT_RESUME] Resuming interrupted {scan_type} scan"
                        + (f" from '{resume_artist}'" if resume_artist else "")
                    )
                    with app.test_request_context(request_path, method="POST"):
                        handler()

                    # Only resume one scan at a time to avoid concurrent scans.
                    break
                except Exception as scan_err:
                    logging.warning(f"[BOOT_RESUME] Could not auto-resume {scan_type}: {scan_err}")
        except Exception as exc:
            logging.error(f"[BOOT_RESUME] Auto-resume worker failed: {exc}", exc_info=True)

    threading.Thread(target=_worker, daemon=True, name="boot-scan-resume").start()





# Elect a leader worker to run startup background tasks exactly once.
_is_startup_leader_worker = _acquire_startup_leader_lock()

# Kick off startup background tasks only in the elected leader worker.
if _is_startup_leader_worker:
    try:
        # Always perform a lightweight album-list sync on reboot so newly
        # added album artists appear quickly, even when full boot import is off.
        _start_boot_album_artist_sync_only()
    except Exception as e:
        logging.error(f"Failed to start boot album-list artist sync: {e}")

    try:
        _start_queue_processor_if_needed(force_restart=False)
    except Exception as e:
        logging.error(f"Failed to start queue processor on boot: {e}")

    if AUTO_BOOT_ND_IMPORT:
        try:
            _start_boot_navidrome_import()
        except Exception as e:
            logging.error(f"Failed to start boot Navidrome import: {e}")

    try:
        _start_navidrome_incremental_scheduler()
    except Exception as e:
        logging.error(f"Failed to start Navidrome incremental scheduler: {e}")

    try:
        _schedule_configured_startup_scan_launch()
    except Exception as e:
        logging.error(f"Failed to schedule startup scan launch: {e}")

    try:
        _auto_resume_interrupted_scans()
    except Exception as e:
        logging.error(f"Failed to schedule auto-resume of interrupted scans: {e}")

    try:
        _start_daily_scheduler()
    except Exception as e:
        logging.error(f"Failed to start daily scheduler: {e}")

    try:
        _start_upcoming_release_match_scheduler()
    except Exception as e:
        logging.error(f"Failed to start upcoming release match scheduler: {e}")
else:
    logging.debug("[BOOT] Non-leader worker: startup background schedulers not started in this process")

def _needs_setup(cfg=None):
    cfg = cfg if cfg is not None else _read_yaml(CONFIG_PATH)[0]
    
    # Check for navidrome_users list first
    nav_users = cfg.get("navidrome_users", [])
    if isinstance(nav_users, list) and nav_users:
        # At least one user with all required fields
        first_user = nav_users[0]
        required = [first_user.get("base_url"), first_user.get("user"), first_user.get("pass")]
        return any(not (v and str(v).strip()) for v in required)
    
    # Fall back to single navidrome entry
    nav = cfg.get("navidrome", {}) or {}
    required = [nav.get("base_url"), nav.get("user"), nav.get("pass")]
    return any(not (v and str(v).strip()) for v in required)


def _authenticate_navidrome(username, password):
    """Authenticate against Navidrome API"""
    cfg = get_config()
    
    # Check navidrome_users list first
    nav_users = cfg.get("navidrome_users", [])
    if isinstance(nav_users, list) and nav_users:
        for user_config in nav_users:
            if user_config.get("user") == username:
                base_url = user_config.get("base_url", "")
                nav_user = user_config.get("user", "")
                nav_pass = user_config.get("pass", "")
                
                if password == nav_pass:
                    # Verify against Navidrome API
                    try:
                        import requests
                        import hashlib
                        salt = "sptnr-auth"
                        token = hashlib.md5((password + salt).encode()).hexdigest()
                        auth_url = f"{base_url}/rest/ping?u={nav_user}&t={token}&s={salt}&v=1.16.0&c=popularr"
                        resp = requests.get(auth_url, timeout=2)
                        if resp.status_code == 200 and "ok" in resp.text.lower():
                            return True
                    except:
                        # If API check fails, fall back to password match
                        return True
                return False
    
    # Fall back to single navidrome entry
    nav = cfg.get("navidrome", {})
    if nav.get("user") == username and nav.get("pass") == password:
        try:
            import requests
            import hashlib
            base_url = nav.get("base_url", "")
            salt = "sptnr-auth"
            token = hashlib.md5((password + salt).encode()).hexdigest()
            auth_url = f"{base_url}/rest/ping?u={username}&t={token}&s={salt}&v=1.16.0&c=popularr"
            resp = requests.get(auth_url, timeout=2)
            if resp.status_code == 200 and "ok" in resp.text.lower():
                return True
        except:
            # If API check fails, fall back to password match
            return True
    
    return False


def login_required(f):
    """Decorator to require login for routes"""
    @wraps(f)
    def decorated_function(*args, **kwargs):
        # Check if config exists - if not, allow access (setup mode)
        if not os.path.exists(CONFIG_PATH):
            return f(*args, **kwargs)
        
        cfg = get_config()
        
        # If setup is needed, redirect to setup
        if _needs_setup(cfg):
            return redirect(url_for('setup'))
        
        # Check if user is logged in
        if 'username' not in session:
            return redirect(url_for('login', next=request.url))
        
        return f(*args, **kwargs)
    return decorated_function


