@app.before_request
def enforce_setup_wizard():
    try:
        exempt = {"setup", "static", "config_edit", "config_editor", "login", "logout"}
        # Exempt all API routes from login requirements
        if request.path.startswith("/api/"):
            return
        if not request.endpoint or request.endpoint in exempt or request.endpoint.startswith("static"):
            try:
                exempt = {"setup", "static", "config_edit", "config_editor", "login", "logout"}
                if not request.endpoint or request.endpoint in exempt or request.endpoint.startswith("static"):
                    return

                # If config doesn't exist or is incomplete, redirect to setup wizard
                cfg = get_config()
                from os.path import exists
                if not exists(CONFIG_PATH) or _needs_setup(cfg):
                    if request.endpoint != "setup":
                        return redirect(url_for("setup"))
                    return

                # Only require login if config exists and is valid
                if 'username' not in session:
                    if request.endpoint != "login":
                        return redirect(url_for("login"))
            except Exception as e:
                logging.error(f"Error in enforce_setup_wizard: {e}")
                import traceback
                traceback.print_exc()
                # Don't block the request, let it fail naturally so we can see the real error
                pass
        # If setup is complete and not logged in, redirect to login
        if 'username' not in session:
            if request.endpoint != "login":
                return redirect(url_for("login"))
    except Exception as e:
        logging.error(f"Error in enforce_setup_wizard: {e}")
        import traceback
        traceback.print_exc()
        # Don't block the request, let it fail naturally so we can see the real error
        pass


# Track if schema has been updated this session
_schema_updated = False
_pg_startup_backoff_until = 0.0
_PG_STARTUP_BACKOFF_SECONDS = float(os.environ.get("PG_STARTUP_BACKOFF_SECONDS", "20"))


def get_db():
    """Get a PostgreSQL database connection."""
    global _schema_updated, _pg_startup_backoff_until
    if not _ensure_psycopg2_loaded() or psycopg2 is None:
        raise RuntimeError("psycopg2 not available - install with: pip install psycopg2-binary")

    now = time.monotonic()
    if _pg_startup_backoff_until and now < _pg_startup_backoff_until:
        wait_left = max(1, int(_pg_startup_backoff_until - now))
        raise RuntimeError(f"PostgreSQL startup backoff active; retry in ~{wait_left}s")

    options_parts = []
    idle_timeout_ms = int(os.environ.get("PG_IDLE_IN_TRANSACTION_TIMEOUT_MS", "300000"))
    if idle_timeout_ms > 0:
        options_parts.append(f"-c idle_in_transaction_session_timeout={idle_timeout_ms}")
    options = " ".join(options_parts) or None

    max_attempts = 3
    retry_delays = (0.6, 1.0)
    connect_timeout = int(os.environ.get("PG_CONNECT_TIMEOUT", "5"))

    for attempt in range(max_attempts):
        try:
            conn = psycopg2.connect(  # type: ignore[name-defined]
                host=PG_HOST,
                port=PG_PORT,
                user=PG_USER,
                password=PG_PASSWORD,
                dbname=PG_DATABASE,
                cursor_factory=psycopg2.extras.RealDictCursor,  # type: ignore[name-defined]
                connect_timeout=connect_timeout,
                options=options,
            )
            wrapped = _AutoRollbackPGConnection(conn)
            if has_request_context():
                tracked = getattr(g, '_request_db_connections', None)
                if tracked is None:
                    tracked = []
                    setattr(g, '_request_db_connections', tracked)
                tracked.append(wrapped)
            _pg_startup_backoff_until = 0.0
            return wrapped
        except Exception as e:
            if _is_pg_startup_unavailable_error(e):
                if attempt < (max_attempts - 1):
                    time.sleep(retry_delays[attempt])
                    continue

                _pg_startup_backoff_until = time.monotonic() + _PG_STARTUP_BACKOFF_SECONDS
                raise RuntimeError(
                    "PostgreSQL is temporarily unavailable; temporary DB operations are deferred"
                ) from e
            raise


@app.teardown_request
def _cleanup_request_db_connections(exception=None):
    """Close all request-scoped DB connections (wrapper auto-rollbacks before close)."""
    tracked = getattr(g, '_request_db_connections', None)
    if not tracked:
        return
    while tracked:
        conn = tracked.pop()
        try:
            conn.close()
        except Exception:
            pass


def _is_postgres_connection(conn):
    """Return True — all connections are PostgreSQL."""
    return True


def get_placeholder(conn):
    """
    Get the appropriate SQL placeholder for the active database connection.
    
    Returns:
        str: '%s' for PostgreSQL
    
    Usage:
        placeholder = get_placeholder(conn)
        cursor.execute(f"SELECT * FROM table WHERE id = {placeholder}", (id_val,))
    """
    return "%s"


# Debug: Log database configuration on startup
pg_configured = True  # PostgreSQL is the only supported backend


def _table_exists(cursor, table_name):
    """Check whether a table exists in the current database."""
    cursor.execute(
        """
        SELECT EXISTS (
            SELECT 1 FROM information_schema.tables
            WHERE table_schema = 'public' AND table_name = %s
        )
        """,
        (table_name,)
    )
    row = cursor.fetchone()
    if isinstance(row, dict):
        return bool(row.get('exists'))
    return bool(row[0]) if row else False

def _get_table_columns(cursor, table_name):
    """Return a set of column names for a table in PostgreSQL."""
    cursor.execute(
        """
        SELECT column_name
        FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = %s
        """,
        (table_name,)
    )
    rows = cursor.fetchall() or []
    cols = set()
    for row in rows:
        if hasattr(row, 'keys'):
            cols.add(row.get('column_name'))
        elif row and len(row) > 0:
            cols.add(row[0])
    return {c for c in cols if c}


def _get_postgres_column_types(conn, table_name, column_names):
    """Return a dict of PostgreSQL column_name -> data_type for the requested columns."""
    if not column_names:
        return {}

    cursor = conn.cursor()
    try:
        cursor.execute(
            """
            SELECT column_name, data_type
            FROM information_schema.columns
            WHERE table_schema = 'public'
              AND table_name = %s
              AND column_name = ANY(%s)
            """,
            (table_name, list(column_names)),
        )
        rows = cursor.fetchall() or []
        result = {}
        for row in rows:
            if hasattr(row, 'keys'):
                col = row.get('column_name')
                dtype = row.get('data_type')
            else:
                col = row[0] if len(row) > 0 else None
                dtype = row[1] if len(row) > 1 else None
            if col:
                result[col] = (dtype or '').lower()
        return result
    finally:
        cursor.close()


def _normalize_track_flag_payload(conn, flag_values):
    """
    Coerce track flag values based on DB schema.

    - PostgreSQL BOOLEAN columns receive True/False.
    - INTEGER/BIGINT/TEXT-backed flags receive 0/1.
    """
    if not flag_values:
        return {}

    if not _is_postgres_connection(conn):
        return {k: int(bool(v)) for k, v in flag_values.items()}

    column_types = _get_postgres_column_types(conn, 'tracks', flag_values.keys())
    normalized = {}
    for col, raw_val in flag_values.items():
        bool_val = bool(raw_val)
        if column_types.get(col) == 'boolean':
            normalized[col] = bool_val
        else:
            normalized[col] = int(bool_val)
    return normalized


def _row_get(row, key, index=None, default=None):
    """Read a column from dict-like or indexable DB rows."""
    if row is None:
        return default

    if hasattr(row, 'keys'):
        return row.get(key, default)

    if index is not None:
        try:
            return row[index]
        except (IndexError, KeyError, TypeError):
            return default

    return default


@app.route("/debug/static")
def debug_static():
    """Debug endpoint to check static file configuration"""
    import os
    response = {
        "app_root": app_root,
        "static_folder": static_folder,
        "static_folder_exists": os.path.isdir(static_folder),
        "app_static_folder": app.static_folder,
        "app_static_url_path": app.static_url_path,
    }
    
    if os.path.isdir(static_folder):
        try:
            files = {}
            for root, dirs, filenames in os.walk(static_folder):
                rel_root = os.path.relpath(root, static_folder)
                if rel_root not in files:
                    files[rel_root] = []
                files[rel_root].extend(filenames)
            response["files"] = files
        except Exception as e:
            response["file_error"] = str(e)
    
    return jsonify(response)


