# ---------------------------------------------------------------------------
# Artist Genre Management
# ---------------------------------------------------------------------------

def _parse_genres_string(s):
    """Parse a comma/backslash-separated genres string into a list."""
    if not s:
        return []
    return [g.strip() for g in re.split(r'[,\\]+', s) if g.strip()]


def _parse_json_genres(col):
    """Parse a JSON genre column (list of strings or list of dicts with 'name' key)."""
    if not col:
        return []
    try:
        data = json.loads(col) if isinstance(col, str) else col
        if not isinstance(data, list):
            return []
        result = []
        for item in data:
            if isinstance(item, str):
                result.append(item.strip())
            elif isinstance(item, dict):
                name = item.get("name") or item.get("tag") or ""
                if name:
                    result.append(str(name).strip())
        return [g for g in result if g]
    except Exception:
        return []


@app.route("/artist/<path:name>/genre-management")
def artist_genre_management(name):
    """Genre management page — view and edit genres at artist/album/track level."""
    from urllib.parse import unquote

    artist_name = unquote(name)
    conn = get_db()
    cursor = conn.cursor()
    placeholder = "%s"

    try:
        cursor.execute(
            f"""
            SELECT
                id,
                album,
                title,
                track_number,
                disc_number,
                file_path,
                COALESCE(artist, '') AS artist,
                COALESCE(NULLIF(album_artist, ''), artist) AS album_artist,
                COALESCE(genres, '') AS genres,
                COALESCE(discogs_genres, '') AS discogs_genres,
                COALESCE(lastfm_tags, '') AS lastfm_tags,
                COALESCE(musicbrainz_genres, '') AS musicbrainz_genres
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
            ORDER BY album, disc_number, track_number, title
            """,
            (artist_name,),
        )
        rows = [dict(r) if hasattr(r, "keys") else {
            "id": r[0], "album": r[1], "title": r[2], "track_number": r[3],
            "disc_number": r[4], "file_path": r[5], "artist": r[6],
            "album_artist": r[7], "genres": r[8], "discogs_genres": r[9],
            "lastfm_tags": r[10], "musicbrainz_genres": r[11],
        } for r in cursor.fetchall()]
    finally:
        conn.close()

    # Build per-track dicts
    all_artist_current = set()
    all_artist_recommended_raw = set()

    albums_map = {}  # album -> {"tracks": [], "all_current": set(), "all_rec_raw": set()}
    for row in rows:
        album = row.get("album") or ""
        current = _parse_genres_string(row.get("genres", ""))
        current_set = set(g.lower() for g in current)

        rec_raw = (
            _parse_json_genres(row.get("discogs_genres"))
            + _parse_json_genres(row.get("lastfm_tags"))
            + _parse_json_genres(row.get("musicbrainz_genres"))
        )
        recommended = [g for g in dict.fromkeys(rec_raw) if g.lower() not in current_set]

        track_dict = {
            "id": row.get("id"),
            "title": row.get("title") or "",
            "album": album,
            "track_number": row.get("track_number"),
            "disc_number": row.get("disc_number"),
            "file_path": row.get("file_path") or "",
            "artist": row.get("artist") or "",
            "current_genres": current,
            "recommended_genres": recommended,
        }

        if album not in albums_map:
            albums_map[album] = {"tracks": [], "all_current": set(), "all_rec_raw": set()}
        albums_map[album]["tracks"].append(track_dict)
        albums_map[album]["all_current"].update(current)
        albums_map[album]["all_rec_raw"].update(rec_raw)

        all_artist_current.update(current)
        all_artist_recommended_raw.update(rec_raw)

    # Build album-level dicts
    albums = []
    for album_name, data in albums_map.items():
        alb_current_set_lower = set(g.lower() for g in data["all_current"])
        alb_recommended = [
            g for g in dict.fromkeys(data["all_rec_raw"])
            if g.lower() not in alb_current_set_lower
        ]
        albums.append({
            "album": album_name,
            "current_genres": sorted(data["all_current"]),
            "recommended_genres": alb_recommended,
            "tracks": data["tracks"],
        })

    artist_current_lower = set(g.lower() for g in all_artist_current)
    artist_recommended_genres = [
        g for g in dict.fromkeys(all_artist_recommended_raw)
        if g.lower() not in artist_current_lower
    ]

    return render_template(
        "artist_genre_management.html",
        artist_name=artist_name,
        albums=albums,
        artist_current_genres=sorted(all_artist_current),
        artist_recommended_genres=artist_recommended_genres,
    )


@app.route("/api/artist/genre-management/save", methods=["POST"])
def api_artist_genre_management_save():
    """Apply genre add/remove changes at artist, album, or track scope."""
    try:
        payload = request.get_json(silent=True) or {}
        artist_name = str(payload.get("artist") or "").strip()
        changes = payload.get("changes") or []

        if not artist_name:
            return jsonify({"success": False, "error": "artist is required"}), 400

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        updated = 0
        failed = 0

        try:
            for change in changes:
                scope = str(change.get("scope") or "").strip()
                add_genres = [str(g).strip() for g in (change.get("add") or []) if g]
                remove_genres_lower = set(str(g).strip().lower() for g in (change.get("remove") or []) if g)

                if not scope or (not add_genres and not remove_genres_lower):
                    continue

                # Determine which tracks to update
                if scope == "artist":
                    cursor.execute(
                        f"SELECT id, genres, file_path FROM tracks"
                        f" WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}",
                        (artist_name,),
                    )
                elif scope == "album":
                    album = str(change.get("album") or "").strip()
                    if not album:
                        continue
                    cursor.execute(
                        f"SELECT id, genres, file_path FROM tracks"
                        f" WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}"
                        f" AND album = {placeholder}",
                        (artist_name, album),
                    )
                elif scope == "track":
                    track_id = change.get("track_id")
                    if track_id is None:
                        continue
                    cursor.execute(
                        f"SELECT id, genres, file_path FROM tracks WHERE id = {placeholder}",
                        (int(track_id),),
                    )
                else:
                    continue

                track_rows = [
                    dict(r) if hasattr(r, "keys") else {"id": r[0], "genres": r[1], "file_path": r[2]}
                    for r in cursor.fetchall()
                ]

                for tr in track_rows:
                    tid = tr.get("id")
                    current = _parse_genres_string(tr.get("genres") or "")
                    current_lower_map = {g.lower(): g for g in current}

                    # Remove
                    new_set = {k: v for k, v in current_lower_map.items() if k not in remove_genres_lower}

                    # Add (avoid duplicates)
                    for g in add_genres:
                        if g.lower() not in new_set:
                            new_set[g.lower()] = g

                    new_genres = list(new_set.values())
                    new_genres_str = ", ".join(new_genres)

                    try:
                        cursor.execute(
                            f"UPDATE tracks SET genres = {placeholder} WHERE id = {placeholder}",
                            (new_genres_str, tid),
                        )
                        conn.commit()

                        fp = tr.get("file_path") or ""
                        if fp and os.path.isfile(fp):
                            ok, err = update_audio_file_genres(fp, new_genres)
                            if not ok:
                                logging.warning(f"[GENRE_SAVE] File tag update failed for {fp}: {err}")
                        updated += 1
                    except Exception as track_err:
                        logging.error(f"[GENRE_SAVE] Failed updating track {tid}: {track_err}")
                        failed += 1

        finally:
            conn.close()

        return jsonify({"success": True, "updated": updated, "failed": failed})

    except Exception as e:
        logging.error(f"[GENRE_SAVE] Error: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/track/match-missing", methods=["POST"])
def api_track_match_missing():
    """Match a MusicBrainz 'missing' track to an existing track in the database.

    Syncs the MB title (and optionally track number and release ID) to the chosen
    existing track, then updates the MP3 file tags if the file exists.
    """
    try:
        data = request.get_json(silent=True) or {}
        track_id = str(data.get("track_id") or "").strip()
        mb_title = (data.get("mb_title") or "").strip()
        mb_track_number = data.get("mb_track_number")
        mb_release_id = (data.get("mb_release_id") or "").strip()

        if not track_id or not mb_title:
            return jsonify({"success": False, "error": "track_id and mb_title are required"}), 400

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        cursor.execute(f"""
            SELECT id, file_path, title, track_number, album, artist, album_artist
            FROM tracks WHERE CAST(id AS TEXT) = {placeholder} LIMIT 1
        """, (track_id,))
        row = cursor.fetchone()
        if not row:
            conn.close()
            return jsonify({"success": False, "error": "Track not found"}), 404

        track = dict(row) if hasattr(row, "keys") else {
            "id": row[0], "file_path": row[1], "title": row[2], "track_number": row[3],
            "album": row[4], "artist": row[5], "album_artist": row[6],
        }

        update_parts = [f"title = {placeholder}"]
        params = [mb_title]
        if mb_track_number is not None:
            update_parts.append(f"track_number = {placeholder}")
            params.append(mb_track_number)
        if mb_release_id:
            # Update musicbrainz_album_mbid if column exists
            try:
                conn2 = get_db()
                c2 = conn2.cursor()
                c2.execute(f"SELECT musicbrainz_album_mbid FROM tracks LIMIT 1")
                conn2.close()
                update_parts.append(f"musicbrainz_album_mbid = {placeholder}")
                params.append(mb_release_id)
            except Exception:
                pass
        params.append(track_id)
        cursor.execute(f"UPDATE tracks SET {', '.join(update_parts)} WHERE CAST(id AS TEXT) = {placeholder}", params)
        conn.commit()
        conn.close()

        # Update MP3 file tags
        updated_file = False
        file_path = track.get("file_path")
        if file_path and os.path.exists(str(file_path)):
            try:
                from helpers.tag_manager import write_tags_to_file
                tag_updates = {"title": mb_title}
                if mb_track_number is not None:
                    tag_updates["tracknumber"] = str(mb_track_number)
                updated_file = write_tags_to_file(str(file_path), tag_updates)
            except Exception as tag_err:
                logging.warning(f"[MATCH_MISSING] Could not update tags for {file_path}: {tag_err}")

        logging.info(
            f"[MATCH_MISSING] Track {track_id} '{track.get('title')}' → '{mb_title}' "
            f"(file_updated={updated_file})"
        )
        return jsonify({
            "success": True,
            "updated_track_id": track_id,
            "old_title": track.get("title"),
            "new_title": mb_title,
            "updated_file": updated_file,
        })
    except Exception as e:
        logging.error(f"[MATCH_MISSING] Error: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/search")
def search():
    """Search page for artists, albums, and tracks"""
    query = request.args.get("q", "").strip()
    return render_template("search.html", initial_query=query)


@app.route("/api/search", methods=["POST"])
def api_search():
    """API endpoint to search the library for artists, albums, and tracks"""
    try:
        data = request.get_json()
        query = data.get("query", "").strip().lower()
        
        if not query or len(query) < 2:
            return jsonify({"error": "Search query must be at least 2 characters"}), 400
        
        conn = get_db()
        cursor = conn.cursor()
        collate_nocase = ""
        placeholder = "%s"
        
        # Prepare search patterns: exact, starts-with, contains
        exact_pattern = query
        starts_pattern = f"{query}%"
        contains_pattern = f"%{query}%"
        
        # Search artists - ranked by: exact match > starts-with > contains, then by track count
        cursor.execute(f"""
            SELECT 
                artist as name,
                COUNT(DISTINCT album) as album_count,
                COUNT(*) as track_count,
                CASE
                    WHEN LOWER(artist) = {placeholder} THEN 0
                    WHEN LOWER(artist) LIKE {placeholder} THEN 1
                    ELSE 2
                END as match_rank
            FROM tracks
            WHERE LOWER(artist) LIKE {placeholder}
            GROUP BY artist
            ORDER BY match_rank ASC, track_count DESC
            LIMIT 20
        """, (exact_pattern, starts_pattern, contains_pattern))
        artists_results = [
            {
                "name": row["name"],
                "album_count": row["album_count"],
                "track_count": row["track_count"]
            }
            for row in cursor.fetchall()
        ]
        
        # Search albums - ranked by: exact match > starts-with > contains, then by track count
        cursor.execute(f"""
            SELECT 
                artist,
                album,
                COUNT(*) as track_count,
                AVG(stars) as avg_stars,
                CASE
                    WHEN LOWER(album) = {placeholder} THEN 0
                    WHEN LOWER(album) LIKE {placeholder} THEN 1
                    ELSE 2
                END as match_rank
            FROM tracks
            WHERE LOWER(album) LIKE {placeholder}
            GROUP BY artist, album
            ORDER BY match_rank ASC, track_count DESC
            LIMIT 20
        """, (exact_pattern, starts_pattern, contains_pattern))
        albums_results = [
            {
                "artist": row["artist"],
                "album": row["album"],
                "track_count": row["track_count"],
                "avg_stars": row["avg_stars"]
            }
            for row in cursor.fetchall()
        ]
        
        # Search tracks - ranked by: exact title match > starts-with > contains, then by stars
        cursor.execute(f"""
            SELECT 
                id,
                title,
                artist,
                album,
                stars,
                CASE
                    WHEN LOWER(title) = {placeholder} THEN 0
                    WHEN LOWER(title) LIKE {placeholder} THEN 1
                    WHEN LOWER(title) LIKE {placeholder} THEN 2
                    ELSE 3
                END as match_rank
            FROM tracks
            WHERE LOWER(title) LIKE {placeholder} OR LOWER(artist) LIKE {placeholder}
            ORDER BY match_rank ASC, stars DESC, title{collate_nocase}
            LIMIT 50
        """, (exact_pattern, starts_pattern, contains_pattern, contains_pattern, contains_pattern))
        tracks_results = [
            {
                "id": row["id"],
                "title": row["title"],
                "artist": row["artist"],
                "album": row["album"],
                "stars": row["stars"]
            }
            for row in cursor.fetchall()
        ]
        
        conn.close()
        
        return jsonify({
            "artists": artists_results,
            "albums": albums_results,
            "tracks": tracks_results
        })
    
    except Exception as e:
        logging.error(f"Search error: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/artist/<path:name>")
def artist_detail(name):
    """View artist details and albums"""
    try:
        # URL decode the artist name
        from urllib.parse import unquote
        name = unquote(name)
        
        conn = get_db()
        cursor = conn.cursor()
        # Get albums for this artist with type information
        # Query by COALESCE(album_artist, artist) to handle cases where album_artist is empty
        # Use NULLIF to treat empty strings as NULL for proper COALESCE behavior
        cursor.execute("""
            SELECT 
                album,
                COUNT(*) as track_count,
                AVG(stars) as avg_stars,
                COALESCE(SUM(CASE WHEN is_single THEN 1 ELSE 0 END), 0) as singles_count,
                MAX(last_scanned) as last_updated,
                MIN(year) as album_year,
                MAX(spotify_album_type) as album_type,
                MAX(COALESCE(NULLIF(album_artist, ''), artist)) as album_artist,
                MAX(musicbrainz_album_mbid) as musicbrainz_album_mbid,
                MAX(discogs_release_id) as discogs_release_id
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = %s
            GROUP BY album
            ORDER BY (MIN(year) IS NULL), MIN(year) DESC NULLS LAST, album
        """, (name,))
        albums_data = cursor.fetchall()
        
        # Get artist stats with additional metrics
        # Query by COALESCE(album_artist, artist) to handle cases where album_artist is empty
        # Use NULLIF to treat empty strings as NULL for proper COALESCE behavior
        cursor.execute(f"""
            SELECT 
                COUNT(*) as track_count,
                COUNT(DISTINCT album) as album_count,
                AVG(stars) as avg_stars,
                SUM(CASE WHEN stars = 5 THEN 1 ELSE 0 END) as five_star_count,
                SUM(COALESCE(duration, 0)) as total_duration,
                MIN(year) as earliest_year,
                MAX(year) as latest_year,
                MAX(musicbrainz_artist_id) as musicbrainz_artist_id,
                MAX(spotify_artist_id) as spotify_artist_id,
                MAX(lastfm_artist_mbid) as lastfm_artist_mbid,
                MAX(discogs_artist_id) as discogs_artist_id,
                MAX(discogs_release_id) as discogs_release_id
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = %s
        """, (name,))
        artist_stats = cursor.fetchone()
        
        # If artist ID not found in tracks, try to get it from album MusicBrainz IDs as fallback
        if artist_stats and not dict(artist_stats).get('musicbrainz_artist_id'):
            try:
                # Look for any album with a MusicBrainz release ID
                cursor.execute("""
                    SELECT DISTINCT musicbrainz_album_mbid 
                    FROM tracks 
                    WHERE COALESCE(NULLIF(album_artist, ''), artist) = %s 
                    AND musicbrainz_album_mbid IS NOT NULL AND musicbrainz_album_mbid != ''
                    LIMIT 1
                """, (name,))
                album_mbid_row = cursor.fetchone()
                
                if album_mbid_row:
                    album_mbid = album_mbid_row['musicbrainz_album_mbid']
                    
                    # Fetch the artist ID from this album's MusicBrainz release
                    try:
                        import requests
                        headers = {"User-Agent": MUSICBRAINZ_USER_AGENT}
                        release_url = f"https://musicbrainz.org/ws/2/release/{album_mbid}"
                        params = {"fmt": "json", "inc": "artist-credits"}
                        resp = requests.get(release_url, params=params, headers=headers, timeout=5)
                        
                        if resp.status_code == 200:
                            release_data = resp.json()
                            artist_credits = release_data.get("artist-credit", [])
                            if artist_credits:
                                # Get the first artist credit
                                first_artist = artist_credits[0]
                                if isinstance(first_artist, dict):
                                    artist_id = first_artist.get("artist", {}).get("id")
                                    if artist_id:
                                        logging.info(f"Found artist ID {artist_id} for {name} via album {album_mbid}")
                                        # Update stats dict with the found artist ID
                                        artist_stats = dict(artist_stats) if artist_stats else {}
                                        artist_stats['musicbrainz_artist_id'] = artist_id
                                        
                                        # Save to database so it persists
                                        try:
                                            cursor.execute("""
                                                UPDATE tracks
                                                SET musicbrainz_artist_id = %s, lastfm_artist_mbid = %s
                                                WHERE COALESCE(NULLIF(album_artist, ''), artist) = %s
                                                AND (musicbrainz_artist_id IS NULL OR musicbrainz_artist_id = '')
                                            """, (artist_id, artist_id, name))
                                            conn.commit()
                                            logging.debug(f"Saved artist ID {artist_id} to {name} tracks")
                                        except Exception as e:
                                            logging.debug(f"Failed to save artist ID to database: {e}")
                    except Exception as e:
                        logging.debug(f"Failed to get artist ID from album MBID: {e}")
            except Exception as e:
                logging.debug(f"Fallback artist ID lookup failed: {e}")
        
        # Get missing releases from database cache
        cursor.execute("""
            SELECT release_id, title, primary_type, first_release_date, cover_art_url, category
            FROM missing_releases
            WHERE artist = %s
            ORDER BY first_release_date DESC
        """, (name,))
        missing_releases_data = cursor.fetchall()

        # Top tracks by z-score (fallback to popularity ordering if z-score column is unavailable)
        try:
            cursor.execute("""
                SELECT
                    id,
                    title,
                    album,
                    COALESCE(popularity_score, 0) as popularity_score,
                    COALESCE(stars, 0) as stars,
                    COALESCE(artist_z_score, 0) as artist_z_score,
                    CASE WHEN is_single THEN 1 ELSE 0 END as is_single,
                    COALESCE(track_number, 0) as track_number,
                    COALESCE(disc_number, 1) as disc_number,
                    COALESCE(duration, 0) as duration
                FROM tracks
                WHERE COALESCE(NULLIF(album_artist, ''), artist) = %s
                ORDER BY COALESCE(artist_z_score, 0) DESC, COALESCE(popularity_score, 0) DESC
                LIMIT 10
            """, (name,))
            top_tracks = cursor.fetchall()
        except Exception:
            cursor.execute("""
                SELECT
                    id,
                    title,
                    album,
                    COALESCE(popularity_score, 0) as popularity_score,
                    COALESCE(stars, 0) as stars,
                    0 as artist_z_score,
                    CASE WHEN is_single THEN 1 ELSE 0 END as is_single,
                    COALESCE(track_number, 0) as track_number,
                    COALESCE(disc_number, 1) as disc_number,
                    COALESCE(duration, 0) as duration
                FROM tracks
                WHERE COALESCE(NULLIF(album_artist, ''), artist) = %s
                ORDER BY COALESCE(popularity_score, 0) DESC, COALESCE(stars, 0) DESC
                LIMIT 10
            """, (name,))
            top_tracks = cursor.fetchall()
        
        # Deduplicate top tracks by title (keep first occurrence)
        if top_tracks:
            seen_titles = set()
            deduped_tracks = []
            for track in top_tracks:
                # Normalize row/dict/tuple access for title
                if hasattr(track, 'keys') and not isinstance(track, dict):
                    track_title = dict(track).get('title', '')
                elif isinstance(track, dict):
                    track_title = track.get('title', '')
                else:
                    track_title = track[1] if len(track) > 1 else ''

                title = str(track_title or '')
                title_lower = title.lower().strip()
                if title_lower not in seen_titles:
                    seen_titles.add(title_lower)
                    deduped_tracks.append(track)
            top_tracks = deduped_tracks

        # Albums where this artist appears as a featured/track artist but is not the album artist
        cursor.execute("""
            SELECT
                album,
                COALESCE(NULLIF(album_artist, ''), artist) as album_artist,
                COUNT(*) as track_count,
                AVG(COALESCE(stars, 0)) as avg_stars,
                MIN(year) as album_year,
                MAX(spotify_album_type) as album_type,
                MAX(last_scanned) as last_updated
            FROM tracks
            WHERE artist = %s
              AND COALESCE(NULLIF(album_artist, ''), artist) != %s
              AND NULLIF(album, '') IS NOT NULL
            GROUP BY album, COALESCE(NULLIF(album_artist, ''), artist)
            ORDER BY (MIN(year) IS NULL), MIN(year) DESC NULLS LAST, album
        """, (name, name))
        appears_on_albums = cursor.fetchall()
        
        # Get potential compilation albums using cached compilation detection from background scan
        # Combined with fallback local heuristics in case scan hasn't run yet
        # IMPORTANT: Filter by album artist identity (not track artist) so featured appearances
        # are handled separately under "Appears On".
        cursor.execute("""
            SELECT 
                album,
                COUNT(*) as track_count,
                AVG(stars) as avg_stars,
                COALESCE(SUM(CASE WHEN is_single THEN 1 ELSE 0 END), 0) as singles_count,
                MAX(last_scanned) as last_updated,
                MIN(year) as album_year,
                MAX(spotify_album_type) as album_type,
                MAX(COALESCE(NULLIF(album_artist, ''), artist)) as album_artist,
                MAX(is_compilation) as is_compilation
            FROM tracks
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = %s
              AND NULLIF(album, '') IS NOT NULL
            GROUP BY album
            ORDER BY (MIN(year) IS NULL), MIN(year) DESC NULLS LAST, album
        """, (name,))
        potential_albums = cursor.fetchall()
        
        # Filter to only include albums that are actually compilations
        # Use cached is_compilation field from background scan, with fallback to local heuristics
        compilation_albums = []
        
        for album_row in potential_albums:
            album_dict = album_row.copy() if isinstance(album_row, dict) else dict(album_row)
            album_artist = album_dict.get('album_artist', '')
            spotify_type = album_dict.get('album_type', '')
            is_compilation_cached = album_dict.get('is_compilation')
            
            # Primary method: use cached compilation detection from background scan
            if is_compilation_cached:
                compilation_albums.append(album_dict)
            # Fallback to local heuristics in case scan hasn't run yet
            elif album_artist and album_artist.lower() in ('various artists', 'various', 'compilation', 'soundtrack'):
                compilation_albums.append(album_dict)
            elif spotify_type and spotify_type.lower() == 'compilation':
                # Also check Spotify's designation as backup
                compilation_albums.append(album_dict)
        
        # Define placeholder here to ensure it's available for all subsequent queries
        placeholder = "%s"
        
        # Get artist metadata (country, image, bio) from artists table if it exists
        artist_country = None
        artist_image_url = None
        artist_bio = None
        try:
            cursor.execute(f"SELECT country, image_url, bio FROM artists WHERE name = {placeholder}", (name,))
            artist_row = cursor.fetchone()
            if artist_row:
                artist_country = artist_row['country'] if artist_row['country'] else None
                artist_image_url = artist_row['image_url'] if artist_row['image_url'] else None
                artist_bio = artist_row['bio'] if artist_row['bio'] else None
        except Exception as e:
            logging.debug(f"Error fetching artist metadata: {e}")
        
        # Fetch genre source data for all tracks to pre-render on the artist page.
        # Genres are populated from external sources (Spotify, Last.fm, etc.) only during
        # the popularity/singles scan and saved to the database. On page open we read
        # them directly from the DB so no AJAX call to external sources is needed.
        tracks_genre_data = []
        try:
            cursor.execute(f"""
                SELECT spotify_genres, lastfm_tags, listenbrainz_genres, discogs_genres, musicbrainz_genres
                FROM tracks WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
            """, (name,))
            tracks_genre_data = [dict(row) for row in cursor.fetchall()]
        except Exception as e:
            logging.debug(f"Error fetching genre data for artist page: {e}")

        artist_members = []
        try:
            from api_clients.musicbrainz import MusicBrainzClient

            mb_client = MusicBrainzClient()
            artist_mbid = None
            if isinstance(artist_stats, dict):
                artist_mbid = artist_stats.get('musicbrainz_artist_id') or artist_stats.get('lastfm_artist_mbid')
            elif artist_stats:
                artist_mbid = dict(artist_stats).get('musicbrainz_artist_id') or dict(artist_stats).get('lastfm_artist_mbid')

            artist_members = mb_client.get_artist_members(artist=name, artist_mbid=artist_mbid)
        except Exception as e:
            logging.debug(f"Error fetching band members for artist page: {e}")

        # Convert all Row objects to dicts while connection is still open.
        # This is critical because Row objects become invalid after connection closes
        albums_data_dicts = [dict(album) for album in albums_data]
        missing_releases_dicts = [dict(release) for release in missing_releases_data]
        appears_on_dicts = [dict(album) for album in appears_on_albums]
        top_tracks_dicts = [dict(track) for track in top_tracks]
        potential_albums_dicts = [dict(album) for album in potential_albums]

        album_download_counts = {}
        try:
            cursor.execute(f"""
                SELECT LOWER(COALESCE(album, '')) AS album_key,
                       COUNT(*) AS downloading_count
                FROM download_queue
                WHERE LOWER(COALESCE(artist, '')) = LOWER({placeholder})
                  AND status IN ('queued', 'searching', 'downloading')
                GROUP BY LOWER(COALESCE(album, ''))
            """, (name,))
            for row in cursor.fetchall():
                row_dict = dict(row)
                album_download_counts[row_dict.get('album_key', '')] = int(row_dict.get('downloading_count', 0) or 0)
        except Exception as e:
            logging.debug(f"Could not preload album download status for {name}: {e}")
        
        # Convert Row to dict for template access with defaults
        if artist_stats:
            artist_stats = dict(artist_stats)
        else:
            # Provide default values if no stats found (artist has no tracks)
            artist_stats = {
                'track_count': 0,
                'album_count': 0,
                'avg_stars': None,
                'five_star_count': 0,
                'total_duration': 0,
                'earliest_year': None,
                'latest_year': None,
                'musicbrainz_artist_id': None,
                'spotify_artist_id': None,
                'lastfm_artist_mbid': None,
                'discogs_artist_id': None,
                'discogs_release_id': None
            }
        
        # Categorize discovered albums by type
        albums_by_category = {
            "album": [],
            "live_album": [],
            "remix_album": [],
            "ep": [],
            "single": [],
            "compilation": [],
            "unknown": []
        }
        
        # Track which albums we've already categorized to avoid duplicates
        categorized_albums = set()
        
        for album in albums_data_dicts:
            album_dict = album.copy()
            album_dict['is_missing'] = False  # Mark as discovered
            album_name = album_dict.get("album", "")
            
            album_key = str(album_name or '').lower()
            total_downloading = int(album_download_counts.get(album_key, 0) or 0)
            album_dict['is_downloading'] = total_downloading > 0
            album_dict['downloading_count'] = total_downloading
            
            album_type = (album_dict.get("album_type") or "").lower()
            track_count = album_dict.get("track_count", 0)
            album_artist = (album_dict.get("album_artist") or "").lower()
            album_name_lower = (album_name or "").lower()
            is_compilation_cached = bool(album_dict.get("is_compilation"))
            
            # First check compilation markers so they never fall through into Albums.
            if (
                is_compilation_cached
                or (album_artist and album_artist in ('various artists', 'various', 'compilation', 'soundtrack'))
                or (album_type and 'compilation' in album_type)
            ):
                albums_by_category["compilation"].append(album_dict)
                categorized_albums.add(album_name)
            # Categorize based on spotify_album_type and track count
            elif album_type and 'live' in album_type:
                albums_by_category["live_album"].append(album_dict)
                categorized_albums.add(album_name)
            elif album_type and 'remix' in album_type and 'live' not in album_type and 'compilation' not in album_type:
                albums_by_category["remix_album"].append(album_dict)
                categorized_albums.add(album_name)
            elif album_name and ('live' in album_name_lower or 'unplugged' in album_name_lower):
                albums_by_category["live_album"].append(album_dict)
                categorized_albums.add(album_name)
            elif album_name and ('remix' in album_name_lower):
                albums_by_category["remix_album"].append(album_dict)
                categorized_albums.add(album_name)
            elif album_type == "album" or (not album_type and track_count > 6):
                albums_by_category["album"].append(album_dict)
                categorized_albums.add(album_name)
            elif album_type == "ep" or (not album_type and 3 <= track_count <= 6):
                albums_by_category["ep"].append(album_dict)
                categorized_albums.add(album_name)
            elif album_type == "single" or (not album_type and track_count < 3):
                albums_by_category["single"].append(album_dict)
                categorized_albums.add(album_name)
            else:
                albums_by_category["unknown"].append(album_dict)
                categorized_albums.add(album_name)
        
        # SAFETY: Remove live albums from non-live categories to prevent duplicates
        live_album_names = {
            _normalize_release_title(a.get('album', ''))
            for a in albums_by_category.get("live_album", [])
            if a.get('album')
        }
        for cat in ["album", "ep", "single", "unknown"]:
            if live_album_names:
                albums_by_category[cat] = [
                    a for a in albums_by_category[cat]
                    if _normalize_release_title(a.get('album', '')) not in live_album_names
                ]

        # SAFETY: Remove remix albums from non-remix categories to prevent duplicates
        remix_album_names = {
            _normalize_release_title(a.get('album', ''))
            for a in albums_by_category.get("remix_album", [])
            if a.get('album')
        }
        for cat in ["album", "ep", "single", "unknown"]:
            if remix_album_names:
                albums_by_category[cat] = [
                    a for a in albums_by_category[cat]
                    if _normalize_release_title(a.get('album', '')) not in remix_album_names
                ]

        # SAFETY: Remove compilation albums from non-compilation categories to prevent duplicates
        compilation_album_names = {
            _normalize_release_title(a.get('album', ''))
            for a in albums_by_category.get("compilation", [])
            if a.get('album')
        }
        for cat in ["album", "live_album", "remix_album", "ep", "single", "unknown"]:
            if compilation_album_names:
                albums_by_category[cat] = [
                    a for a in albums_by_category[cat]
                    if _normalize_release_title(a.get('album', '')) not in compilation_album_names
                ]

        # Process compilation albums
        for album in compilation_albums:
            album_dict = dict(album)
            album_name = album_dict.get("album", "")
            
            # Skip if already categorized
            if album_name in categorized_albums:
                continue
            
            album_dict['is_missing'] = False
            album_dict['is_compilation'] = True
            albums_by_category["compilation"].append(album_dict)
        
        # Categorize missing releases
        missing_by_category = {
            "album": [],
            "live_album": [],
            "remix_album": [],
            "ep": [],
            "single": [],
            "compilation": []
        }
        
        for release in missing_releases_dicts:
            release_dict = release.copy()
            release_dict['is_missing'] = True  # Mark as missing
            primary_type = (release_dict.get("primary_type") or "").lower()
            category = (release_dict.get("category") or "").lower()
            title_lower = (release_dict.get("title") or "").lower()

            is_compilation_by_title = (
                "greatest hits" in title_lower
                or "best of" in title_lower
                or "anthology" in title_lower
                or "collection" in title_lower
            )

            # Category from scan is authoritative when present; fallback to type/title heuristics.
            release_bucket = _derive_release_bucket(primary_type=primary_type, category=category, title=title_lower)
            if release_bucket == "album" and is_compilation_by_title:
                release_bucket = "compilation"

            if release_bucket in ("album", "live_album", "remix_album", "ep", "single", "compilation"):
                missing_by_category[release_bucket].append(release_dict)
        
        # SAFETY: Remove live albums from missing releases in wrong categories
        missing_live_names = {
            _normalize_release_title(a.get('title', ''))
            for a in missing_by_category.get("live_album", [])
            if a.get('title')
        }
        for cat in ["album", "ep", "single"]:
            if missing_live_names:
                missing_by_category[cat] = [
                    a for a in missing_by_category[cat]
                    if _normalize_release_title(a.get('title', '')) not in missing_live_names
                ]

        # SAFETY: Remove remix albums from missing releases in wrong categories
        missing_remix_names = {
            _normalize_release_title(a.get('title', ''))
            for a in missing_by_category.get("remix_album", [])
            if a.get('title')
        }
        for cat in ["album", "ep", "single"]:
            if missing_remix_names:
                missing_by_category[cat] = [
                    a for a in missing_by_category[cat]
                    if _normalize_release_title(a.get('title', '')) not in missing_remix_names
                ]

        # SAFETY: Remove compilation albums from missing releases in wrong categories
        missing_compilation_names = {
            _normalize_release_title(a.get('title', ''))
            for a in missing_by_category.get("compilation", [])
            if a.get('title')
        }
        for cat in ["album", "ep", "single"]:
            if missing_compilation_names:
                missing_by_category[cat] = [
                    a for a in missing_by_category[cat]
                    if _normalize_release_title(a.get('title', '')) not in missing_compilation_names
                ]

        # Merge discovered and missing albums by category, then sort by release date
        merged_albums_by_category = {}
        for category in ["album", "compilation", "live_album", "remix_album", "ep", "single", "unknown"]:
            merged_list = albums_by_category.get(category, []) + missing_by_category.get(category, [])
            
            # Sort by release date (newest first)
            # For discovered albums, use album_year; for missing, use first_release_date
            def get_sort_key(item):
                if item.get('is_missing'):
                    # Missing album - extract year from first_release_date (format: YYYY-MM-DD or YYYY)
                    date_str = item.get('first_release_date', '')
                    if date_str:
                        year = date_str[:4] if len(date_str) >= 4 else ''
                        try:
                            # Ensure year is a string before checking if it's a digit
                            return int(year) if (isinstance(year, str) and year.isdigit()) else 0
                        except (ValueError, AttributeError, TypeError):
                            return 0
                    return 0
                else:
                    # Discovered album - use album_year
                    return item.get('album_year') or 0
            
            merged_list.sort(key=get_sort_key, reverse=True)
            merged_albums_by_category[category] = merged_list
        
        # Aggregate genres from all tracks by this artist
        genres = aggregate_genres_from_tracks(name, DB_PATH)
        
        # Compute genre sources for server-side rendering (from DB data populated during scans)
        genre_sources = {}
        try:
            genre_sources = get_artist_genres_summary(tracks_genre_data, limit=30)
        except Exception as e:
            logging.debug(f"Error computing genre sources for artist page: {e}")

        # Preload similar artists from DB; page should not re-fetch on open.
        similar_artists_data = {
            "lastfm": [],
            "listenbrainz": []
        }
        try:
            cursor.execute(f"""
                SELECT similar_artists_lastfm, similar_artists_listenbrainz
                FROM artists
                WHERE name = {placeholder}
                LIMIT 1
            """, (name,))

            similar_row = cursor.fetchone()
            if similar_row:
                similar_lastfm_raw = similar_row.get("similar_artists_lastfm") if isinstance(similar_row, dict) else similar_row[0]
                similar_listenbrainz_raw = similar_row.get("similar_artists_listenbrainz") if isinstance(similar_row, dict) else similar_row[1]

                similar_lastfm = []
                similar_listenbrainz = []

                try:
                    if similar_lastfm_raw:
                        parsed_lastfm = json.loads(similar_lastfm_raw) if isinstance(similar_lastfm_raw, str) else similar_lastfm_raw
                        if isinstance(parsed_lastfm, list):
                            similar_lastfm = parsed_lastfm[:10]
                except Exception:
                    pass

                try:
                    if similar_listenbrainz_raw:
                        parsed_listenbrainz = json.loads(similar_listenbrainz_raw) if isinstance(similar_listenbrainz_raw, str) else similar_listenbrainz_raw
                        if isinstance(parsed_listenbrainz, list):
                            similar_listenbrainz = parsed_listenbrainz[:10]
                except Exception:
                    pass

                # Annotate with in_collection status
                if similar_lastfm or similar_listenbrainz:
                    all_similar_names = [_similar_artist_name(a) for a in similar_lastfm + similar_listenbrainz]
                    in_collection = _get_artists_in_collection(cursor, all_similar_names, placeholder)
                    similar_artists_data["lastfm"] = _annotate_in_collection(similar_lastfm, in_collection)
                    similar_artists_data["listenbrainz"] = _annotate_in_collection(similar_listenbrainz, in_collection)
        except Exception as e:
            logging.debug(f"Error loading similar artists for artist page: {e}")

        conn.close()
        
        # Get qBittorrent and slskd configs
        cfg = get_config()
        qbit_config = cfg.get("qbittorrent", {"enabled": False, "web_url": "http://localhost:8080"})
        slskd_config = cfg.get("slskd", {"enabled": False})
        
        # Convert all template data to JSON-serializable format
        # This ensures Row objects, datetime, Decimal, etc. are all properly converted
        albums_data_dicts = convert_row_to_json_serializable(albums_data_dicts)
        merged_albums_by_category = convert_row_to_json_serializable(merged_albums_by_category)
        missing_by_category = convert_row_to_json_serializable(missing_by_category)
        top_tracks = convert_row_to_json_serializable(top_tracks_dicts)
        appears_on_albums = convert_row_to_json_serializable(appears_on_dicts)
        artist_stats = convert_row_to_json_serializable(artist_stats)
        genres = convert_row_to_json_serializable(genres)
        genre_sources = convert_row_to_json_serializable(genre_sources)
        similar_artists_data = convert_row_to_json_serializable(similar_artists_data)
        artist_members = convert_row_to_json_serializable(artist_members)
        
        return render_template("artist.html", 
                             artist_name=name,
                             albums=albums_data_dicts,  # Keep for compatibility
                             albums_by_category=merged_albums_by_category,
                             missing_by_category=missing_by_category,  # Keep for backward compatibility
                             top_tracks=top_tracks,
                             appears_on_albums=appears_on_albums,
                             stats=artist_stats,
                             genres=genres,
                             genre_sources=genre_sources,
                             similar_artists_data=similar_artists_data,
                             artist_members=artist_members,
                             artist_country=artist_country,
                             artist_image_url=artist_image_url,
                             artist_bio=artist_bio,
                             qbit_config=qbit_config,
                             slskd_config=slskd_config)
    except Exception as e:
        import traceback
        logging.error(f"Error loading artist details: {str(e)}")
        logging.error(f"Traceback: {traceback.format_exc()}")
        flash(f"Error loading artist: {str(e)}", "error")
        return redirect(url_for("artists"))


def _normalize_release_title(text: str) -> str:
    """Normalize release titles for comparison."""
    if not text:
        return ""
    text = unicodedata.normalize("NFKD", text)
    text = "".join(c for c in text if not unicodedata.combining(c))
    text = text.lower()
    text = re.sub(r"\([^)]*\)|\[[^\]]*\]", " ", text)
    text = re.sub(r"(?i)\b(remaster(?:ed)?\s*\d{0,4}|remaster|deluxe|live|mono|stereo|edit|mix|version|bonus track)\b", " ", text)
    text = re.sub(r"[^a-z0-9]+", " ", text)
    return " ".join(text.split())


def _normalize_artist_name(text: str) -> str:
    """Normalize artist names for strict artist-credit comparison."""
    if not text:
        return ""
    text = unicodedata.normalize("NFKD", text)
    text = "".join(c for c in text if not unicodedata.combining(c))
    text = text.lower()
    text = re.sub(r"[^a-z0-9]+", " ", text)
    return " ".join(text.split())


def _normalize_release_category(value: str) -> str:
    """Normalize release category labels into canonical internal buckets."""
    normalized = (value or "").strip().lower().replace("-", " ").replace("_", " ")
    normalized = " ".join(normalized.split())
    if normalized in ("live", "live album"):
        return "live_album"
    if normalized in ("remix", "remix album"):
        return "remix_album"
    if normalized == "compilation":
        return "compilation"
    if normalized == "ep":
        return "ep"
    if normalized == "single":
        return "single"
    if normalized == "album":
        return "album"
    return ""


def _derive_release_bucket(primary_type: str, category: str, title: str = "") -> str:
    """Derive the most reliable release bucket for artist-page classification."""
    category_bucket = _normalize_release_category(category)
    primary = (primary_type or "").strip().lower()
    title_lower = (title or "").lower()

    # Category is computed from MB primary+secondary types during scan and can correct stale primary_type rows.
    if category_bucket in ("compilation", "live_album", "remix_album", "ep", "single", "album"):
        return category_bucket

    if "compilation" in primary:
        return "compilation"
    if "live" in primary or "live" in title_lower or "unplugged" in title_lower:
        return "live_album"
    if "remix" in primary or "remix" in title_lower:
        return "remix_album"
    if primary == "ep":
        return "ep"
    if primary == "single":
        return "single"
    if primary == "album" or not primary:
        return "album"
    return "unknown"


def _fetch_musicbrainz_releases(artist_name: str, limit: int = 100, artist_mbid: str | None = None) -> list[dict]:
    """
    Fetch release-groups from MusicBrainz for an artist with retry logic and pagination.
    
    If artist_mbid is provided, uses direct MBID lookup (more accurate).
    Otherwise uses text search by artist name.
    
    Handles SSL errors, timeouts, and other network issues with exponential backoff.
    Implements pagination to fetch all releases (not just first 100).
    """
    if not artist_name:
        return []
    
    headers = {"User-Agent": MUSICBRAINZ_USER_AGENT}
    releases: list[dict] = []
    url = "https://musicbrainz.org/ws/2/release-group"
    
    requested_artist_norm = _normalize_artist_name(artist_name)

    # Use artist MBID for lookup if available (more accurate than text search)
    if artist_mbid:
        query = f'arid:"{artist_mbid}" AND (primarytype:album OR primarytype:ep OR primarytype:single)'
        logging.debug(f"MusicBrainz: Using artist MBID lookup for {artist_name} ({artist_mbid})")
    else:
        query = f'artist:"{artist_name}" AND (primarytype:album OR primarytype:ep OR primarytype:single)'
        logging.debug(f"MusicBrainz: Using text search for {artist_name}")
    
    # Retry with exponential backoff
    max_retries = 3
    base_delay = 1
    used_relaxed_query_fallback = False
    
    # Pagination loop - fetch all pages of results
    offset = 0
    page_size = min(limit, 100)  # MusicBrainz max is 100 per request
    max_total = 500  # Safety limit to avoid excessive API calls
    pages_fetched = 0
    max_pages = 10  # Additional safety: max 10 pages (1000 releases if page_size=100)
    
    while offset < max_total and pages_fetched < max_pages:
        params = {
            "fmt": "json",
            "limit": page_size,
            "query": query,
            "offset": offset,
            "inc": "artist-credits",
        }
        
        fetched_this_page = False
        for attempt in range(max_retries):
            try:
                resp = requests.get(url, headers=headers, params=params, timeout=(6, 20))
                resp.raise_for_status()
                data = resp.json()
                
                release_groups = data.get("release-groups", []) or []
                total_count = data.get("count", 0)
                
                for rg in release_groups:
                    primary_type = (rg.get("primary-type") or "").lower()
                    # Keep response consistent with the intended query scope.
                    if primary_type not in ("album", "ep", "single"):
                        continue

                    # When no MBID is available, tighten matching to avoid cross-artist overmatches
                    # from broad text search (e.g., artists with similar names).
                    if not artist_mbid:
                        raw_score = rg.get("score", 0)
                        try:
                            rg_score = int(raw_score)
                        except (TypeError, ValueError):
                            rg_score = 0

                        # Require a strong text score when relying on name-based query.
                        if rg_score and rg_score < 90:
                            continue

                        artist_credit_names = []
                        for credit in rg.get("artist-credit") or []:
                            if isinstance(credit, dict):
                                artist_obj = credit.get("artist") or {}
                                name = artist_obj.get("name") or credit.get("name") or ""
                                if name:
                                    artist_credit_names.append(name)

                        # If artist credits are provided, require an exact normalized artist match.
                        if artist_credit_names:
                            if not any(_normalize_artist_name(n) == requested_artist_norm for n in artist_credit_names):
                                continue

                    rg_id = rg.get("id", "")
                    releases.append({
                        "id": rg_id,
                        "title": rg.get("title", ""),
                        "primary_type": rg.get("primary-type", ""),
                        "first_release_date": rg.get("first-release-date", ""),
                        "secondary_types": rg.get("secondary-types", []),
                        "cover_art_url": f"https://coverartarchive.org/release-group/{rg_id}/front-500" if rg_id else "",
                    })
                
                fetched_this_page = True
                pages_fetched += 1
                
                # Check if we've fetched all available releases
                if len(release_groups) < page_size or offset + len(release_groups) >= total_count:
                    logging.debug(f"MusicBrainz: Fetched {len(releases)} total releases for {artist_name}")
                    return releases  # Success - all pages fetched
                
                # Move to next page
                offset += page_size
                # MusicBrainz rate limiting: wait 1 second between requests
                time.sleep(1.0)
                break  # Success, exit retry loop
                
            except requests.exceptions.Timeout:
                logging.debug(f"MusicBrainz timeout (attempt {attempt+1}/{max_retries}) for {artist_name} at offset {offset}")
                if attempt < max_retries - 1:
                    time.sleep(base_delay * (2 ** attempt))  # Exponential backoff
            except requests.exceptions.HTTPError as e:
                status_code = e.response.status_code if e.response is not None else None
                if status_code in (429, 500, 502, 503, 504) and attempt < max_retries - 1:
                    retry_after = None
                    if e.response is not None:
                        retry_after_raw = e.response.headers.get("Retry-After")
                        try:
                            retry_after = float(retry_after_raw) if retry_after_raw else None
                        except (TypeError, ValueError):
                            retry_after = None
                    wait_seconds = retry_after if retry_after is not None else float(base_delay * (2 ** attempt))
                    logging.debug(
                        f"MusicBrainz transient HTTP {status_code} (attempt {attempt+1}/{max_retries}) "
                        f"for {artist_name} at offset {offset}; waiting {wait_seconds:.1f}s"
                    )
                    time.sleep(wait_seconds)
                else:
                    logging.debug(
                        f"MusicBrainz HTTP error for {artist_name} at offset {offset}: {status_code}"
                    )
                    break
            except requests.exceptions.ConnectionError as e:
                # Includes SSLEOFError and other connection issues
                logging.debug(f"MusicBrainz connection error (attempt {attempt+1}/{max_retries}) for {artist_name}: {type(e).__name__}")
                if attempt < max_retries - 1:
                    time.sleep(base_delay * (2 ** attempt))
            except requests.exceptions.RequestException as e:
                logging.debug(f"MusicBrainz request error for {artist_name}: {e}")
                break  # Don't retry for other request errors
            except Exception as e:
                logging.debug(f"Unexpected error fetching MusicBrainz releases for {artist_name}: {e}")
                break
        
        # If we failed to fetch this page after all retries, return what we have
        if not fetched_this_page:
            if offset == 0 and not releases and not artist_mbid and not used_relaxed_query_fallback:
                # Some environments fail strict query parsing/routing intermittently.
                # Retry once with a relaxed query and filter types client-side.
                query = f'artist:"{artist_name}"'
                used_relaxed_query_fallback = True
                logging.debug(
                    f"MusicBrainz: retrying first page for {artist_name} with relaxed query fallback"
                )
                continue
            logging.warning(f"MusicBrainz: Failed to fetch page at offset {offset} for {artist_name}, returning {len(releases)} releases")
            return releases
    
    return releases


def _search_musicbrainz_releasegroup_matches(artist_name: str, album_name: str, limit: int = 10) -> list[dict]:
    """
    Search MusicBrainz release-groups with fuzzy match scoring.
    
    Returns matches sorted by similarity score (highest first), with confidence tiers:
    - high: score >= 0.90 (very likely match)
    - medium: 0.75 <= score < 0.90 (probable match)
    - low: score < 0.75 (weak match)
    """
    if not artist_name or not album_name:
        return []

    headers = {"User-Agent": MUSICBRAINZ_USER_AGENT}
    search_url = "https://musicbrainz.org/ws/2/release-group"
    query = f"artist:{artist_name} AND releasegroup:{album_name}"
    params = {
        "fmt": "json",
        "query": query,
        "limit": max(1, min(limit, 25)),
    }

    try:
        response = requests.get(search_url, headers=headers, params=params, timeout=15)
        response.raise_for_status()
        data = response.json() or {}
    except Exception as e:
        logging.debug(f"MusicBrainz release-group match search failed for {artist_name} - {album_name}: {e}")
        return []

    from difflib import SequenceMatcher
    
    def normalize(s):
        """Normalize string for comparison (lowercase, strip punctuation)"""
        import re
        s = s.lower().strip()
        s = re.sub(r'[^\w\s]', '', s)  # Remove punctuation
        s = re.sub(r'\s+', ' ', s)  # Normalize whitespace
        return s
    
    def calculate_match_score(mb_title, mb_artist_credit, local_album, local_artist):
        """
        Calculate fuzzy match score using weighted formula:
        - Title similarity: 60%
        - Artist similarity: 40%
        """
        title_sim = SequenceMatcher(None, normalize(local_album), normalize(mb_title)).ratio()
        
        # Extract artist name from artist-credit (can be list of dicts)
        artist_name_from_credit = ""
        if isinstance(mb_artist_credit, list) and len(mb_artist_credit) > 0:
            artist_name_from_credit = mb_artist_credit[0].get("name", "")
        elif isinstance(mb_artist_credit, str):
            artist_name_from_credit = mb_artist_credit
        
        artist_sim = SequenceMatcher(None, normalize(local_artist), normalize(artist_name_from_credit)).ratio()
        
        # Weighted score: title is more important than artist
        score = (title_sim * 0.6) + (artist_sim * 0.4)
        return score

    matches = []
    for rg in data.get("release-groups", []) or []:
        mb_title = rg.get("title", "")
        mb_artist_credit = rg.get("artist-credit", [])
        
        # Calculate similarity score
        score = calculate_match_score(mb_title, mb_artist_credit, album_name, artist_name)
        
        # Determine confidence tier
        if score >= 0.90:
            confidence = "high"
        elif score >= 0.75:
            confidence = "medium"
        else:
            confidence = "low"
        
        matches.append({
            "id": rg.get("id", ""),
            "title": mb_title,
            "primary_type": rg.get("primary-type", ""),
            "first_release_date": rg.get("first-release-date", ""),
            "secondary_types": rg.get("secondary-types", []),
            "match_score": round(score, 3),
            "confidence": confidence,
        })

    # Sort by score descending (best matches first)
    matches.sort(key=lambda x: x["match_score"], reverse=True)

    return matches


@app.route("/api/artist/exists", methods=["GET"])
def api_artist_exists():
    """Check if an artist exists in the database."""
    artist = request.args.get("artist", "").strip()
    if not artist:
        return jsonify({"error": "Artist is required"}), 400
    
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Check if artist exists using the same logic as the artist listing page
        # Look for artist as main artist or album artist
        cursor.execute(f"""
            SELECT COUNT(*) AS cnt FROM tracks 
            WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
        """, (artist,))
        result = cursor.fetchone()
        conn.close()
        
        exists = result['cnt'] > 0 if result else False
        
        return jsonify({
            "exists": exists,
            "artist": artist
        })
    except Exception as e:
        logging.error(f"Error checking artist existence: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/artist/missing-releases", methods=["GET"])
def api_artist_missing_releases():
    """Detect missing releases for an artist by comparing to MusicBrainz."""
    artist = request.args.get("artist", "").strip()
    if not artist:
        return jsonify({"error": "Artist is required"}), 400

    conn = get_db()
    cursor = conn.cursor()
    placeholder = "%s"
    
    # Use canonical artist identity for all comparisons (album_artist preferred)
    artist_compare_expr = "COALESCE(NULLIF(album_artist, ''), artist)"

    # Get artist MBID if available for more accurate MusicBrainz lookup
    artist_mbid = None
    try:
        cursor.execute(f"""
            SELECT MAX(musicbrainz_artist_id) AS mbid
            FROM tracks
            WHERE LOWER({artist_compare_expr}) = LOWER({placeholder})
        """, (artist,))
        row = cursor.fetchone()
        if row and row['mbid']:
            artist_mbid = row['mbid']
    except:
        pass

    if not artist_mbid:
        try:
            from api_clients.musicbrainz import lookup_and_save_artist_mbid
            artist_mbid = lookup_and_save_artist_mbid(artist, conn) or None
        except Exception as e:
            logging.debug(f"[MISSING_RELEASES] Could not resolve artist MBID for {artist}: {e}")
    
    cursor.execute(f"""
        SELECT DISTINCT album
        FROM tracks
        WHERE LOWER({artist_compare_expr}) = LOWER({placeholder})
    """, (artist,))
    existing_albums = [row['album'] for row in cursor.fetchall()]

    existing_norm = {_normalize_release_title(a) for a in existing_albums if a}

    # Use artist MBID for accurate lookup when available
    mb_releases = _fetch_musicbrainz_releases(artist, artist_mbid=artist_mbid)
    missing = []
    seen_missing_keys = set()
    for rg in mb_releases:
        norm_title = _normalize_release_title(rg.get("title") or "")
        if not norm_title or norm_title in existing_norm:
            continue

        # Include albums, EPs, and singles. Route by primary type and secondary type
        # so artist page sections (Albums, Live Albums, Remix Albums, Compilations,
        # EPs, Singles) can display missing items.
        primary_type = (rg.get("primary_type") or "").lower()
        if primary_type not in ("album", "ep", "single"):
            continue

        secondary = [s.lower() for s in rg.get("secondary_types") or []]
        if "compilation" in secondary:
            category = "Compilation"
        elif "live" in secondary:
            category = "Live Album"
        elif "remix" in secondary:
            category = "Remix"
        elif primary_type == "ep":
            category = "EP"
        elif primary_type == "single":
            category = "Single"
        else:
            category = "Album"

        dedupe_key = (norm_title, category)
        if dedupe_key in seen_missing_keys:
            continue
        seen_missing_keys.add(dedupe_key)

        release_id = rg.get("id", "") or f"{artist}-{norm_title}"
        missing.append({
            "id": release_id,
            "title": rg.get("title", ""),
            "primary_type": rg.get("primary_type", ""),
            "first_release_date": rg.get("first_release_date", ""),
            "secondary_types": rg.get("secondary_types", []),
            "cover_art_url": rg.get("cover_art_url", ""),
            "category": category,
        })

    # Persist latest artist-level missing releases so they survive page reloads/restarts.
    try:
        cursor.execute(
            f"DELETE FROM missing_releases WHERE LOWER(artist) = LOWER({placeholder})",
            (artist,)
        )
        cursor.execute("SELECT COALESCE(MAX(id), 0) + 1 AS next_id FROM missing_releases")
        next_id_row = cursor.fetchone()
        next_missing_release_id = int(next_id_row.get("next_id", 1)) if isinstance(next_id_row, dict) else int(next_id_row[0] if next_id_row else 1)
        for item in missing:
            cursor.execute(f"""
                INSERT INTO missing_releases
                (id, artist, release_id, title, primary_type, first_release_date, cover_art_url, category, last_checked)
                VALUES ({placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, CURRENT_TIMESTAMP)
            """, (
                next_missing_release_id,
                artist,
                item.get("id", ""),
                item.get("title", ""),
                item.get("primary_type", "Album"),
                item.get("first_release_date", ""),
                item.get("cover_art_url", ""),
                item.get("category", "Album")
            ))
            next_missing_release_id += 1
        conn.commit()
    except Exception as persist_error:
        logging.warning(f"[MISSING_RELEASES] Could not persist artist missing releases for {artist}: {persist_error}")
    finally:
        conn.close()

    # Auto-queue new releases for favourited artists (current year, straight albums only)
    try:
        auto_queued = _auto_queue_favourite_artist_releases(artist, missing)
        if auto_queued:
            logging.info(f"[AUTO-QUEUE] Auto-queued {auto_queued} release(s) for favourited artist '{artist}'")
    except Exception as aq_err:
        logging.debug(f"[AUTO-QUEUE] Error during auto-queue for '{artist}': {aq_err}")

    # Auto-queue missing singles for album artists when those tracks are not already in collection.
    try:
        singles_auto_queued = _auto_queue_missing_singles_for_album_artist(artist, missing)
        if singles_auto_queued:
            logging.info(
                f"[AUTO-QUEUE] Auto-queued {singles_auto_queued} missing single(s) for album artist '{artist}'"
            )
    except Exception as aq_single_err:
        logging.debug(f"[AUTO-QUEUE] Error auto-queuing missing singles for '{artist}': {aq_single_err}")

    return jsonify({
        "artist": artist,
        "missing": missing,
        "total_musicbrainz": len(mb_releases),
        "existing_albums": existing_albums,
    })


@app.route("/api/artist/import-release", methods=["POST"])
def api_import_release():
    """Import a MusicBrainz release with full tracklisting to the database."""
    data = request.json or {}
    artist = data.get("artist", "").strip()
    release_id = data.get("release_id", "").strip()
    title = data.get("title", "").strip()
    
    if not artist or not release_id or not title:
        return jsonify({"error": "Artist, release_id, and title are required"}), 400
    
    try:
        headers = {"User-Agent": MUSICBRAINZ_USER_AGENT}

        def _fetch_release_payload(mbid):
            """Fetch a release payload by release MBID, with release-group fallback."""
            mb_url = f"https://musicbrainz.org/ws/2/release/{mbid}"
            params = {
                "fmt": "json",
                "inc": "recordings+artist-credits+release-groups"
            }
            response = requests.get(mb_url, params=params, headers=headers, timeout=15)
            if response.status_code == 404:
                # Some UI paths provide a release-group MBID. Resolve it to a concrete
                # release and retry with that MBID.
                search_resp = requests.get(
                    "https://musicbrainz.org/ws/2/release",
                    params={
                        "fmt": "json",
                        "release-group": mbid,
                        "limit": 1,
                    },
                    headers=headers,
                    timeout=15,
                )
                search_resp.raise_for_status()
                releases = (search_resp.json() or {}).get("releases") or []
                if not releases:
                    return None, mbid

                resolved_release_id = releases[0].get("id")
                if not resolved_release_id:
                    return None, mbid

                retry_resp = requests.get(
                    f"https://musicbrainz.org/ws/2/release/{resolved_release_id}",
                    params=params,
                    headers=headers,
                    timeout=15,
                )
                retry_resp.raise_for_status()
                return retry_resp.json(), resolved_release_id

            response.raise_for_status()
            return response.json(), mbid

        release_data, resolved_release_id = _fetch_release_payload(release_id)
        
        if not release_data:
            return jsonify({"error": "Release not found on MusicBrainz"}), 404
        
        # Extract media and tracks
        media = release_data.get("media", [])
        if not media:
            return jsonify({"error": "Release has no media/tracks"}), 400
        
        conn = get_db()
        imported_count = 0
        
        # Get year from release-date
        year = release_data.get("date", "")
        if year:
            year = year[:4]
        
        # Process each track from all media (discs)
        for disc_idx, disc in enumerate(media, start=1):
            disc_number = disc.get("position", disc_idx)
            tracks_list = disc.get("tracks", [])
            
            for track_idx, track in enumerate(tracks_list, start=1):
                recording = track.get("recording", {})
                track_title = recording.get("title") or track.get("title") or "Unknown"
                duration = recording.get("length")
                mbid = recording.get("id", "")
                
                # Build track record
                track_record = {
                    "id": recording.get("id", f"{resolved_release_id}_{disc_number}_{track_idx}"),
                    "title": track_title,
                    "artist": artist,
                    "album": title,
                    "track_number": track_idx,
                    "disc_number": disc_number,
                    "duration": duration,
                    "year": year,
                    "mbid": mbid,
                    "writer": json.dumps([]),  # Empty writer list - MusicBrainz doesn't provide lyricist info easily
                    "score": 0.0,
                    "spotify_score": 0,
                    "lastfm_score": 0,
                    "age_score": 0,
                    "genres": json.dumps([]),  # Serialize as JSON string
                    "file_path": None,
                    "stars": 0,
                    "last_scanned": datetime.now().isoformat(),
                }
                
                # Insert or update track in database
                save_to_db(track_record)
                imported_count += 1
        
        conn.close()
        
        logging.info(
            f"[IMPORT] Imported {imported_count} tracks from '{title}' by {artist} "
            f"(requested MB ID: {release_id}, resolved release MB ID: {resolved_release_id})"
        )
        
        return jsonify({
            "success": True,
            "message": f"Imported {imported_count} tracks from '{title}'",
            "tracks_imported": imported_count,
            "artist": artist,
            "album": title,
            "release_id": resolved_release_id,
        })
        
    except requests.exceptions.HTTPError as e:
        status_code = e.response.status_code if e.response is not None else 500
        if status_code == 404:
            logging.warning(
                f"[IMPORT] MusicBrainz release not found for release_id={release_id}; "
                f"artist='{artist}', title='{title}'"
            )
            return jsonify({
                "error": "Release not found on MusicBrainz",
                "release_id": release_id,
                "artist": artist,
                "title": title,
            }), 404

        logging.error(f"[IMPORT] MusicBrainz API error: {e}")
        return jsonify({"error": f"MusicBrainz API error: {status_code}"}), 500
    except Exception as e:
        logging.error(f"[IMPORT] Error importing release: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


@app.route("/api/artist/scan-all-missing-releases", methods=["POST"])
def api_scan_all_missing_releases():
    """Scan all artists in database for missing releases and cache results."""
    global scan_process_missing_releases
    
    # Check if already running
    if scan_process_missing_releases and isinstance(scan_process_missing_releases, dict):
        thread = scan_process_missing_releases.get('thread')
        if thread and thread.is_alive():
            return jsonify({"error": "Missing releases scan already running"}), 400
    
    def run_missing_releases_scan():
        global scan_process_missing_releases
        # Define progress_file at function scope so it's always available
        progress_file = os.path.join(os.path.dirname(DB_PATH), "missing_releases_scan_progress.json")
        
        try:
            conn = get_db()
            cursor = conn.cursor()
            placeholder = "%s"
            # Get canonical artist identities from album_artist when available.
            # This avoids scanning featured track artists that do not represent a real catalog owner.
            cursor.execute("""
                SELECT DISTINCT COALESCE(NULLIF(album_artist, ''), artist) AS canonical_artist
                FROM tracks
                WHERE COALESCE(NULLIF(album_artist, ''), artist) IS NOT NULL
                  AND COALESCE(NULLIF(album_artist, ''), artist) != ''
                ORDER BY canonical_artist
            """)
            artists = [row[0] for row in cursor.fetchall()]
            total_artists = len(artists)
            
            logging.info(f"[MISSING_RELEASES] Starting scan for {total_artists} artists")
            
            # Clean up any releases that are NOW in the database (were imported since last scan)
            cursor.execute("""
                DELETE FROM missing_releases mr
                WHERE EXISTS (
                    SELECT 1 FROM tracks t
                    WHERE LOWER(t.artist) = LOWER(mr.artist)
                    AND LOWER(TRIM(t.album)) = LOWER(TRIM(mr.title))
                )
            """)
            imported_count = cursor.rowcount
            conn.commit()
            if imported_count > 0:
                logging.info(f"[MISSING_RELEASES] Cleaned up {imported_count} releases that were imported since last scan")
            
            processed = 0
            total_missing = 0
            
            for artist_name in artists:
                try:
                    # Check if scan should stop
                    with scan_lock:
                        stop_requested = scan_process_missing_releases is None or _is_stop_requested_from_progress(progress_file)
                        if stop_requested:
                            logging.info("[MISSING_RELEASES] Stop signal received, exiting gracefully")
                            progress_data = {
                                "is_running": False,
                                "scan_type": "missing_releases_scan",
                                "status": "stopped",
                                "processed_artists": processed,
                                "total_artists": total_artists,
                                "total_missing_found": total_missing,
                                "percent_complete": int((processed / total_artists * 100)) if total_artists > 0 else 0
                            }
                            with open(progress_file, 'w') as f:
                                json.dump(progress_data, f)
                            return
                    
                    processed += 1
                    
                    # Update progress file
                    progress_data = {
                        "is_running": True,
                        "scan_type": "missing_releases_scan",
                        "current_artist": artist_name,
                        "processed_artists": processed,
                        "total_artists": total_artists,
                        "total_missing_found": total_missing,
                        "percent_complete": int((processed / total_artists * 100)) if total_artists > 0 else 0
                    }
                    
                    with open(progress_file, 'w') as f:
                        json.dump(progress_data, f)
                    
                    # Look up and save artist MBID if not already saved
                    # This strengthens MusicBrainz lookups for album type detection
                    try:
                        from api_clients.musicbrainz import lookup_and_save_artist_mbid
                        cursor.execute(f"""
                            SELECT MAX(musicbrainz_artist_id)
                            FROM tracks
                            WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
                        """, (artist_name,))
                        result = cursor.fetchone()
                        existing_mbid = result[0] if result and result[0] else None
                        resolved_artist_mbid = existing_mbid
                        
                        if not existing_mbid:
                            # No MBID saved yet, try to look it up from MusicBrainz
                            mbid = lookup_and_save_artist_mbid(artist_name, conn)
                            if mbid:
                                resolved_artist_mbid = mbid
                                logging.debug(f"[MISSING_RELEASES] Artist MBID saved for {artist_name}: {mbid}")
                        else:
                            logging.debug(f"[MISSING_RELEASES] Artist {artist_name} already has MBID: {existing_mbid}")
                    except Exception as e:
                        logging.debug(f"[MISSING_RELEASES] Could not look up MBID for {artist_name}: {e}")
                        resolved_artist_mbid = None
                    
                    # Get existing albums for this artist
                    cursor.execute(f"""
                        SELECT DISTINCT album
                        FROM tracks
                        WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
                    """, (artist_name,))
                    existing_albums = [row[0] for row in cursor.fetchall()]
                    existing_norm = {_normalize_release_title(a) for a in existing_albums if a}
                    
                    # Fetch MusicBrainz releases, preferring MBID lookups for accuracy.
                    mb_releases = _fetch_musicbrainz_releases(artist_name, artist_mbid=resolved_artist_mbid)
                    missing_for_artist = []
                    
                    # Check for missing releases AND update cover art for existing albums
                    for rg in mb_releases:
                        norm_title = _normalize_release_title(rg.get("title") or "")
                        cover_art_url = rg.get("cover_art_url", "")
                        
                        # If album exists, update its cover art
                        if norm_title and norm_title in existing_norm:
                            if cover_art_url:
                                # Update cover_art_url for all tracks in this album
                                original_album = next((a for a in existing_albums if _normalize_release_title(a) == norm_title), None)
                                if original_album:
                                    # Update the URL in tracks table
                                    cursor.execute(f"""
                                        UPDATE tracks 
                                        SET cover_art_url = {placeholder}
                                        WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}
                                          AND album = {placeholder}
                                    """, (cover_art_url, artist_name, original_album))
                                    
                                    # Also download and save the actual album art image data (same as popularity scan does)
                                    try:
                                        if download_and_save_album_art(artist_name, original_album, cover_art_url):
                                            logging.info(f"[MISSING_RELEASES] Downloaded and cached album art for {artist_name} - {original_album}")
                                        else:
                                            logging.debug(f"[MISSING_RELEASES] Failed to download album art for {artist_name} - {original_album}")
                                    except Exception as e:
                                        logging.debug(f"[MISSING_RELEASES] Error downloading album art for {artist_name} - {original_album}: {e}")
                            continue
                        
                        if not norm_title:
                            continue
                        
                        # Include albums, EPs, and singles. Route by primary type and secondary
                        # type so artist page sections can display missing items by category.
                        primary_type = (rg.get("primary_type") or "").lower()
                        if primary_type not in ("album", "ep", "single"):
                            continue

                        secondary = [s.lower() for s in rg.get("secondary_types") or []]
                        if "compilation" in secondary:
                            category = "Compilation"
                        elif "live" in secondary:
                            category = "Live Album"
                        elif "remix" in secondary:
                            category = "Remix"
                        elif primary_type == "ep":
                            category = "EP"
                        elif primary_type == "single":
                            category = "Single"
                        else:
                            category = "Album"

                        missing_for_artist.append({
                            "id": rg.get("id", ""),
                            "title": rg.get("title", ""),
                            "primary_type": rg.get("primary_type", ""),
                            "first_release_date": rg.get("first_release_date", ""),
                            "cover_art_url": cover_art_url,
                            "category": category,
                        })
                        
                        # Insert missing release into database with DB-aware upsert
                        try:
                            cursor.execute(
                                f"DELETE FROM missing_releases WHERE LOWER(artist) = LOWER({placeholder}) AND release_id = {placeholder}",
                                (artist_name, rg.get("id", ""))
                            )
                            cursor.execute("SELECT COALESCE(MAX(id), 0) + 1 AS next_id FROM missing_releases")
                            next_id_row = cursor.fetchone()
                            next_missing_release_id = int(next_id_row.get("next_id", 1)) if isinstance(next_id_row, dict) else int(next_id_row[0] if next_id_row else 1)
                            cursor.execute(f"""
                                INSERT INTO missing_releases 
                                (id, artist, release_id, title, primary_type, first_release_date, cover_art_url, category, last_checked)
                                VALUES ({placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder}, CURRENT_TIMESTAMP)
                            """, (
                                next_missing_release_id,
                                artist_name,
                                rg.get("id", ""),
                                rg.get("title", ""),
                                rg.get("primary_type", "Album"),
                                rg.get("first_release_date", ""),
                                cover_art_url,
                                category
                            ))
                            total_missing += 1
                        except Exception as e:
                            logging.warning(f"[MISSING_RELEASES] Error inserting release {rg.get('title')}: {e}")
                    
                    conn.commit()

                    try:
                        singles_auto_queued = _auto_queue_missing_singles_for_album_artist(artist_name, missing_for_artist)
                        if singles_auto_queued:
                            logging.info(
                                "[AUTO-QUEUE] Auto-queued %s missing single(s) for album artist '%s' during missing scan",
                                singles_auto_queued,
                                artist_name,
                            )
                    except Exception as auto_single_err:
                        logging.warning(
                            "[AUTO-QUEUE] Error auto-queuing missing singles for '%s' during missing scan: %s",
                            artist_name,
                            auto_single_err,
                        )
                    
                    # Rate limiting
                    time.sleep(1.1)  # MusicBrainz rate limit: 1 request per second
                    
                except Exception as e:
                    logging.error(f"[MISSING_RELEASES] Error scanning {artist_name}: {e}")
                    continue
            
            # Write final progress
            progress_data = {
                "is_running": False,
                "scan_type": "missing_releases_scan",
                "processed_artists": total_artists,
                "total_artists": total_artists,
                "total_missing_found": total_missing,
                "percent_complete": 100,
                "status": "complete"
            }
            with open(progress_file, 'w') as f:
                json.dump(progress_data, f)
            
            conn.close()
            logging.info(f"[MISSING_RELEASES] Scan complete. Found {total_missing} missing releases across {total_artists} artists")
            
        except Exception as e:
            logging.error(f"[MISSING_RELEASES] Scan failed: {e}", exc_info=True)
            progress_data = {
                "is_running": False,
                "scan_type": "missing_releases_scan",
                "status": "error",
                "error": str(e)
            }
            try:
                with open(progress_file, 'w') as f:
                    json.dump(progress_data, f)
            except:
                pass
    
    # Start scan in background thread
    scan_thread = threading.Thread(target=run_missing_releases_scan, daemon=False)
    scan_thread.start()
    scan_process_missing_releases = {'thread': scan_thread, 'type': 'missing_releases'}
    
    return jsonify({
        "success": True,
        "message": "Missing releases scan started"
    })


@app.route("/api/artist/country", methods=["POST"])
def api_fetch_artist_country():
    """Fetch artist country from MusicBrainz and update database."""
    try:
        data = request.get_json()
        artist_name = data.get("artist_name", "").strip()
        
        if not artist_name:
            return jsonify({"error": "Artist name required"}), 400
        
        # Fetch country from MusicBrainz
        from api_clients.musicbrainz import get_artist_country
        country = get_artist_country(artist_name, enabled=True)
        
        if not country:
            return jsonify({"error": "No country information found on MusicBrainz"}), 404
        
        # Update artists table
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Ensure artist exists in artists table
        cursor.execute(f"SELECT id FROM artists WHERE name = {placeholder}", (artist_name,))
        artist_row = cursor.fetchone()
        
        if artist_row:
            # Update existing artist
            cursor.execute(f"UPDATE artists SET country = {placeholder} WHERE name = {placeholder}", (country, artist_name))
        else:
            # Insert new artist entry
            cursor.execute(f"INSERT INTO artists (id, name, country) VALUES ({placeholder}, {placeholder}, {placeholder})", 
                         (artist_name, artist_name, country))
        
        # Also update all tracks by this artist
        cursor.execute(f"UPDATE tracks SET artist_country = {placeholder} WHERE artist = {placeholder}", (country, artist_name))
        
        conn.commit()
        conn.close()
        
        return jsonify({
            "success": True,
            "country": country,
            "message": f"Updated country to {country}"
        })
        
    except Exception as e:
        logging.error(f"[ARTIST_COUNTRY] Error: {e}", exc_info=True)
        return jsonify({"error": str(e)}), 500


