@app.route("/api/artist/covered-by")
def api_artist_covered_by():
    """Get tracks from other artists that are covers of this artist's songs.

    Returns a list of tracks in the user's library that have been detected
    as covers of songs originally by the given artist.
    """
    artist_name = request.args.get("artist", "").strip()
    if not artist_name:
        return jsonify({"error": "Artist name required"}), 400

    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        # Find tracks where original_cover_artist matches AND the performing artist is different
        cursor.execute(
            f"""
            SELECT id, title, artist, album, year,
                   original_cover_artist, is_cover_reason
            FROM tracks
            WHERE original_cover_artist ILIKE {placeholder}
              AND LOWER(COALESCE(album_artist, artist)) != LOWER({placeholder})
            ORDER BY artist, title
            """,
            (artist_name, artist_name),
        )
        rows = cursor.fetchall() or []
        conn.close()

        def _cover_field(row_obj, key, index):
            """Safely read a field from dict-like rows (Postgres) or tuple-like rows (SQLite)."""
            try:
                if hasattr(row_obj, "keys"):
                    return row_obj.get(key)
                return row_obj[index]
            except Exception:
                return None

        covers = []
        for row in rows:
            # Support both mapping-style and index-style row access
            try:
                covers.append({
                    "id": _cover_field(row, "id", 0),
                    "title": _cover_field(row, "title", 1),
                    "artist": _cover_field(row, "artist", 2),
                    "album": _cover_field(row, "album", 3),
                    "year": _cover_field(row, "year", 4),
                    "original_cover_artist": _cover_field(row, "original_cover_artist", 5),
                })
            except (KeyError, TypeError, IndexError) as e:
                logging.debug(f"Error parsing cover row: {e}")
                covers.append({
                    "id": row[0],
                    "title": row[1],
                    "artist": row[2],
                    "album": row[3],
                    "year": row[4],
                    "original_cover_artist": row[5],
                })

        return jsonify({"success": True, "covers": covers, "total": len(covers)})

    except Exception as e:
        logging.error(f"Error fetching covered-by data for '{artist_name}': {e}")
        return jsonify({"success": False, "error": str(e), "covers": []}), 500


def _is_bookmarks_null_id_error(error):
    msg = str(error or "")
    return 'null value in column "id"' in msg and 'relation "bookmarks"' in msg


def _repair_postgres_bookmarks_id_default(conn):
    """Ensure PostgreSQL bookmarks.id has a working sequence-backed default."""
    if not _is_postgres_connection(conn):
        return False

    cursor = conn.cursor()
    cursor.execute("CREATE SEQUENCE IF NOT EXISTS bookmarks_id_seq")
    cursor.execute(
        "SELECT setval('bookmarks_id_seq', COALESCE((SELECT MAX(id) FROM bookmarks), 0) + 1, false)"
    )
    cursor.execute(
        "ALTER TABLE bookmarks ALTER COLUMN id SET DEFAULT nextval('bookmarks_id_seq')"
    )
    try:
        cursor.execute("ALTER SEQUENCE bookmarks_id_seq OWNED BY bookmarks.id")
    except Exception:
        # Ownership may already be set or unavailable in some environments.
        pass
    conn.commit()
    return True


def _insert_bookmark_resilient(conn, query, params):
    """Execute bookmark insert and auto-repair missing PG id default if needed."""
    cursor = conn.cursor()
    try:
        cursor.execute(query, params)
        return cursor
    except Exception as insert_err:
        if _is_postgres_connection(conn) and _is_bookmarks_null_id_error(insert_err):
            logging.warning("[BOOKMARKS] Detected missing bookmarks.id default; attempting auto-repair")
            conn.rollback()
            _repair_postgres_bookmarks_id_default(conn)
            cursor = conn.cursor()
            cursor.execute(query, params)
            return cursor
        raise


@app.route("/api/artist/favourite", methods=["GET", "POST", "DELETE"])
def api_artist_favourite():
    """Check, add, or remove an artist from favourites.

    Favourites are stored in the bookmarks table with type='artist_favourite'.

    GET  ?artist=<name>  → {"is_favourite": bool}
    POST  {"artist": <name>}  → {"success": true, "is_favourite": true}
    DELETE ?artist=<name>   → {"success": true, "is_favourite": false}
    """
    conn = get_db()
    cursor = conn.cursor()
    placeholder = "%s"

    try:
        if request.method == "GET":
            artist_name = request.args.get("artist", "").strip()
            if not artist_name:
                conn.close()
                return jsonify({"error": "Artist name required"}), 400
            cursor.execute(
                f"SELECT id FROM bookmarks WHERE type = {placeholder} AND LOWER(name) = LOWER({placeholder})",
                ("artist_favourite", artist_name),
            )
            row = cursor.fetchone()
            conn.close()
            return jsonify({"is_favourite": row is not None})

        elif request.method == "POST":
            data = request.get_json() or {}
            artist_name = data.get("artist", "").strip()
            if not artist_name:
                conn.close()
                return jsonify({"error": "Artist name required"}), 400
            _insert_bookmark_resilient(
                conn,
                f"""
                INSERT INTO bookmarks (type, name)
                VALUES ({placeholder}, {placeholder})
                ON CONFLICT DO NOTHING
                """,
                # ON CONFLICT DO NOTHING handles the UNIQUE(type, name, artist, album, track_id) constraint
                ("artist_favourite", artist_name),
            )
            conn.commit()
            conn.close()
            return jsonify({"success": True, "is_favourite": True})

        elif request.method == "DELETE":
            artist_name = request.args.get("artist", "").strip()
            if not artist_name:
                conn.close()
                return jsonify({"error": "Artist name required"}), 400
            cursor.execute(
                f"DELETE FROM bookmarks WHERE type = {placeholder} AND LOWER(name) = LOWER({placeholder})",
                ("artist_favourite", artist_name),
            )
            conn.commit()
            conn.close()
            return jsonify({"success": True, "is_favourite": False})

    except Exception as e:
        logging.error(f"Error managing artist favourite for '{request.args.get('artist', '')}': {e}")
        try:
            conn.close()
        except Exception:
            pass
        return jsonify({"success": False, "error": str(e)}), 500


def _is_artist_favourited(artist_name: str) -> bool:
    """Return True if the given artist is marked as a favourite.

    Checks both:
    - bookmarks table (type='artist_favourite')
    - user_loved_artists table (is_loved=1)
    """
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        # Check bookmarks
        cursor.execute(
            f"SELECT 1 FROM bookmarks WHERE type = {placeholder} AND LOWER(name) = LOWER({placeholder}) LIMIT 1",
            ("artist_favourite", artist_name),
        )
        if cursor.fetchone():
            conn.close()
            return True

        # Check user_loved_artists
        cursor.execute(
            f"SELECT 1 FROM user_loved_artists WHERE LOWER(artist) = LOWER({placeholder}) AND is_loved = TRUE LIMIT 1",
            (artist_name,),
        )
        result = cursor.fetchone() is not None
        conn.close()
        return result
    except Exception as e:
        logging.debug(f"Error checking favourite status for '{artist_name}': {e}")
        return False


def _auto_queue_favourite_artist_releases(artist: str, new_releases: list) -> int:
    """Auto-queue new releases for a favourited artist.

    Only queues releases that:
    - Are from the current year
    - Have primary_type = 'Album' (straight album, no secondary category)
    - Are not already in the download queue

    Returns the count of releases added to the queue.
    """
    import datetime

    current_year = str(datetime.datetime.now().year)
    queued_count = 0

    if not _is_artist_favourited(artist):
        return 0

    for release in new_releases:
        first_release_date = release.get("first_release_date", "") or ""
        release_year = first_release_date[:4] if first_release_date else ""
        primary_type = (release.get("primary_type") or "").lower()
        category = (release.get("category") or "").lower()
        release_title = release.get("title", "")

        # Only auto-queue straight albums from the current year
        if release_year != current_year:
            continue
        if primary_type != "album":
            continue
        # 'Album' category means no secondary type (Live, Compilation, etc.).
        # An empty category also indicates a plain album (no secondary classification).
        if category not in ("album", ""):
            continue

        try:
            from download_queue_manager import add_to_queue
            result = add_to_queue(
                artist=artist,
                title=release_title,
                album=release_title,
                source="soulseek",
                priority=5,
                import_type="album",
                year=release_year or None,
                release_id=release.get("id") or release.get("release_id"),
                release_source="musicbrainz",
            )
            if result:
                queued_count += 1
                logging.info(
                    f"[AUTO-QUEUE] Added '{artist} - {release_title}' ({release_year}) "
                    f"to download queue (favourited artist)"
                )
        except Exception as e:
            logging.warning(f"[AUTO-QUEUE] Failed to queue '{artist} - {release_title}': {e}")

    return queued_count


def _is_album_artist_in_collection(artist: str) -> bool:
    """Return True when artist appears as a canonical album artist in local collection."""
    if not artist:
        return False

    try:
        conn = get_db()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT 1
            FROM tracks
            WHERE LOWER(COALESCE(NULLIF(album_artist, ''), artist)) = LOWER(%s)
            LIMIT 1
        """, (artist,))
        exists = cursor.fetchone() is not None
        conn.close()
        return exists
    except Exception as exc:
        logging.debug(f"[AUTO-QUEUE] Could not verify album-artist status for '{artist}': {exc}")
        return False


def _auto_queue_missing_singles_for_album_artist(artist: str, missing_releases: list[dict]) -> int:
    """Auto-queue missing singles for album artists when the track is not already in collection."""
    if not artist or not missing_releases:
        return 0
    if not _is_album_artist_in_collection(artist):
        return 0

    existing_track_titles_norm = set()
    try:
        conn = get_db()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT DISTINCT title
            FROM tracks
            WHERE LOWER(COALESCE(NULLIF(album_artist, ''), artist)) = LOWER(%s)
               OR LOWER(artist) = LOWER(%s)
        """, (artist, artist))
        for row in (cursor.fetchall() or []):
            track_title = _row_get(row, 'title', index=0)
            norm_track_title = _normalize_release_title(track_title or "")
            if norm_track_title:
                existing_track_titles_norm.add(norm_track_title)
        conn.close()
    except Exception as exc:
        logging.warning("[AUTO-QUEUE] Could not load existing titles for '%s': %s", artist, exc)

    queued_count = 0
    seen_titles = set()
    from download_queue_manager import add_to_queue

    for release in missing_releases:
        title = (release.get("title") or "").strip()
        if not title:
            continue

        release_bucket = _derive_release_bucket(
            primary_type=release.get("primary_type") or "",
            category=release.get("category") or "",
            title=title,
        )
        if release_bucket != "single":
            continue

        norm_title = _normalize_release_title(title)
        if not norm_title or norm_title in seen_titles:
            continue
        seen_titles.add(norm_title)

        if norm_title in existing_track_titles_norm:
            logging.info(
                "[AUTO-QUEUE] Skipping missing single '%s - %s' because it already exists in collection",
                artist,
                title,
            )
            continue

        first_release_date = str(release.get("first_release_date") or "")
        release_year = first_release_date[:4] if len(first_release_date) >= 4 and first_release_date[:4].isdigit() else None

        try:
            result = add_to_queue(
                artist=artist,
                title=title,
                album=None,
                source="soulseek",
                priority=4,
                import_type="song",
                year=release_year,
                release_id=release.get("id") or release.get("release_id"),
                release_source="missing_release_single_auto",
            )
            if result and not bool(result.get("already_queued")):
                queued_count += 1
                logging.info("[AUTO-QUEUE] Added missing single '%s - %s'", artist, title)
        except Exception as exc:
            logging.warning("[AUTO-QUEUE] Failed queuing missing single '%s - %s': %s", artist, title, exc)

    return queued_count


def _auto_queue_collection_artist_singles_from_release_groups(artist: str, release_groups: list[dict]) -> int:
    """Auto-queue current-year singles for collection artists when no same-title album is present."""
    if not artist or not release_groups:
        return 0

    current_year = datetime.now().year
    album_titles_current_year = set()
    single_candidates = []
    existing_track_titles_norm = set()

    # Build a normalized title set for this artist so we only queue singles that are not already in collection.
    try:
        conn = get_db()
        cursor = conn.cursor()
        cursor.execute("""
            SELECT DISTINCT title
            FROM tracks
            WHERE LOWER(COALESCE(NULLIF(album_artist, ''), artist)) = LOWER(%s)
               OR LOWER(artist) = LOWER(%s)
        """, (artist, artist))
        for row in (cursor.fetchall() or []):
            track_title = _row_get(row, 'title', index=0)
            norm_track_title = _normalize_release_title(track_title or "")
            if norm_track_title:
                existing_track_titles_norm.add(norm_track_title)
        conn.close()
    except Exception as exc:
        logging.warning("[AUTO-QUEUE] Could not load existing track titles for '%s': %s", artist, exc)

    for rg in release_groups:
        primary_type = (rg.get("primary_type") or "").strip().lower()
        if primary_type not in ("album", "single"):
            continue

        parsed_date = _parse_musicbrainz_release_date(rg.get("first_release_date"))
        if not parsed_date or len(parsed_date) < 4 or not parsed_date[:4].isdigit():
            continue

        release_year = int(parsed_date[:4])
        if release_year != current_year:
            continue

        title = (rg.get("title") or "").strip()
        norm_title = _normalize_release_title(title)
        if not norm_title:
            continue

        secondary = [str(s).lower() for s in (rg.get("secondary_types") or []) if s]
        if "compilation" in secondary or "live" in secondary or "remix" in secondary:
            continue

        if primary_type == "album":
            album_titles_current_year.add(norm_title)
            continue

        single_candidates.append((title, norm_title, rg.get("id") or ""))

    if not single_candidates:
        return 0

    queued_count = 0
    from download_queue_manager import add_to_queue

    for title, norm_title, release_id in single_candidates:
        if norm_title in album_titles_current_year:
            continue
        if norm_title in existing_track_titles_norm:
            logging.info(
                "[AUTO-QUEUE] Skipping '%s - %s' because a matching track already exists in collection",
                artist,
                title,
            )
            continue

        try:
            result = add_to_queue(
                artist=artist,
                title=title,
                album=None,
                source="soulseek",
                priority=4,
                import_type="song",
                year=str(current_year),
                release_id=release_id or None,
                release_source="musicbrainz_daily_single",
            )
            if result:
                queued_count += 1
                logging.info(
                    "[AUTO-QUEUE] Added current-year single '%s - %s' to queue (collection artist)",
                    artist,
                    title,
                )
        except Exception as exc:
            logging.warning("[AUTO-QUEUE] Failed to queue single '%s - %s': %s", artist, title, exc)

    return queued_count


def api_create_essential_playlist():
    """Create an Essential Playlist for an artist using single detection logic"""
    data = request.json or {}
    artist_name = data.get("artist", "").strip()
    
    if not artist_name:
        return jsonify({"error": "Artist name required"}), 400
    
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Get all singles with high confidence
        # Handle boolean type in PostgreSQL vs integer in SQLite
        cursor.execute("""
                SELECT id, title, album, stars, score, single_confidence 
                FROM tracks 
                WHERE artist = %s AND is_single = TRUE
                ORDER BY
                    CASE single_confidence 
                        WHEN 'high' THEN 3
                        WHEN 'medium' THEN 2
                        WHEN 'low' THEN 1
                        ELSE 0
                    END DESC,
                    score DESC,
                    stars DESC
                LIMIT 50
            """, (artist_name,))
        
        singles = cursor.fetchall()
        conn.close()
        
        if not singles:
            return jsonify({"error": "No singles found for this artist"}), 404
        
        # Create playlist name
        playlist_name = f"{artist_name} - Essential"
        
        # For now, just return success - Navidrome playlist creation would go here
        logging.info(f"Created essential playlist for {artist_name} with {len(singles)} tracks")
        
        return jsonify({
            "success": True,
            "message": f"Created Essential Playlist with {len(singles)} tracks",
            "playlist_name": playlist_name,
            "track_count": len(singles)
        })
        
    except Exception as e:
        logging.error(f"Error creating essential playlist: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/artist/image")
def api_artist_image():
    """Get artist image from database cache, with AudioDB fallback for similar artists"""
    artist_name = request.args.get("name", "").strip()
    if not artist_name:
        return Response("", status=404)
    
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # First check artists table (populated by scans)
        cursor.execute(f"""
            SELECT image_url 
            FROM artists 
            WHERE LOWER(name) = LOWER({placeholder})
                AND image_url IS NOT NULL
                AND image_url != ''
            ORDER BY CASE WHEN name = {placeholder} THEN 0 ELSE 1 END
            LIMIT 1
        """, (artist_name, artist_name))
        row = cursor.fetchone()
        
        if row and row['image_url']:
            conn.close()
            logging.debug(f"[ARTIST IMAGE] Found image for {artist_name}")
            return redirect(row['image_url'])
        
        # Fall back to artist_images table (populated by manual image selection)
        try:
            cursor.execute(f"""
                SELECT image_url
                FROM artist_images
                WHERE LOWER(artist_name) = LOWER({placeholder})
                    AND image_url IS NOT NULL
                    AND image_url != ''
                LIMIT 1
            """, (artist_name,))
            img_row = cursor.fetchone()
            if img_row and img_row['image_url']:
                conn.close()
                logging.debug(f"[ARTIST IMAGE] Found image in artist_images for {artist_name}")
                return redirect(img_row['image_url'])
        except Exception as e:
            logging.debug(f"[ARTIST IMAGE] artist_images lookup failed for {artist_name}: {e}")
        
        # AudioDB fallback: try to fetch artist image from AudioDB and cache it
        try:
            from api_clients.audiodb import get_artist_fanart, DEFAULT_API_KEY
            image_url = get_artist_fanart(artist_name, api_key=DEFAULT_API_KEY, enabled=True)
            if image_url:
                # Cache the result in artist_images table for future requests
                try:
                    cursor.execute("""
                        INSERT INTO artist_images (artist_name, image_url, updated_at)
                        VALUES (%s, %s, CURRENT_TIMESTAMP)
                        ON CONFLICT (artist_name) DO UPDATE SET
                            image_url = EXCLUDED.image_url,
                            updated_at = CURRENT_TIMESTAMP
                    """, (artist_name, image_url))
                    conn.commit()
                except Exception as cache_err:
                    logging.debug(f"[ARTIST IMAGE] Failed to cache AudioDB image for {artist_name}: {cache_err}")
                conn.close()
                logging.debug(f"[ARTIST IMAGE] Found AudioDB image for {artist_name}")
                return redirect(image_url)
        except Exception as e:
            logging.debug(f"[ARTIST IMAGE] AudioDB fallback failed for {artist_name}: {e}")
        
        conn.close()
        logging.debug(f"[ARTIST IMAGE] No image for {artist_name} - run scan to fetch")
        
    except Exception as e:
        logging.error(f"[ARTIST IMAGE] Error fetching image for {artist_name}: {e}")
    
    # Return a lightweight placeholder instead of 404 to avoid noisy console errors.
    placeholder_svg = """<svg xmlns='http://www.w3.org/2000/svg' width='300' height='300' viewBox='0 0 300 300'>
<rect width='300' height='300' fill='#1b1b1b'/>
<circle cx='150' cy='110' r='48' fill='#7d7d7d'/>
<rect x='78' y='180' width='144' height='80' rx='40' fill='#7d7d7d'/>
</svg>"""
    response = Response(placeholder_svg, status=200, mimetype="image/svg+xml")
    response.headers["Cache-Control"] = "public, max-age=3600"
    return response


@app.route("/api/artist/search-images")
def api_artist_search_images():
    """Search for artist images on MusicBrainz, Discogs, or Spotify"""
    artist_name = request.args.get("name", "").strip()
    source = request.args.get("source", "musicbrainz").strip()
    
    if not artist_name:
        return jsonify({"error": "Artist name required"}), 400
    
    try:
        images = []
        
        if source == "musicbrainz":
            # Get artist MBID
            search_url = "https://musicbrainz.org/ws/2/artist"
            params = {"query": f'artist:"{artist_name}"', "fmt": "json", "limit": 5}
            headers = {"User-Agent": MUSICBRAINZ_USER_AGENT}
            
            resp = requests.get(search_url, params=params, headers=headers, timeout=10)
            resp.raise_for_status()
            data = resp.json()
            
            for artist in data.get("artists", [])[:5]:
                mbid = artist.get("id")
                if mbid:
                    # Try to get image from CAA
                    image_url = f"https://coverartarchive.org/artist/{mbid}/front-500"
                    images.append({"url": image_url, "source": "MusicBrainz CAA"})
        
        elif source == "discogs":
            # Search Discogs for artist
            from api_clients.discogs import DiscogsClient

            config_data, _ = _read_yaml(CONFIG_PATH)
            discogs_config = config_data.get("api_integrations", {}).get("discogs", {})
            discogs_token = discogs_config.get("token", "")

            client = DiscogsClient(discogs_token)
            # Discogs API does not have a direct 'search_artist', so use database/search with type=artist
            search_url = f"https://api.discogs.com/database/search"
            params = {"q": artist_name, "type": "artist", "per_page": 5}
            res = client.session.get(search_url, headers=client.headers, params=params, timeout=10)
            res.raise_for_status()
            results = res.json().get("results", [])
            for result in results[:5]:
                if result.get("thumb"):
                    images.append({"url": result["thumb"], "source": "Discogs"})
        
        
        return jsonify({"images": images})
        
    except Exception as e:
        logging.error(f"Error searching artist images: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({"error": str(e), "images": []}), 500


@app.route("/api/artist/set-image", methods=["POST"])
def api_artist_set_image():
    """Set custom artist image"""
    data = request.json or {}
    artist_name = data.get("artist", "").strip()
    image_url = data.get("image_url", "").strip()
    
    if not artist_name or not image_url:
        return jsonify({"error": "Artist name and image URL required"}), 400
    
    # Validate that image_url is a valid HTTP/HTTPS URL, not a data URI or other scheme
    if not image_url.startswith(('http://', 'https://')):
        return jsonify({"error": "Image URL must be a valid HTTP or HTTPS URL"}), 400
    
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        # Create artist_images table if it doesn't exist
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS artist_images (
                artist_name TEXT PRIMARY KEY,
                image_url TEXT NOT NULL,
                updated_at TEXT NOT NULL
            )
        """)
        
        # Insert or update with DB-aware upsert
        cursor.execute(f"""
            INSERT INTO artist_images (artist_name, image_url, updated_at)
            VALUES ({placeholder}, {placeholder}, CURRENT_TIMESTAMP)
            ON CONFLICT (artist_name) DO UPDATE SET
                image_url = EXCLUDED.image_url,
                updated_at = CURRENT_TIMESTAMP
        """, (artist_name, image_url))
        conn.commit()
        conn.close()
        
        return jsonify({"success": True, "message": "Artist image updated"})
        
    except Exception as e:
        logging.error(f"Error setting artist image: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/artist/update-ids", methods=["POST"])
def api_artist_update_ids():
    """Update artist IDs (Spotify, Last.fm, MusicBrainz, Discogs) for an artist"""
    try:
        data = request.get_json(silent=True) or {}

        def _clean_str(value):
            if value is None:
                return ""
            return str(value).strip()

        artist_name = _clean_str(data.get("artist"))
        spotify_id = _clean_str(data.get("spotify_artist_id"))
        lastfm_mbid = _clean_str(data.get("lastfm_artist_mbid"))
        musicbrainz_id = _clean_str(data.get("musicbrainz_artist_id"))
        discogs_id = _clean_str(data.get("discogs_artist_id"))
        
        if not artist_name:
            return jsonify({"error": "Missing artist name"}), 400
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Update all tracks for this artist with the new IDs
        # Only update non-NULL values
        updates = []
        params = []
        
        if spotify_id:
            updates.append(f"spotify_artist_id = {placeholder}")
            params.append(spotify_id)
        
        if lastfm_mbid:
            updates.append(f"lastfm_artist_mbid = {placeholder}")
            params.append(lastfm_mbid)
        
        if musicbrainz_id:
            updates.append(f"musicbrainz_artist_id = {placeholder}")
            params.append(musicbrainz_id)
        
        if discogs_id:
            updates.append(f"discogs_artist_id = {placeholder}")
            params.append(discogs_id)
        
        if updates:
            params.append(artist_name)
            query = f"UPDATE tracks SET {', '.join(updates)} WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder}"
            cursor.execute(query, params)
            conn.commit()
        
        conn.close()
        
        return jsonify({
            "success": True,
            "message": f"Artist IDs updated for {artist_name}",
            "updated": {
                "spotify_artist_id": spotify_id if spotify_id else None,
                "lastfm_artist_mbid": lastfm_mbid if lastfm_mbid else None,
                "musicbrainz_artist_id": musicbrainz_id if musicbrainz_id else None,
                "discogs_artist_id": discogs_id if discogs_id else None
            }
        })
    except Exception as e:
        logging.error(f"Error updating artist IDs: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/album/update-ids", methods=["POST"])
def api_album_update_ids():
    """Update album/release IDs for an album"""
    try:
        data = request.get_json()
        artist_name = data.get("artist")
        album_name = data.get("album")
        spotify_album_id = data.get("spotify_album_id", "").strip()
        musicbrainz_release_id = data.get("musicbrainz_release_id", "").strip()
        discogs_release_id = data.get("discogs_release_id", "").strip()
        
        if not artist_name or not album_name:
            return jsonify({"error": "Missing artist or album name"}), 400
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        # Use canonical MusicBrainz album MBID column.
        track_columns = _get_table_columns(cursor, "tracks") or set()

        mb_album_column = "musicbrainz_album_mbid" if "musicbrainz_album_mbid" in track_columns else None

        discogs_album_column = None
        if "discogs_album_id" in track_columns:
            discogs_album_column = "discogs_album_id"
        elif "discogs_release_id" in track_columns:
            discogs_album_column = "discogs_release_id"
        
        # Update all tracks for this album with the new IDs
        updates = []
        params = []
        
        if spotify_album_id:
            updates.append(f"spotify_album_id = {placeholder}")
            params.append(spotify_album_id)
        
        if musicbrainz_release_id:
            if mb_album_column:
                updates.append(f"{mb_album_column} = {placeholder}")
                params.append(musicbrainz_release_id)
            else:
                logging.warning("Skipping MusicBrainz release ID update: no MB album ID column found in tracks table")
        
        if discogs_release_id:
            if discogs_album_column:
                updates.append(f"{discogs_album_column} = {placeholder}")
                params.append(discogs_release_id)
            else:
                logging.warning("Skipping Discogs release ID update: no Discogs album ID column found in tracks table")
        
        if updates:
            params.extend([artist_name, album_name])
            query = (
                f"UPDATE tracks SET {', '.join(updates)} "
                f"WHERE COALESCE(NULLIF(album_artist, ''), artist) = {placeholder} "
                f"AND album = {placeholder}"
            )
            cursor.execute(query, params)
            conn.commit()
        
        conn.close()
        
        return jsonify({
            "success": True,
            "message": f"Album IDs updated for {album_name}",
            "updated": {
                "spotify_album_id": spotify_album_id if spotify_album_id else None,
                "musicbrainz_release_id": musicbrainz_release_id if musicbrainz_release_id else None,
                "discogs_release_id": discogs_release_id if discogs_release_id else None
            }
        })
    except Exception as e:
        logging.error(f"Error updating album IDs: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/album/bulk-delete", methods=["POST"])
def api_album_bulk_delete():
    """Delete multiple tracks from database and optionally delete MP3 files"""
    try:
        data = request.get_json()
        track_ids = data.get("track_ids", [])
        artist = data.get("artist", "")
        album = data.get("album", "")
        delete_files = data.get("delete_files", True)  # Default to true for backward compatibility
        
        if not track_ids:
            return jsonify({"error": "No tracks selected"}), 400
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        deleted_count = 0
        
        for track_id in track_ids:
            try:
                # Get file path
                cursor.execute(
                    f"SELECT file_path FROM tracks WHERE id = {placeholder}",
                    (track_id,)
                )
                result = cursor.fetchone()
                
                if result:
                    # Delete MP3 file if requested and it exists
                    if delete_files:
                        # Try beets_path first, then file_path
                        file_path = row_get(result, 'file_path')
                        
                        if file_path and os.path.exists(file_path):
                            try:
                                os.remove(file_path)
                                logging.info(f"[DELETE] Deleted MP3 file: {file_path}")
                            except Exception as e:
                                logging.warning(f"[DELETE] Failed to delete MP3: {file_path} - {e}")
                    
                    # Delete from database
                    cursor.execute(f"DELETE FROM tracks WHERE id = {placeholder}", (track_id,))
                    deleted_count += 1
                    action = "and file(s)" if delete_files else "from database"
                    logging.info(f"[DELETE] Deleted track {track_id} {action}")
            except Exception as e:
                logging.error(f"[DELETE] Error deleting track {track_id}: {e}")
                continue
        
        conn.commit()
        conn.close()
        
        return jsonify({
            "success": True,
            "deleted_count": deleted_count,
            "message": f"Deleted {deleted_count} track(s) and file(s)"
        })
    except Exception as e:
        logging.error(f"[DELETE] Error in bulk delete: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/album/bulk-tag", methods=["POST"])
def api_album_bulk_tag():
    """Add genre tags to multiple tracks and write to audio files"""
    try:
        data = request.get_json()
        track_ids = data.get("track_ids", [])
        genres = data.get("genres", [])
        artist = data.get("artist", "")
        album = data.get("album", "")
        
        if not track_ids:
            return jsonify({"error": "No tracks selected"}), 400
        
        if not genres:
            return jsonify({"error": "No genres provided"}), 400
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        updated_count = 0
        failed_files = []
        genre_str = ", ".join(genres)
        # Format for ID3 tags (double backslash separated)
        genre_id3_str = '\\'.join(genres)
        
        # Check if mutagen is available (imported at module level)
        has_mutagen = MP3 is not None and FLAC is not None and ID3 is not None
        
        for track_id in track_ids:
            try:
                # Get track info
                placeholder = "%s"
                cursor.execute(f"SELECT title, genres, beets_path, file_path FROM tracks WHERE id = {placeholder}", (track_id,))
                result = cursor.fetchone()
                
                if result:
                    current_genres = row_get(result, 'genres') or ''
                    # Parse existing genres (handle both comma-separated and double-backslash formats)
                    if '\\' in current_genres:
                        existing = set(g.strip() for g in current_genres.split('\\') if g.strip())
                    else:
                        existing = set(g.strip() for g in current_genres.split(',') if g.strip())
                    # Add new genres
                    existing.update(genres)
                    # Join back for database (comma-separated for display)
                    new_genres = ', '.join(sorted(existing))
                    # Format for ID3 tags (double backslash separated)
                    genre_id3_final = '\\'.join(sorted(existing))
                    
                    # Write to audio file if mutagen is available
                    if has_mutagen:
                        file_path = row_get(result, 'beets_path') or row_get(result, 'file_path')
                        if file_path and os.path.exists(file_path):
                            try:
                                # Determine file format and handle accordingly
                                file_ext = os.path.splitext(file_path)[1].lower()
                                
                                if file_ext == '.mp3':
                                    # Handle MP3 files with ID3 tags
                                    audio = MP3(file_path, ID3=ID3)
                                    if audio.tags is None:
                                        audio.add_tags()
                                    # Write with double backslash format for ID3 tags
                                    audio.tags['TCON'] = TagCON(encoding=3, text=[genre_id3_final])
                                    audio.save()
                                    logging.info(f"[TAG] Updated MP3 tags for {file_path}: {genre_id3_final}")
                                elif file_ext == '.flac':
                                    # Handle FLAC files with Vorbis comments
                                    audio = FLAC(file_path)
                                    # FLAC uses vorbis comments, which support multiple genre values
                                    audio['genre'] = sorted(existing)
                                    audio.save()
                                    logging.info(f"[TAG] Updated FLAC tags for {file_path}: {', '.join(sorted(existing))}")
                                else:
                                    # For unsupported formats, only update database
                                    logging.debug(f"[TAG] Skipping file tag update for unsupported format: {file_path}")
                            except Exception as file_error:
                                logging.warning(f"[TAG] Failed to update tags for {file_path}: {file_error}")
                                track_title = row_get(result, 'title', '')
                                failed_files.append(track_title if track_title else f"Track ID: {track_id}")
                    
                    # Update database (store comma-separated for display)
                    cursor.execute(f"""
                        UPDATE tracks SET genres = {placeholder} WHERE id = {placeholder}
                    """, (new_genres, track_id))
                    
                    updated_count += 1
                    logging.info(f"[TAG] Added genres to track {track_id}: {new_genres}")
            except Exception as e:
                logging.error(f"[TAG] Error tagging track {track_id}: {e}")
                continue
        
        conn.commit()
        conn.close()
        
        response = {
            "success": True,
            "updated_count": updated_count,
            "genres": genres,
            "message": f"Added {len(genres)} genre(s) to {updated_count} track(s)"
        }
        
        if failed_files:
            response["warning"] = f"⚠️ Failed to update audio tags for: {', '.join(failed_files[:5])}{'...' if len(failed_files) > 5 else ''}"
        elif not has_mutagen:
            response["warning"] = "ℹ️ Genres updated in database. Install mutagen (pip install mutagen) to update audio files."
        
        return jsonify(response)
    except Exception as e:
        logging.error(f"[TAG] Error in bulk tag: {e}")
        return jsonify({"error": str(e)}), 500


