def _similar_artist_name(entry):
    """Extract artist name from a similar artists entry (string or dict)."""
    if isinstance(entry, str):
        return entry.strip()
    if isinstance(entry, dict):
        return str(entry.get("name") or entry.get("artist") or "").strip()
    return ""


def _get_artists_in_collection(cursor, names, placeholder):
    """Return a set of lowercased artist names that exist in the tracks table."""
    if not names:
        return set()
    names = [n for n in names if n]
    if not names:
        return set()
    # Build parameterized IN clause
    in_clause = ", ".join([placeholder] * len(names))
    try:
        cursor.execute(f"""
            SELECT DISTINCT COALESCE(NULLIF(album_artist, ''), artist) AS artist_name
            FROM tracks
            WHERE LOWER(COALESCE(NULLIF(album_artist, ''), artist)) IN ({in_clause})
        """, [n.lower() for n in names])
        rows = cursor.fetchall()
        get_name = lambda row: row["artist_name"] if isinstance(row, dict) else row[0]
        return {get_name(row).lower() for row in rows if get_name(row)}
    except Exception:
        return set()


def _annotate_in_collection(artists, in_collection_set):
    """Add in_collection flag to each artist entry."""
    result = []
    for entry in artists:
        if isinstance(entry, str):
            name = entry.strip()
            result.append({"name": name, "in_collection": name.lower() in in_collection_set})
        elif isinstance(entry, dict):
            name = str(entry.get("name") or entry.get("artist") or "").strip()
            annotated = dict(entry)
            annotated["in_collection"] = name.lower() in in_collection_set
            result.append(annotated)
    return result


@app.route("/api/artist/<path:artist>/similar", methods=["GET"])
def api_get_similar_artists(artist):
    """Get similar artists for a given artist (from Last.fm and ListenBrainz)
    
    If data exists in database, return it immediately.
    If not, fetch from APIs, cache in database, and return.
    """
    try:
        from urllib.parse import unquote
        import json
        import requests
        
        artist = unquote(artist)
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Get similar artists from database
        cursor.execute(f"""
            SELECT similar_artists_lastfm, similar_artists_listenbrainz
            FROM artists
            WHERE name = {placeholder}
            LIMIT 1
        """, (artist,))
        
        row = cursor.fetchone()
        
        # Parse JSON arrays (support both tuple rows and dict rows)
        similar_lastfm_raw = None
        similar_listenbrainz_raw = None
        
        if row:
            similar_lastfm_raw = row.get("similar_artists_lastfm") if isinstance(row, dict) else row[0]
            similar_listenbrainz_raw = row.get("similar_artists_listenbrainz") if isinstance(row, dict) else row[1]

        similar_lastfm = []
        similar_listenbrainz = []

        try:
            if similar_lastfm_raw:
                similar_lastfm = json.loads(similar_lastfm_raw) if isinstance(similar_lastfm_raw, str) else similar_lastfm_raw
        except Exception:
            pass

        try:
            if similar_listenbrainz_raw:
                similar_listenbrainz = json.loads(similar_listenbrainz_raw) if isinstance(similar_listenbrainz_raw, str) else similar_listenbrainz_raw
        except Exception:
            pass
        
        # If we have data, annotate with in_collection and return it
        if similar_lastfm or similar_listenbrainz:
            in_collection = _get_artists_in_collection(
                cursor,
                [_similar_artist_name(a) for a in similar_lastfm[:10] + similar_listenbrainz[:10]],
                placeholder
            )
            conn.close()
            return jsonify({
                "success": True,
                "artist": artist,
                "similar_artists": {
                    "lastfm": _annotate_in_collection(similar_lastfm[:10], in_collection),
                    "listenbrainz": _annotate_in_collection(similar_listenbrainz[:10], in_collection)
                },
                "cached": True
            })
        
        # By default, do not perform live network fetches during page load.
        # This endpoint is called by track/album/artist pages and should return fast.
        allow_live_fetch = str(request.args.get("allow_live", "0")).strip().lower() in {"1", "true", "yes", "on"}
        if not allow_live_fetch:
            conn.close()
            return jsonify({
                "success": True,
                "artist": artist,
                "similar_artists": {
                    "lastfm": [],
                    "listenbrainz": []
                },
                "cached": False,
                "live_fetch_skipped": True,
                "message": "No cached similar artists yet. Run a popularity scan to populate caches, or call with allow_live=1."
            })

        # No cached data and live fetch explicitly requested - fetch from APIs
        logging.info(f"[SIMILAR ARTISTS] No cached data for {artist}, fetching from APIs (allow_live=1)...")
        
        # Fetch from Last.fm
        try:
            cfg = get_config()
            api_integrations = cfg.get("api_integrations", {})
            lastfm_config = api_integrations.get("lastfm", api_integrations.get("last_fm", {}))
            
            if lastfm_config.get("enabled") and lastfm_config.get("api_key"):
                api_key = lastfm_config.get("api_key")
                if api_key not in ["your_lastfm_api_key", "YOUR_API_KEY", "<your_api_key>", ""]:
                    from api_clients.lastfm import LastFmClient
                    lastfm_client = LastFmClient(api_key)
                    
                    try:
                        similar_lastfm = lastfm_client.get_similar_artists(artist, limit=10)
                        if similar_lastfm:
                            logging.info(f"[SIMILAR ARTISTS] Found {len(similar_lastfm)} from Last.fm")
                    except Exception as e:
                        logging.debug(f"[SIMILAR ARTISTS] Last.fm fetch failed: {e}")
        except Exception as e:
            logging.debug(f"[SIMILAR ARTISTS] Last.fm API error: {e}")
        
        # Fetch from ListenBrainz (requires artist MBID)
        try:
            from api_clients.musicbrainz import MusicBrainzClient
            mb_client = MusicBrainzClient()
            
            # Try to get artist MBID
            artist_mbid, confidence = mb_client.get_suggested_mbid(
                title=artist,
                artist="",
                limit=1
            )
            
            if artist_mbid:
                logging.debug(f"[SIMILAR ARTISTS] Found MBID {artist_mbid} for {artist}")
                
                # Fetch from ListenBrainz
                lb_url = "https://labs.api.listenbrainz.org/similar-artists/json"
                params = {"artist_mbids": artist_mbid}
                
                lb_response = requests.get(lb_url, params=params, timeout=(5, 10))
                lb_response.raise_for_status()
                lb_results = lb_response.json()
                
                if lb_results and "payload" in lb_results:
                    similar_records = lb_results.get("payload", {}).get("artists", [])
                    
                    if similar_records:
                        similar_listenbrainz = [
                            {
                                "name": record.get("artist_name", ""),
                                "mbid": record.get("artist_mbid", "")
                            }
                            for record in similar_records[:10]
                        ]
                        logging.info(f"[SIMILAR ARTISTS] Found {len(similar_listenbrainz)} from ListenBrainz")
        except Exception as e:
            logging.debug(f"[SIMILAR ARTISTS] ListenBrainz fetch failed: {e}")
        
        # Store in database if we fetched anything
        if similar_lastfm or similar_listenbrainz:
            try:
                cursor.execute(f"""
                    INSERT INTO artists (id, name, similar_artists_lastfm, similar_artists_listenbrainz, similar_artists_last_updated)
                    VALUES ({placeholder}, {placeholder}, {placeholder}, {placeholder}, {placeholder})
                    ON CONFLICT(id) DO UPDATE SET 
                        similar_artists_lastfm = excluded.similar_artists_lastfm,
                        similar_artists_listenbrainz = excluded.similar_artists_listenbrainz,
                        similar_artists_last_updated = excluded.similar_artists_last_updated
                """, (
                    artist,
                    artist,
                    json.dumps(similar_lastfm) if similar_lastfm else None,
                    json.dumps(similar_listenbrainz) if similar_listenbrainz else None,
                    datetime.now().isoformat()
                ))
                conn.commit()
                logging.info(f"[SIMILAR ARTISTS] Cached data for {artist}")
            except Exception as e:
                logging.warning(f"[SIMILAR ARTISTS] Failed to cache data: {e}")
        
        # Annotate with in_collection before returning
        if similar_lastfm or similar_listenbrainz:
            in_collection = _get_artists_in_collection(
                cursor,
                [_similar_artist_name(a) for a in similar_lastfm[:10] + similar_listenbrainz[:10]],
                placeholder
            )
        else:
            in_collection = set()

        conn.close()
        
        return jsonify({
            "success": True,
            "artist": artist,
            "similar_artists": {
                "lastfm": _annotate_in_collection(similar_lastfm[:10], in_collection),
                "listenbrainz": _annotate_in_collection(similar_listenbrainz[:10], in_collection)
            },
            "cached": False
        })
    
    except Exception as e:
        logging.error(f"[SIMILAR ARTISTS] Error getting similar artists: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/library/artists/similar", methods=["GET"])
def api_library_similar_artists():
    """Get aggregated similar artists from all artists in the user's collection"""
    try:
        import json
        from collections import defaultdict
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Get all artists with their similar artists
        cursor.execute("""
            SELECT name, similar_artists_lastfm, similar_artists_listenbrainz
            FROM artists
            WHERE similar_artists_lastfm IS NOT NULL OR similar_artists_listenbrainz IS NOT NULL
            ORDER BY name
        """)
        
        rows = cursor.fetchall()
        
        similar_cache = {}
        
        for row in rows:
            artist_name = row.get("name") if isinstance(row, dict) else row[0]
            similar_lastfm = row.get("similar_artists_lastfm") if isinstance(row, dict) else row[1]
            similar_listenbrainz = row.get("similar_artists_listenbrainz") if isinstance(row, dict) else row[2]

            # Process Last.fm similar artists
            if similar_lastfm:
                try:
                    artists = json.loads(similar_lastfm) if isinstance(similar_lastfm, str) else similar_lastfm
                    for similar in artists:
                        if isinstance(similar, str):
                            name = similar.strip()
                            match_value = 0
                        elif isinstance(similar, dict):
                            name = str(similar.get('name', '')).strip()
                            match_value = float(similar.get('match', 0) or 0)
                        else:
                            continue

                        if name and name != artist_name:
                            key = name.lower()
                            if key not in similar_cache:
                                similar_cache[key] = {'name': name, 'count': 0, 'match': 0, 'from_artists': set()}
                            similar_cache[key]['count'] += 1
                            similar_cache[key]['match'] += match_value
                            similar_cache[key]['from_artists'].add(artist_name)
                except Exception:
                    pass

            # Process ListenBrainz similar artists
            if similar_listenbrainz:
                try:
                    artists = json.loads(similar_listenbrainz) if isinstance(similar_listenbrainz, str) else similar_listenbrainz
                    for similar in artists:
                        if isinstance(similar, str):
                            name = similar.strip()
                        elif isinstance(similar, dict):
                            name = str(similar.get('name', '')).strip()
                        else:
                            continue

                        if name and name != artist_name:
                            key = name.lower()
                            if key not in similar_cache:
                                similar_cache[key] = {'name': name, 'count': 0, 'match': 0, 'from_artists': set()}
                            similar_cache[key]['count'] += 1
                            similar_cache[key]['from_artists'].add(artist_name)
                except Exception:
                    pass

        # Check which similar artists are in the collection
        placeholder = "%s"
        all_names = list(similar_cache.keys())
        in_collection = _get_artists_in_collection(cursor, [similar_cache[k]['name'] for k in all_names], placeholder)
        conn.close()

        # Format results
        results = []
        for key, data in similar_cache.items():
            count = data.get('count', 0)
            match = data.get('match', 0)
            avg_match = (match / count) if count > 0 else 0
            from_artists = data.get('from_artists', set())
            
            results.append({
                'name': data['name'],
                'count': count,
                'match': avg_match,
                'from_artists': sorted(from_artists),
                'in_collection': data['name'].lower() in in_collection
            })
        
        # Sort by frequency then by match score
        results.sort(key=lambda x: (-x['count'], -x['match']))
        
        # Limit results
        results = results[:100]
        
        return jsonify({
            "success": True,
            "similar_artists": results,
            "total_similar": len(results)
        })
    
    except Exception as e:
        logging.error(f"[LIBRARY SIMILAR] Error aggregating similar artists: {e}")
        return jsonify({"error": str(e)}), 500


