@app.route("/track/<track_id>")
def track_detail(track_id):
    """View and edit track details"""
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        cursor.execute(f"SELECT * FROM tracks WHERE id = {placeholder}", (track_id,))
        track = cursor.fetchone()
        
        if not track:
            conn.close()
            flash("Track not found", "error")
            return redirect(url_for("dashboard"))
        
        # Convert Row to dict to ensure all columns are accessible
        track = dict(track)
        
        # Parse genre fields - handle both JSON and comma-separated formats
        for genre_field in ['navidrome_genres', 'spotify_genres', 'lastfm_tags', 'discogs_genres', 'musicbrainz_genres']:
            if genre_field in track and track[genre_field]:
                genre_val = track[genre_field]
                try:
                    # Try to parse as JSON first
                    if isinstance(genre_val, str) and genre_val.startswith('['):
                        import json as json_module
                        parsed = json_module.loads(genre_val)
                        # Convert list to comma-separated string for template
                        if isinstance(parsed, list):
                            track[genre_field] = ", ".join([g.strip() for g in parsed if g.strip()])
                    # Handle backslash-separated strings (from Navidrome)
                    elif isinstance(genre_val, str) and '\\' in genre_val:
                        # Replace backslashes with commas for consistent display
                        track[genre_field] = genre_val.replace('\\', ',')
                    # Otherwise leave as-is (already comma-separated or string)
                except Exception:
                    pass  # Keep original value if parsing fails
        
        # Parse writer field (JSON array from Navidrome lyricist field)
        if 'writer' in track and track['writer']:
            writer_val = track['writer']
            try:
                if isinstance(writer_val, str) and writer_val.startswith('['):
                    import json as json_module
                    parsed = json_module.loads(writer_val)
                    if isinstance(parsed, list):
                        track['writer'] = ", ".join([w.strip() for w in parsed if w.strip()])
            except Exception:
                pass  # Keep original value if parsing fails

        # Parse single_sources JSON array into a Python list for the template
        try:
            import json as json_module
            sources_raw = track.get('single_sources')
            if sources_raw and isinstance(sources_raw, str):
                track['single_sources_list'] = json_module.loads(sources_raw)
            elif isinstance(sources_raw, list):
                track['single_sources_list'] = sources_raw
            else:
                track['single_sources_list'] = []
        except Exception:
            track['single_sources_list'] = []

        # Get recommended genres from other tracks with similar titles or artists
        recommended_genres = []
        artist_name = track.get('artist', '')
        if artist_name:
            cursor.execute(f"""
                SELECT genres FROM tracks 
                WHERE artist = {placeholder} AND genres IS NOT NULL AND genres != ''
                LIMIT 10
            """, (artist_name,))
            genre_rows = cursor.fetchall()
            genre_set = set()
            for row in genre_rows:
                if row['genres']:
                    # Parse comma-separated genres
                    genres = [g.strip() for g in row['genres'].split(',') if g.strip()]
                    genre_set.update(genres)
            recommended_genres = sorted(list(genre_set))

        # Check favourite status for this track
        is_track_favourite = False
        try:
            cursor.execute(f"""
                SELECT 1
                FROM bookmarks
                WHERE type = {placeholder}
                  AND track_id = {placeholder}
                LIMIT 1
            """, ("track", track_id))
            is_track_favourite = cursor.fetchone() is not None
        except Exception as fav_err:
            logging.debug(f"Track favourite check failed for {track_id}: {fav_err}")
        
        conn.close()
        
        # Load config for template
        try:
            cfg = get_config()
            qbit_config = cfg.get("qbittorrent", {"enabled": False, "web_url": "http://localhost:8080"})
            slskd_config = cfg.get("slskd", {"enabled": False})
        except Exception as e:
            logging.warning(f"Could not load config for track template: {e}")
            qbit_config = {"enabled": False, "web_url": "http://localhost:8080"}
            slskd_config = {"enabled": False}
        
        return render_template("track.html", track=track, recommended_genres=recommended_genres, track_id=track_id,
                     is_track_favourite=is_track_favourite,
                             qbit_config=qbit_config, slskd_config=slskd_config)
    
    except Exception as e:
        logging.error(f"Error loading track {track_id}: {e}")
        import traceback
        logging.error(traceback.format_exc())
        flash(f"Error loading track: {str(e)}", "error")
        return redirect(url_for("dashboard"))


@app.route("/track/<track_id>/edit", methods=["POST"])
def track_edit(track_id):
    """Update track metadata and write to audio file"""
    conn = get_db()
    cursor = conn.cursor()
    placeholder = "%s"
    
    # Get form data - ensure all string fields have defaults to avoid None when calling .strip()
    title = request.form.get("title", "").strip() or None
    artist = request.form.get("artist", "").strip() or None
    album = request.form.get("album", "").strip() or None
    album_artist = request.form.get("album_artist", "").strip() or None
    stars = request.form.get("stars", type=int)
    # is_single is now a dropdown ("true"/"false") but also accept legacy "on" checkbox value
    is_single_raw = request.form.get("is_single", "false")
    is_single = is_single_raw in ("true", "on", "1", "yes")
    single_confidence = request.form.get("single_confidence", "low")
    mbid = request.form.get("mbid", "").strip() or None
    suggested_mbid = request.form.get("suggested_mbid", "").strip() or None
    suggested_mbid_confidence = request.form.get("suggested_mbid_confidence", type=float)
    
    # All MP3 metadata fields
    genres = request.form.get("genres", "").strip() or None
    year = request.form.get("year", "").strip() or None
    composer = request.form.get("composer", "").strip() or None
    writer = request.form.get("writer", "").strip() or None
    arranger = request.form.get("arranger", "").strip() or None
    mixer = request.form.get("mixer", "").strip() or None
    producer = request.form.get("producer", "").strip() or None
    work = request.form.get("work", "").strip() or None
    track_number = request.form.get("track_number", "").strip() or None
    disc_number = request.form.get("disc_number", type=int) or None
    comment = request.form.get("comment", "").strip() or None
    isrc = request.form.get("isrc", "").strip() or None
    bpm = request.form.get("bpm", type=int) or None
    bitrate = request.form.get("bitrate", type=int) or None
    sample_rate = request.form.get("sample_rate", type=int) or None
    
    # Flags
    is_cover = request.form.get("is_cover") == "on"
    cover_manual_override = request.form.get("cover_manual_override") == "on"
    alternate_take = request.form.get("alternate_take") == "on"
    is_compilation = request.form.get("is_compilation") == "on"

    # Persist feature flags according to DB schema (BOOLEAN vs INTEGER/BIGINT).
    normalized_flags = _normalize_track_flag_payload(conn, {
        'is_single': is_single,
        'is_cover': is_cover,
        'cover_manual_override': cover_manual_override,
        'alternate_take': alternate_take,
        'is_compilation': is_compilation,
        'single_manual_override': True,
    })
    is_single_db = normalized_flags.get('is_single')
    is_cover_db = normalized_flags.get('is_cover')
    cover_manual_override_db = normalized_flags.get('cover_manual_override')
    alternate_take_db = normalized_flags.get('alternate_take')
    is_compilation_db = normalized_flags.get('is_compilation')
    single_manual_override_db = normalized_flags.get('single_manual_override')
    
    # First, get the file path from database
    cursor.execute(f"SELECT file_path FROM tracks WHERE id = {placeholder}", (track_id,))
    file_result = cursor.fetchone()
    file_path = file_result["file_path"] if file_result else None
    
    # Update database with PostgreSQL syntax
    file_write_success = False
    try:
        cursor.execute(f"""
            UPDATE tracks
            SET title = {placeholder}, artist = {placeholder}, album = {placeholder}, album_artist = {placeholder}, stars = {placeholder}, 
                is_single = {placeholder}, single_confidence = {placeholder},
                mbid = {placeholder}, suggested_mbid = {placeholder}, suggested_mbid_confidence = {placeholder},
                genres = {placeholder}, year = {placeholder}, composer = {placeholder}, writer = {placeholder}, 
                arranger = {placeholder}, mixer = {placeholder}, producer = {placeholder}, work = {placeholder},
                track_number = {placeholder}, disc_number = {placeholder}, comment = {placeholder}, isrc = {placeholder},
                bpm = {placeholder}, bitrate = {placeholder}, sample_rate = {placeholder},
                is_cover = {placeholder}, cover_manual_override = {placeholder},
                alternate_take = {placeholder}, is_compilation = {placeholder},
                single_manual_override = {placeholder}
            WHERE id = {placeholder}
        """, (title, artist, album, album_artist, stars, 
              is_single_db, single_confidence,
              mbid, suggested_mbid, suggested_mbid_confidence,
              genres, year, composer, writer, 
              arranger, mixer, producer, work,
              track_number, disc_number, comment, isrc,
              bpm, bitrate, sample_rate,
              is_cover_db, cover_manual_override_db,
              alternate_take_db, is_compilation_db, single_manual_override_db,
              track_id))
        
        conn.commit()
        
        # Now write tags to audio file if file path exists
        if file_path:
            try:
                from helpers.tag_manager import write_tags_to_file

                def _resolve_music_file_path(path_value):
                    if not path_value:
                        return None
                    raw_path = str(path_value).strip()
                    if not raw_path:
                        return None
                    candidates = [raw_path]
                    if not os.path.isabs(raw_path):
                        roots = [
                            os.environ.get("MUSIC_FOLDER"),
                            os.environ.get("MUSIC_ROOT"),
                            os.environ.get("MUSIC_DIR"),
                            "/music",
                        ]
                        seen = set()
                        for root in roots:
                            if not root:
                                continue
                            root_text = str(root).strip()
                            if not root_text:
                                continue
                            candidate = os.path.join(root_text, raw_path)
                            if candidate not in seen:
                                candidates.append(candidate)
                                seen.add(candidate)
                    for candidate in candidates:
                        if os.path.exists(candidate):
                            return candidate
                    return None

                resolved_file_path = _resolve_music_file_path(file_path)
                if not resolved_file_path:
                    flash_result_panel(
                        "Track metadata update completed with missing file",
                        category="warning",
                        summary=f"Updated '{title or 'Unknown'}' in the database, but the audio file could not be found on disk.",
                        stats=[
                            {"label": "Track", "value": title or 'Unknown'},
                            {"label": "File updated", "value": "No"},
                        ],
                        sections=[{
                            "title": "Missing file path",
                            "items": [str(file_path)],
                        }],
                    )
                    return redirect(url_for("track_detail", track_id=track_id))
                
                # Prepare tags dictionary
                tags_to_write = {}
                if title:
                    tags_to_write["title"] = title
                if artist:
                    tags_to_write["artist"] = artist
                if album:
                    tags_to_write["album"] = album
                if album_artist:
                    tags_to_write["album_artist"] = album_artist
                if genres:
                    tags_to_write["genre"] = genres
                if year:
                    tags_to_write["year"] = year
                if composer:
                    tags_to_write["composer"] = composer
                if writer:
                    tags_to_write["writer"] = writer
                if arranger:
                    tags_to_write["arranger"] = arranger
                if mixer:
                    tags_to_write["mixer"] = mixer
                if producer:
                    tags_to_write["producer"] = producer
                if work:
                    tags_to_write["work"] = work
                if track_number:
                    tags_to_write["track_number"] = int(track_number.split("/")[0]) if "/" in str(track_number) else (int(track_number) if str(track_number).isdigit() else track_number)
                if disc_number:
                    tags_to_write["disc_number"] = disc_number
                if comment:
                    tags_to_write["comment"] = comment
                if mbid:
                    tags_to_write["mbid"] = mbid
                if isrc:
                    tags_to_write["isrc"] = isrc
                if bpm:
                    tags_to_write["bpm"] = bpm
                
                # Write to file
                file_write_success = write_tags_to_file(resolved_file_path, tags_to_write)
                
                if file_write_success:
                    flash_result_panel(
                        "Track metadata update completed",
                        category="success",
                        summary=f"Updated '{title or 'Unknown'}' in the database and wrote tags to the audio file.",
                        stats=[
                            {"label": "Track", "value": title or 'Unknown'},
                            {"label": "File updated", "value": "Yes"},
                        ],
                    )
                else:
                    flash_result_panel(
                        "Track metadata update completed with file write failure",
                        category="warning",
                        summary=f"Updated '{title or 'Unknown'}' in the database, but the audio file could not be updated.",
                        stats=[
                            {"label": "Track", "value": title or 'Unknown'},
                            {"label": "File updated", "value": "No"},
                        ],
                        sections=[{
                            "title": "Failed file",
                            "items": [str(resolved_file_path)],
                        }],
                    )
            except ImportError as e:
                logging.warning(f"Tag manager import failed: {e}")
                flash_result_panel(
                    "Track metadata update completed",
                    category="info",
                    summary=f"Updated '{title or 'Unknown'}' in the database. File tag writing is unavailable.",
                    stats=[
                        {"label": "Track", "value": title or 'Unknown'},
                        {"label": "File updated", "value": "Unavailable"},
                    ],
                    sections=[{
                        "title": "Tag writer unavailable",
                        "items": [str(e)],
                    }],
                )
        else:
            flash_result_panel(
                "Track metadata update completed",
                category="info",
                summary=f"Updated '{title or 'Unknown'}' in the database. No file path was available for file tag writing.",
                stats=[
                    {"label": "Track", "value": title or 'Unknown'},
                    {"label": "File updated", "value": "No path"},
                ],
            )
            
    except Exception as e:
        conn.rollback()
        logging.error(f"Error updating track: {e}")
        flash_result_panel(
            "Track metadata update failed",
            category="danger",
            summary="The track could not be updated.",
            sections=[{
                "title": "Error",
                "items": [str(e)],
            }],
        )
    finally:
        conn.close()
    
    return redirect(url_for("track_detail", track_id=track_id))


@app.route("/api/track/<track_id>/toggle-manual-single", methods=["POST"])
def api_toggle_manual_single(track_id):
    """Toggle single_manual_override flag for a track (prevents auto-detection from overwriting)"""
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Get current value
        placeholder = "%s"
        cursor.execute(f"SELECT single_manual_override FROM tracks WHERE id = {placeholder}", (track_id,))
        result = cursor.fetchone()
        
        if not result:
            return jsonify({"error": "Track not found"}), 404
        
        current_value = result[0] or 0
        new_value = 1 - current_value  # Toggle between 0 and 1
        
        # Update
        cursor.execute(
            f"UPDATE tracks SET single_manual_override = {placeholder} WHERE id = {placeholder}",
            (new_value, track_id)
        )
        conn.commit()
        conn.close()
        
        return jsonify({
            "success": True,
            "track_id": track_id,
            "single_manual_override": new_value,
            "message": f"Single manual override {'enabled' if new_value else 'disabled'} - single detection scan will {'skip' if new_value else 'process'} this track"
        })
    except Exception as e:
        logging.error(f"Error toggling manual single flag: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/track/<track_id>/rescan-single", methods=["POST"])
def api_rescan_single_track(track_id):
    """Force a fresh single detection scan for one track on the next popularity run.

    Clears single_detection_last_updated so the next popularity scan re-evaluates
    this track regardless of the normal TTL cache.  Optionally accepts a ``source``
    body param for UI display purposes (ignored at runtime — all sources are checked).
    """
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        cursor.execute(f"SELECT id, title, artist FROM tracks WHERE id = {placeholder}", (track_id,))
        row = cursor.fetchone()
        if not row:
            conn.close()
            return jsonify({"error": "Track not found"}), 404

        cursor.execute(
            f"UPDATE tracks SET single_detection_last_updated = NULL WHERE id = {placeholder}",
            (track_id,)
        )
        conn.commit()
        conn.close()

        return jsonify({
            "success": True,
            "track_id": track_id,
            "message": "Single detection cache cleared — track will be re-evaluated on next scan"
        })
    except Exception as e:
        logging.error(f"Error resetting single detection for track {track_id}: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/scan/start", methods=["POST"])
def scan_start():
    """Start a library scan"""
    global scan_process
    
    scan_type = request.form.get("scan_type", "full")
    artist = request.form.get("artist")
    force_artist_scan = str(request.form.get("force", "")).strip().lower() in ("1", "true", "yes", "on")
    
    logging.info(f"scan_start called: scan_type={scan_type}, artist={artist}")
    
    # Handle artist-specific scan differently - use threaded worker instead of subprocess
    if scan_type == "artist":
        if artist:
            logging.info(f"Starting artist scan thread for: {artist}")
            threading.Thread(target=_run_artist_scan_pipeline, args=(artist, force_artist_scan), daemon=True).start()
            mode_label = "Forced" if force_artist_scan else "Changes Only"
            flash(f"Scan started for artist: {artist} ({mode_label})", "success")
            return redirect(url_for("artist_detail", name=artist))
        else:
            logging.error("Artist scan requested but no artist name provided")
            flash("Error: No artist name provided", "danger")
            return redirect(url_for("dashboard"))
    
    # For batch/force scans, use subprocess as before
    with scan_lock:
        if scan_process and scan_process.poll() is None:
            flash("A scan is already running", "warning")
            return redirect(url_for("dashboard"))
        
        # Build command
        cmd = ["python", "/app/start.py"]
        
        if scan_type == "full":
            cmd.append("--full-scan")
        elif scan_type == "force":
            cmd.extend(["--full-scan", "--force"])
        
        # Start process
        scan_process = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1
        )
        
        flash(f"Scan started: {scan_type}", "success")
    
    return redirect(url_for("dashboard"))


@app.route("/scan/unified", methods=["POST"])
def scan_unified():
    """Start the unified scan pipeline (popularity + singles)"""
    global scan_process
    
    with scan_lock:
        if scan_process and scan_process.poll() is None:
            flash("A scan is already running", "warning")
            return redirect(url_for("dashboard"))
        
        try:
            # Read force setting from config
            config_data, _ = _read_yaml(CONFIG_PATH)
            force = config_data.get("features", {}).get("force", False)
            
            # Start unified scan process
            cmd = [sys.executable, "unified_scan.py", "--verbose"]
            if force:
                cmd.append("--force")
            scan_process = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1
            )
            flash("✅ Unified scan started (popularity → singles → ratings)", "success")
        except Exception as e:
            flash(f"❌ Error starting unified scan: {str(e)}", "danger")
    
    return redirect(url_for("dashboard"))


@app.route("/scan/popularity", methods=["POST"])
def scan_popularity_route():
    """Run popularity score update from external sources"""
    global scan_process_popularity
    
    # Get scan mode from query parameters (default: "all")
    mode = request.args.get('mode', 'all')  # all, force, missing, singles, resume, resume_force
    restart_requested = str(request.args.get('restart', '0')).strip().lower() in ('1', 'true', 'yes', 'on')
    force_start = str(request.args.get('force_start', '0')).strip().lower() in ('1', 'true', 'yes', 'on')
    
    with scan_lock:
        # Check if scan is already running
        if scan_process_popularity is not None:
            scan_already_running = False
            if isinstance(scan_process_popularity, dict):
                thread = scan_process_popularity.get('thread')
                if thread and thread.is_alive():
                    scan_already_running = True
            elif hasattr(scan_process_popularity, 'is_alive') and scan_process_popularity.is_alive():
                scan_already_running = True

            if scan_already_running and not force_start:
                return jsonify({"scan_running": True, "message": "A popularity scan is already running."}), 409

        try:
            db_dir = os.path.dirname(DB_PATH)
            if restart_requested:
                checkpoint_path = os.path.join(db_dir, "popularity_scan_checkpoint.json")
                if os.path.exists(checkpoint_path):
                    try:
                        os.remove(checkpoint_path)
                        logging.info("Restart requested: cleared popularity checkpoint to start from beginning")
                    except Exception as checkpoint_err:
                        logging.warning(f"Restart requested but failed to clear popularity checkpoint: {checkpoint_err}")
            
            # Use different progress files for singles-only mode
            if mode == 'singles':
                popularity_progress_file = os.path.join(db_dir, "singles_scan_progress.json")
                _write_progress_file(popularity_progress_file, "singles_scan", True, {"status": "starting"})
            else:
                popularity_progress_file = os.path.join(db_dir, "popularity_scan_progress.json")
                _write_progress_file(popularity_progress_file, "popularity_scan", True, {"status": "starting"})

            # Run popularity scan in background thread instead of subprocess
            from popularity import popularity_scan as scan_popularity_func
            
            # Determine force and filter logic based on mode
            force_rescan = (mode == 'force' or mode == 'resume_force')
            filter_missing = (mode == 'missing')
            singles_only = (mode == 'singles')
            
            # Determine resume artist for resume mode
            resume_from_artist = None
            if mode == 'resume' or mode == 'resume_force':
                from scan_resume import get_last_scanned_artist
                resume_from_artist = get_last_scanned_artist(scan_type="popularity", db_path=DB_PATH)
                if resume_from_artist:
                    logging.info(f"Resume mode: Found last scanned artist '{resume_from_artist}'")
                else:
                    logging.warning("Resume mode: No last scanned artist found, starting from beginning")
            
            def run_popularity_scan_bg():
                try:
                    if singles_only:
                        logging.info(f"Starting singles-only scan in background")
                        completed = scan_popularity_func(
                            verbose=False,
                            force=False,
                            singles_only=True,
                            resume_from=resume_from_artist,
                            stop_progress_file=popularity_progress_file
                        )
                        if completed is False:
                            _write_progress_with_current_artist(popularity_progress_file, "singles_scan", False, {"status": "stopped", "exit_code": 0})
                            logging.info("Singles scan stopped by user request")
                        else:
                            _write_progress_with_current_artist(popularity_progress_file, "singles_scan", False, {"status": "complete", "exit_code": 0})
                            logging.info("Singles scan completed successfully")
                            _log_scan_session_complete("singles")
                    else:
                        logging.info(f"Starting popularity score scan in background (force={force_rescan}, filter_missing={filter_missing}, resume_from={resume_from_artist})")
                        completed = scan_popularity_func(
                            verbose=False,
                            force=force_rescan,
                            filter_missing=filter_missing,
                            resume_from=resume_from_artist,
                            stop_progress_file=popularity_progress_file
                        )
                        if completed is False:
                            _write_progress_with_current_artist(popularity_progress_file, "popularity_scan", False, {"status": "stopped", "exit_code": 0})
                            logging.info("Popularity scan stopped by user request")
                        else:
                            _write_progress_with_current_artist(popularity_progress_file, "popularity_scan", False, {"status": "complete", "exit_code": 0})
                            logging.info("Popularity scan completed successfully")
                            _log_scan_session_complete("popularity")
                except Exception as e:
                    logging.error(f"Error in popularity scan: {e}", exc_info=True)
                    _write_progress_with_current_artist(popularity_progress_file, "popularity_scan" if not singles_only else "singles_scan", False, {"status": "error", "error": str(e), "exit_code": 1})
            
            scan_thread = threading.Thread(target=run_popularity_scan_bg, daemon=False)
            scan_thread.start()
            scan_process_popularity = {'thread': scan_thread, 'type': 'popularity'}
            
            if singles_only:
                flash("✅ Singles detection scan started (popularity only)", "success")
            else:
                mode_desc = {
                    'all': 'Full', 
                    'force': 'Full (Forced)', 
                    'missing': 'Missing Only',
                    'resume': 'Resume from Last',
                    'resume_force': 'Resume (Forced)'
                }.get(mode, 'Full')
                flash(f"✅ Popularity and singles scan started ({mode_desc} scan)", "success")
            logging.info("Popularity scan thread started successfully")
        except Exception as e:
            logging.error(f"Error starting popularity scan: {e}", exc_info=True)
            flash(f"❌ Error starting popularity scan: {str(e)}", "danger")
    
    return redirect(url_for("dashboard"))


