@app.route("/api/essentia/download-models", methods=["POST"])
def api_essentia_download_models():
    """Download the Essentia-to-Metadata script and ML model files to the container.

    Starts a background thread that:
      1. git-clones (or git-pulls) https://github.com/WB2024/Essentia-to-Metadata
         into the directory derived from the configured script_path (or the Docker default).
      2. Downloads the 5 Essentia ML model files from essentia.upf.edu
         into the configured models_dir (or the Docker default /opt/essentia_models).

    Returns JSON ``{"status": "started"}`` immediately, or ``{"status": "already_running"}``
    if a download is already in progress.  Poll ``/api/essentia/download-status`` for progress.
    """
    global _essentia_download_thread

    db_dir = os.path.dirname(DB_PATH)
    progress_file = os.path.join(db_dir, "essentia_download_progress.json")

    _ESSENTIA_MODEL_URLS = [
        "https://essentia.upf.edu/models/music-style-classification/discogs-effnet/discogs-effnet-bs64-1.pb",
        "https://essentia.upf.edu/models/classification-heads/genre_discogs400/genre_discogs400-discogs-effnet-1.pb",
        "https://essentia.upf.edu/models/classification-heads/genre_discogs400/genre_discogs400-discogs-effnet-1.json",
        "https://essentia.upf.edu/models/classification-heads/mtg_jamendo_moodtheme/mtg_jamendo_moodtheme-discogs-effnet-1.pb",
        "https://essentia.upf.edu/models/classification-heads/mtg_jamendo_moodtheme/mtg_jamendo_moodtheme-discogs-effnet-1.json",
    ]
    _ESSENTIA_REPO_URL = "https://github.com/WB2024/Essentia-to-Metadata.git"
    _BUNDLED_SCRIPT_DEFAULT = "/opt/Essentia-to-Metadata/tag_music.py"
    _BUNDLED_MODELS_DEFAULT = "/opt/essentia_models"

    with scan_lock:
        if _essentia_download_thread is not None and _essentia_download_thread.is_alive():
            return jsonify({"status": "already_running", "message": "Download already in progress"}), 409

        def _do_download():
            global _essentia_download_thread
            try:
                # Read configured paths from config
                try:
                    from helpers.config_helpers import get_config
                    cfg = get_config()
                    essentia_cfg = cfg.get("essentia", {}) if isinstance(cfg, dict) else {}
                    script_path = (essentia_cfg.get("script_path") or "").strip()
                    models_dir_cfg = (essentia_cfg.get("models_dir") or "").strip()
                except Exception:
                    script_path = ""
                    models_dir_cfg = ""

                # Resolve target directories
                if script_path:
                    clone_dir = os.path.dirname(script_path)
                else:
                    clone_dir = os.path.dirname(_BUNDLED_SCRIPT_DEFAULT)  # /opt/Essentia-to-Metadata

                target_models_dir = models_dir_cfg if models_dir_cfg else _BUNDLED_MODELS_DEFAULT

                total_files = len(_ESSENTIA_MODEL_URLS)

                # ── Step 1: Clone or update the script repository ───────────────────
                _write_progress_file(progress_file, "essentia_download", True, {
                    "status": "cloning_script",
                    "current_step": f"Cloning Essentia-to-Metadata to {clone_dir}…",
                    "files_done": 0,
                    "files_total": total_files,
                })

                parent_dir = os.path.dirname(clone_dir)
                if parent_dir:
                    os.makedirs(parent_dir, exist_ok=True)

                if os.path.isdir(os.path.join(clone_dir, ".git")):
                    # Repo already present — pull latest changes
                    result = subprocess.run(
                        ["git", "-C", clone_dir, "pull", "--ff-only"],
                        capture_output=True, text=True, timeout=120,
                    )
                    if result.returncode != 0:
                        logging.warning(
                            "Essentia git pull returned non-zero (non-fatal): %s", result.stderr.strip()
                        )
                else:
                    result = subprocess.run(
                        ["git", "clone", "--depth=1", _ESSENTIA_REPO_URL, clone_dir],
                        capture_output=True, text=True, timeout=180,
                    )
                    if result.returncode != 0:
                        raise RuntimeError(f"git clone failed: {result.stderr.strip()[:300]}")

                # ── Step 2: Download model files ─────────────────────────────────────
                os.makedirs(target_models_dir, exist_ok=True)

                for idx, url in enumerate(_ESSENTIA_MODEL_URLS):
                    filename = os.path.basename(url)
                    dest_path = os.path.join(target_models_dir, filename)

                    _write_progress_file(progress_file, "essentia_download", True, {
                        "status": "downloading_models",
                        "current_step": f"Downloading {filename} ({idx + 1}/{total_files})…",
                        "files_done": idx,
                        "files_total": total_files,
                    })

                    if os.path.isfile(dest_path):
                        logging.info("Essentia model already present, skipping: %s", dest_path)
                    else:
                        tmp_path = dest_path + ".tmp"
                        try:
                            resp = requests.get(url, stream=True, timeout=300)
                            resp.raise_for_status()
                            with open(tmp_path, "wb") as fh:
                                for chunk in resp.iter_content(chunk_size=1 << 20):
                                    if chunk:
                                        fh.write(chunk)
                            os.replace(tmp_path, dest_path)
                        except Exception:
                            if os.path.exists(tmp_path):
                                try:
                                    os.remove(tmp_path)
                                except OSError:
                                    pass
                            raise

                _write_progress_file(progress_file, "essentia_download", False, {
                    "status": "complete",
                    "current_step": "Download complete",
                    "files_done": total_files,
                    "files_total": total_files,
                    "models_dir": target_models_dir,
                    "script_dir": clone_dir,
                })
                from helpers.logging_config import log_unified
                log_unified(
                    f"Essentia Scan - Models and script downloaded successfully"
                    f" (models: {target_models_dir}, script: {clone_dir})"
                )

            except Exception as exc:
                logging.error("Essentia model download failed: %s", exc, exc_info=True)
                _write_progress_file(progress_file, "essentia_download", False, {
                    "status": "error",
                    "current_step": f"Error: {exc}",
                    "error": str(exc),
                })

        _essentia_download_thread = threading.Thread(
            target=_do_download, daemon=False, name="essentia-download"
        )
        _essentia_download_thread.start()

    return jsonify({"status": "started", "message": "Essentia download started"})


@app.route("/api/essentia/download-status")
def api_essentia_download_status():
    """Return the current status of the Essentia model/script download."""
    db_dir = os.path.dirname(DB_PATH)
    progress_file = os.path.join(db_dir, "essentia_download_progress.json")
    try:
        with open(progress_file, "r", encoding="utf-8") as f:
            return jsonify(json.load(f))
    except FileNotFoundError:
        return jsonify({"status": "idle", "is_running": False, "scan_type": "essentia_download"})
    except Exception as exc:
        return jsonify({"status": "error", "error": str(exc)}), 500


@app.route("/scan/stop-all", methods=["POST"])
def scan_stop_all():
    """Stop all running scans"""
    global scan_process, scan_process_navidrome, scan_process_popularity, scan_process_singles, scan_process_mood, scan_process_essentia_mood, scan_process_combined, scan_process_missing_releases, scan_process_mp3_import
    
    stopped_scans = []
    db_dir = os.path.dirname(DB_PATH)
    
    with scan_lock:
        # Stop main scan process
        if scan_process is not None and scan_process.poll() is None:
            scan_process.terminate()
            stopped_scans.append("main")
        
        # Stop Navidrome scan
        if scan_process_navidrome is not None:
            if isinstance(scan_process_navidrome, dict):
                thread = scan_process_navidrome.get('thread')
                if thread and thread.is_alive():
                    _request_scan_stop(os.path.join(db_dir, "navidrome_scan_progress.json"), "navidrome_scan")
                    scan_process_navidrome = None
                    stopped_scans.append("Navidrome")
        else:
            # Check progress file even if global is None (Flask restart scenario)
            nav_progress_file = os.path.join(db_dir, "navidrome_scan_progress.json")
            if os.path.exists(nav_progress_file):
                try:
                    with open(nav_progress_file, 'r') as f:
                        progress = json.load(f)
                        if progress.get('is_running'):
                            _request_scan_stop(nav_progress_file, "navidrome_scan")
                            stopped_scans.append("Navidrome")
                except Exception:
                    pass
        
        # Stop Popularity scan
        if scan_process_popularity is not None:
            if isinstance(scan_process_popularity, dict):
                thread = scan_process_popularity.get('thread')
                if thread and thread.is_alive():
                    _request_scan_stop(os.path.join(db_dir, "popularity_scan_progress.json"), "popularity_scan")
                    _request_scan_stop(os.path.join(db_dir, "singles_scan_progress.json"), "singles_scan")
                    scan_process_popularity = None
                    stopped_scans.append("Popularity")
        else:
            # Check progress files even if global is None
            pop_progress_file = os.path.join(db_dir, "popularity_scan_progress.json")
            if os.path.exists(pop_progress_file):
                try:
                    with open(pop_progress_file, 'r') as f:
                        progress = json.load(f)
                        if progress.get('is_running'):
                            _request_scan_stop(pop_progress_file, "popularity_scan")
                            _request_scan_stop(os.path.join(db_dir, "singles_scan_progress.json"), "singles_scan")
                            stopped_scans.append("Popularity")
                except Exception:
                    pass
        
        # Stop Singles scan
        if scan_process_singles is not None:
            if isinstance(scan_process_singles, dict):
                thread = scan_process_singles.get('thread')
                if thread and thread.is_alive():
                    _request_scan_stop(os.path.join(db_dir, "singles_scan_progress.json"), "singles_scan")
                    scan_process_singles = None
                    stopped_scans.append("Singles")
        else:
            # Check progress file
            single_progress_file = os.path.join(db_dir, "singles_scan_progress.json")
            if os.path.exists(single_progress_file):
                try:
                    with open(single_progress_file, 'r') as f:
                        progress = json.load(f)
                        if progress.get('is_running') and "Popularity" not in stopped_scans:
                            _request_scan_stop(single_progress_file, "singles_scan")
                            stopped_scans.append("Singles")
                except Exception:
                    pass

        # Stop Mood scan
        if scan_process_mood is not None:
            if isinstance(scan_process_mood, dict):
                thread = scan_process_mood.get('thread')
                if thread and thread.is_alive():
                    _request_scan_stop(os.path.join(db_dir, "mood_scan_progress.json"), "mood_scan")
                    scan_process_mood = None
                    stopped_scans.append("Mood")
        else:
            mood_progress_file = os.path.join(db_dir, "mood_scan_progress.json")
            if os.path.exists(mood_progress_file):
                try:
                    with open(mood_progress_file, 'r') as f:
                        progress = json.load(f)
                        if progress.get('is_running'):
                            _request_scan_stop(mood_progress_file, "mood_scan")
                            stopped_scans.append("Mood")
                except Exception:
                    pass

        # Stop Essentia Mood scan
        if scan_process_essentia_mood is not None:
            if isinstance(scan_process_essentia_mood, dict):
                thread = scan_process_essentia_mood.get('thread')
                if thread and thread.is_alive():
                    _request_scan_stop(os.path.join(db_dir, "essentia_mood_scan_progress.json"), "essentia_mood_scan")
                    scan_process_essentia_mood = None
                    stopped_scans.append("Essentia Mood")
        else:
            essentia_progress_file = os.path.join(db_dir, "essentia_mood_scan_progress.json")
            if os.path.exists(essentia_progress_file):
                try:
                    with open(essentia_progress_file, 'r') as f:
                        progress = json.load(f)
                        if progress.get('is_running'):
                            _request_scan_stop(essentia_progress_file, "essentia_mood_scan")
                            stopped_scans.append("Essentia Mood")
                except Exception:
                    pass
        
        # Stop Combined scan
        if scan_process_combined is not None:
            if isinstance(scan_process_combined, dict):
                thread = scan_process_combined.get('thread')
                if thread and thread.is_alive():
                    _request_scan_stop(os.path.join(db_dir, "combined_scan_progress.json"), "combined_scan")
                    scan_process_combined = None
                    stopped_scans.append("Combined")
        else:
            # Check progress file
            comb_progress_file = os.path.join(db_dir, "combined_scan_progress.json")
            if os.path.exists(comb_progress_file):
                try:
                    with open(comb_progress_file, 'r') as f:
                        progress = json.load(f)
                        if progress.get('is_running'):
                            _request_scan_stop(comb_progress_file, "combined_scan")
                            stopped_scans.append("Combined")
                except Exception:
                    pass
        
        # Stop Missing Releases scan
        if scan_process_missing_releases is not None:
            if isinstance(scan_process_missing_releases, dict):
                thread = scan_process_missing_releases.get('thread')
                if thread and thread.is_alive():
                    _request_scan_stop(os.path.join(db_dir, "missing_releases_scan_progress.json"), "missing_releases_scan")
                    scan_process_missing_releases = None
                    stopped_scans.append("Missing releases")
        else:
            # Check progress file
            missing_progress_file = os.path.join(db_dir, "missing_releases_scan_progress.json")
            if os.path.exists(missing_progress_file):
                try:
                    with open(missing_progress_file, 'r') as f:
                        progress = json.load(f)
                        if progress.get('is_running'):
                            _request_scan_stop(missing_progress_file, "missing_releases_scan")
                            stopped_scans.append("Missing releases")
                except Exception:
                    pass
        
        # Stop MP3 Import scan
        if scan_process_mp3_import is not None:
            if hasattr(scan_process_mp3_import, 'is_alive') and scan_process_mp3_import.is_alive():
                mp3_progress_file = os.path.join(db_dir, "mp3_import_progress.json")
                try:
                    with open(mp3_progress_file, 'r', encoding='utf-8') as f:
                        progress = json.load(f)
                    progress['is_running'] = False
                    with open(mp3_progress_file, 'w', encoding='utf-8') as f:
                        json.dump(progress, f, indent=2)
                except Exception:
                    pass
                scan_process_mp3_import = None
                stopped_scans.append("MP3 import")
        else:
            # Check progress file
            mp3_progress_file = os.path.join(db_dir, "mp3_import_progress.json")
            if os.path.exists(mp3_progress_file):
                try:
                    with open(mp3_progress_file, 'r', encoding='utf-8') as f:
                        progress = json.load(f)
                        if progress.get('is_running'):
                            progress['is_running'] = False
                            with open(mp3_progress_file, 'w', encoding='utf-8') as f:
                                json.dump(progress, f, indent=2)
                            stopped_scans.append("MP3 import")
                except Exception:
                    pass
    
    if stopped_scans:
        flash(f"✅ Stopped {len(stopped_scans)} scan(s): {', '.join(stopped_scans)}", "success")
    else:
        flash("No scans are currently running", "info")
    
    return redirect(url_for("dashboard"))


@app.route("/scan/clear-stuck", methods=["POST"])
def scan_clear_stuck():
    """Clear all stuck scan progress files"""
    global scan_process_navidrome, scan_process_popularity, scan_process_singles, scan_process_mood, scan_process_essentia_mood, scan_process_combined, scan_process_missing_releases
    
    with scan_lock:
        db_dir = os.path.dirname(DB_PATH)
        cleared_count = 0
        
        # List of all progress files to check
        progress_files = [
            ("navidrome_scan_progress.json", scan_process_navidrome),
            ("popularity_scan_progress.json", scan_process_popularity),
            ("singles_scan_progress.json", scan_process_singles),
            ("mood_scan_progress.json", scan_process_mood),
            ("essentia_mood_scan_progress.json", scan_process_essentia_mood),
            ("combined_scan_progress.json", scan_process_combined),
            ("missing_releases_scan_progress.json", scan_process_missing_releases),
        ]
        
        for filename, process_ref in progress_files:
            filepath = os.path.join(db_dir, filename)
            if os.path.exists(filepath):
                try:
                    with open(filepath, 'r') as f:
                        progress = json.load(f)
                    
                    # If it says running, check if process is actually alive using helper
                    if progress.get("is_running", False):
                        is_alive = _is_process_alive(process_ref)
                        
                        # If not alive, mark as stopped
                        if not is_alive:
                            progress["is_running"] = False
                            progress["status"] = "cleared"
                            with open(filepath, 'w') as f:
                                json.dump(progress, f)
                            cleared_count += 1
                            logging.info(f"Cleared stuck progress file: {filename}")
                except Exception as e:
                    logging.error(f"Error clearing progress file {filename}: {e}")
        
        # Also clean up global process references if they're dead (explicit assignments for security)
        if scan_process_navidrome and not _is_process_alive(scan_process_navidrome):
            scan_process_navidrome = None
        if scan_process_popularity and not _is_process_alive(scan_process_popularity):
            scan_process_popularity = None
        if scan_process_singles and not _is_process_alive(scan_process_singles):
            scan_process_singles = None
        if scan_process_mood and not _is_process_alive(scan_process_mood):
            scan_process_mood = None
        if scan_process_combined and not _is_process_alive(scan_process_combined):
            scan_process_combined = None
        if scan_process_missing_releases and not _is_process_alive(scan_process_missing_releases):
            scan_process_missing_releases = None
        
        if cleared_count > 0:
            flash(f"✅ Cleared {cleared_count} stuck scan(s)", "success")
        else:
            flash("No stuck scans found", "info")
    
    return redirect(url_for("dashboard"))


@app.route("/scan/status")
def scan_status():
    """Get scan status (JSON)"""
    with scan_lock:
        web_ui_running = scan_process is not None and scan_process.poll() is None
    
    # Check if background scan from start.py is running
    lock_file_path = os.path.join(os.path.dirname(CONFIG_PATH), ".scan_lock")
    background_running = os.path.exists(lock_file_path)
    
    running = web_ui_running or background_running
    
    return jsonify({"running": running})


@app.route("/login", methods=["GET", "POST"])
def login():
    """Login page"""
    try:
        # If already logged in, redirect to dashboard
        if 'username' in session:
            return redirect(url_for('dashboard'))
        
        # If config doesn't exist, redirect to setup
        if not os.path.exists(CONFIG_PATH):
            return redirect(url_for('setup'))
        
        cfg = get_config()
        if _needs_setup(cfg):
            return redirect(url_for('setup'))
        
        if request.method == 'POST':
            username = request.form.get('username', '').strip()
            password = request.form.get('password', '').strip()
            
            if _authenticate_navidrome(username, password):
                session.permanent = True
                session['username'] = username
                flash(f'Welcome back, {username}!', 'success')
                
                # Redirect to next URL or dashboard
                next_url = request.args.get('next')
                if next_url:
                    return redirect(next_url)
                return redirect(url_for('dashboard'))
            else:
                flash('Invalid username or password. Please use your Navidrome credentials.', 'danger')
    except Exception as e:
        logging.error(f"Login error: {e}")
        import traceback
        traceback.print_exc()
        flash(f"Login system error: {str(e)}", "danger")
    
    return render_template('login.html')


@app.route("/logout")
def logout():
    """Logout and clear session"""
    username = session.get('username', 'User')
    session.clear()
    flash(f'Goodbye, {username}!', 'info')
    return redirect(url_for('login'))


