@app.route("/config", methods=["GET", "POST"])
def config_editor():
    """View/edit config.yaml. Always allow access, show warning if setup incomplete."""

    def _as_dict(value):
        return value if isinstance(value, dict) else {}

    def _as_list_of_dicts(value):
        if not isinstance(value, list):
            return []
        return [item for item in value if isinstance(item, dict)]

    if request.method == "POST":
        # Require authentication for config changes
        if 'username' not in session:
            flash("Authentication required to save configuration", "error")
            return redirect(url_for("login", next=request.url))
        
        # Handle raw YAML save from modal
        try:
            config_content = request.form.get('config_content', '')
            if not config_content:
                flash("No configuration content provided", "error")
                return redirect(url_for("config_editor"))
            
            # Validate YAML before saving
            try:
                yaml.safe_load(config_content)
            except yaml.YAMLError as e:
                flash(f"Invalid YAML: {str(e)}", "error")
                return redirect(url_for("config_editor"))
            
            # Save to file
            cfg_dir = os.path.dirname(CONFIG_PATH)
            if cfg_dir:
                os.makedirs(cfg_dir, exist_ok=True)
            with open(CONFIG_PATH, "w", encoding="utf-8") as f:
                f.write(config_content)
            
            flash("Configuration saved successfully", "success")
            return redirect(url_for("config_editor"))
        except Exception as e:
            flash(f"Error saving configuration: {str(e)}", "error")
            return redirect(url_for("config_editor"))
    
    # GET request - show config editor
    config, raw = _read_yaml(CONFIG_PATH)
    # Ensure config is a dict (in case YAML parsed to something else)
    if not isinstance(config, dict):
        config = {}

    # Normalize top-level sections to dicts to prevent template crashes like
    # "'str object' has no attribute 'get'" when YAML contains malformed values.
    for key in [
        'navidrome', 'qbittorrent', 'slskd', 'authentik', 'bookmarks',
        'downloads', 'api_integrations', 'database', 'logging', 'watcher',
        'features', 'weights', 'single_detection', 'tags'
    ]:
        config[key] = _as_dict(config.get(key))

    # Normalize upcoming_releases: keep as dict but ensure sources is a list.
    ur = config.get('upcoming_releases')
    if not isinstance(ur, dict):
        ur = {}
    if not isinstance(ur.get('sources'), list):
        ur['sources'] = []
    config['upcoming_releases'] = ur

    # Ensure nested structures used by config.html are also dicts.
    config['features']['retry_scheduler'] = _as_dict(config['features'].get('retry_scheduler'))
    config['features']['download_queue_cleanup_scheduler'] = _as_dict(config['features'].get('download_queue_cleanup_scheduler'))
    config['features']['downloads_duplicate_cleanup'] = _as_dict(config['features'].get('downloads_duplicate_cleanup'))

    # Keep navidrome_users predictable for setup checks and template iteration.
    config['navidrome_users'] = _as_list_of_dicts(config.get('navidrome_users'))

    # Check for required keys in navidrome_users (for warning only)
    navidrome_users = config.get('navidrome_users', [])
    required_keys = ["base_url", "user", "pass"]
    needs_setup = False
    if not navidrome_users:
        needs_setup = True
    else:
        for user in navidrome_users:
            for key in required_keys:
                if not user.get(key):
                    needs_setup = True
                    break
            if needs_setup:
                break
    if not raw:
        raw = yaml.safe_dump(config, sort_keys=False, allow_unicode=False) if config else ""
    return render_template("config.html", config=config, config_raw=raw, CONFIG_PATH=CONFIG_PATH, needs_setup=needs_setup)


