@app.route("/config/save-json", methods=["POST"])
def config_save_json():
    """Save config as JSON - converts to YAML and updates config.yaml"""
    try:
        def _as_dict(value):
            return value if isinstance(value, dict) else {}

        def _as_list(value):
            return value if isinstance(value, list) else []

        # Get JSON data
        data = request.get_json()
        
        if data is None:
            return jsonify({"success": False, "error": "No JSON data provided"}), 400
        
        # Build YAML structure from JSON
        navidrome_users = _as_list(data.get('navidrome_users', []))
        # Map legacy/alternate keys to expected keys on save
        for user in navidrome_users:
            if not isinstance(user, dict):
                continue
            if "navidrome_base_url" in user:
                user["base_url"] = user["navidrome_base_url"]
            if "navidrome_password" in user:
                user["pass"] = user["navidrome_password"]
            if "username" in user:
                user["user"] = user["username"]

        features = _as_dict(data.get('features', {}))
        features['retry_scheduler'] = _as_dict(features.get('retry_scheduler'))
        features['download_queue_cleanup_scheduler'] = _as_dict(features.get('download_queue_cleanup_scheduler'))

        config_dict = {
            'navidrome_users': navidrome_users,
            'qbittorrent': _as_dict(data.get('qbittorrent', {})),
            'slskd': _as_dict(data.get('slskd', {})),
            'authentik': _as_dict(data.get('authentik', {})),
            'bookmarks': _as_dict(data.get('bookmarks', {})),
            'downloads': _as_dict(data.get('downloads', {})),
            'logging': _as_dict(data.get('logging', {})),
            'web_api_key': data.get('web_api_key', ''),
            'enable_web_api_key': data.get('enable_web_api_key', True),
            'features': features,
            'weights': _as_dict(data.get('weights', {})),
            'single_detection': _as_dict(data.get('single_detection', {})),
            'strip_parentheses_filters': data.get('strip_parentheses_filters', []),
            'upcoming_releases': _as_dict(data.get('upcoming_releases', {}))
        }
        # Always set main navidrome section to first user for compatibility
        if navidrome_users and len(navidrome_users) > 0:
            config_dict['navidrome'] = {
                'base_url': navidrome_users[0].get('base_url', ''),
                'user': navidrome_users[0].get('user', ''),
                'pass': navidrome_users[0].get('pass', ''),
            }
        
        # Read existing config to preserve sections that are no longer submitted by the UI
        existing_config, _ = _read_yaml(CONFIG_PATH)
        if existing_config:
            # Only preserve features/weights/single_detection if not explicitly provided in the request
            if 'features' not in data and 'features' in existing_config:
                config_dict['features'] = existing_config['features']
            if 'weights' not in data and 'weights' in existing_config:
                config_dict['weights'] = existing_config['weights']
            if 'single_detection' not in data and 'single_detection' in existing_config:
                config_dict['single_detection'] = existing_config['single_detection']
            if 'strip_parentheses_filters' not in data and 'strip_parentheses_filters' in existing_config:
                config_dict['strip_parentheses_filters'] = existing_config['strip_parentheses_filters']
            if 'upcoming_releases' not in data and 'upcoming_releases' in existing_config:
                config_dict['upcoming_releases'] = existing_config['upcoming_releases']
            if 'logging' not in data and 'logging' in existing_config:
                config_dict['logging'] = existing_config['logging']

            # api_integrations and database are no longer managed via this endpoint
            # (api_integrations is per-user; database is PostgreSQL-only with no UI).
            # Always restore them from disk to prevent data loss.
            if 'api_integrations' in existing_config:
                config_dict['api_integrations'] = existing_config['api_integrations']
            if 'database' in existing_config:
                config_dict['database'] = existing_config['database']

            # Also preserve legacy navidrome config if it exists (for backward compatibility)
            if 'navidrome' in existing_config and not config_dict.get('navidrome_users'):
                config_dict['navidrome'] = existing_config['navidrome']
        
        # Convert to YAML
        yaml_content = yaml.safe_dump(config_dict, sort_keys=False, allow_unicode=True, default_flow_style=False)
        
        # Validate YAML before writing
        yaml.safe_load(yaml_content)
        
        # Write to file
        cfg_dir = os.path.dirname(CONFIG_PATH)
        if cfg_dir:
            os.makedirs(cfg_dir, exist_ok=True)
        with open(CONFIG_PATH, "w", encoding="utf-8") as f:
            f.write(yaml_content)
        
        return jsonify({"success": True, "message": "Configuration saved successfully"})
    
    except yaml.YAMLError as e:
        return jsonify({"success": False, "error": f"YAML error: {str(e)}"}), 400
    except IOError as e:
        return jsonify({"success": False, "error": f"File write error: {str(e)}"}), 400
    except Exception as e:
        import traceback
        error_msg = str(e)
        tb = traceback.format_exc()
        print(f"Config save error: {tb}")  # Log to console for debugging
        return jsonify({"success": False, "error": error_msg}), 400


@app.route("/api/navidrome/ratings/sync-now", methods=["POST"])
def api_navidrome_sync_ratings_now():
    """Sync local track star ratings to all configured Navidrome users immediately."""
    if 'username' not in session:
        return jsonify({"success": False, "error": "Authentication required"}), 401

    def _get_val(row, key, index=0):
        if row is None:
            return None
        if isinstance(row, dict):
            return row.get(key)
        if hasattr(row, "keys"):
            try:
                return row[key]
            except Exception:
                pass
        try:
            return row[index]
        except Exception:
            return None

    def _collect_navidrome_users(cfg):
        users = []
        for item in (cfg.get("navidrome_users") or []):
            if not isinstance(item, dict):
                continue
            base_url = (item.get("base_url") or "").strip().rstrip("/")
            username = (item.get("user") or "").strip()
            password = (item.get("pass") or "").strip()
            display_name = (item.get("display_name") or username or "Navidrome User").strip()
            if base_url and username and password:
                users.append({
                    "base_url": base_url,
                    "user": username,
                    "pass": password,
                    "display_name": display_name,
                })

        if users:
            return users

        nav_cfg = cfg.get("navidrome", {}) if isinstance(cfg.get("navidrome"), dict) else {}
        base_url = (nav_cfg.get("base_url") or "").strip().rstrip("/")
        username = (nav_cfg.get("user") or "").strip()
        password = (nav_cfg.get("pass") or "").strip()
        if base_url and username and password:
            users.append({
                "base_url": base_url,
                "user": username,
                "pass": password,
                "display_name": username,
            })
        return users

    conn = None
    try:
        cfg = get_config()
        nav_users = _collect_navidrome_users(cfg)
        if not nav_users:
            return jsonify({"success": False, "error": "No configured Navidrome users with credentials"}), 400

        conn = get_db()
        cursor = conn.cursor()
        cursor.execute("SELECT id, stars FROM tracks WHERE stars IS NOT NULL AND stars > 0")
        rows = cursor.fetchall() or []

        rated_tracks = []
        for row in rows:
            track_id = _get_val(row, "id", 0)
            stars_raw = _get_val(row, "stars", 1)
            if track_id is None or stars_raw is None:
                continue
            try:
                stars = int(stars_raw)
            except (TypeError, ValueError):
                continue
            if stars < 1:
                continue
            if stars > 5:
                stars = 5
            rated_tracks.append((str(track_id), stars))

        if not rated_tracks:
            return jsonify({
                "success": True,
                "message": "No rated tracks found to sync",
                "tracks_total": 0,
                "users_total": len(nav_users),
                "attempted_total": 0,
                "synced_total": 0,
                "failed_total": 0,
                "users": []
            })

        from api_clients.navidrome import NavidromeClient

        users_result = []
        total_attempted = 0
        total_synced = 0
        total_failed = 0

        for user_cfg in nav_users:
            client = NavidromeClient(
                base_url=user_cfg["base_url"],
                username=user_cfg["user"],
                password=user_cfg["pass"],
            )

            user_success = 0
            user_failed = 0
            sample_errors = []

            for track_id, stars in rated_tracks:
                total_attempted += 1
                try:
                    response = client.session.get(
                        f"{user_cfg['base_url']}/rest/setRating.view",
                        params=client._build_params(id=track_id, rating=stars),
                        timeout=10,
                    )
                    response.raise_for_status()
                    payload = response.json() if response.content else {}
                    status = (payload.get("subsonic-response") or {}).get("status")
                    if status == "ok":
                        user_success += 1
                        total_synced += 1
                    else:
                        user_failed += 1
                        total_failed += 1
                        error_info = ((payload.get("subsonic-response") or {}).get("error") or {})
                        if len(sample_errors) < 3:
                            sample_errors.append(
                                f"{track_id}: {error_info.get('message', 'API status not ok')}"
                            )
                except Exception as exc:
                    user_failed += 1
                    total_failed += 1
                    if len(sample_errors) < 3:
                        sample_errors.append(f"{track_id}: {exc}")

            users_result.append({
                "display_name": user_cfg["display_name"],
                "username": user_cfg["user"],
                "base_url": user_cfg["base_url"],
                "synced": user_success,
                "failed": user_failed,
                "errors": sample_errors,
            })

        return jsonify({
            "success": total_synced > 0,
            "tracks_total": len(rated_tracks),
            "users_total": len(nav_users),
            "attempted_total": total_attempted,
            "synced_total": total_synced,
            "failed_total": total_failed,
            "users": users_result,
        })
    except Exception as exc:
        logging.error(f"[CONFIG] Sync-now rating push failed: {exc}", exc_info=True)
        return jsonify({"success": False, "error": str(exc)}), 500
    finally:
        try:
            if conn:
                conn.close()
        except Exception:
            pass


@app.route("/api/features/update", methods=["POST"])
def api_features_update():
    """Update individual feature flags and startup-scan preferences in config.yaml."""
    try:
        data = request.get_json()
        if data is None:
            return jsonify({"success": False, "error": "No JSON data provided"}), 400

        config_data, _ = _read_yaml(CONFIG_PATH)
        if config_data is None:
            config_data = {}

        features = config_data.get("features", {})

        allowed_bool_keys = {"perpetual", "force", "launch_on_startup", "startup_scan_restart"}
        for key in allowed_bool_keys:
            if key in data:
                features[key] = bool(data[key])

        if "startup_scan_type" in data:
            scan_type = str(data.get("startup_scan_type") or "").strip().lower()
            if scan_type in {"navidrome", "metadata", "popularity", "mood", "combined"}:
                features["startup_scan_type"] = scan_type

        config_data["features"] = features

        yaml_content = yaml.safe_dump(config_data, sort_keys=False, allow_unicode=True, default_flow_style=False)
        yaml.safe_load(yaml_content)

        cfg_dir = os.path.dirname(CONFIG_PATH)
        if cfg_dir:
            os.makedirs(cfg_dir, exist_ok=True)
        with open(CONFIG_PATH, "w", encoding="utf-8") as f:
            f.write(yaml_content)

        return jsonify({
            "success": True,
            "perpetual": features.get("perpetual", False),
            "force": features.get("force", False),
            "launch_on_startup": features.get("launch_on_startup", False),
            "startup_scan_type": features.get("startup_scan_type", "navidrome"),
            "startup_scan_restart": features.get("startup_scan_restart", False),
        })
    except Exception as e:
        logging.error(f"Error updating features: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/config/migrate_postgres", methods=["POST"])
def config_migrate_postgres():
    """Validate and persist PostgreSQL connection settings."""
    global PG_HOST, PG_PORT, PG_USER, PG_PASSWORD, PG_DATABASE

    try:
        if not _ensure_psycopg2_loaded() or psycopg2 is None or psql is None:
            return jsonify({
                "success": False,
                "error": "PostgreSQL driver not available. Install psycopg2-binary and restart the service/container if required."
            }), 400

        payload = request.get_json(force=True) or {}
        pg_host = str(payload.get("pg_host", "")).strip()
        pg_port = str(payload.get("pg_port", "5432")).strip() or "5432"
        pg_user = str(payload.get("pg_user", "")).strip()
        pg_password = str(payload.get("pg_password", ""))
        pg_database = str(payload.get("pg_database", "")).strip()
        if not pg_host or not pg_user or not pg_database:
            return jsonify({
                "success": False,
                "error": "pg_host, pg_user, and pg_database are required"
            }), 400

        pg_conn = psycopg2.connect(  # type: ignore[name-defined]
            host=pg_host,
            port=pg_port,
            user=pg_user,
            password=pg_password,
            dbname=pg_database,
        )
        try:
            pg_conn.close()
        finally:
            try:
                pg_conn.close()
            except Exception:
                pass

        # Persist PostgreSQL settings to config file.
        config, _ = _read_yaml(CONFIG_PATH)
        if not isinstance(config, dict):
            config = {}
        config["PG_HOST"] = pg_host
        config["PG_PORT"] = pg_port
        config["PG_USER"] = pg_user
        config["PG_PASSWORD"] = pg_password
        config["PG_DATABASE"] = pg_database

        cfg_dir = os.path.dirname(CONFIG_PATH)
        if cfg_dir:
            os.makedirs(cfg_dir, exist_ok=True)
        with open(CONFIG_PATH, "w", encoding="utf-8") as f:
            yaml.safe_dump(config, f, sort_keys=False, allow_unicode=True)

        # Update process env/globals so runtime can switch without waiting for a restart.
        os.environ["PG_HOST"] = pg_host
        os.environ["PG_PORT"] = pg_port
        os.environ["PG_USER"] = pg_user
        os.environ["PG_PASSWORD"] = pg_password
        os.environ["PG_DATABASE"] = pg_database
        PG_HOST = pg_host
        PG_PORT = pg_port
        PG_USER = pg_user
        PG_PASSWORD = pg_password
        PG_DATABASE = pg_database

        # Schedule Flask restart after returning response
        def restart_flask_after_response():
            """Gracefully restart Flask after response is sent"""
            try:
                time.sleep(2)  # Give client time to receive response
                logging.info("[MIGRATION] Restarting Flask to apply PostgreSQL connection...")
                
                # Get the current Python executable and any original args
                import sys
                python_exe = sys.executable
                script_args = sys.argv[1:] if len(sys.argv) > 1 else []
                
                # Use os.execv to replace current process with new Flask process
                # This preserves the same PID and ensures clean restart
                os.execv(python_exe, [python_exe] + script_args)
            except Exception as e:
                logging.error(f"[MIGRATION] Failed to restart Flask: {e}")
                # If restart fails, log error but don't crash - user can manually restart
        
        # Start restart in background thread (non-blocking)
        restart_thread = threading.Thread(target=restart_flask_after_response, daemon=True)
        restart_thread.start()

        return jsonify({
            "success": True,
            "message": "PostgreSQL configuration saved",
            "requires_restart": True,
            "restart_delay_seconds": 2
        })

    except Exception as e:
        logging.error(f"PostgreSQL migration failed: {e}", exc_info=True)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/help")
@app.route("/help/<path:doc_name>")
def help_page(doc_name=None):
    """Display documentation from /documentation folder"""
    import markdown
    import os
    
    doc_path = os.path.join(os.path.dirname(__file__), "documentation")
    
    # If no doc specified, show index
    if not doc_name:
        doc_name = "INDEX.md"
    elif not doc_name.endswith('.md'):
        doc_name = doc_name + '.md'
    
    # Security: prevent path traversal
    doc_name = os.path.basename(doc_name)
    full_path = os.path.join(doc_path, doc_name)
    
    # Get list of all documentation files
    try:
        doc_files = sorted([f for f in os.listdir(doc_path) if f.endswith('.md')])
    except:
        doc_files = []
    
    # Read and render the markdown file
    content = ""
    doc_title = doc_name.replace('.md', '').replace('_', ' ').title()
    
    if os.path.exists(full_path):
        try:
            with open(full_path, 'r', encoding='utf-8') as f:
                md_content = f.read()
                # Convert markdown to HTML
                content = markdown.markdown(md_content, extensions=['extra', 'codehilite', 'toc'])
        except Exception as e:
            content = f"<p>Error loading documentation: {str(e)}</p>"
    else:
        content = f"<p>Documentation file not found: {doc_name}</p>"
    
    return render_template('help.html', 
                         content=content, 
                         doc_title=doc_title,
                         doc_files=doc_files,
                         current_doc=doc_name)


