@app.route("/api/scan/artist", methods=["POST"])
def api_scan_single_artist():
    """API endpoint to scan a single artist"""
    try:
        data = request.json or {}
        artist = data.get("artist", "").strip()
        force_artist_scan = bool(data.get("force", False))
        
        if not artist:
            return jsonify({"success": False, "error": "Artist name is required"}), 400
        
        # Run the artist scan pipeline in the background
        from threading import Thread
        
        def run_scan():
            try:
                _run_artist_scan_pipeline(artist, force_artist_scan)
                logging.info(f"✅ Scan completed for artist: {artist}")
            except Exception as e:
                logging.error(f"❌ Scan failed for artist {artist}: {e}", exc_info=True)
        
        thread = Thread(target=run_scan, daemon=True)
        thread.start()
        
        return jsonify({
            "success": True,
            "message": f"Scan started for artist: {artist}",
            "artist": artist,
            "mode": "Forced" if force_artist_scan else "Changes Only"
        })
    
    except Exception as e:
        logging.error(f"Error starting artist scan: {e}", exc_info=True)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/scan/from-artist", methods=["POST"])
def api_scan_from_artist():
    """API endpoint to start a popularity scan from a specific artist or letter"""
    global scan_process_popularity
    
    try:
        data = request.json or {}
        artist = data.get("artist", "").strip()
        letter = data.get("letter", "").strip()
        scan_mode = data.get("scan_mode", "changes")  # 'changes' or 'forced'
        
        # If letter is provided, resolve first matching artist from local library.
        # This keeps artist-page scans independent from Navidrome availability/state.
        if letter:
            try:
                letter_upper = letter.upper()
                conn = get_db()
                cursor = conn.cursor()
                placeholder = "%s"
                artist_expr = "COALESCE(NULLIF(album_artist, ''), artist)"

                if letter_upper == '#':
                    cursor.execute(f"""
                        SELECT DISTINCT {artist_expr} AS artist_name
                        FROM tracks
                        WHERE {artist_expr} IS NOT NULL
                          AND {artist_expr} <> ''
                          AND UPPER(SUBSTR({artist_expr}, 1, 1)) NOT BETWEEN 'A' AND 'Z'
                        ORDER BY LOWER({artist_expr})
                        LIMIT 1
                    """)
                else:
                    cursor.execute(f"""
                        SELECT DISTINCT {artist_expr} AS artist_name
                        FROM tracks
                        WHERE {artist_expr} IS NOT NULL
                          AND {artist_expr} <> ''
                          AND UPPER({artist_expr}) LIKE {placeholder}
                        ORDER BY LOWER({artist_expr})
                        LIMIT 1
                    """, (f"{letter_upper}%",))

                row = cursor.fetchone()
                conn.close()

                if not row or not row.get('artist_name'):
                    return jsonify({"success": False, "error": f"No artists found in library starting with '{letter}'"}), 400

                artist = row['artist_name']
                logging.info(f"Letter '{letter}' scan: Using first artist from library: '{artist}'")
                log_unified(f"Popularity Scan - Letter '{letter}' resolved to artist '{artist}' from library")
                
            except Exception as e:
                logging.error(f"Error resolving library artist for letter '{letter}': {e}", exc_info=True)
                return jsonify({"success": False, "error": f"Failed to resolve artist from library: {str(e)}"}), 500
        
        if not artist:
            return jsonify({"success": False, "error": "Artist name or letter is required"}), 400
        
        with scan_lock:
            # Check if popularity scan is already running
            if scan_process_popularity is not None:
                if isinstance(scan_process_popularity, dict):
                    thread = scan_process_popularity.get('thread')
                    if thread and thread.is_alive():
                        return jsonify({"success": False, "error": "Popularity scan is already running"}), 400
                elif hasattr(scan_process_popularity, 'is_alive') and scan_process_popularity.is_alive():
                    return jsonify({"success": False, "error": "Popularity scan is already running"}), 400
            
            # Determine scan parameters
            force_rescan = (scan_mode == "forced")
            
            # Start the popularity scan from this artist
            from popularity import popularity_scan as scan_popularity_func
            import threading
            
            db_dir = os.path.dirname(DB_PATH)
            popularity_progress_file = os.path.join(db_dir, "popularity_scan_progress.json")
            _write_progress_file(
                popularity_progress_file,
                "popularity_scan",
                True,
                {
                    "status": "starting",
                    "resume_from": artist,
                    "current_artist": artist,
                    "processed_artists": 0,
                    "total_artists": 0,
                    "percent_complete": 0,
                }
            )
            mode_desc = "Full (Forced)" if force_rescan else "Changes Only"
            message_suffix = f" (from library letter '{letter}')" if letter else ""
            log_unified(f"Popularity Scan - Starting from artist '{artist}' ({mode_desc}){message_suffix}")
            
            def run_popularity_scan_bg():
                try:
                    logging.info(f"Starting popularity scan from artist '{artist}' (force={force_rescan})")
                    log_unified(f"Popularity Scan - Worker started from artist '{artist}' (force={force_rescan})")
                    completed = scan_popularity_func(
                        verbose=False,
                        force=force_rescan,
                        resume_from=artist,
                        stop_progress_file=popularity_progress_file
                    )
                    if completed is False:
                        _write_progress_with_current_artist(popularity_progress_file, "popularity_scan", False, {"status": "stopped", "exit_code": 0})
                        logging.info(f"Popularity scan from '{artist}' stopped by user request")
                        log_unified(f"Popularity Scan - Stopped from artist '{artist}'")
                    else:
                        _write_progress_with_current_artist(popularity_progress_file, "popularity_scan", False, {"status": "complete", "exit_code": 0})
                        logging.info(f"Popularity scan from '{artist}' completed successfully")
                        log_unified(f"Popularity Scan - Completed from artist '{artist}'")
                        _log_scan_session_complete("popularity")
                except Exception as e:
                    logging.error(f"Error in popularity scan from '{artist}': {e}", exc_info=True)
                    log_unified(f"Popularity Scan - Error from artist '{artist}': {e}")
                    _write_progress_with_current_artist(popularity_progress_file, "popularity_scan", False, {"status": "error", "error": str(e), "exit_code": 1})
            
            scan_thread = threading.Thread(target=run_popularity_scan_bg, daemon=False)
            scan_thread.start()
            scan_process_popularity = {'thread': scan_thread, 'type': 'popularity'}
            
            logging.info(f"Popularity scan thread started from artist '{artist}' ({mode_desc}){message_suffix}")
            
            return jsonify({
                "success": True,
                "message": f"Popularity scan started from artist: {artist}",
                "artist": artist,
                "mode": mode_desc
            })
    
    except Exception as e:
        logging.error(f"Error starting scan from artist: {e}", exc_info=True)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/scan-status")
def api_scan_status():
    """API endpoint to get status of all scan types"""
    global scan_process, scan_process_navidrome, scan_process_popularity, scan_process_singles, scan_process_mood, scan_process_combined, scan_process_missing_releases
    
    def is_process_running(proc):
        """Check if a process/thread is running, handling both dict and process objects."""
        if proc is None:
            return False
        if isinstance(proc, dict):
            # Handle dict format: {'thread': thread_obj, 'type': '...'}
            thread = proc.get('thread')
            if thread is None:
                return False
            # For threads, check is_alive()
            if hasattr(thread, 'is_alive'):
                return thread.is_alive()
            # For processes, check poll()
            if hasattr(thread, 'poll'):
                return thread.poll() is None
            return False
        # Direct process/thread object
        if hasattr(proc, 'is_alive'):
            return proc.is_alive()
        if hasattr(proc, 'poll'):
            return proc.poll() is None
        return False
    
    with scan_lock:
        return jsonify({
            "main_scan": {
                "name": "Main Rating Scan",
                "running": is_process_running(scan_process)
            },
            "navidrome_scan": {
                "name": "Navidrome Sync",
                "running": is_process_running(scan_process_navidrome)
            },
            "popularity_scan": {
                "name": "Popularity Update",
                "running": is_process_running(scan_process_popularity)
            },
            "singles_scan": {
                "name": "Single Detection",
                "running": is_process_running(scan_process_singles)
            },
            "mood_scan": {
                "name": "Mood Scan",
                "running": is_process_running(scan_process_mood)
            },
            "combined_scan": {
                "name": "Combined Scan",
                "running": is_process_running(scan_process_combined)
            },
            "missing_releases_scan": {
                "name": "Missing Releases Scan",
                "running": is_process_running(scan_process_missing_releases)
            }
        })


@app.route("/api/recent-scans")
def api_recent_scans():
    """Return latest album scan events for dashboard refresh (up to 100 items)."""
    try:
        limit = request.args.get("limit", 100, type=int)
        limit = min(limit, 100)
        from scan_history import get_recent_album_scans
        scans = get_recent_album_scans(limit=limit)

        response = jsonify({
            "scans": scans,
            "fetched_at": datetime.utcnow().isoformat() + "Z",
        })
        response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"
        return response
    except Exception as e:
        logging.error(f"Error fetching recent scans: {e}")
        response = jsonify({
            "scans": [],
            "error": str(e),
            "fetched_at": datetime.utcnow().isoformat() + "Z",
        })
        response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"
        return response


@app.route("/api/scan-progress")
def api_scan_progress():
    """API endpoint to get detailed scan progress"""
    global scan_process_navidrome, scan_process_popularity, scan_process_singles, scan_process_mood, scan_process_essentia_mood, scan_process_combined, scan_process_missing_releases
    
    try:
        from unified_scan import get_scan_progress
        progress = get_scan_progress()

        def _active_entry(scan_key: str, state: dict):
            return {
                "scan_type": state.get("scan_type") or scan_key,
                "is_running": bool(state.get("is_running", False)),
                "percent_complete": int(state.get("percent_complete", 0) or 0),
                "current_artist": state.get("current_artist"),
                "current_album": state.get("current_album"),
                "processed_artists": state.get("processed_artists"),
                "total_artists": state.get("total_artists"),
                "scanned_albums": state.get("scanned_albums"),
                "total_albums": state.get("total_albums"),
            }

        active_scans = []
        if progress.get("is_running", False):
            active_scans.append(_active_entry(progress.get("scan_type") or "unified_scan", progress))

        db_dir = os.path.dirname(DB_PATH)
        scan_checks = [
            ("navidrome_scan", os.path.join(db_dir, "navidrome_scan_progress.json"), scan_process_navidrome),
            ("popularity_scan", os.path.join(db_dir, "popularity_scan_progress.json"), scan_process_popularity),
            ("singles_scan", os.path.join(db_dir, "singles_scan_progress.json"), scan_process_singles),
            ("mood_scan", os.path.join(db_dir, "mood_scan_progress.json"), scan_process_mood),
            ("essentia_mood_scan", os.path.join(db_dir, "essentia_mood_scan_progress.json"), scan_process_essentia_mood),
            ("combined_scan", os.path.join(db_dir, "combined_scan_progress.json"), scan_process_combined),
            ("missing_releases_scan", os.path.join(db_dir, "missing_releases_scan_progress.json"), scan_process_missing_releases),
        ]

        progress_by_type = {}
        for scan_key, file_path, proc_ref in scan_checks:
            state = _validate_and_cleanup_progress_file(file_path, proc_ref)
            if state and state.get("is_running", False):
                entry = _active_entry(scan_key, state)
                scan_type = entry.get("scan_type") or scan_key
                if scan_type not in progress_by_type:
                    progress_by_type[scan_type] = state
                    active_scans.append(entry)

        # De-duplicate active scan entries by scan_type while preserving order.
        deduped_active_scans = []
        seen_scan_types = set()
        for entry in active_scans:
            scan_type = entry.get("scan_type") or "unknown"
            if scan_type in seen_scan_types:
                continue
            seen_scan_types.add(scan_type)
            deduped_active_scans.append(entry)
        active_scans = deduped_active_scans
        
        # If unified scan is not running, check for Navidrome, Popularity, Singles, and Combined scans
        if not progress.get("is_running", False):
            priority = [
                "navidrome_scan",
                "popularity_scan",
                "singles_scan",
                "mood_scan",
                "essentia_mood_scan",
                "combined_scan",
                "missing_releases_scan",
            ]
            for scan_type in priority:
                state = progress_by_type.get(scan_type)
                if state and state.get("is_running", False):
                    payload = dict(state)
                    payload["active_scans"] = active_scans
                    payload["active_scan_count"] = len(active_scans)
                    return jsonify(payload)

        payload = dict(progress)
        payload["active_scans"] = active_scans
        payload["active_scan_count"] = len(active_scans)
        if active_scans and not payload.get("is_running", False):
            payload["is_running"] = True
        return jsonify(payload)
    except Exception as e:
        logging.error(f"Error getting scan progress: {e}")
        return jsonify({
            "is_running": False,
            "percent_complete": 0,
            "current_artist": None,
            "current_album": None,
            "active_scans": [],
            "active_scan_count": 0,
            "error": str(e)
        })


@app.route("/api/scan-logs")
def api_scan_logs():
    """API endpoint to get last log entries for each scan type"""
    import re
    
    log_files = {
        "navidrome": LOG_PATH,  # Navidrome scans log to main app log
        "popularity": os.path.join(os.path.dirname(CONFIG_PATH), "popularity.log"),
        "singles": os.path.join(os.path.dirname(CONFIG_PATH), "popularity.log"),  # Singles detection integrated into popularity.py
        # Beets auto-import now drives the file-path scan; read its log instead of the old mp3scanner log
        "file_paths": os.path.join(os.path.dirname(CONFIG_PATH), "beets_import.log")
    }
    
    def extract_meaningful_log(line):
        """Extract meaningful log message, removing timestamps and excessive details"""
        # Remove timestamp prefix (e.g., "2024-01-15 10:30:45,123 - ")
        line = re.sub(r'^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2},\d+ - ', '', line)
        # Remove log level prefix (e.g., "INFO - ", "DEBUG - ", "ERROR - ")
        line = re.sub(r'^(INFO|DEBUG|WARNING|ERROR|CRITICAL)\s*-?\s*', '', line)
        # Remove full file paths (keep just filename)
        line = re.sub(r'[A-Za-z]:\\[^\s]*\\', '', line)
        line = re.sub(r'/[^\s]*/([^\s/]*\.mp3)', r'\1', line)
        return line.strip()
    
    def is_meaningful_log(line):
        """Check if log line contains meaningful scan information"""
        line_lower = line.lower()
        # Keywords that indicate meaningful log entries
        meaningful_keywords = [
            'scanning', 'syncing', 'scanning album', 'scanning artist',
            'found', 'match', 'updated', 'importing', 'processing',
            'completed', 'finished', 'detected', 'checking', 'analyzing',
            'no match', 'error', 'failed', 'success', 'track', 'album',
            'artist', 'single', 'rating', 'score', 'popularity'
        ]
        # Skip debug lines that are too verbose
        skip_keywords = ['debug', 'checking match', 'checking for', 'found in']
        
        # Check if line contains skip keywords
        for skip in skip_keywords:
            if skip in line_lower:
                return False
        
        # Check if line contains meaningful keywords
        return any(keyword in line_lower for keyword in meaningful_keywords)
    
    result = {}
    for scan_type, log_path in log_files.items():
        lines = []
        if os.path.exists(log_path):
            try:
                with open(log_path, 'r', encoding='utf-8', errors='ignore') as f:
                    all_lines = f.readlines()
                    # Get last meaningful non-empty lines
                    for line in reversed(all_lines):
                        line = line.strip()
                        if line and is_meaningful_log(line):
                            meaningful_line = extract_meaningful_log(line)
                            if meaningful_line and len(lines) < 3:
                                lines.append(meaningful_line)
                    lines.reverse()
            except Exception as e:
                lines = [f"Error reading log: {str(e)}"]
        result[scan_type] = lines
    
    return jsonify(result)


@app.route("/api/track-count")
def api_track_count():
    """API endpoint to get total track count for progress calculation"""
    conn = None
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        def _scalar_value(row):
            if row is None:
                return 0
            if isinstance(row, dict):
                return next(iter(row.values()), 0)
            if hasattr(row, "keys"):
                return row[0]
            return row[0]

        cursor.execute("SELECT COUNT(*) AS count FROM tracks")
        total_tracks = _scalar_value(cursor.fetchone())

        # Also get counts with different metadata filled in.
        cursor.execute("SELECT COUNT(*) AS count FROM tracks WHERE stars IS NOT NULL")
        navidrome_filled = _scalar_value(cursor.fetchone())

        cursor.execute("SELECT COUNT(*) AS count FROM tracks WHERE spotify_score IS NOT NULL")
        popularity_filled = _scalar_value(cursor.fetchone())

        cursor.execute("SELECT COUNT(*) AS count FROM tracks WHERE is_single IS NOT NULL")
        singles_filled = _scalar_value(cursor.fetchone())

        cursor.execute("SELECT COUNT(*) AS count FROM tracks WHERE file_path IS NOT NULL")
        filepath_filled = _scalar_value(cursor.fetchone())

        return jsonify({
            "total_tracks": total_tracks,
            "navidrome_filled": navidrome_filled,
            "popularity_filled": popularity_filled,
            "singles_filled": singles_filled,
            "filepath_filled": filepath_filled
        })
    except Exception as e:
        logging.error(f"Error getting track count: {e}")
        return jsonify({"error": str(e)}), 500
    finally:
        try:
            if conn:
                conn.close()
        except Exception:
            pass


