@app.route("/api/musicbrainz/downloads", methods=["GET"])

def api_musicbrainz_downloads():
    """Get all managed downloads with track count information"""
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        cursor.execute("""
            SELECT id, release_id, release_title, artist, method, status, 
                   external_id, error_message, created_at, updated_at, completed_at
            FROM managed_downloads
            WHERE status != 'removed'
            ORDER BY created_at DESC
            LIMIT 100
        """)
        
        rows = cursor.fetchall()
        
        downloads = []
        for row in rows:
            download_id = row[0]
            release_id = row[1]
            
            # Count associated tracks in download_queue for this release
            cursor.execute(f"""
                SELECT COUNT(*) as total, 
                       SUM(CASE WHEN status = 'completed' THEN 1 ELSE 0 END) as completed,
                       SUM(CASE WHEN status IN ('downloading', 'in_progress') THEN 1 ELSE 0 END) as downloading,
                       SUM(CASE WHEN status = 'failed' THEN 1 ELSE 0 END) as failed
                FROM download_queue
                WHERE release_id = {placeholder}
            """, (release_id,))
            
            track_row = cursor.fetchone()
            total_tracks = track_row[0] if track_row else 0
            completed_tracks = track_row[1] if track_row else 0
            downloading_tracks = track_row[2] if track_row else 0
            failed_tracks = track_row[3] if track_row else 0
            
            downloads.append({
                "id": row[0],
                "release_id": row[1],
                "release_title": row[2],
                "artist": row[3],
                "method": row[4],
                "status": row[5],
                "external_id": row[6],
                "error_message": row[7],
                "created_at": row[8],
                "updated_at": row[9],
                "completed_at": row[10],
                "total_tracks": total_tracks,
                "completed_tracks": completed_tracks,
                "downloading_tracks": downloading_tracks,
                "failed_tracks": failed_tracks
            })
        
        conn.close()
        return jsonify({"downloads": downloads})
        
    except Exception as e:
        logging.error(f"[MB_DOWNLOADS] Error: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/musicbrainz/download/<int:download_id>/retry", methods=["POST"])
def api_musicbrainz_retry(download_id):
    """Retry a failed download"""
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        cursor.execute(f"""
            SELECT release_id, release_title, artist, method, download_query
            FROM managed_downloads
            WHERE id = {placeholder}
        """, (download_id,))
        
        row = cursor.fetchone()
        if not row:
            conn.close()
            return jsonify({"error": "Download not found"}), 404
        
        _, _, _, method, download_query = row
        
        # Reset status to queued and clear error
        cursor.execute(f"""
            UPDATE managed_downloads 
            SET status = 'queued', error_message = NULL, external_id = NULL, updated_at = CURRENT_TIMESTAMP
            WHERE id = {placeholder}
        """, (download_id,))
        conn.commit()
        conn.close()
        
        # Reinitiate download in background thread with fresh connection
        if method == "slskd":
            thread = threading.Thread(target=_initiate_slskd_download_bg, args=(download_id, download_query), daemon=True)
            thread.start()
        elif method == "qbittorrent":
            thread = threading.Thread(target=_initiate_qbit_download_bg, args=(download_id, download_query), daemon=True)
            thread.start()
        
        return jsonify({"success": True, "message": "Download retry initiated"})
        
    except Exception as e:
        logging.error(f"[MB_RETRY] Error: {e}")
        return jsonify({"error": str(e)}), 500


