@app.route("/api/downloads/folder-duplicates", methods=["GET"])
def api_downloads_folder_duplicates():
    """
    Detect duplicate folders that match the same MusicBrainz release.
    Returns groups of folders that should be merged.
    """
    try:
        conn = get_db()
        cursor = conn.cursor()
        if not _table_exists(cursor, 'folder_album_matches'):
            conn.close()
            return jsonify({
                "success": True,
                "duplicates": [],
                "total_duplicate_groups": 0,
                "message": "folder_album_matches table not found"
            })
        
        # Find releases with multiple folder matches
        cursor.execute("""
            SELECT
                mb_release_id,
                mb_source,
                MIN(artist) AS artist,
                MIN(album) AS album,
                COUNT(*) as folder_count
            FROM folder_album_matches
            GROUP BY mb_release_id, mb_source
            HAVING COUNT(*) > 1
            ORDER BY folder_count DESC
        """)
        
        duplicates = []
        for row in cursor.fetchall():
            mb_release_id = _row_get(row, 'mb_release_id', 0)
            mb_source = _row_get(row, 'mb_source', 1)
            
            # Get all folders for this release
            placeholder = "%s"
            cursor.execute(f"""
                SELECT 
                    id, folder_path, total_expected_tracks, 
                    matched_tracks_count, status, created_at
                FROM folder_album_matches
                WHERE mb_release_id = {placeholder} AND mb_source = {placeholder}
                ORDER BY created_at ASC
            """, (mb_release_id, mb_source))
            
            folders = [
                {
                    'id': _row_get(f, 'id', 0),
                    'folder_path': _row_get(f, 'folder_path', 1),
                    'total_expected_tracks': _row_get(f, 'total_expected_tracks', 2),
                    'matched_tracks_count': _row_get(f, 'matched_tracks_count', 3),
                    'status': _row_get(f, 'status', 4),
                    'created_at': _row_get(f, 'created_at', 5)
                }
                for f in cursor.fetchall()
            ]
            
            duplicates.append({
                'mb_release_id': mb_release_id,
                'mb_source': mb_source,
                'artist': _row_get(row, 'artist', 2),
                'album': _row_get(row, 'album', 3),
                'folder_count': _row_get(row, 'folder_count', 4),
                'folders': folders,
                'suggestion': 'merge_to_first' if len(folders) > 1 else None
            })
        
        conn.close()
        
        return jsonify({
            "success": True,
            "duplicates": duplicates,
            "total_duplicate_groups": len(duplicates)
        })
        
    except Exception as e:
        if _is_pg_startup_unavailable_error(e):
            logging.info("Folder duplicate detection unavailable while PostgreSQL starts; returning empty list")
            return jsonify({
                "success": True,
                "duplicates": [],
                "total_duplicate_groups": 0,
                "message": "PostgreSQL is starting up; try again shortly"
            })
        logging.error(f"Error detecting folder duplicates: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({
            "success": False,
            "error": str(e)
        }), 500


@app.route("/api/downloads/folder-merge", methods=["POST"])
def api_downloads_folder_merge():
    """
    Merge duplicate folders into the primary folder.
    Moves track files and updates database records.
    
    Request JSON:
        primary_folder_id: ID of folder to keep
        secondary_folder_ids: List of folder IDs to merge into primary
    """
    try:
        import shutil
        from pathlib import Path
        
        data = request.get_json() or {}
        primary_id = data.get('primary_folder_id')
        secondary_ids = data.get('secondary_folder_ids', [])
        
        if not primary_id or not secondary_ids:
            return jsonify({
                "success": False,
                "error": "primary_folder_id and secondary_folder_ids are required"
            }), 400
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Get primary folder info
        cursor.execute(f"""
            SELECT folder_path, artist, album, total_expected_tracks
            FROM folder_album_matches
            WHERE id = {placeholder}
        """, (primary_id,))
        
        primary_row = cursor.fetchone()
        if not primary_row:
            conn.close()
            return jsonify({
                "success": False,
                "error": f"Primary folder {primary_id} not found"
            }), 404
        
        primary_path = _row_get(primary_row, 'folder_path', 0)
        merged_count = 0
        errors = []
        
        # Merge each secondary folder
        for secondary_id in secondary_ids:
            try:
                # Get secondary folder tracks
                cursor.execute(f"""
                    SELECT file_path, track_number, track_title, track_artist
                    FROM folder_track_matches
                    WHERE folder_match_id = {placeholder}
                """, (secondary_id,))
                
                secondary_tracks = cursor.fetchall()
                
                # Move track files to primary folder
                for track in secondary_tracks:
                    source_file = _row_get(track, 'file_path', 0)
                    if not os.path.exists(source_file):
                        continue
                    
                    # Keep same filename
                    filename = os.path.basename(source_file)
                    dest_file = os.path.join(primary_path, filename)
                    
                    # Handle filename conflicts
                    if os.path.exists(dest_file):
                        base, ext = os.path.splitext(filename)
                        counter = 1
                        while os.path.exists(dest_file):
                            dest_file = os.path.join(primary_path, f"{base}_{counter}{ext}")
                            counter += 1
                    
                    # Move file
                    shutil.move(source_file, dest_file)
                    logging.info(f"Merged file: {source_file} -> {dest_file}")
                    
                    # Update track match to point to primary folder
                    cursor.execute(f"""
                        UPDATE folder_track_matches
                        SET folder_match_id = {placeholder}, file_path = {placeholder}
                        WHERE folder_match_id = {placeholder} AND file_path = {placeholder}
                    """, (primary_id, dest_file, secondary_id, source_file))
                    
                    merged_count += 1
                
                # Delete secondary folder record
                cursor.execute(f"DELETE FROM folder_album_matches WHERE id = {placeholder}", (secondary_id,))
                
                logging.info(f"Merged folder {secondary_id} into {primary_id}")
                
            except Exception as merge_error:
                error_msg = f"Error merging folder {secondary_id}: {merge_error}"
                logging.error(error_msg)
                errors.append(error_msg)
        
        # Update primary folder track count
        cursor.execute(f"""
            UPDATE folder_album_matches
            SET matched_tracks_count = (
                SELECT COUNT(*) FROM folder_track_matches WHERE folder_match_id = {placeholder}
            ),
            updated_at = CURRENT_TIMESTAMP
            WHERE id = {placeholder}
        """, (primary_id, primary_id))
        
        conn.commit()
        conn.close()
        
        return jsonify({
            "success": True,
            "merged_tracks": merged_count,
            "merged_folders": len(secondary_ids) - len(errors),
            "errors": errors
        })
        
    except Exception as e:
        logging.error(f"Error merging folders: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({
            "success": False,
            "error": str(e)
        }), 500


# ===== Download Queue Management (New Dynamic Queue System) =====

def _check_track_in_local_collection(artist, title, album=None):
    """Check whether a track already exists in the local music library.

    Queries the ``tracks`` table (populated by the Navidrome import) using
    case-insensitive exact matching on artist + title, with an optional album
    filter.  The ``file_path`` column in that table holds the on-disk path
    reported by Navidrome (e.g. ``/music/Xandria/2023 - …/03 - Song.flac``).

    Returns:
        dict:
            ``found``     – bool
            ``file_path`` – str | None  (the library path)
            ``title``     – str | None
            ``artist``    – str | None
            ``album``     – str | None
    """
    if not artist or not title:
        return {"found": False}

    artist_lc = artist.strip().lower()
    title_lc = title.strip().lower()

    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        if album:
            album_lc = album.strip().lower()
            cursor.execute(
                f"""
                SELECT title, artist, album, file_path
                FROM tracks
                WHERE LOWER(COALESCE(NULLIF(album_artist, ''), artist)) = {placeholder}
                  AND LOWER(title) = {placeholder}
                  AND LOWER(COALESCE(album, '')) = {placeholder}
                LIMIT 1
                """,
                (artist_lc, title_lc, album_lc),
            )
        else:
            cursor.execute(
                f"""
                SELECT title, artist, album, file_path
                FROM tracks
                WHERE LOWER(COALESCE(NULLIF(album_artist, ''), artist)) = {placeholder}
                  AND LOWER(title) = {placeholder}
                LIMIT 1
                """,
                (artist_lc, title_lc),
            )

        row = cursor.fetchone()
        conn.close()

        if not row:
            return {"found": False}

        if hasattr(row, 'get'):
            return {
                "found": True,
                "file_path": row.get("file_path"),
                "title": row.get("title"),
                "artist": row.get("artist"),
                "album": row.get("album"),
            }
        return {
            "found": True,
            "file_path": row[3] if len(row) > 3 else None,
            "title": row[0] if len(row) > 0 else None,
            "artist": row[1] if len(row) > 1 else None,
            "album": row[2] if len(row) > 2 else None,
        }
    except Exception as e:
        logging.debug(f"[COLLECTION_CHECK] {artist} – {title}: {e}")
        return {"found": False}


@app.route("/api/queue/check-collection-batch", methods=["POST"])
def api_queue_check_collection_batch():
    """Check which tracks in a list already exist in the local music library.

    Request body::

        {
          "tracks": [
            {"artist": "…", "title": "…", "album": "…"},
            …
          ]
        }

    Response::

        {
          "results": [
            {
              "artist": "…", "title": "…", "album": "…",
              "found": true,
              "file_path": "/music/…/track.flac"
            },
            …
          ]
        }
    """
    try:
        data = request.get_json() or {}
        tracks = data.get("tracks") or []
        if not isinstance(tracks, list):
            return jsonify({"error": "tracks must be an array"}), 400

        results = []
        for t in tracks:
            artist = str(t.get("artist") or "").strip()
            title = str(t.get("title") or "").strip()
            album = str(t.get("album") or "").strip() or None
            check = _check_track_in_local_collection(artist, title, album)
            results.append({
                "artist": artist,
                "title": title,
                "album": album,
                "found": check["found"],
                "file_path": check.get("file_path"),
            })

        return jsonify({"results": results})
    except Exception as e:
        logging.error(f"[CHECK_COLLECTION] Batch check failed: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/queue/add", methods=["POST"])
def api_queue_add():
    """Add song/album to download queue"""
    try:
        from download_queue_manager import add_to_queue, check_downloads_folder
        allowed_sources = {"soulseek", "qbittorrent"}
        
        data = request.get_json()
        if not data:
            logging.warning(f"Queue add called with no JSON data")
            return jsonify({"error": "No data provided"}), 400
        
        # Log received data for debugging
        logging.debug(f"Queue add request data: {data}")
            
        artist = data.get('artist', '').strip() if data.get('artist') else ''
        title = data.get('title', '').strip() if data.get('title') else ''
        album = data.get('album', '').strip() if data.get('album') else None
        import_type = str(data.get('import_type', 'song') or 'song').strip().lower()
        explicit_source = data.get('source')
        if explicit_source:
            source = str(explicit_source).strip().lower()
        else:
            # Default routing policy:
            # - Album/full-release requests: qBittorrent first
            # - Individual tracks: Soulseek first
            is_album_request = bool(data.get('is_album')) or import_type == 'album'
            source = 'qbittorrent' if is_album_request else 'soulseek'

        if source not in allowed_sources:
            return jsonify({
                "error": f"Invalid source '{source}'. Allowed: {', '.join(sorted(allowed_sources))}"
            }), 400

        # Optional metadata used by file organization (year-based folder naming)
        # and post-download enrichment.
        track_number = data.get('track_number')
        if track_number:
            track_number = str(track_number).strip() if isinstance(track_number, str) else str(track_number)
        else:
            track_number = None

        album_artist = data.get('album_artist', '').strip() if data.get('album_artist') else None

        year = data.get('year')
        if year:
            year = str(year).strip() if isinstance(year, str) else str(year)
            if len(year) >= 4:
                year = year[:4]
        else:
            year = None

        release_id = data.get('release_id', '').strip() if data.get('release_id') else None
        release_source = data.get('release_source', '').strip() if data.get('release_source') else None

        disc_number = data.get('disc_number')
        if disc_number:
            disc_number = str(disc_number).strip() if isinstance(disc_number, str) else str(disc_number)
        else:
            disc_number = None

        release_mbid = data.get('release_mbid', '').strip() if data.get('release_mbid') else None
        recording_mbid = data.get('recording_mbid', '').strip() if data.get('recording_mbid') else None
        cover_art_url = data.get('cover_art_url', '').strip() if data.get('cover_art_url') else None

        duration = data.get('duration')
        if duration not in (None, ''):
            try:
                duration = float(duration)
                if duration <= 0:
                    duration = None
            except (TypeError, ValueError):
                duration = None
        else:
            duration = None
        
        # Handle priority parsing
        try:
            priority = int(data.get('priority', 5))
        except (ValueError, TypeError):
            priority = 5
        
        if not artist or not title:
            logging.warning(f"Queue add missing required fields: artist='{artist}', title='{title}'")
            return jsonify({"error": "Artist and title are required"}), 400

        # Pre-queue collection check: skip download if track already in local library.
        collection_hit = _check_track_in_local_collection(artist, title, album)
        if collection_hit["found"]:
            return jsonify({
                "success": True,
                "skipped": True,
                "in_collection": True,
                "collection_path": collection_hit.get("file_path"),
                "message": (
                    f"{artist} – {title} is already in your library"
                    + (f" at {collection_hit['file_path']}" if collection_hit.get("file_path") else "")
                ),
            })

        logging.info(f"Adding to queue: {artist} - {title} (album: {album}, source: {source}, priority: {priority})")
        
        # Add to queue
        try:
            item = add_to_queue(
                artist,
                title,
                album,
                source,
                priority,
                import_type=import_type,
                track_number=track_number,
                album_artist=album_artist,
                year=year,
                release_id=release_id,
                release_source=release_source,
                duration=duration,
                disc_number=disc_number,
                release_mbid=release_mbid,
                recording_mbid=recording_mbid,
                cover_art_url=cover_art_url,
            )
        except Exception as e:
            logging.error(f"Error in add_to_queue: {type(e).__name__}: {e}")
            import traceback
            logging.error(traceback.format_exc())
            return jsonify({"error": f"Failed to add to queue: {str(e)}"}), 500
        
        if item:
            return jsonify({
                "success": True,
                "queue_id": item.get('id') if isinstance(item, dict) else None,
                "message": f"Added to queue: {artist} - {title}",
                "item": item
            })
        else:
            error_msg = "Failed to add to queue - check server logs for details"
            logging.error(f"add_to_queue returned None for: {artist} - {title}")
            return jsonify({"error": error_msg}), 500
            
    except Exception as e:
        logging.error(f"Unexpected error adding to queue: {type(e).__name__}: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({"error": f"Server error: {type(e).__name__}"}), 500


@app.route("/api/queue/add-batch", methods=["POST"])
def api_queue_add_batch():
    """Add multiple songs/albums to download queue in a single request"""
    try:
        from download_queue_manager import add_to_queue
        import download_queue_manager as dqm
        import uuid
        allowed_sources = {"soulseek", "qbittorrent"}

        def _run_queue_schema_self_heal_once(already_ran):
            """Best-effort runtime schema repair for stale DBs during batch queue adds."""
            if already_ran:
                return True
            try:
                from migrations.startup_queue_columns_fast import main as startup_schema_migration_main
                startup_schema_migration_main()
            except Exception as migration_err:
                logging.warning(f"[QUEUE_BATCH] Startup schema self-heal failed: {migration_err}")
            try:
                dqm._queue_schema_checked = False
            except Exception:
                pass
            return True
        
        data = request.get_json()
        if not data or 'items' not in data:
            logging.warning(f"Batch queue add called with no items")
            return jsonify({"error": "No items provided"}), 400
        
        items = data.get('items', [])
        if not isinstance(items, list):
            return jsonify({"error": "items must be an array"}), 400

        batch_source = str(data.get('source') or '').strip().lower()
        
        logging.info(f"Adding {len(items)} items to queue in batch")
        
        # Use provided import_group_id, or generate one based on artist+album if available
        # This allows downloads from the same album to be grouped together for batch organization
        import_group_id = data.get('import_group')
        
        if not import_group_id and items:
            # Generate group ID from artist + album of first item
            first_item = items[0]
            artist = first_item.get('artist', '').strip() if first_item.get('artist') else 'Unknown'
            album = first_item.get('album', '').strip() if first_item.get('album') else None
            
            if album:
                # Use artist+album as group identifier: safe for filesystem and URLs
                import_group_id = f"{artist}_{album}".replace(' ', '_')[:100]
            else:
                # Fallback to UUID if no album
                import_group_id = str(uuid.uuid4())
        
        # Determine import type based on context and number of items
        import_type = data.get('import_type', 'playlist' if len(items) > 1 else 'song')
        
        added_count = 0
        skipped_count = 0
        failed_count = 0
        failed_tracks = []
        failed_details = []
        skipped_tracks = []
        in_collection_count = 0
        in_collection_tracks = []
        schema_self_heal_ran = False
        
        for item_data in items:
            artist = item_data.get('artist', '').strip() if item_data.get('artist') else ''
            title = item_data.get('title', '').strip() if item_data.get('title') else ''
            album = item_data.get('album', '').strip() if item_data.get('album') else None
            item_source = str(item_data.get('source') or '').strip().lower()
            if item_source in allowed_sources:
                source = item_source
            elif batch_source in allowed_sources:
                source = batch_source
            else:
                # Batch default routing policy:
                # - Album imports: qBittorrent first
                # - Song/playlist track imports: Soulseek first
                source = 'qbittorrent' if import_type == 'album' else 'soulseek'

            if item_source and item_source not in allowed_sources:
                logging.info(
                    f"[QUEUE_BATCH] Ignoring non-transport item source '{item_source}' for {artist} - {title}; using '{source}'"
                )
            elif batch_source and batch_source not in allowed_sources:
                logging.info(
                    f"[QUEUE_BATCH] Ignoring non-transport batch source '{batch_source}' for import_group={import_group_id}; using '{source}'"
                )

            if source not in allowed_sources:
                failed_count += 1
                failed_tracks.append(title or 'Unknown')
                logging.warning(f"Skipping item with invalid source '{source}' for {artist} - {title}")
                continue
            
            # Extract MusicBrainz/Discogs metadata if provided
            # Handle both string and int types for numeric fields
            track_number = item_data.get('track_number')
            if track_number:
                track_number = str(track_number).strip() if isinstance(track_number, str) else str(track_number)
            else:
                track_number = None
            
            album_artist = item_data.get('album_artist', '').strip() if item_data.get('album_artist') else None
            
            year = item_data.get('year')
            if year:
                year = str(year).strip() if isinstance(year, str) else str(year)
            else:
                year = None
            
            release_id = item_data.get('release_id', '').strip() if item_data.get('release_id') else None
            release_source = item_data.get('release_source', '').strip() if item_data.get('release_source') else None

            disc_number = item_data.get('disc_number')
            if disc_number:
                disc_number = str(disc_number).strip() if isinstance(disc_number, str) else str(disc_number)
            else:
                disc_number = None

            release_mbid = item_data.get('release_mbid', '').strip() if item_data.get('release_mbid') else None
            recording_mbid = item_data.get('recording_mbid', '').strip() if item_data.get('recording_mbid') else None
            cover_art_url = item_data.get('cover_art_url', '').strip() if item_data.get('cover_art_url') else None

            duration = item_data.get('duration')
            if duration not in (None, ''):
                try:
                    duration = float(duration)
                    if duration <= 0:
                        duration = None
                except (TypeError, ValueError):
                    duration = None
            else:
                duration = None
            
            try:
                priority = int(item_data.get('priority', 5))
            except (ValueError, TypeError):
                priority = 5
            
            if not artist or not title:
                failed_count += 1
                failed_tracks.append(title or 'Unknown')
                logging.warning(f"Skipping item with missing fields: artist='{artist}', title='{title}'")
                continue

            # Pre-queue collection check: skip download if already in local library.
            collection_hit = _check_track_in_local_collection(artist, title, album)
            if collection_hit["found"]:
                in_collection_count += 1
                in_collection_tracks.append({
                    "artist": artist,
                    "title": title,
                    "album": album,
                    "file_path": collection_hit.get("file_path"),
                })
                skipped_count += 1
                skipped_tracks.append(title)
                logging.info(
                    f"[QUEUE_BATCH] Skipping {artist} – {title}: already in local library "
                    f"at {collection_hit.get('file_path')}"
                )
                continue

            try:
                item = add_to_queue(artist, title, album, source, priority,
                                   import_group=import_group_id, import_type=import_type,
                                   track_number=track_number, album_artist=album_artist,
                                   year=year, release_id=release_id, release_source=release_source,
                                   duration=duration, disc_number=disc_number,
                                   release_mbid=release_mbid, recording_mbid=recording_mbid,
                                   cover_art_url=cover_art_url)

                # Self-heal path: add_to_queue can return None on schema drift.
                # Run startup schema migration once, then retry this item.
                if not item:
                    schema_self_heal_ran = _run_queue_schema_self_heal_once(schema_self_heal_ran)
                    item = add_to_queue(artist, title, album, source, priority,
                                       import_group=import_group_id, import_type=import_type,
                                       track_number=track_number, album_artist=album_artist,
                                       year=year, release_id=release_id, release_source=release_source,
                                       duration=duration, disc_number=disc_number,
                                       release_mbid=release_mbid, recording_mbid=recording_mbid,
                                       cover_art_url=cover_art_url)

                if item:
                    outcome = str(item.get('_queue_outcome', 'added')).strip().lower() if hasattr(item, 'get') else 'added'
                    if outcome == 'duplicate' or bool(item.get('already_queued')):
                        skipped_count += 1
                        skipped_tracks.append(title)
                    else:
                        added_count += 1
                else:
                    failed_count += 1
                    failed_tracks.append(title)
                    failed_details.append({
                        "artist": artist,
                        "title": title,
                        "reason": "add_to_queue returned no result"
                    })
            except Exception as e:
                failed_count += 1
                failed_tracks.append(title)
                logging.error(f"Error adding track '{title}' to queue: {e}")
                failed_details.append({
                    "artist": artist,
                    "title": title,
                    "reason": str(e)
                })

                # Retry once after schema self-heal for known DB drift errors.
                err_text = str(e).lower()
                if (
                    ("column" in err_text or "download_queue" in err_text or "tracks" in err_text or "transaction" in err_text)
                    and not schema_self_heal_ran
                ):
                    try:
                        schema_self_heal_ran = _run_queue_schema_self_heal_once(schema_self_heal_ran)
                        retry_item = add_to_queue(artist, title, album, source, priority,
                                                  import_group=import_group_id, import_type=import_type,
                                                  track_number=track_number, album_artist=album_artist,
                                                  year=year, release_id=release_id, release_source=release_source,
                                                  duration=duration, disc_number=disc_number,
                                                  release_mbid=release_mbid, recording_mbid=recording_mbid,
                                                  cover_art_url=cover_art_url)
                        if retry_item:
                            failed_count -= 1
                            failed_tracks.pop()
                            failed_details.pop()
                            outcome = str(retry_item.get('_queue_outcome', 'added')).strip().lower() if hasattr(retry_item, 'get') else 'added'
                            if outcome == 'duplicate' or bool(retry_item.get('already_queued')):
                                skipped_count += 1
                                skipped_tracks.append(title)
                            else:
                                added_count += 1
                    except Exception as retry_err:
                        logging.error(f"Retry after schema self-heal failed for '{title}': {retry_err}")

        # When every item was already in the library, treat as full success (nothing to download)
        all_failed = failed_count > 0 and added_count == 0 and skipped_count == 0
        success_value = not all_failed

        if all_failed:
            logging.error(
                f"[QUEUE_BATCH] All {failed_count} batch add items failed (import_group={import_group_id}, import_type={import_type})"
            )
            if failed_details:
                # Keep this compact in logs while still surfacing actionable causes.
                logging.error(
                    "[QUEUE_BATCH] Sample failure reasons: %s",
                    failed_details[:3],
                )
            return jsonify({
                "success": False,
                "error": "Failed to add any items to queue",
                "added": added_count,
                "skipped": skipped_count,
                "failed": failed_count,
                "failed_tracks": failed_tracks,
                "failed_details": failed_details,
                "in_collection": in_collection_count,
                "in_collection_tracks": in_collection_tracks,
                "import_group": import_group_id,
                "import_type": import_type,
                "schema_self_heal_ran": schema_self_heal_ran,
                "message": "Failed to add any items to queue"
            }), 500

        return jsonify({
            "success": success_value,
            "added": added_count,
            "skipped": skipped_count,
            "failed": failed_count,
            "failed_tracks": failed_tracks,
            "failed_details": failed_details,
            "skipped_tracks": skipped_tracks,
            "in_collection": in_collection_count,
            "in_collection_tracks": in_collection_tracks,
            "import_group": import_group_id,
            "import_type": import_type,
            "schema_self_heal_ran": schema_self_heal_ran,
            "message": (
                f"Added {added_count} items to queue"
                + (f", skipped {skipped_count}" if skipped_count > 0 else "")
                + (f", {in_collection_count} already in library" if in_collection_count > 0 else "")
                + (f", {failed_count} failed" if failed_count > 0 else "")
            )
        })
        
    except Exception as e:
        logging.error(f"Unexpected error in batch queue add: {type(e).__name__}: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({"error": f"Server error: {type(e).__name__}"}), 500


@app.route("/api/queue/migrate-existing", methods=["POST"])
def api_queue_migrate_existing():
    """Backfill legacy queue rows into current grouped/source conventions."""
    try:
        from download_queue_manager import migrate_existing_queue_items_to_grouped_setup

        data = request.get_json(silent=True) or {}
        # Accept limit from query/form/json so callers can POST without a JSON body.
        limit = request.values.get('limit')
        if limit is None:
            limit = data.get('limit')
        if limit is not None:
            try:
                limit = int(limit)
                if limit <= 0:
                    return jsonify({"error": "limit must be a positive integer"}), 400
            except (TypeError, ValueError):
                return jsonify({"error": "limit must be an integer"}), 400

        result = migrate_existing_queue_items_to_grouped_setup(limit=limit)
        status_code = 200 if result.get("success") else 500
        return jsonify(result), status_code
    except Exception as e:
        logging.error(f"Error migrating existing queue rows: {e}", exc_info=True)
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/queue/status", methods=["GET"])
def api_queue_status():
    """Get queue status and items"""
    try:
        from download_queue_manager import (
            get_queue,
            get_completed_queue,
            check_downloads_folder,
            check_and_remove_failed_downloads,
        )

        status = request.args.get('status')
        # source=None returns all sources (soulseek, qbittorrent, discovered/unmatched)
        source = request.args.get('source') or None
        limit = int(request.args.get('limit', 50))
        reconcile = str(request.args.get('reconcile', 'false')).strip().lower() in ('1', 'true', 'yes', 'on')

        # Reconciliation is optional to keep this endpoint side-effect free by default.
        if reconcile:
            try:
                check_and_remove_failed_downloads()
            except Exception as reconcile_err:
                logging.debug(f"Queue status reconcile skipped: {reconcile_err}")

        # Get queue items (all sources by default)
        active_queue = get_queue(status=status, source=source, limit=limit)

        # Get completed items (includes 'unmatched')
        completed = get_completed_queue(limit=20)

        # Check downloads folder for new files
        newly_completed = check_downloads_folder()

        return jsonify({
            "success": True,
            "active": active_queue,
            "completed": completed,
            "newly_completed": newly_completed,
            "total_active": len(active_queue),
            "total_completed": len(completed)
        })

    except Exception as e:
        logging.error(f"Error getting queue status: {e}")
        return jsonify({"error": str(e)}), 400


@app.route("/api/queue/imported", methods=["GET"])
def api_queue_imported():
    """Get recently imported tracks from beets organization"""
    try:
        limit = int(request.args.get('limit', 50))
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Get recently organized/imported tracks from download_queue.
        # Only return items that were explicitly added with a MusicBrainz/Discogs
        # release ID (release_id IS NOT NULL) so that auto-discovered folder-matched
        # files are excluded from this list.
        cursor.execute(f"""
            SELECT id, artist, title, album, source, status, 
                   import_group, import_type, imported_at, file_path, found_filename,
                   release_id, release_source
            FROM download_queue 
            WHERE status = 'completed' AND imported_at IS NOT NULL
              AND release_id IS NOT NULL
            ORDER BY imported_at DESC
            LIMIT {placeholder}
        """, (limit,))
        
        imported = [dict(row) for row in cursor.fetchall()]
        conn.close()
        
        return jsonify({
            "success": True,
            "imported": imported,
            "total": len(imported)
        })
        
    except Exception as e:
        logging.error(f"Error getting imported tracks: {e}")
        return jsonify({"error": str(e)}), 400


@app.route("/api/queue/<int:queue_id>/update", methods=["POST"])
def api_queue_update(queue_id):
    """Update queue item status"""
    try:
        from download_queue_manager import update_queue_item, mark_as_failed
        
        data = request.get_json()
        action = data.get('action')  # 'searching', 'downloading', 'failed', 'completed'
        
        if action == 'failed':
            reason = data.get('reason', 'Unknown error')
            retry_delay = int(data.get('retry_delay_minutes', 30))
            item = mark_as_failed(queue_id, reason, retry_delay)
        else:
            # Generic update
            item = update_queue_item(queue_id, status=action)
        
        if item:
            return jsonify({
                "success": True,
                "message": f"Queue item updated to: {action}",
                "item": item
            })
        else:
            return jsonify({"error": "Queue item not found"}), 404
            
    except Exception as e:
        logging.error(f"Error updating queue item: {e}")
        return jsonify({"error": str(e)}), 400


@app.route("/api/queue/<int:queue_id>/copy-from-local", methods=["POST"])
def api_queue_copy_from_local(queue_id):
    """Copy a file from its existing /music location to /downloads so it can be
    re-tagged with the queue's target MBID release and moved to the correct album
    folder.

    This handles the case where the same recording already exists in the library
    under a different album (e.g. on a compilation).  The workflow is:
      1. Copy the source file from /music to /downloads.
      2. Set queue status to 'matched' so the normal tag-and-move pipeline picks
         it up automatically on the next processing cycle.
    """
    try:
        import shutil as _shutil

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        cursor.execute(f"SELECT * FROM download_queue WHERE id = {placeholder}", (queue_id,))
        row = cursor.fetchone()
        conn.close()

        if not row:
            return jsonify({"success": False, "error": "Queue item not found"}), 404

        item = dict(row) if hasattr(row, 'keys') else {col[0]: row[idx] for idx, col in enumerate(cursor.description or [])}

        source_path = (item.get('source_music_path') or '').strip()
        if not source_path:
            return jsonify({"success": False, "error": "No source music path stored for this queue item"}), 400
        if not os.path.isfile(source_path):
            return jsonify({"success": False, "error": f"Source file not found on disk: {source_path}"}), 400

        # Resolve /downloads directory.
        try:
            from download_queue_manager import get_downloads_dir
            downloads_dir = get_downloads_dir()
        except Exception:
            downloads_dir = os.environ.get('DOWNLOADS_DIR', '/downloads')

        dest_filename = os.path.basename(source_path)
        dest_path = os.path.join(downloads_dir, dest_filename)

        # Avoid silently overwriting an existing /downloads file.
        if os.path.exists(dest_path):
            base, ext = os.path.splitext(dest_filename)
            dest_path = os.path.join(downloads_dir, f"{base}_local_copy{ext}")

        _shutil.copy2(source_path, dest_path)
        logging.info(
            f"[COPY_FROM_LOCAL] Queue {queue_id}: copied '{source_path}' → '{dest_path}'"
        )

        # Mark as 'matched' with the /downloads copy as the working file so the
        # normal move-to-music pipeline applies the correct MBID tags and moves it.
        from download_queue_manager import update_queue_item
        update_queue_item(queue_id, status='matched', file_path=dest_path)

        return jsonify({
            "success": True,
            "message": "File copied to downloads — will be tagged and moved automatically.",
            "dest_path": dest_path,
        })

    except Exception as e:
        logging.error(f"[COPY_FROM_LOCAL] Error for queue {queue_id}: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/queue/<int:queue_id>/delete", methods=["DELETE"])
def api_queue_delete(queue_id):
    """Delete queue item"""
    try:
        from download_queue_manager import clear_queue_events_for_items
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        delete_download_file = request.args.get('delete_download_file', '0').lower() in {'1', 'true', 'yes'}
        downloads_root = os.path.abspath(_resolve_downloads_monitor_dir(get_config()))
        music_root = os.path.abspath(os.environ.get("MUSIC_ROOT", "/music"))

        cursor.execute(
            f"SELECT file_path, found_filename, title FROM download_queue WHERE id = {placeholder}",
            (queue_id,)
        )
        row = cursor.fetchone()
        if not row:
            conn.close()
            return jsonify({"error": "Queue item not found"}), 404

        file_path = row['file_path'] if isinstance(row, dict) else row[0]
        found_filename = row['found_filename'] if isinstance(row, dict) else row[1]
        track_title = row['title'] if isinstance(row, dict) else row[2]

        deleted_files = []

        def _is_within_allowed_root(path_value):
            if not path_value:
                return False
            try:
                abs_path = os.path.abspath(path_value)
                return (
                    os.path.commonpath([abs_path, downloads_root]) == downloads_root
                    or os.path.commonpath([abs_path, music_root]) == music_root
                )
            except Exception:
                return False

        def _try_delete(path_value):
            if not path_value or not os.path.exists(path_value):
                return
            if not _is_within_allowed_root(path_value):
                logging.info(f"[QUEUE] Skip delete outside allowed roots: {path_value}")
                return
            try:
                os.remove(path_value)
                if not os.path.exists(path_value):
                    deleted_files.append(path_value)
            except Exception as delete_err:
                logging.warning(f"[QUEUE] Failed to delete download file '{path_value}': {delete_err}")

        if delete_download_file:
            # 1) Delete direct file_path only when it is actually inside DOWNLOADS_DIR.
            _try_delete(file_path)

            # 2) Fallback lookup by found filename inside DOWNLOADS_DIR.
            if found_filename and os.path.isdir(downloads_root):
                for root, _dirs, files in os.walk(downloads_root):
                    if found_filename in files:
                        _try_delete(os.path.join(root, found_filename))
                        # Stop after first successful deletion to avoid deleting duplicates.
                        if deleted_files:
                            break
        
        cursor.execute(f"DELETE FROM download_queue WHERE id = {placeholder}", (queue_id,))
        # Clean up event logs for this deleted item
        clear_queue_events_for_items([queue_id])
        conn.commit()
        
        deleted = cursor.rowcount > 0
        conn.close()
        
        if deleted:
            message = "Queue item deleted"
            if delete_download_file:
                if deleted_files:
                    message = "Queue item and download file deleted"
                else:
                    message = "Queue item deleted (no matching file removed from downloads)"
            return jsonify({
                "success": True,
                "message": message,
                "deleted_download_files": deleted_files,
                "title": track_title,
            })
        else:
            return jsonify({"error": "Queue item not found"}), 404
            
    except Exception as e:
        logging.error(f"Error deleting queue item: {e}")
        return jsonify({"error": str(e)}), 400


@app.route("/api/queue/cleanup-copied", methods=["POST"])
def api_queue_cleanup_copied_sources():
    """Delete copied source files from downloads without removing queue rows."""
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        downloads_root = os.path.abspath(_resolve_downloads_monitor_dir(get_config()))

        cursor.execute("""
            SELECT id, file_path, found_filename
            FROM download_queue
            WHERE copied_individually = 1 OR status = 'imported'
        """)
        items = cursor.fetchall()

        def _is_within_downloads(path_value):
            if not path_value:
                return False
            try:
                abs_path = os.path.abspath(path_value)
                return os.path.commonpath([abs_path, downloads_root]) == downloads_root
            except Exception:
                return False

        def _delete_if_exists(path_value):
            if not path_value or not os.path.isfile(path_value):
                return False
            if not _is_within_downloads(path_value):
                return False
            try:
                os.remove(path_value)
                return not os.path.exists(path_value)
            except Exception as del_err:
                logging.warning(f"[CLEANUP] Failed to delete '{path_value}': {del_err}")
                return False

        deleted_count = 0
        scanned_count = 0
        deleted_paths = []

        for row in items:
            queue_id = row['id'] if isinstance(row, dict) else row[0]
            file_path = row['file_path'] if isinstance(row, dict) else row[1]
            found_filename = row['found_filename'] if isinstance(row, dict) else row[2]

            scanned_count += 1
            deleted = False

            if _delete_if_exists(file_path):
                deleted = True
                deleted_paths.append(file_path)

            if not deleted and found_filename and os.path.isdir(downloads_root):
                for root, _dirs, files in os.walk(downloads_root):
                    if found_filename in files:
                        candidate = os.path.join(root, found_filename)
                        if _delete_if_exists(candidate):
                            deleted = True
                            deleted_paths.append(candidate)
                            break

            if deleted:
                deleted_count += 1
                cursor.execute(
                    f"UPDATE download_queue SET updated_at = CURRENT_TIMESTAMP WHERE id = {placeholder}",
                    (queue_id,),
                )

        conn.commit()
        conn.close()

        return jsonify({
            "success": True,
            "scanned": scanned_count,
            "deleted": deleted_count,
            "deleted_paths": deleted_paths,
            "message": f"Cleanup complete: deleted {deleted_count} copied source file(s)"
        })

    except Exception as e:
        logging.error(f"Error cleaning copied source files: {e}")
        return jsonify({"error": str(e)}), 400


@app.route("/api/queue/folder/delete", methods=["POST"])
def api_queue_delete_folder():
    """Delete all files in a downloads folder and optionally remove linked queue items."""
    try:
        from download_queue_manager import clear_queue_events_for_items
        data = request.get_json(silent=True) or {}
        folder_path = (data.get("folder_path") or "").strip()
        remove_queue_items = bool(data.get("remove_queue_items", True))

        if not folder_path:
            return jsonify({"error": "folder_path is required"}), 400

        downloads_root = os.path.abspath(_resolve_downloads_monitor_dir(get_config()))
        allowed_roots = [downloads_root]
        # Scan functions (e.g. scan_downloads_grouped_by_folder) return relative paths;
        # anchor them to downloads_root before resolving, so os.path.abspath doesn't
        # resolve relative to the process CWD and fail the security check.
        if not os.path.isabs(folder_path):
            folder_path = os.path.join(downloads_root, folder_path)
        folder_abs = os.path.abspath(folder_path)

        def _is_within_downloads(path_value):
            try:
                abs_path = os.path.abspath(path_value)
                for root in allowed_roots:
                    if os.path.commonpath([abs_path, os.path.abspath(root)]) == os.path.abspath(root):
                        return True
            except Exception:
                return False
            return False

        if not _is_within_downloads(folder_abs):
            return jsonify({"error": "Refusing to delete outside downloads root"}), 400

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        like_prefix = folder_abs.rstrip(os.sep) + os.sep + "%"
        cursor.execute(
            f"""
            SELECT id, file_path, matched_file_path
            FROM download_queue
            WHERE (file_path = {placeholder} OR file_path LIKE {placeholder})
               OR (matched_file_path = {placeholder} OR matched_file_path LIKE {placeholder})
            """,
            (folder_abs, like_prefix, folder_abs, like_prefix)
        )
        queue_rows = cursor.fetchall() or []

        queue_ids_deleted = []
        candidate_file_paths = set()
        for row in queue_rows:
            queue_id = _row_get(row, 'id', 0)
            if queue_id is not None:
                queue_ids_deleted.append(queue_id)

            for field_name, field_index in (('file_path', 1), ('matched_file_path', 2)):
                path_value = _row_get(row, field_name, field_index)
                if not path_value:
                    continue
                path_abs = os.path.abspath(str(path_value))
                if _is_within_downloads(path_abs):
                    candidate_file_paths.add(path_abs)

        deleted_queue_items = 0
        if remove_queue_items and queue_ids_deleted:
            cursor.execute("DELETE FROM download_queue WHERE id = ANY(%s)", (queue_ids_deleted,))
            deleted_queue_items = cursor.rowcount
            # Clean up event logs for deleted queue items
            clear_queue_events_for_items(queue_ids_deleted)

        deleted_files = []
        deleted_dirs = []

        # Delete all files referenced by queue items first.
        for file_path in sorted(candidate_file_paths):
            if not os.path.isfile(file_path):
                continue
            try:
                os.remove(file_path)
                if not os.path.exists(file_path):
                    deleted_files.append(file_path)
            except Exception as delete_err:
                logging.warning(f"[QUEUE_FOLDER_DELETE] Failed to delete queued file '{file_path}': {delete_err}")

        # Then remove any leftover files under the target folder.
        if os.path.isdir(folder_abs):
            for root, _dirs, files in os.walk(folder_abs, topdown=False):
                for filename in files:
                    full_path = os.path.join(root, filename)
                    if not _is_within_downloads(full_path):
                        continue
                    try:
                        os.remove(full_path)
                        if not os.path.exists(full_path):
                            deleted_files.append(full_path)
                    except Exception as delete_err:
                        logging.warning(f"[QUEUE_FOLDER_DELETE] Failed to delete '{full_path}': {delete_err}")

        def _prune_empty_dirs(start_dir, stop_dir):
            current = os.path.abspath(start_dir)
            stop_abs = os.path.abspath(stop_dir)
            while current and _is_within_downloads(current):
                if not os.path.isdir(current):
                    break
                try:
                    if os.listdir(current):
                        break
                    os.rmdir(current)
                    deleted_dirs.append(current)
                except Exception:
                    break

                if current == stop_abs:
                    break
                parent = os.path.dirname(current)
                if parent == current:
                    break
                current = parent

        # Prune parent directories for deleted files, then ensure the selected folder is pruned.
        for deleted_file in deleted_files:
            _prune_empty_dirs(os.path.dirname(deleted_file), folder_abs)
        _prune_empty_dirs(folder_abs, folder_abs)

        conn.commit()

        conn.close()

        return jsonify({
            "success": True,
            "folder": folder_abs,
            "deleted_queue_items": deleted_queue_items,
            "deleted_files_count": len(deleted_files),
            "deleted_dirs_count": len(deleted_dirs),
            "deleted_files": deleted_files,
            "deleted_dirs": deleted_dirs,
        })

    except Exception as e:
        logging.error(f"Error deleting queue folder: {e}")
        return jsonify({"error": str(e)}), 400


@app.route("/api/queue/group/remove", methods=["POST"])
def api_queue_remove_group():
    """Remove queue rows for a group and optionally delete linked downloads files/folder."""
    conn = None
    try:
        from download_queue_manager import clear_queue_events_for_items

        data = request.get_json(silent=True) or {}
        queue_ids_raw = data.get('queue_ids') or []
        folder_path = (data.get('folder_path') or '').strip()
        remove_files = bool(data.get('remove_files', True))

        queue_ids = []
        if isinstance(queue_ids_raw, list):
            for value in queue_ids_raw:
                try:
                    qid = int(value)
                    if qid > 0:
                        queue_ids.append(qid)
                except Exception:
                    continue
        queue_ids = list(dict.fromkeys(queue_ids))

        if not queue_ids:
            return jsonify({"success": False, "error": "queue_ids is required"}), 400

        cfg = get_config()
        downloads_root = os.path.abspath(_resolve_downloads_monitor_dir(cfg))

        def _is_within_downloads(path_value):
            try:
                abs_path = os.path.abspath(path_value)
                return os.path.commonpath([abs_path, downloads_root]) == downloads_root
            except Exception:
                return False

        folder_abs = None
        if folder_path:
            candidate = folder_path
            if not os.path.isabs(candidate):
                candidate = os.path.join(downloads_root, candidate)
            candidate = os.path.abspath(candidate)
            if not _is_within_downloads(candidate):
                return jsonify({"success": False, "error": "Refusing to remove outside downloads root"}), 400
            folder_abs = candidate

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        ids_placeholders = ", ".join([placeholder] * len(queue_ids))
        cursor.execute(
            f"""
            SELECT id, file_path, matched_file_path
            FROM download_queue
            WHERE id IN ({ids_placeholders})
            """,
            tuple(queue_ids),
        )
        rows = cursor.fetchall() or []

        candidate_files = set()
        for row in rows:
            for field_name, field_index in (('file_path', 1), ('matched_file_path', 2)):
                value = _row_get(row, field_name, field_index)
                if not value:
                    continue
                full = os.path.abspath(str(value))
                if _is_within_downloads(full):
                    candidate_files.add(full)

        cursor.execute(
            f"DELETE FROM download_queue WHERE id IN ({ids_placeholders})",
            tuple(queue_ids),
        )
        deleted_queue_items = int(cursor.rowcount or 0)

        if queue_ids:
            clear_queue_events_for_items(queue_ids)

        conn.commit()
        conn.close()
        conn = None

        deleted_files = []
        deleted_dirs = []

        def _delete_file_if_exists(path_value):
            if not remove_files:
                return False
            if not path_value or not os.path.isfile(path_value):
                return False
            if not _is_within_downloads(path_value):
                return False
            try:
                os.remove(path_value)
                return not os.path.exists(path_value)
            except Exception as del_err:
                logging.warning(f"[QUEUE_GROUP_REMOVE] Failed to delete '{path_value}': {del_err}")
                return False

        for file_path in sorted(candidate_files):
            if _delete_file_if_exists(file_path):
                deleted_files.append(file_path)

        if remove_files and folder_abs and os.path.isdir(folder_abs):
            for root, _dirs, files in os.walk(folder_abs, topdown=False):
                for filename in files:
                    full = os.path.join(root, filename)
                    if _delete_file_if_exists(full):
                        deleted_files.append(full)

        def _prune_empty_dirs(start_dir, stop_dir):
            current = os.path.abspath(start_dir)
            stop_abs = os.path.abspath(stop_dir)
            while current and _is_within_downloads(current):
                if not os.path.isdir(current):
                    break
                try:
                    if os.listdir(current):
                        break
                    os.rmdir(current)
                    deleted_dirs.append(current)
                except Exception:
                    break
                if current == stop_abs:
                    break
                parent = os.path.dirname(current)
                if parent == current:
                    break
                current = parent

        for deleted_file in deleted_files:
            _prune_empty_dirs(os.path.dirname(deleted_file), folder_abs or downloads_root)
        if folder_abs:
            _prune_empty_dirs(folder_abs, folder_abs)

        return jsonify({
            "success": True,
            "deleted_queue_items": deleted_queue_items,
            "deleted_files_count": len(deleted_files),
            "deleted_dirs_count": len(deleted_dirs),
            "deleted_files": deleted_files,
            "deleted_dirs": deleted_dirs,
            "folder": folder_abs,
        })

    except Exception as e:
        logging.error(f"Error removing queue group: {e}")
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        return jsonify({"success": False, "error": str(e)}), 400


@app.route("/api/queue/clear", methods=["POST", "DELETE"])
def api_queue_clear():
    """Clear non-imported items from the download queue and their event logs."""
    try:
        from download_queue_manager import clear_queue_events_for_items
        data = request.get_json(silent=True) or {}
        filters = data.get('filters', {})  # Optional filters: status, artist, album

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        # First, get the IDs of items to be deleted so we can clean up their event logs
        select_query = f"SELECT id FROM download_queue WHERE status != {placeholder}"
        select_params = ['imported']

        if filters.get('status'):
            select_query = f"SELECT id FROM download_queue WHERE status = {placeholder}"
            select_params = [filters['status']]

        if filters.get('artist'):
            select_query += f" AND artist = {placeholder}"
            select_params.append(filters['artist'])

        if filters.get('album'):
            select_query += f" AND album = {placeholder}"
            select_params.append(filters['album'])

        cursor.execute(select_query, select_params)
        queue_ids_to_delete = [row[0] for row in cursor.fetchall()]

        # Now delete the items
        delete_query = f"DELETE FROM download_queue WHERE status != {placeholder}"
        delete_params = ['imported']

        if filters.get('status'):
            delete_query = f"DELETE FROM download_queue WHERE status = {placeholder}"
            delete_params = [filters['status']]

        if filters.get('artist'):
            delete_query += f" AND artist = {placeholder}"
            delete_params.append(filters['artist'])

        if filters.get('album'):
            delete_query += f" AND album = {placeholder}"
            delete_params.append(filters['album'])

        cursor.execute(delete_query, delete_params)
        deleted_count = cursor.rowcount
        
        # Clean up event logs for deleted items
        if queue_ids_to_delete:
            clear_queue_events_for_items(queue_ids_to_delete)
        
        conn.commit()
        conn.close()

        message = f"Cleared {deleted_count} item(s) from download queue"
        logging.info(f"[QUEUE] {message}")

        return jsonify({
            "success": True,
            "message": message,
            "deleted": deleted_count,
            "deleted_count": deleted_count,
        })

    except Exception as e:
        logging.error(f"Error clearing download queue: {e}")
        return jsonify({"error": str(e)}), 400


@app.route("/api/queue/purge-all", methods=["POST", "DELETE"])
def api_queue_purge_all():
    """Hard purge queue data and remove all files under the configured downloads folder."""
    conn = None
    try:
        import shutil

        cfg = get_config()
        downloads_dir = _resolve_downloads_monitor_dir(cfg)
        downloads_abs = os.path.abspath(downloads_dir or "")

        # Safety rails: never allow purging filesystem root.
        if not downloads_abs or os.path.splitdrive(downloads_abs)[1] in (os.sep, ""):
            return jsonify({
                "success": False,
                "error": f"Unsafe downloads path for purge: {downloads_abs or downloads_dir}"
            }), 400

        conn = get_db()
        cursor = conn.cursor()
        queue_count = 0
        folder_count = 0
        track_count = 0
        events_count = 0

        has_download_queue = _table_exists(cursor, 'download_queue')
        has_folder_albums = _table_exists(cursor, 'folder_album_matches')
        has_folder_tracks = _table_exists(cursor, 'folder_track_matches')
        has_queue_events = _table_exists(cursor, 'queue_events')

        if has_download_queue:
            cursor.execute("SELECT COUNT(*) FROM download_queue")
            queue_count = _row_get(cursor.fetchone(), 0, 0)
        if has_folder_albums:
            cursor.execute("SELECT COUNT(*) FROM folder_album_matches")
            folder_count = _row_get(cursor.fetchone(), 0, 0)
        if has_folder_tracks:
            cursor.execute("SELECT COUNT(*) FROM folder_track_matches")
            track_count = _row_get(cursor.fetchone(), 0, 0)
        if has_queue_events:
            cursor.execute("SELECT COUNT(*) FROM queue_events")
            events_count = _row_get(cursor.fetchone(), 0, 0)

        # Delete dependent rows first.
        if has_folder_tracks:
            cursor.execute("DELETE FROM folder_track_matches")
        if has_folder_albums:
            cursor.execute("DELETE FROM folder_album_matches")
        if has_queue_events:
            cursor.execute("DELETE FROM queue_events")
        if has_download_queue:
            cursor.execute("DELETE FROM download_queue")

        conn.commit()
        conn.close()
        conn = None

        deleted_files = 0
        deleted_dirs = 0
        fs_errors = []

        if os.path.isdir(downloads_abs):
            for child_name in os.listdir(downloads_abs):
                child_path = os.path.join(downloads_abs, child_name)
                try:
                    if os.path.isdir(child_path):
                        # Count files before deletion for reporting.
                        for _root, _dirs, files in os.walk(child_path):
                            deleted_files += len(files)
                        shutil.rmtree(child_path)
                        deleted_dirs += 1
                    else:
                        os.remove(child_path)
                        deleted_files += 1
                except Exception as fs_err:
                    fs_errors.append(f"{child_path}: {fs_err}")
        else:
            fs_errors.append(f"Downloads folder not found: {downloads_abs}")

        logging.warning(
            f"[QUEUE_PURGE] Purged queue + downloads folder. "
            f"queue_items={queue_count}, folder_matches={folder_count}, "
            f"track_matches={track_count}, queue_events={events_count}, "
            f"deleted_files={deleted_files}, deleted_dirs={deleted_dirs}, downloads_dir={downloads_abs}"
        )

        return jsonify({
            "success": True,
            "message": "Queue and downloads folder purged",
            "downloads_dir": downloads_abs,
            "queue_items_deleted": queue_count,
            "folder_matches_deleted": folder_count,
            "track_matches_deleted": track_count,
            "queue_events_deleted": events_count,
            "deleted_files": deleted_files,
            "deleted_dirs": deleted_dirs,
            "fs_errors": fs_errors[:25],
        })
    except Exception as e:
        logging.error(f"Error purging queue and downloads folder: {e}")
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/queue/retry-all-failed", methods=["POST"])
def api_queue_retry_all_failed():
    """Re-queue all items with status='failed' back to 'queued'."""
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        cursor.execute(
            f"""UPDATE download_queue
                SET status = {placeholder},
                    failure_reason = NULL,
                    retry_count = 0,
                    updated_at = CURRENT_TIMESTAMP
                WHERE status = {placeholder}""",
            ('queued', 'failed'),
        )
        retried = cursor.rowcount
        conn.commit()
        conn.close()

        logging.info(f"[QUEUE] Retried {retried} failed item(s)")
        return jsonify({"success": True, "retried": retried})

    except Exception as e:
        logging.error(f"Error retrying all failed: {e}")
        return jsonify({"error": str(e)}), 400


def _queue_sanitize_component(value):
    value = (value or '').strip()
    for ch in '<>:"|?*\\':
        value = value.replace(ch, '_')
    return value.strip('. ')


def _queue_normalize_album_artist(value):
    normalized = str(value or '').strip()
    key = normalized.lower().replace('-', ' ').replace('_', ' ').replace('.', ' ')
    key = ' '.join(key.split())
    if (
        key in ('various', 'various artist', 'various artists', 'va', 'v/a')
        or key.startswith('various artists ')
        or key.startswith('various artist ')
        or key.startswith('various ')
    ):
        return 'Various Artists'
    return normalized


def _queue_safe_track_number(track_number_value):
    if track_number_value is None:
        return '00'
    raw = str(track_number_value).strip()
    if not raw:
        return '00'
    raw = raw.split('/')[0].strip()
    if raw.isdigit():
        return f"{int(raw):02d}"
    digits = ''.join(ch for ch in raw if ch.isdigit())
    if digits:
        return f"{int(digits):02d}"
    return _queue_sanitize_component(raw) or '00'


def _read_queue_naming_format():
    """Read configurable queue organize path format from config, with sensible default."""
    try:
        cfg, _ = _read_yaml(CONFIG_PATH)
        downloads_cfg = cfg.get('downloads', {}) if isinstance(cfg, dict) else {}
        fmt = downloads_cfg.get('file_name_format') if isinstance(downloads_cfg, dict) else None
        if isinstance(fmt, str) and fmt.strip():
            return fmt.strip()
    except Exception as cfg_err:
        logging.debug(f"[ORGANIZE] Could not read naming config: {cfg_err}")
    return '{album_artist}/{year} - {album}/{track_number}. {artist} - {title}'


def _build_queue_target_path(music_root_value, album_artist_value, year_value, album_value, track_artist_value, title_value, track_number_value, source_file_path):
    file_name_format = _read_queue_naming_format()
    ext_local = os.path.splitext(source_file_path)[1]
    album_artist_part = _queue_sanitize_component(
        _queue_normalize_album_artist(album_artist_value)
    ) or 'Unknown Artist'
    album_part = _queue_sanitize_component(album_value) or 'Unknown Album'
    year_part = str(year_value).strip()[:4] if year_value else ''
    format_vars = {
        'track_number': _queue_safe_track_number(track_number_value),
        'artist': _queue_sanitize_component(track_artist_value) or 'Unknown Artist',
        'album_artist': album_artist_part,
        'title': _queue_sanitize_component(title_value) or 'Unknown Title',
        'album': album_part,
        'year': year_part or 'Unknown',
    }

    fallback_rel = f"{album_artist_part}/{format_vars['year']} - {album_part}/{format_vars['track_number']}. {format_vars['artist']} - {format_vars['title']}"

    try:
        relative_path = file_name_format.format(**format_vars)
    except Exception:
        relative_path = fallback_rel

    if not isinstance(relative_path, str) or not relative_path.strip():
        relative_path = fallback_rel

    # Keep target under MUSIC_ROOT; strip absolute prefixes and traversal segments.
    relative_path = relative_path.strip().replace('\\', '/').lstrip('/').lstrip('\\')
    relative_parts = []
    for part in relative_path.split('/'):
        clean_part = _queue_sanitize_component(part)
        if not clean_part or clean_part in ('.', '..'):
            continue
        relative_parts.append(clean_part)

    if not relative_parts:
        relative_parts = [
            album_artist_part,
            _queue_sanitize_component(f"{format_vars['year']} - {album_part}"),
            f"{format_vars['track_number']}. {format_vars['artist']} - {format_vars['title']}"
        ]

    relative_path_safe = os.path.join(*relative_parts)
    base_name_local, ext_from_format = os.path.splitext(relative_path_safe)
    if ext_from_format:
        target_path_local = os.path.join(music_root_value, relative_path_safe)
    else:
        target_path_local = os.path.join(music_root_value, f"{relative_path_safe}{ext_local}")

    target_dir_local = os.path.dirname(target_path_local)
    os.makedirs(target_dir_local, exist_ok=True)

    if os.path.exists(target_path_local):
        counter_local = 1
        file_stem, file_ext = os.path.splitext(target_path_local)
        while True:
            candidate = f"{file_stem}_{counter_local}{file_ext}"
            if not os.path.exists(candidate):
                target_path_local = candidate
                break
            counter_local += 1

    return target_path_local


@app.route("/api/queue/<int:queue_id>/organize", methods=["POST"])
def api_queue_organize(queue_id):
    """Copy a single file from /downloads to /music (individual copy).

    - Searches the downloads folder independently for the track when
      file_path is missing or the file no longer exists at that path.
    - Updates file metadata (ID3/FLAC tags) from the matched release
      before copying.
    - Marks the item as ``copied_individually`` so the album auto-move
      can recognise it as already done and skip it when the rest of the
      album completes.
    """
    try:
        import shutil
        from download_queue_manager import update_queue_item, is_match

        request_data = request.get_json(silent=True) or {}
        metadata_overrides = request_data.get('metadata') if isinstance(request_data.get('metadata'), dict) else {}

        def _first_non_empty(*values):
            for value in values:
                if value is None:
                    continue
                if isinstance(value, str):
                    if value.strip():
                        return value.strip()
                    continue
                return value
            return None

        def _resolve_musicbrainz_metadata(queue_id_value, release_id_value):
            """Resolve canonical metadata from MusicBrainz release tables when available."""
            resolved = {}
            try:
                rconn = get_db()
                rcursor = rconn.cursor()
                placeholder_local = "%s"

                # Prefer queue_id mapping because it gives exact track_number/title for this queue item.
                rcursor.execute(f"""
                    SELECT r.release_title, r.artist, r.release_year,
                           rt.track_number, rt.track_title, rt.track_artist
                    FROM musicbrainz_release_tracks rt
                    JOIN musicbrainz_releases r ON r.release_id = rt.release_id
                    WHERE rt.queue_id = {placeholder_local}
                    LIMIT 1
                """, (queue_id_value,))
                row = rcursor.fetchone()

                # Fallback to release-level metadata when track mapping wasn't persisted.
                if not row and release_id_value:
                    rcursor.execute(f"""
                        SELECT release_title, artist, release_year
                        FROM musicbrainz_releases
                        WHERE release_id = {placeholder_local}
                        LIMIT 1
                    """, (release_id_value,))
                    row = rcursor.fetchone()

                if row:
                    resolved = {
                        'album': _row_get(row, 'release_title', 0),
                        'album_artist': _row_get(row, 'artist', 1),
                        'year': _row_get(row, 'release_year', 2),
                        'track_number': _row_get(row, 'track_number', 3),
                        'title': _row_get(row, 'track_title', 4),
                        'artist': _row_get(row, 'track_artist', 5),
                    }

                rconn.close()
            except Exception as resolve_err:
                logging.debug(f"[ORGANIZE] Could not resolve MusicBrainz metadata for queue {queue_id_value}: {resolve_err}")
            return resolved

        conn = get_db()
        cursor = conn.cursor()

        placeholder = "%s"
        cursor.execute(f"""
            SELECT id, file_path, artist, album, title, release_id,
                   album_artist, year, track_number, found_filename
            FROM download_queue WHERE id = {placeholder}
        """, (queue_id,))

        item = cursor.fetchone()

        if not item:
            conn.close()
            return jsonify({"error": "Queue item not found"}), 404

        file_path = item['file_path']
        artist = item['artist'] or 'Unknown Artist'
        album = item['album'] or 'Unknown Album'
        album_artist = item['album_artist'] or artist
        year = item['year']
        track_number = item['track_number']
        title = item['title']
        release_id = item['release_id']
        found_filename = item['found_filename']

        # If no file_path or file no longer exists, search downloads folder
        # independently for this specific track.
        if not file_path or not os.path.exists(file_path):
            logging.info(f"[ORGANIZE] No valid file_path for queue {queue_id}, searching downloads folder independently...")
            downloads_dir = _resolve_downloads_monitor_dir(get_config())
            found_path = None

            if os.path.isdir(downloads_dir):
                item_dict = dict(item)
                for root, dirs, files in os.walk(downloads_dir):
                    for f in files:
                        if not f.endswith(('.mp3', '.flac', '.m4a', '.ogg', '.wav')):
                            continue
                        full_path = os.path.join(root, f)
                        rel_path = os.path.relpath(full_path, downloads_dir)
                        # Exact filename match first
                        if found_filename and f == found_filename:
                            found_path = full_path
                            break
                        # Fuzzy match on artist/title
                        if is_match(rel_path, item_dict):
                            found_path = full_path
                            break
                    if found_path:
                        break

            if not found_path:
                conn.close()
                logging.warning(f"[ORGANIZE] Could not find file for queue {queue_id}: {artist} - {title}")
                return jsonify({"error": f"Could not find file in downloads folder for: {artist} - {title}"}), 404

            logging.info(f"[ORGANIZE] Found file via independent search: {found_path}")
            file_path = found_path
            # Update the queue item so future calls have the correct path
            update_queue_item(
                queue_id,
                file_path=file_path,
                status='completed',
                found_filename=os.path.basename(file_path)
            )

        conn.close()

        logging.info(f"[ORGANIZE] Starting individual copy for queue {queue_id}: {file_path}")

        # Resolve best-available metadata before move.
        resolved_mb_metadata = _resolve_musicbrainz_metadata(queue_id, release_id)
        title = _first_non_empty(metadata_overrides.get('title'), resolved_mb_metadata.get('title'), title)
        artist = _first_non_empty(metadata_overrides.get('artist'), resolved_mb_metadata.get('artist'), artist)
        album = _first_non_empty(metadata_overrides.get('album'), resolved_mb_metadata.get('album'), album)
        album_artist = _first_non_empty(
            metadata_overrides.get('album_artist'),
            resolved_mb_metadata.get('album_artist'),
            album_artist,
            artist
        )
        year = _first_non_empty(metadata_overrides.get('year'), resolved_mb_metadata.get('year'), year)
        track_number = _first_non_empty(metadata_overrides.get('track_number'), resolved_mb_metadata.get('track_number'), track_number)
        disc_number = _first_non_empty(metadata_overrides.get('disc_number'), request_data.get('disc_number'))

        # Persist corrected metadata back to queue item so future operations stay consistent.
        try:
            update_queue_item(
                queue_id,
                title=title,
                artist=artist,
                album=album,
                album_artist=album_artist,
                year=str(year) if year is not None else None,
                track_number=str(track_number) if track_number is not None else None,
            )
        except Exception as queue_meta_err:
            logging.debug(f"[ORGANIZE] Could not persist resolved metadata to queue item {queue_id}: {queue_meta_err}")

        # Update file metadata from release info before copying.
        # Existing tags are stripped first to avoid stale source metadata.
        try:
            from post_download_processor import update_file_metadata
            metadata = {
                'title': title,
                'artist': artist,
                'album_artist': album_artist,
                'album': album,
                'year': year,
                'track_number': track_number,
                'disc_number': disc_number,
            }
            if any(v for v in [title, artist, album, year, track_number, album_artist] if v):
                success = update_file_metadata(file_path, metadata, clear_existing_tags=True)
                if success:
                    logging.info(f"[ORGANIZE] ✅ Metadata updated for: {file_path}")
                else:
                    logging.warning(f"[ORGANIZE] Metadata update skipped/failed (non-fatal): {file_path}")
        except Exception as meta_err:
            logging.warning(f"[ORGANIZE] Metadata update error (non-fatal): {meta_err}")

        # Get paths and create directory structure
        music_root = os.environ.get("MUSIC_ROOT", "/music")
        target_path = _build_queue_target_path(
            music_root,
            album_artist,
            year,
            album,
            artist,
            title,
            track_number,
            file_path,
        )

        # Copy file and retain source until explicit cleanup.
        logging.info(f"[ORGANIZE] Copying file from {file_path} to {target_path}")
        shutil.copy2(file_path, target_path)

        # Verify copy integrity while source remains in downloads.
        copied_ok = (
            os.path.exists(target_path)
            and os.path.getsize(target_path) > 0
            and os.path.exists(file_path)
            and os.path.getsize(file_path) == os.path.getsize(target_path)
        )

        if copied_ok:
            logging.info(f"[ORGANIZE] ✅ File copied successfully: {target_path}")
            # Mark as imported AND as individually copied so the album auto-move
            # knows this track is already done.
            update_queue_item(
                queue_id,
                status='imported',
                file_path=target_path,
                copied_individually=1,
                copied_individually_at=datetime.now().isoformat()
            )
            return jsonify({
                "success": True,
                "message": "File copied to library successfully (source retained for cleanup)",
                "target_path": target_path,
                "copied_individually": True
            })
        else:
            logging.error(f"[ORGANIZE] Copy verification failed: target_exists={os.path.exists(target_path)}, source_exists={os.path.exists(file_path)}")
            update_queue_item(queue_id, status='failed', failure_reason='File copy verification failed')
            return jsonify({"error": "File copy verification failed"}), 400

    except Exception as e:
        logging.error(f"[ORGANIZE] Error organizing file: {e}")
        log_debug(f"[ORGANIZE] Error organizing file: {e}")
        import traceback
        logging.error(traceback.format_exc())
        log_debug(traceback.format_exc())
        return jsonify({"error": str(e)}), 400

@app.route("/api/queue/organize-group", methods=["POST"])
def api_queue_organize_group():
    """Organize a group of downloads with metadata confirmation"""
    try:
        import shutil
        from download_queue_manager import update_queue_item
        
        data = request.get_json(silent=True) or {}
        group_id = data.get('group_id')
        metadata = data.get('metadata', {})
        
        if not group_id:
            return jsonify({"error": "group_id required"}), 400
        
        # Get all items in this group from completed queue
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        cursor.execute(f"""
            SELECT id, file_path, artist, album, title, track_number, disc_number, album_artist, year
            FROM download_queue
            WHERE import_group = {placeholder} AND status = 'completed'
        """, (group_id,))
        
        items = cursor.fetchall()
        conn.close()
        
        if not items:
            return jsonify({"error": "No completed items found for this group"}), 404
        
        # Update metadata for all tracks in the group
        album_artist = metadata.get('album_artist') or metadata.get('artist', '')
        year = metadata.get('year', '')
        album_name = metadata.get('album', '')
        artist_match_threshold = float(os.environ.get("QUEUE_ARTIST_MATCH_THRESHOLD", "0.78"))

        def _artist_similarity_score(expected_artist, candidate_artist):
            expected_norm = _normalize_artist_name(expected_artist)
            candidate_norm = _normalize_artist_name(candidate_artist)
            if not expected_norm or not candidate_norm:
                return 0.0
            if expected_norm == candidate_norm:
                return 1.0
            ratio = difflib.SequenceMatcher(None, expected_norm, candidate_norm).ratio()
            if expected_norm in candidate_norm or candidate_norm in expected_norm:
                ratio = max(ratio, 0.92)
            return ratio
        
        updated_count = 0
        errors = []
        
        logging.info(f"[ORGANIZE_GROUP] ========================================")
        logging.info(f"[ORGANIZE_GROUP] Group organization started - group_id={group_id}")
        logging.info(f"[ORGANIZE_GROUP] Album Artist: {album_artist}, Album: {album_name}, Year: {year}")
        logging.info(f"[ORGANIZE_GROUP] Total items to process: {len(items)}")
        logging.info(f"[ORGANIZE_GROUP] =========================================")
        
        for item in items:
            try:
                file_path = item['file_path']
                item_artist = item['artist']
                item_title = item['title']
                item_track_number = item['track_number']
                item_disc_number = item['disc_number']
                
                if not os.path.exists(file_path):
                    error_msg = f"File not found at {file_path}"
                    errors.append(f"{item['title']}: {error_msg}")
                    logging.error(f"[ORGANIZE_GROUP] Item {item['id']}: {error_msg}")
                    log_debug(f"[ORGANIZE_GROUP] Item {item['id']}: {error_msg}")
                    continue
                
                logging.debug(f"[ORGANIZE_GROUP] Processing item {item['id']}: {file_path} (title: {item['title']})")
                
                # Resolve metadata with fallbacks - define these before any try/except blocks
                resolved_album_artist = album_artist if album_artist else item['album_artist'] or item['artist']
                resolved_album_name = album_name if album_name else item['album']
                resolved_year = year if year else item['year']

                # Pull canonical release metadata for this queue item from MusicBrainz tables when available.
                try:
                    mb_conn = get_db()
                    mb_cursor = mb_conn.cursor()
                    mb_placeholder = "%s"

                    mb_cursor.execute(
                        f"""
                        SELECT r.release_title, r.artist, r.release_year,
                               rt.track_number, rt.track_title, rt.track_artist
                        FROM musicbrainz_release_tracks rt
                        JOIN musicbrainz_releases r ON r.release_id = rt.release_id
                        WHERE rt.queue_id = {mb_placeholder}
                        LIMIT 1
                        """,
                        (item['id'],),
                    )
                    mb_row = mb_cursor.fetchone()
                    mb_conn.close()

                    if mb_row:
                        resolved_album_name = _row_get(mb_row, 'release_title', 0) or resolved_album_name
                        resolved_album_artist = _row_get(mb_row, 'artist', 1) or resolved_album_artist
                        resolved_year = _row_get(mb_row, 'release_year', 2) or resolved_year
                        item_track_number = _row_get(mb_row, 'track_number', 3)
                        item_track_title = _row_get(mb_row, 'track_title', 4)
                        item_track_artist = _row_get(mb_row, 'track_artist', 5)

                        if item_track_number:
                            item_track_number = item_track_number
                        if item_track_title:
                            item_title = item_track_title
                        if item_track_artist:
                            item_artist = item_track_artist
                except Exception as mb_item_err:
                    logging.debug(f"[ORGANIZE_GROUP] Item {item['id']}: MusicBrainz metadata enrichment skipped: {mb_item_err}")

                # Verify downloaded metadata has a close artist match before any update or file copy.
                try:
                    embedded_metadata = read_mp3_metadata(file_path) or {}
                except Exception as metadata_read_error:
                    embedded_metadata = {}
                    logging.warning(f"[ORGANIZE_GROUP] Item {item['id']}: Could not read embedded metadata for artist check: {metadata_read_error}")

                expected_artist = item_artist or resolved_album_artist
                artist_candidates = [
                    embedded_metadata.get('artist'),
                    embedded_metadata.get('album_artist'),
                ]

                scored_candidates = []
                for candidate in artist_candidates:
                    if candidate and str(candidate).strip():
                        scored_candidates.append((str(candidate), _artist_similarity_score(expected_artist, candidate)))

                if scored_candidates:
                    best_candidate, best_score = max(scored_candidates, key=lambda x: x[1])
                    if best_score < artist_match_threshold:
                        error_msg = (
                            f"Artist metadata mismatch (expected='{expected_artist}', "
                            f"found='{best_candidate}', score={best_score:.2f}, threshold={artist_match_threshold:.2f})"
                        )
                        errors.append(f"{item_title}: {error_msg}")
                        update_queue_item(item['id'], status='failed', failure_reason=error_msg)
                        logging.warning(f"[ORGANIZE_GROUP] Item {item['id']}: {error_msg}")
                        log_debug(f"[ORGANIZE_GROUP] Item {item['id']}: {error_msg}")
                        continue

                    logging.debug(
                        f"[ORGANIZE_GROUP] Item {item['id']}: Artist metadata match accepted "
                        f"(expected='{expected_artist}', found='{best_candidate}', score={best_score:.2f})"
                    )
                else:
                    error_msg = "Artist metadata check failed (no embedded artist/album_artist tags found)"
                    errors.append(f"{item_title}: {error_msg}")
                    update_queue_item(item['id'], status='failed', failure_reason=error_msg)
                    logging.warning(f"[ORGANIZE_GROUP] Item {item['id']}: {error_msg}")
                    log_debug(f"[ORGANIZE_GROUP] Item {item['id']}: {error_msg}")
                    continue
                
                # Update track metadata in database
                try:
                    update_queue_item(
                        item['id'],
                        artist=item_artist,
                        title=item_title,
                        album=resolved_album_name,
                        album_artist=resolved_album_artist,
                        year=resolved_year,
                        track_number=item_track_number,
                    )
                    logging.debug(f"[ORGANIZE_GROUP] Item {item['id']}: Updated metadata - artist={item_artist}, album={resolved_album_name}, album_artist={resolved_album_artist}, year={resolved_year}")
                except Exception as meta_error:
                    logging.warning(f"[ORGANIZE_GROUP] Item {item['id']}: Failed to update metadata: {meta_error}")
                    log_debug(f"[ORGANIZE_GROUP] Item {item['id']}: Failed to update metadata: {meta_error}")

                # Update embedded file tags before moving so tracks attach to the target album correctly.
                # Existing tags are stripped first to avoid carrying source metadata.
                try:
                    from post_download_processor import update_file_metadata
                    file_metadata = {
                        'title': item_title,
                        'artist': item_artist,
                        'album_artist': resolved_album_artist,
                        'album': resolved_album_name,
                        'year': resolved_year,
                        'track_number': item_track_number,
                        'disc_number': item_disc_number,
                    }
                    tag_success = update_file_metadata(file_path, file_metadata, clear_existing_tags=True)
                    if tag_success:
                        logging.info(f"[ORGANIZE_GROUP] Item {item['id']}: ✅ Metadata tags updated")
                    else:
                        logging.warning(f"[ORGANIZE_GROUP] Item {item['id']}: Metadata tag update skipped/failed (non-fatal)")
                except Exception as tag_error:
                    logging.warning(f"[ORGANIZE_GROUP] Item {item['id']}: Metadata tag update error (non-fatal): {tag_error}")
                
                # Move file to music directory
                try:
                    music_root = os.environ.get("MUSIC_ROOT", "/music")
                    target_path = _build_queue_target_path(
                        music_root,
                        resolved_album_artist,
                        resolved_year,
                        resolved_album_name,
                        item_artist,
                        item_title,
                        item_track_number,
                        file_path,
                    )
                    
                    logging.debug(f"[ORGANIZE_GROUP] Item {item['id']}: Copy - source={file_path}")
                    logging.debug(f"[ORGANIZE_GROUP] Item {item['id']}: Copy - target={target_path}")
                    
                    logging.info(f"[ORGANIZE_GROUP] Item {item['id']}: Copying file")
                    os.makedirs(os.path.dirname(target_path), exist_ok=True)

                    if not os.path.exists(target_path):
                        shutil.copy2(file_path, target_path)
                    else:
                        logging.info(f"[ORGANIZE_GROUP] Item {item['id']}: Target already exists, skipping copy")
                    
                    # Verify copy integrity before any source deletion
                    copied_ok = (
                        os.path.exists(target_path)
                        and os.path.getsize(target_path) > 0
                        and os.path.getsize(file_path) == os.path.getsize(target_path)
                    )

                    if copied_ok:
                        logging.info(f"[ORGANIZE_GROUP] Item {item['id']}: ✅ Copy successful")

                        # Mark queue item imported and point to the new location
                        update_queue_item(item['id'], status='imported', file_path=target_path)

                        logging.info(
                            f"[ORGANIZE_GROUP] Item {item['id']}: Source retained in /downloads; "
                            f"use cleanup action to remove copied files"
                        )

                        updated_count += 1
                    else:
                        error_msg = f"Copy verification failed"
                        errors.append(f"{item_title}: {error_msg}")
                        update_queue_item(item['id'], status='failed', failure_reason=error_msg)
                        logging.error(f"[ORGANIZE_GROUP] Item {item['id']}: {error_msg}")
                        log_debug(f"[ORGANIZE_GROUP] Item {item['id']}: {error_msg}")
                        
                except Exception as move_error:
                    error_msg = str(move_error)
                    errors.append(f"{item_title}: {error_msg}")
                    update_queue_item(item['id'], status='failed', failure_reason=error_msg)
                    logging.error(f"[ORGANIZE_GROUP] Item {item['id']}: Copy failed - {type(move_error).__name__}: {move_error}")
                    log_debug(f"[ORGANIZE_GROUP] Item {item['id']}: Copy failed - {type(move_error).__name__}: {move_error}")
                    
            except Exception as e:
                errors.append(f"{item['title'] or 'Unknown'}: {str(e)}")
                logging.error(f"[ORGANIZE_GROUP] Error processing item {item['id']}: {e}")
                log_debug(f"[ORGANIZE_GROUP] Error processing item {item['id']}: {e}")
                continue
        
        logging.info(f"[ORGANIZE_GROUP] ========================================")
        logging.info(f"[ORGANIZE_GROUP] Organization complete!")
        logging.info(f"[ORGANIZE_GROUP] Results: {updated_count}/{len(items)} successful")
        if errors:
            logging.info(f"[ORGANIZE_GROUP] Failed items ({len(errors)}):")
            for error in errors:
                logging.info(f"[ORGANIZE_GROUP]   - {error}")
        logging.info(f"[ORGANIZE_GROUP] =========================================")
        
        return jsonify({
            "success": True,
            "organized": updated_count,
            "total": len(items),
            "errors": errors,
            "message": f"Organized {updated_count}/{len(items)} files"
        })

        
    except Exception as e:
        logging.error(f"[ORGANIZE_GROUP] Unhandled error during organization: {type(e).__name__}: {e}")
        log_debug(f"[ORGANIZE_GROUP] Unhandled error during organization: {type(e).__name__}: {e}")
        import traceback
        logging.error(f"[ORGANIZE_GROUP] Traceback: {traceback.format_exc()}")
        log_debug(f"[ORGANIZE_GROUP] Traceback: {traceback.format_exc()}")
        return jsonify({"error": str(e)}), 400


@app.route("/api/queue-processor/status", methods=["GET"])
def api_queue_processor_status():
    """Get queue processor status"""
    try:
        # Try to find the queue processor process
        processor_running = False
        processor_pid = None
        processor_memory = 0
        processor_uptime = None

        proc = _find_queue_processor_process()
        if proc:
            try:
                processor_running = True
                processor_pid = proc.pid
                processor_memory = proc.memory_info().rss / 1024 / 1024  # Convert to MB
                processor_uptime = datetime.now() - datetime.fromtimestamp(proc.create_time())
            except Exception:
                processor_running = True
        
        # Check queue status via a single aggregate query (cheap, no schema checks).
        conn = get_db()
        cursor = conn.cursor()
        cursor.execute(
            """
            SELECT status, COUNT(*) AS count
            FROM download_queue
            GROUP BY status
            """
        )
        rows = cursor.fetchall() or []
        conn.close()

        counts = {
            'queued': 0,
            'searching': 0,
            'downloading': 0,
            'queried': 0,
            'discovered': 0,
            'pending_match': 0,
            'matched': 0,
            'possible_duplicate': 0,
            'duplicate': 0,
            'completed': 0,
            'in_collection': 0,
            'failed': 0,
        }
        for row in rows:
            status_value = _row_get(row, 'status', 0)
            count_value = int(_row_get(row, 'count', 1, 0) or 0)
            if status_value in counts:
                counts[status_value] = count_value

        active_total = (
            counts['queued']
            + counts['searching']
            + counts['downloading']
            + counts['queried']
            + counts['discovered']
            + counts['pending_match']
        )
        completed_total = (
            counts['matched']
            + counts['possible_duplicate']
            + counts['duplicate']
            + counts['completed']
            + counts['in_collection']
        )
        total_count = active_total + completed_total + counts['failed']
        
        return jsonify({
            "success": True,
            "processor_running": processor_running,
            "processor_pid": processor_pid,
            "processor_memory_mb": round(processor_memory, 2) if processor_memory else 0,
            "processor_uptime": str(processor_uptime) if processor_uptime else None,
            "status_counts": counts,
            "queue_stats": {
                "queued": counts['queued'] + counts['searching'] + counts['queried'] + counts['discovered'] + counts['pending_match'],
                "downloading": counts['downloading'],
                "failed": counts['failed'],
                "completed": completed_total,
                "active": active_total,
                "total": total_count
            }
        })
        
    except Exception as e:
        logging.error(f"Error getting queue processor status: {e}")
        return jsonify({
            "success": False,
            "processor_running": False,
            "error": str(e)
        }), 500


@app.route("/api/queue-processor/restart", methods=["POST"])
def api_queue_processor_restart():
    """Restart queue processor"""
    try:
        had_existing = _find_queue_processor_process() is not None
        started = _start_queue_processor_if_needed(force_restart=True)

        # Verify process became visible after restart request.
        time.sleep(1)
        running_now = _find_queue_processor_process() is not None

        if started and running_now:
            logging.info("Queue processor restarted successfully")
            return jsonify({
                "success": True,
                "message": "Queue processor restarted successfully",
                "killed_previous": had_existing,
            })

        return jsonify({
            "success": False,
            "message": "Failed to start queue processor",
            "killed_previous": had_existing,
        }), 500
            
    except Exception as e:
        logging.error(f"Error restarting queue processor: {e}")
        return jsonify({
            "success": False,
            "error": str(e)
        }), 500


# ============================================================================
# Download Monitor Enhancements API
# ============================================================================

def _delete_queue_entry(queue_id: int) -> bool:
    """Delete a single download queue entry by ID. Returns True on success."""
    try:
        conn_del = get_db()
        cursor_del = conn_del.cursor()
        ph = "%s"
        cursor_del.execute(f"DELETE FROM download_queue WHERE id = {ph}", (queue_id,))
        conn_del.commit()
        conn_del.close()
        logging.info(f"[QUEUE_DELETE] Auto-deleted queue entry {queue_id} after successful move to music")
        return True
    except Exception as _del_err:
        logging.warning(f"[QUEUE_DELETE] Could not auto-delete queue entry {queue_id}: {_del_err}")
        return False


_move_to_music_tasks = {}
_move_to_music_tasks_lock = threading.Lock()


def _move_to_music_task_set(task_id, **updates):
    with _move_to_music_tasks_lock:
        task = _move_to_music_tasks.get(task_id, {"task_id": task_id})
        task.update(updates)
        task.setdefault("updated_at", datetime.now().isoformat())
        task["updated_at"] = datetime.now().isoformat()
        _move_to_music_tasks[task_id] = task


def _move_to_music_task_get(task_id):
    with _move_to_music_tasks_lock:
        return dict(_move_to_music_tasks.get(task_id) or {})


def _perform_queue_move_to_music(queue_id):
    """Core move-to-music logic shared by sync and async API paths."""
    conn = get_db()
    placeholder = "%s"
    cursor = conn.cursor()
    cursor.execute(
        f"SELECT status, file_path, matched_file_path, music_file_path, found_filename FROM download_queue WHERE id = {placeholder}",
        (queue_id,),
    )
    row = cursor.fetchone()
    conn.close()

    if not row:
        return {"success": False, "error": "Queue item not found"}, 404

    if isinstance(row, (list, tuple)):
        item_status = row[0]
        file_path_value = row[1] if len(row) > 1 else None
        matched_file_path_value = row[2] if len(row) > 2 else None
        music_file_path_value = row[3] if len(row) > 3 else None
        found_filename_value = row[4] if len(row) > 4 else None
    else:
        item_status = row.get('status')
        file_path_value = row.get('file_path')
        matched_file_path_value = row.get('matched_file_path')
        music_file_path_value = row.get('music_file_path')
        found_filename_value = row.get('found_filename')

    # Idempotency: already moved — return success immediately.
    if item_status == 'imported':
        return {
            "success": True,
            "message": "Track already imported to music directory",
            "already_imported": True,
        }, 200

    # Background processor has claimed this item — block the button.
    if item_status == 'moving':
        return {
            "success": False,
            "error": "Move already in progress by the background processor. Please wait a moment and refresh.",
            "in_progress": True,
        }, 409

    def _normalize_runtime_path(path_value):
        if not path_value:
            return ""
        return os.path.normpath(str(path_value)).replace("\\", "/").rstrip("/")

    def _is_under_root(path_value, root_value):
        normalized_path = _normalize_runtime_path(path_value)
        normalized_root = _normalize_runtime_path(root_value)
        if not normalized_path or not normalized_root:
            return False
        lowered_path = normalized_path.lower()
        lowered_root = normalized_root.lower()
        return lowered_path == lowered_root or lowered_path.startswith(lowered_root + "/")

    music_root = os.environ.get("MUSIC_ROOT", "/music")
    try:
        from download_queue_manager import get_downloads_dir
        downloads_root = get_downloads_dir()
    except Exception:
        downloads_root = os.environ.get("DOWNLOADS_DIR", "/downloads")

    candidate_paths = [file_path_value, matched_file_path_value, music_file_path_value, found_filename_value]
    file_in_music = any(_is_under_root(path_value, music_root) for path_value in candidate_paths if path_value)
    file_in_downloads = any(
        _is_under_root(path_value, downloads_root) or _is_under_root(path_value, "/downloads")
        for path_value in candidate_paths if path_value
    )

    if item_status == 'matched':
        from download_queue_manager import _try_claim_for_move, _release_move_claim
        if not _try_claim_for_move(queue_id, 'matched'):
            return {
                "success": False,
                "error": "Move already in progress by another process. Please wait a moment and refresh.",
                "in_progress": True,
            }, 409
        try:
            from download_monitor_enhancements import move_to_music_collection
            result = move_to_music_collection(queue_id)
            if 'error' in result:
                _release_move_claim(queue_id, restore_status='matched')
                return {"success": False, "error": result['error']}, 400
        except Exception:
            _release_move_claim(queue_id, restore_status='matched')
            raise

        _delete_queue_entry(queue_id)
        return {
            "success": True,
            "path": result.get('path'),
            "message": f"File moved to music collection: {result.get('path')}",
            "deleted": True,
        }, 200

    if item_status in ('completed', 'pending_match', 'in_collection', 'queued', 'discovered'):
        from download_queue_manager import _try_claim_for_move, _release_move_claim, move_single_track_to_music_dir, update_queue_item
        from download_file_verification import verify_file_in_music, mark_queue_item_moved

        if item_status == 'in_collection' and file_in_music:
            return {"success": False, "error": "Queue item already points to a file under /music"}, 400

        if item_status == 'in_collection' and not file_in_downloads:
            return {
                "success": False,
                "error": "Queue item marked in_collection can only be moved when its source file is still under /downloads",
            }, 400

        if item_status in ('queued', 'discovered') and not file_in_downloads:
            return {
                "success": False,
                "error": "Queue item can only be manually moved when its file is under the downloads directory",
            }, 400

        conn2 = get_db()
        placeholder_conn2 = "%s"
        cursor2 = conn2.cursor()
        cursor2.execute(f"SELECT * FROM download_queue WHERE id = {placeholder_conn2}", (queue_id,))
        queue_item = cursor2.fetchone()
        if queue_item and not isinstance(queue_item, dict):
            column_names = [col[0] for col in cursor2.description]
            queue_item = dict(zip(column_names, queue_item))
        conn2.close()

        if not queue_item:
            return {"success": False, "error": "Queue item not found"}, 404

        source_path = (
            queue_item.get('file_path')
            or queue_item.get('matched_file_path')
            or queue_item.get('music_file_path')
            or queue_item.get('found_filename')
        )
        if source_path:
            queue_item['file_path'] = source_path

        if not queue_item.get('file_path'):
            return {
                "success": False,
                "error": f"Queue item {queue_id} has no file path detected. Cannot move to music directory until a file is found.",
            }, 400

        if not _try_claim_for_move(queue_id, item_status):
            return {
                "success": False,
                "error": "Move already in progress by another process. Please wait a moment and refresh.",
                "in_progress": True,
            }, 409

        try:
            move_result = move_single_track_to_music_dir(dict(queue_item))
        except Exception:
            _release_move_claim(queue_id, restore_status=item_status)
            raise

        if not move_result.get('success'):
            _release_move_claim(queue_id, restore_status=item_status)
            return {"success": False, "error": move_result.get('error', 'Move failed')}, 500

        target_path = move_result['target_path']
        verify_result = verify_file_in_music(queue_id, target_path)
        if verify_result.get('success'):
            mark_queue_item_moved(queue_id, target_path)
            update_queue_item(
                queue_id,
                status='imported',
                file_path=target_path,
                copied_individually=1,
                copied_individually_at=datetime.now().isoformat(),
            )
            logging.info(f"[MANUAL_MOVE] Queue {queue_id}: verified and imported to {target_path}")
        else:
            update_queue_item(queue_id, status='completed', file_path=target_path)
            return {
                "success": False,
                "error": f"File moved but verification failed: {verify_result.get('error')}",
            }, 500

        _delete_queue_entry(queue_id)
        return {
            "success": True,
            "path": target_path,
            "message": f"File moved to music collection: {target_path}",
            "deleted": True,
        }, 200

    return {
        "success": False,
        "error": f"Track must be matched, completed, pending_match, in_collection, queued (with file+MBID), or discovered (with file+MBID) (current status: {item_status})",
    }, 400


@app.route("/api/queue/move-to-music/status/<task_id>", methods=["GET"])
def api_queue_move_to_music_status(task_id):
    """Return status for a background move-to-music request."""
    task = _move_to_music_task_get(task_id)
    if not task:
        queue_id = request.args.get("queue_id", type=int)
        if queue_id is not None:
            try:
                conn = get_db()
                cursor = conn.cursor()
                cursor.execute("SELECT status, file_path, matched_file_path, music_file_path FROM download_queue WHERE id = %s", (queue_id,))
                row = cursor.fetchone()
                conn.close()

                if not row:
                    return jsonify({
                        "success": True,
                        "task_id": task_id,
                        "queue_id": queue_id,
                        "status": "completed",
                        "status_code": 200,
                        "result": {
                            "success": True,
                            "message": "Move completed (queue entry no longer exists)."
                        },
                        "recovered": True,
                    })

                if isinstance(row, (list, tuple)):
                    item_status = row[0]
                    file_path_value = row[1] if len(row) > 1 else None
                    matched_file_path_value = row[2] if len(row) > 2 else None
                    music_file_path_value = row[3] if len(row) > 3 else None
                else:
                    item_status = row.get("status")
                    file_path_value = row.get("file_path")
                    matched_file_path_value = row.get("matched_file_path")
                    music_file_path_value = row.get("music_file_path")

                candidate_paths = [file_path_value, matched_file_path_value, music_file_path_value]
                has_music_path = any(str(path or "").replace("\\", "/").startswith("/music/") for path in candidate_paths)

                if item_status in {"failed", "error"}:
                    return jsonify({
                        "success": False,
                        "task_id": task_id,
                        "queue_id": queue_id,
                        "status": "failed",
                        "status_code": 500,
                        "result": {
                            "success": False,
                            "error": "Move task failed"
                        },
                        "recovered": True,
                    })

                if item_status in {"imported", "in_collection"} or has_music_path:
                    return jsonify({
                        "success": True,
                        "task_id": task_id,
                        "queue_id": queue_id,
                        "status": "completed",
                        "status_code": 200,
                        "result": {
                            "success": True,
                            "message": "Move completed"
                        },
                        "recovered": True,
                    })

                return jsonify({
                    "success": None,
                    "task_id": task_id,
                    "queue_id": queue_id,
                    "status": "running",
                    "message": "Move still running",
                    "recovered": True,
                })
            except Exception as recovery_err:
                logging.warning(f"[MOVE_TASK] Failed to recover missing task state for {task_id}: {recovery_err}")

        return jsonify({
            "success": None,
            "task_id": task_id,
            "status": "running",
            "message": "Task state unavailable; still processing",
            "recovered": True,
        })
    return jsonify(task)


@app.route("/api/queue/move-to-music/<int:queue_id>", methods=["POST"])
def api_queue_move_to_music(queue_id):
    """
    Move a matched or completed queue item to /music directory with proper tagging.
    Supports background mode to avoid request timeouts on large file operations.
    """
    try:
        async_requested = str(request.args.get("async", "0")).strip().lower() in {"1", "true", "yes", "on"}

        if async_requested:
            task_id = str(uuid.uuid4())
            _move_to_music_task_set(
                task_id,
                success=None,
                status="running",
                queue_id=queue_id,
                message="Move started",
                started_at=datetime.now().isoformat(),
            )

            def _worker():
                try:
                    with app.app_context():
                        payload, status_code = _perform_queue_move_to_music(queue_id)
                    _move_to_music_task_set(
                        task_id,
                        success=bool(payload.get("success")),
                        status="completed" if payload.get("success") else "failed",
                        status_code=status_code,
                        result=payload,
                        completed_at=datetime.now().isoformat(),
                    )
                except Exception as worker_err:
                    logging.error(f"Error in async move-to-music worker for queue {queue_id}: {worker_err}")
                    import traceback
                    logging.error(traceback.format_exc())
                    _move_to_music_task_set(
                        task_id,
                        success=False,
                        status="failed",
                        status_code=500,
                        result={"success": False, "error": str(worker_err)},
                        completed_at=datetime.now().isoformat(),
                    )

            threading.Thread(
                target=_worker,
                daemon=True,
                name=f"queue-move-to-music-{queue_id}-{task_id[:8]}",
            ).start()

            return jsonify({
                "success": True,
                "accepted": True,
                "queue_id": queue_id,
                "task_id": task_id,
                "status": "running",
                "message": "Move started in background",
            }), 202

        payload, status_code = _perform_queue_move_to_music(queue_id)
        return jsonify(payload), status_code

    except Exception as e:
        logging.error(f"Error moving queue item to music: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/queue/cleanup", methods=["POST"])
def api_queue_cleanup():
    """
    Trigger manual cleanup of download queue:
    - Remove expired duplicates (>24 hours old)
    - Remove completed albums (all tracks completed/in_collection)
    """
    try:
        from download_monitor_enhancements import cleanup_download_queue
        
        stats = cleanup_download_queue()
        
        if 'error' in stats:
            return jsonify({"success": False, "error": stats['error']}), 500
        
        return jsonify({
            "success": True,
            "message": "Cleanup completed",
            "stats": stats
        })
        
    except Exception as e:
        logging.error(f"Error cleaning up queue: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/queue/matched-releases", methods=["GET"])
def api_queue_matched_releases():
    """
    Return all unique MusicBrainz-backed releases currently in the download queue.
    Used to populate the 'current queue' list in the Change Queue Item Match modal.
    """
    conn = None
    try:
        conn = get_db()
        cursor = conn.cursor()
        artist_filter = (request.args.get('artist') or '').strip()
        album_filter = (request.args.get('album') or '').strip()
        try:
            requested_limit = int(request.args.get('limit', 80))
        except Exception:
            requested_limit = 80
        limit = max(10, min(requested_limit, 250))

        release_uuid_expr = "COALESCE(NULLIF(release_mbid, ''), NULLIF(release_id, ''))"
        release_uuid_length_expr = f"char_length({release_uuid_expr})"
        placeholder = "%s"

        active_statuses = (
            'queued', 'searching', 'downloading',
            'matched', 'completed',
            'unmatched', 'queried',
            'discovered', 'pending_match',
            'possible_duplicate', 'duplicate'
        )
        status_placeholders = ", ".join([placeholder] * len(active_statuses))

        cursor.execute(f"""
            SELECT
                {release_uuid_expr} AS mbid,
                MAX(COALESCE(NULLIF(album_artist, ''), artist)) AS release_artist,
                MAX(COALESCE(NULLIF(album, ''), '')) AS release_album,
                MAX(COALESCE(NULLIF(CAST(release_year AS TEXT), ''), NULLIF(CAST(year AS TEXT), ''))) AS resolved_year,
                COUNT(*) AS track_count,
                MAX(
                    CASE
                        WHEN {placeholder} <> ''
                         AND LOWER(COALESCE(NULLIF(album_artist, ''), artist)) = LOWER({placeholder})
                        THEN 1 ELSE 0
                    END
                ) AS artist_match,
                MAX(
                    CASE
                        WHEN {placeholder} <> ''
                         AND LOWER(COALESCE(NULLIF(album, ''), '')) = LOWER({placeholder})
                        THEN 1 ELSE 0
                    END
                ) AS album_match
            FROM download_queue
            WHERE {release_uuid_expr} IS NOT NULL
              AND (
                    release_source = 'musicbrainz'
                    OR (
                        (release_source IS NULL OR release_source = '')
                        AND {release_uuid_length_expr} = 36
                        AND {release_uuid_expr} LIKE '________-____-____-____-____________'
                    )
                  )
              AND status IN ({status_placeholders})
            GROUP BY {release_uuid_expr}
            ORDER BY artist_match DESC,
                     album_match DESC,
                     track_count DESC,
                     LOWER(MAX(COALESCE(NULLIF(album_artist, ''), artist))),
                     LOWER(MAX(COALESCE(NULLIF(album, ''), '')))
            LIMIT {placeholder}
        """, (artist_filter, artist_filter, album_filter, album_filter, *active_statuses, limit))
        rows = cursor.fetchall()
        conn.close()
        conn = None

        releases = []
        for row in rows:
            if isinstance(row, dict):
                releases.append({
                    'artist': row.get('release_artist') or '',
                    'album': row.get('release_album') or '',
                    'mbid': row.get('mbid') or '',
                    'year': row.get('resolved_year') or '',
                    'track_count': row.get('track_count') or 0,
                })
            else:
                releases.append({
                    'mbid': row[0] or '',
                    'artist': row[1] or '',
                    'album': row[2] or '',
                    'year': row[3] or '',
                    'track_count': row[4] or 0,
                })

        return jsonify({"success": True, "releases": releases})

    except Exception as e:
        logging.error(f"Error fetching matched releases from queue: {e}")
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/queue/match-targets", methods=["GET"])
def api_queue_match_targets():
    """Return queue items that can be selected as the target song for manual rematch."""
    conn = None
    try:
        conn = get_db()
        cursor = conn.cursor()

        artist_filter = (request.args.get('artist') or '').strip()
        album_filter = (request.args.get('album') or '').strip()
        selected_queue_id_raw = (request.args.get('selected_queue_id') or '').strip()

        try:
            selected_queue_id = int(selected_queue_id_raw) if selected_queue_id_raw else None
        except Exception:
            selected_queue_id = None

        if not artist_filter or not album_filter:
            return jsonify({"success": False, "error": "artist and album are required"}), 400

        active_statuses = (
            'queued', 'searching', 'downloading',
            'matched', 'completed',
            'unmatched', 'queried',
            'discovered', 'pending_match',
            'possible_duplicate', 'duplicate'
        )
        status_placeholders = ", ".join(["%s"] * len(active_statuses))

        cursor.execute(
            f"""
            SELECT
                id,
                artist,
                title,
                album,
                status,
                track_number,
                release_mbid,
                found_filename,
                created_at
            FROM download_queue
            WHERE LOWER(COALESCE(NULLIF(album_artist, ''), artist)) = LOWER(%s)
              AND LOWER(COALESCE(NULLIF(album, ''), '')) = LOWER(%s)
              AND status IN ({status_placeholders})
            ORDER BY
                CASE
                    WHEN %s IS NOT NULL AND id = %s THEN 0
                    ELSE 1
                END,
                CASE
                    WHEN NULLIF(TRIM(COALESCE(track_number, '')), '') ~ '^\\d+$'
                        THEN TRIM(track_number)::integer
                    ELSE 9999
                END,
                COALESCE(NULLIF(TRIM(track_number), ''), '9999'),
                id
            LIMIT 250
            """,
            (artist_filter, album_filter, *active_statuses, selected_queue_id, selected_queue_id),
        )

        rows = cursor.fetchall()
        conn.close()
        conn = None

        targets = []
        for row in rows:
            if isinstance(row, dict):
                targets.append({
                    "id": row.get('id'),
                    "artist": row.get('artist') or '',
                    "title": row.get('title') or '',
                    "album": row.get('album') or '',
                    "status": row.get('status') or '',
                    "track_number": row.get('track_number'),
                    "release_mbid": row.get('release_mbid') or '',
                    "found_filename": row.get('found_filename') or '',
                    "created_at": row.get('created_at'),
                })
            else:
                targets.append({
                    "id": row[0],
                    "artist": row[1] or '',
                    "title": row[2] or '',
                    "album": row[3] or '',
                    "status": row[4] or '',
                    "track_number": row[5],
                    "release_mbid": row[6] or '',
                    "found_filename": row[7] or '',
                    "created_at": row[8],
                })

        return jsonify({
            "success": True,
            "targets": targets,
            "selected_queue_id": selected_queue_id,
        })

    except Exception as e:
        logging.error(f"Error fetching queue match targets: {e}")
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/queue/missing-tracks", methods=["GET"])
def api_queue_missing_tracks():
    """Return MusicBrainz release tracks that are not currently present in queue rows."""
    conn = None
    try:
        from folder_matching_enhancements import get_musicbrainz_release_metadata

        release_mbid = (request.args.get('release_mbid') or '').strip()
        queue_ids_raw = (request.args.get('queue_ids') or '').strip()

        if not release_mbid:
            return jsonify({"success": False, "error": "release_mbid is required"}), 400

        queue_ids = []
        if queue_ids_raw:
            for value in queue_ids_raw.split(','):
                value = value.strip()
                if not value:
                    continue
                try:
                    qid = int(value)
                    if qid > 0:
                        queue_ids.append(qid)
                except Exception:
                    continue
        queue_ids = list(dict.fromkeys(queue_ids))

        release_metadata = get_musicbrainz_release_metadata(release_mbid) or {}
        release_tracks = release_metadata.get('tracks') or []

        if not release_tracks:
            return jsonify({
                "success": True,
                "release_mbid": release_mbid,
                "total_release_tracks": 0,
                "missing_tracks": [],
            })

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        if queue_ids:
            ids_placeholders = ", ".join([placeholder] * len(queue_ids))
            cursor.execute(
                f"""
                SELECT id, title, track_number, disc_number, recording_mbid
                FROM download_queue
                WHERE id IN ({ids_placeholders})
                  AND status NOT IN ('removed', 'cancelled', 'deleted')
                """,
                tuple(queue_ids),
            )
        else:
            cursor.execute(
                f"""
                SELECT id, title, track_number, disc_number, recording_mbid
                FROM download_queue
                WHERE COALESCE(NULLIF(release_mbid, ''), NULLIF(release_id, '')) = {placeholder}
                  AND status NOT IN ('removed', 'cancelled', 'deleted')
                """,
                (release_mbid,),
            )

        queue_rows = cursor.fetchall() or []
        conn.close()
        conn = None

        def _norm_text(value):
            return re.sub(r"\s+", " ", re.sub(r"[^a-z0-9]+", " ", str(value or '').lower())).strip()

        def _queue_track_key(disc_number, track_number, title):
            disc = str(disc_number or '').strip()
            track = str(track_number or '').strip()
            title_norm = _norm_text(title)
            return f"{disc}:{track}:{title_norm}" if (disc or track or title_norm) else ''

        existing_recording_mbids = set()
        existing_track_keys = set()

        for row in queue_rows:
            recording_mbid = (_row_get(row, 'recording_mbid', 4, '') or '').strip()
            if recording_mbid:
                existing_recording_mbids.add(recording_mbid.lower())

            key = _queue_track_key(
                _row_get(row, 'disc_number', 3, ''),
                _row_get(row, 'track_number', 2, ''),
                _row_get(row, 'title', 1, ''),
            )
            if key:
                existing_track_keys.add(key)

        missing_tracks = []
        for track in release_tracks:
            recording_mbid = str(track.get('recording_mbid') or '').strip()
            disc_number = track.get('disc_number')
            track_number = track.get('track_number')
            title = (track.get('title') or '').strip()

            track_key = _queue_track_key(disc_number, track_number, title)
            missing = True

            if recording_mbid and recording_mbid.lower() in existing_recording_mbids:
                missing = False
            elif track_key and track_key in existing_track_keys:
                missing = False

            if not missing:
                continue

            select_key = recording_mbid or track_key or f"{disc_number or ''}:{track_number or ''}:{title}"
            missing_tracks.append({
                "key": select_key,
                "disc_number": disc_number,
                "track_number": track_number,
                "title": title,
                "artist": track.get('artist') or release_metadata.get('artist') or '',
                "duration": track.get('duration') or 0,
                "recording_mbid": recording_mbid,
                "isrc": track.get('isrc') or '',
            })

        return jsonify({
            "success": True,
            "release_mbid": release_mbid,
            "release_title": release_metadata.get('release_title') or '',
            "release_artist": release_metadata.get('artist') or '',
            "release_year": release_metadata.get('release_year'),
            "total_release_tracks": len(release_tracks),
            "missing_tracks": missing_tracks,
        })

    except Exception as e:
        logging.error(f"Error fetching queue missing tracks: {e}")
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/queue/import-missing-tracks", methods=["POST"])
def api_queue_import_missing_tracks():
    """Add selected missing MusicBrainz release tracks back into the download queue."""
    conn = None
    try:
        from folder_matching_enhancements import get_musicbrainz_release_metadata
        from download_queue_manager import add_to_queue

        payload = request.get_json(force=True, silent=True) or {}
        release_mbid = (payload.get('release_mbid') or '').strip()
        selected_keys_raw = payload.get('selected_keys') or []
        queue_ids_raw = payload.get('queue_ids') or []

        if not release_mbid:
            return jsonify({"success": False, "error": "release_mbid is required"}), 400

        selected_keys = []
        if isinstance(selected_keys_raw, list):
            for key in selected_keys_raw:
                key_text = str(key or '').strip()
                if key_text:
                    selected_keys.append(key_text)
        selected_keys = list(dict.fromkeys(selected_keys))

        if not selected_keys:
            return jsonify({"success": False, "error": "selected_keys is required"}), 400

        queue_ids = []
        if isinstance(queue_ids_raw, list):
            for value in queue_ids_raw:
                try:
                    qid = int(value)
                    if qid > 0:
                        queue_ids.append(qid)
                except Exception:
                    continue
        queue_ids = list(dict.fromkeys(queue_ids))

        release_metadata = get_musicbrainz_release_metadata(release_mbid) or {}
        release_tracks = release_metadata.get('tracks') or []
        if not release_tracks:
            return jsonify({"success": False, "error": "No MusicBrainz track metadata available for this release"}), 400

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        reference = None
        if queue_ids:
            ids_placeholders = ", ".join([placeholder] * len(queue_ids))
            cursor.execute(
                f"""
                SELECT id, artist, album, album_artist, source, import_group, import_type
                FROM download_queue
                WHERE id IN ({ids_placeholders})
                ORDER BY id
                LIMIT 1
                """,
                tuple(queue_ids),
            )
            reference = cursor.fetchone()

        conn.close()
        conn = None

        def _norm_text(value):
            return re.sub(r"\s+", " ", re.sub(r"[^a-z0-9]+", " ", str(value or '').lower())).strip()

        def _track_key(disc_number, track_number, title):
            disc = str(disc_number or '').strip()
            track = str(track_number or '').strip()
            title_norm = _norm_text(title)
            return f"{disc}:{track}:{title_norm}" if (disc or track or title_norm) else ''

        selected_set = set(selected_keys)

        ref_artist = (_row_get(reference, 'artist', 1, '') or '').strip() if reference else ''
        ref_album = (_row_get(reference, 'album', 2, '') or '').strip() if reference else ''
        ref_album_artist = (_row_get(reference, 'album_artist', 3, '') or '').strip() if reference else ''
        ref_source = (_row_get(reference, 'source', 4, '') or 'soulseek').strip() if reference else 'soulseek'
        ref_import_group = (_row_get(reference, 'import_group', 5, '') or '').strip() if reference else ''
        ref_import_type = (_row_get(reference, 'import_type', 6, '') or 'album').strip() if reference else 'album'

        release_title = (release_metadata.get('release_title') or ref_album or '').strip()
        release_artist = (release_metadata.get('artist') or ref_album_artist or ref_artist or '').strip()
        release_year = release_metadata.get('release_year') or None
        import_group = ref_import_group or f"mbid_{release_mbid}"

        added_count = 0
        skipped_count = 0
        failed_count = 0
        imported_items = []
        skipped_items = []
        failed_items = []

        for track in release_tracks:
            title = (track.get('title') or '').strip()
            if not title:
                continue

            recording_mbid = (track.get('recording_mbid') or '').strip()
            key = recording_mbid or _track_key(track.get('disc_number'), track.get('track_number'), title)
            if key not in selected_set:
                continue

            track_artist = (track.get('artist') or release_artist or ref_artist or '').strip()
            queue_item = add_to_queue(
                artist=track_artist,
                title=title,
                album=release_title,
                source=ref_source or 'soulseek',
                priority=5,
                import_group=import_group,
                import_type=ref_import_type or 'album',
                track_number=track.get('track_number'),
                album_artist=release_artist or track_artist,
                year=release_year,
                release_id=release_mbid,
                release_source='musicbrainz',
                duration=track.get('duration'),
                disc_number=track.get('disc_number'),
                release_mbid=release_mbid,
                recording_mbid=recording_mbid,
                isrc=track.get('isrc'),
            )

            if queue_item and queue_item.get('_queue_outcome') == 'added':
                added_count += 1
                imported_items.append({
                    "queue_id": queue_item.get('id'),
                    "title": title,
                    "artist": track_artist,
                })
            elif queue_item and queue_item.get('_queue_outcome') == 'duplicate':
                skipped_count += 1
                skipped_items.append({
                    "existing_queue_id": queue_item.get('id'),
                    "title": title,
                    "artist": track_artist,
                })
            else:
                failed_count += 1
                failed_items.append({
                    "title": title,
                    "artist": track_artist,
                })

        return jsonify({
            "success": True,
            "release_mbid": release_mbid,
            "added_count": added_count,
            "skipped_count": skipped_count,
            "failed_count": failed_count,
            "imported_items": imported_items,
            "skipped_items": skipped_items,
            "failed_items": failed_items,
        })

    except Exception as e:
        logging.error(f"Error importing missing queue tracks: {e}")
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/musicbrainz/search/releases", methods=["GET"])
def api_musicbrainz_search_releases():
    """
    Search MusicBrainz for releases by artist and album
    Used for manual MBID selection in download monitor
    """
    try:
        from download_folder_grouping import match_folder_group_with_musicbrainz
        
        artist = request.args.get('artist', '').strip()
        album = request.args.get('album', '').strip()
        
        if not artist or not album:
            return jsonify({"error": "Artist and album are required"}), 400
        
        # Use MusicBrainz-only path for this modal to keep search latency low.
        match_result = match_folder_group_with_musicbrainz('', artist, album, allow_discogs_fallback=False)
        releases = match_result.get('candidates', []) if isinstance(match_result, dict) else []
        
        # Format for UI
        formatted_releases = []
        for rel in releases:
            formatted_releases.append({
                'id': rel.get('id'),
                'title': rel.get('title'),
                'artist': rel.get('artist', artist),
                'year': rel.get('date', '')[:4] if rel.get('date') else None,
                'country': rel.get('country'),
                'tracks': rel.get('track_count', rel.get('track-count', 0)),
                'format': rel.get('format'),
                'barcode': rel.get('barcode')
            })
        
        return jsonify({
            "success": True,
            "releases": formatted_releases,
            "count": len(formatted_releases)
        })
        
    except Exception as e:
        logging.error(f"Error searching MusicBrainz: {e}")
        import traceback
        logging.error(traceback.format_exc())
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/queue/update-album-mbid", methods=["POST"])
def api_queue_update_album_mbid():
    """
    Update all queue items for an album with new MusicBrainz release ID
    Used when user selects a better MBID match
    """
    conn = None
    try:
        data = request.get_json(force=True, silent=True) or {}

        old_artist = data.get('old_artist', '').strip()
        old_album = data.get('old_album', '').strip()
        new_mbid = data.get('new_mbid', '').strip()
        new_artist = data.get('new_artist', '').strip()
        new_album = data.get('new_album', '').strip()

        if not all([old_artist, old_album, new_mbid]):
            return jsonify({"error": "Missing required fields"}), 400

        # Keep this endpoint fast: do not block on external metadata fetches.
        release_year = None

        # Update existing queue items
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        mbid_import_group = f"mbid_{new_mbid}"

        cursor.execute(
            f"""
            UPDATE download_queue
            SET release_mbid = {placeholder},
                release_id = {placeholder},
                release_source = 'musicbrainz',
                album = {placeholder},
                album_artist = {placeholder},
                import_group = {placeholder},
                release_year = {placeholder},
                updated_at = CURRENT_TIMESTAMP
            WHERE LOWER(COALESCE(NULLIF(album_artist, ''), artist)) = LOWER({placeholder})
              AND LOWER(album) = LOWER({placeholder})
            """,
            (new_mbid, new_mbid, new_album, new_artist, mbid_import_group, release_year, old_artist, old_album)
        )

        updated_count = cursor.rowcount or 0

        # Merge any existing queue rows for this MBID under the same import_group so
        # the monitor collapses them into one folder/group.
        cursor.execute(
            f"""
            UPDATE download_queue
            SET import_group = {placeholder},
                release_source = 'musicbrainz',
                album_artist = COALESCE(NULLIF(album_artist, ''), {placeholder}),
                updated_at = CURRENT_TIMESTAMP
            WHERE COALESCE(NULLIF(release_mbid, ''), NULLIF(release_id, '')) = {placeholder}
            """,
            (mbid_import_group, new_artist, new_mbid),
        )
        merged_count = cursor.rowcount or 0

        conn.commit()
        conn.close()
        conn = None

        # Local-only reconciliation: match existing album files to queue rows.
        # If a file does not match any queue row, remove it from /downloads.
        reconcile_summary = {
            "success": False,
            "queue_items_considered": 0,
            "files_considered": 0,
            "matched_count": 0,
            "deleted_unmatched_count": 0,
            "unmatched_files": [],
        }
        try:
            from download_queue_manager import reconcile_album_files_with_queue
            reconcile_summary = reconcile_album_files_with_queue(
                artist=new_artist,
                album=new_album,
                release_mbid=new_mbid,
                delete_unmatched=True,
            )
        except Exception as reconcile_err:
            logging.warning(f"[UPDATE_MBID] Reconcile pass failed for {new_artist} - {new_album}: {reconcile_err}")

        return jsonify({
            "success": True,
            "message": f"Updated {updated_count} queue items with new MBID",
            "updated_count": updated_count,
            "merged_count": merged_count,
            "release_mbid": new_mbid,
            "reconcile": reconcile_summary,
        })

    except Exception as e:
        logging.error(f"Error updating album MBID: {e}")
        import traceback
        logging.error(traceback.format_exc())
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/queue/<int:queue_id>/send", methods=["POST"])
def api_queue_send_to_download(queue_id):
    """
    Change status from 'queried' to 'queued' to send to download processor
    Used for manually approving auto-queried tracks
    """
    conn = None
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Verify item exists and is in 'queried' status
        cursor.execute(
            f"SELECT status FROM download_queue WHERE id = {placeholder}",
            (queue_id,)
        )
        
        item = cursor.fetchone()
        
        if not item:
            conn.close()
            return jsonify({"error": "Queue item not found"}), 404
        
        current_status = item[0] if isinstance(item, tuple) else item.get('status')
        
        if current_status != 'queried':
            conn.close()
            return jsonify({
                "error": f"Item status is '{current_status}', must be 'queried' to send"
            }), 400
        
        # Update status to queued
        cursor.execute(
            f"""
            UPDATE download_queue
            SET status = 'queued',
                updated_at = CURRENT_TIMESTAMP
            WHERE id = {placeholder}
            """,
            (queue_id,)
        )
        
        conn.commit()
        conn.close()
        conn = None
        
        return jsonify({
            "success": True,
            "message": "Queue item sent for download",
            "queue_id": queue_id
        })
        
    except Exception as e:
        logging.error(f"Error sending queue item to download: {e}")
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        return jsonify({"success": False, "error": str(e)}), 500
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


@app.route("/api/queue/<int:queue_id>/apply-mbid-match", methods=["POST"])
def api_queue_apply_mbid_match(queue_id):
    """Apply a MusicBrainz release match to a single queue item and queue all release tracks."""
    conn = None
    try:
        data = request.get_json(force=True, silent=True) or {}
        new_mbid = (data.get('new_mbid') or '').strip()
        new_artist = (data.get('new_artist') or '').strip()
        new_album = (data.get('new_album') or '').strip()
        target_track_title = (data.get('target_track_title') or '').strip()
        target_recording_mbid = (data.get('target_recording_mbid') or '').strip()

        target_track_number = data.get('target_track_number')
        try:
            target_track_number = str(int(target_track_number)) if target_track_number not in (None, '') else None
        except Exception:
            target_track_number = None

        target_disc_number = data.get('target_disc_number')
        try:
            target_disc_number = str(int(target_disc_number)) if target_disc_number not in (None, '') else None
        except Exception:
            target_disc_number = None

        if not new_mbid:
            return jsonify({"error": "new_mbid is required"}), 400

        # Keep the request fast: do not block on external metadata lookup before
        # applying the selected MBID. Any enrichment happens asynchronously.
        release_year = None
        release_metadata = None

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        cursor.execute(
            f"""
            SELECT artist, album, status, file_path, matched_file_path, music_file_path, found_filename
            FROM download_queue
            WHERE id = {placeholder}
            """,
            (queue_id,)
        )
        row = cursor.fetchone()
        if not row:
            conn.close()
            conn = None
            return jsonify({"error": "Queue item not found"}), 404

        current_artist = row.get('artist') if isinstance(row, dict) else row[0]
        current_album = row.get('album') if isinstance(row, dict) else row[1]
        current_status = row.get('status') if isinstance(row, dict) else row[2]
        current_file_path = row.get('file_path') if isinstance(row, dict) else row[3]
        current_matched_file_path = row.get('matched_file_path') if isinstance(row, dict) else row[4]
        current_music_file_path = row.get('music_file_path') if isinstance(row, dict) else row[5]
        current_found_filename = row.get('found_filename') if isinstance(row, dict) else row[6]

        target_artist = new_artist or current_artist
        target_album = new_album or current_album

        cursor.execute(
            f"""
            UPDATE download_queue
            SET release_mbid = {placeholder},
                release_id = {placeholder},
                release_source = 'musicbrainz',
                album_artist = {placeholder},
                album = {placeholder},
                title = CASE
                    WHEN {placeholder} <> '' THEN {placeholder}
                    ELSE title
                END,
                track_number = COALESCE({placeholder}, track_number),
                disc_number = COALESCE({placeholder}, disc_number),
                recording_mbid = CASE
                    WHEN {placeholder} <> '' THEN {placeholder}
                    ELSE recording_mbid
                END,
                release_year = COALESCE(release_year, {placeholder}),
                status = CASE
                    WHEN TRIM(COALESCE(status, '')) = '' OR status = 'matched' THEN 'queued'
                    WHEN status = 'unmatched' AND TRIM(COALESCE(file_path, '')) != '' THEN 'matched'
                    WHEN status = 'unmatched' THEN 'queued'
                    ELSE status
                END,
                updated_at = CURRENT_TIMESTAMP
            WHERE id = {placeholder}
            """,
            (
                new_mbid,
                new_mbid,
                target_artist,
                target_album,
                target_track_title,
                target_track_title,
                target_track_number,
                target_disc_number,
                target_recording_mbid,
                target_recording_mbid,
                release_year,
                queue_id,
            )
        )

        conn.commit()
        conn.close()
        conn = None

        local_file_updated = False
        local_file_path = None
        local_file_warning = None
        had_local_file = any(
            str(path or '').strip()
            for path in (current_file_path, current_matched_file_path, current_music_file_path, current_found_filename)
        )
        current_status_normalized = str(current_status or '').strip().lower()

        if had_local_file and current_status_normalized in {'completed', 'imported', 'in_collection'}:
            sync_conn = None
            try:
                from download_queue_manager import move_single_track_to_music_dir, update_queue_item

                sync_conn = get_db()
                sync_cursor = sync_conn.cursor()
                sync_cursor.execute(f"SELECT * FROM download_queue WHERE id = {placeholder}", (queue_id,))
                queue_item = sync_cursor.fetchone()
                if queue_item and not isinstance(queue_item, dict):
                    column_names = [col[0] for col in sync_cursor.description]
                    queue_item = dict(zip(column_names, queue_item))
                sync_conn.close()
                sync_conn = None

                if queue_item:
                    move_result = move_single_track_to_music_dir(dict(queue_item))
                    if move_result.get('success'):
                        local_file_path = move_result.get('target_path')
                        if local_file_path:
                            update_queue_item(queue_id, file_path=local_file_path)
                        local_file_updated = True
                    else:
                        local_file_warning = move_result.get('error') or 'Local file update failed'
            except Exception as sync_err:
                logging.warning(f"[QUEUE_MATCH] Local file update failed for queue {queue_id}: {sync_err}")
                local_file_warning = str(sync_err)
            finally:
                if sync_conn is not None:
                    try:
                        sync_conn.close()
                    except Exception:
                        pass

        return jsonify({
            "success": True,
            "message": "Queue item match updated",
            "queue_id": queue_id,
            "release_mbid": new_mbid,
            "artist": target_artist,
            "album": target_album,
            "target_track_number": target_track_number,
            "target_disc_number": target_disc_number,
            "target_track_title": target_track_title,
            "local_file_updated": local_file_updated,
            "local_file_path": local_file_path,
            "warning": local_file_warning,
            "tracks_added": 0,
        })
    except Exception as e:
        logging.error(f"Error applying queue MBID match: {e}")
        import traceback
        logging.error(traceback.format_exc())
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
            try:
                conn.close()
            except Exception:
                pass
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/queue/apply-mbid-match-batch", methods=["POST"])
def api_queue_apply_mbid_match_batch():
    """Apply one MusicBrainz release match to multiple queue items in a single merge operation."""
    conn = None
    try:
        data = request.get_json(force=True, silent=True) or {}
        queue_ids_raw = data.get('queue_ids') or []
        new_mbid = (data.get('new_mbid') or '').strip()
        new_artist = (data.get('new_artist') or '').strip()
        new_album = (data.get('new_album') or '').strip()
        expand_tracks = bool(data.get('expand_tracks', False))

        queue_ids = []
        if isinstance(queue_ids_raw, list):
            for value in queue_ids_raw:
                try:
                    qid = int(value)
                    if qid > 0:
                        queue_ids.append(qid)
                except Exception:
                    continue

        # Preserve input order while de-duplicating ids.
        queue_ids = list(dict.fromkeys(queue_ids))

        if not queue_ids:
            return jsonify({"error": "queue_ids is required"}), 400
        if not new_mbid:
            return jsonify({"error": "new_mbid is required"}), 400

        # Keep the request fast: avoid blocking on external MusicBrainz calls.
        # Queue rows are updated immediately; optional release expansion can run
        # asynchronously when explicitly requested.
        release_year = None
        release_metadata = None

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        # Resolve fallback artist/album from first queue item when caller did not pass values.
        first_queue_id = queue_ids[0]
        cursor.execute(
            f"SELECT artist, album FROM download_queue WHERE id = {placeholder}",
            (first_queue_id,)
        )
        first_row = cursor.fetchone()
        if not first_row:
            conn.close()
            conn = None
            return jsonify({"error": "Queue item not found"}), 404

        fallback_artist = first_row.get('artist') if isinstance(first_row, dict) else first_row[0]
        fallback_album = first_row.get('album') if isinstance(first_row, dict) else first_row[1]
        target_artist = new_artist or fallback_artist
        target_album = new_album or fallback_album
        mbid_import_group = f"mbid_{new_mbid}"

        ids_placeholders = ", ".join([placeholder] * len(queue_ids))
        cursor.execute(
            f"""
            UPDATE download_queue
            SET release_mbid = {placeholder},
                release_id = {placeholder},
                release_source = 'musicbrainz',
                album_artist = {placeholder},
                album = {placeholder},
                release_year = COALESCE(release_year, {placeholder}),
                import_group = {placeholder},
                status = CASE
                    WHEN TRIM(COALESCE(status, '')) = '' OR status = 'matched' THEN 'queued'
                    WHEN status = 'unmatched' AND TRIM(COALESCE(file_path, '')) != '' THEN 'matched'
                    WHEN status = 'unmatched' THEN 'queued'
                    ELSE status
                END,
                updated_at = CURRENT_TIMESTAMP
            WHERE id IN ({ids_placeholders})
            """,
            (new_mbid, new_mbid, target_artist, target_album, release_year, mbid_import_group, *queue_ids)
        )

        updated_count = cursor.rowcount or 0
        conn.commit()
        conn.close()
        conn = None

        if expand_tracks:
            # Optional expansion path retained for explicit callers only.
            def _expand_release_tracks_async(mbid, artist_name, album_name, prefetched_release_metadata=None):
                try:
                    from folder_matching_enhancements import get_musicbrainz_release_metadata
                    from download_queue_manager import add_to_queue

                    release_data = prefetched_release_metadata or get_musicbrainz_release_metadata(mbid) or {}
                    release_tracks = release_data.get('tracks', [])
                    inferred_year_raw = release_data.get('release_year')
                    inferred_year = str(inferred_year_raw).strip() if inferred_year_raw not in (None, '') else None

                    added_tracks = 0
                    for track in release_tracks or []:
                        track_title = track.get('title', '')
                        if not track_title:
                            continue
                        track_artist = (track.get('artist') or artist_name or '').strip() or artist_name
                        track_number = track.get('track_number')
                        disc_number = track.get('disc_number')
                        recording_mbid = track.get('recording_mbid') or track.get('id')
                        track_duration = track.get('duration', 0)
                        if track_duration:
                            track_duration = track_duration // 1000

                        queued = add_to_queue(
                            artist=track_artist,
                            title=track_title,
                            album=album_name,
                            album_artist=artist_name,
                            source='soulseek',
                            release_mbid=mbid,
                            release_id=mbid,
                            release_source='musicbrainz',
                            track_number=track_number,
                            disc_number=disc_number,
                            recording_mbid=recording_mbid,
                            year=inferred_year,
                            duration=track_duration,
                        )
                        if queued:
                            added_tracks += 1

                    log_unified(
                        f"[QUEUE_MATCH_BATCH] Expanded MBID {mbid}: added {added_tracks} track(s)"
                    )
                except Exception as async_err:
                    logging.warning(f"[QUEUE_MATCH_BATCH] Background release expansion failed for MBID {mbid}: {async_err}")

            threading.Thread(
                target=_expand_release_tracks_async,
                args=(new_mbid, target_artist, target_album, release_metadata),
                daemon=True,
                name=f"queue-match-batch-expand-{new_mbid[:8]}",
            ).start()

        return jsonify({
            "success": True,
            "message": "Folder queue match updated",
            "queue_ids": queue_ids,
            "updated_count": updated_count,
            "failed_count": max(len(queue_ids) - int(updated_count or 0), 0),
            "release_mbid": new_mbid,
            "artist": target_artist,
            "album": target_album,
            "tracks_pending": bool(expand_tracks),
            "expand_tracks": bool(expand_tracks),
        })

    except Exception as e:
        logging.error(f"Error applying batch queue MBID match: {e}")
        import traceback
        logging.error(traceback.format_exc())
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
            try:
                conn.close()
            except Exception:
                pass
        return jsonify({"success": False, "error": str(e)}), 500


@app.route("/api/queue/<int:queue_id>/reset-match", methods=["POST"])
def api_queue_reset_match(queue_id):
    """Reset a queue item's current match so it can be rematched manually."""
    conn = None
    try:
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"

        cursor.execute(
            f"""
            UPDATE download_queue
            SET release_mbid = NULL,
                release_id = NULL,
                release_source = NULL,
                mb_release_group_id = NULL,
                mb_match_status = NULL,
                mb_match_score = NULL,
                mb_match_candidates = NULL,
                mb_matched_title = NULL,
                mb_matched_artist = NULL,
                mb_matched_year = NULL,
                mb_last_match_at = NULL,
                status = 'unmatched',
                matched_file_path = NULL,
                music_file_path = NULL,
                found_filename = NULL,
                in_collection = 0,
                collection_track_id = NULL,
                collection_matched_at = NULL,
                failure_reason = NULL,
                updated_at = CURRENT_TIMESTAMP
            WHERE id = {placeholder}
            """,
            (queue_id,)
        )

        updated = cursor.rowcount > 0
        conn.commit()
        conn.close()
        conn = None

        if not updated:
            return jsonify({"error": "Queue item not found"}), 404

        return jsonify({
            "success": True,
            "message": "Queue item match reset",
            "queue_id": queue_id,
        })
    except Exception as e:
        logging.error(f"Error resetting queue match: {e}")
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        return jsonify({"success": False, "error": str(e)}), 500
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


@app.route("/api/queue/cleanup-invalid-mbids", methods=["POST"])
def api_queue_cleanup_invalid_mbids():
    """Reset queue rows that contain a non-UUID release_mbid value.

    This repairs legacy rows where a non-MusicBrainz ID (for example, a Discogs
    numeric ID) was stored in release_mbid and later caused MusicBrainz lookup
    failures.
    """
    conn = None
    try:
        payload = request.get_json(silent=True) or {}
        dry_run = bool(payload.get("dry_run", False))

        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        length_expr = "char_length"
        current_ts_expr = "CURRENT_TIMESTAMP"
        valid_uuid_like = "________-____-____-____-____________"

        invalid_condition = (
            "TRIM(COALESCE(release_mbid, '')) != '' "
            f"AND NOT ({length_expr}(release_mbid) = 36 AND release_mbid LIKE {placeholder})"
        )

        cursor.execute(
            f"""
            SELECT id, artist, album, release_mbid, status
            FROM download_queue
            WHERE {invalid_condition}
            ORDER BY id
            LIMIT 25
            """,
            (valid_uuid_like,),
        )
        sample_rows = cursor.fetchall()

        cursor.execute(
            f"""
            SELECT COUNT(*)
            FROM download_queue
            WHERE {invalid_condition}
            """,
            (valid_uuid_like,),
        )
        count_row = cursor.fetchone()
        invalid_count = count_row[0] if not isinstance(count_row, dict) else count_row.get("count", 0)

        sample = []
        for row in sample_rows:
            if isinstance(row, dict):
                sample.append({
                    "id": row.get("id"),
                    "artist": row.get("artist"),
                    "album": row.get("album"),
                    "release_mbid": row.get("release_mbid"),
                    "status": row.get("status"),
                })
            else:
                sample.append({
                    "id": row[0],
                    "artist": row[1],
                    "album": row[2],
                    "release_mbid": row[3],
                    "status": row[4],
                })

        if dry_run:
            conn.close()
            conn = None
            return jsonify({
                "success": True,
                "dry_run": True,
                "invalid_count": invalid_count,
                "sample": sample,
            })

        cursor.execute(
            f"""
            UPDATE download_queue
            SET release_mbid = NULL,
                release_id = CASE
                    WHEN release_source = 'musicbrainz' OR release_id = release_mbid THEN NULL
                    ELSE release_id
                END,
                release_source = CASE
                    WHEN release_source = 'musicbrainz' OR release_id = release_mbid THEN NULL
                    ELSE release_source
                END,
                mb_release_group_id = NULL,
                mb_match_status = NULL,
                mb_match_score = NULL,
                mb_match_candidates = NULL,
                mb_matched_title = NULL,
                mb_matched_artist = NULL,
                mb_matched_year = NULL,
                mb_last_match_at = NULL,
                status = CASE
                    WHEN status IN ('matched', 'queried', 'pending_match', 'possible_duplicate', 'duplicate')
                    THEN 'unmatched'
                    ELSE status
                END,
                failure_reason = CASE
                    WHEN status IN ('matched', 'queried', 'pending_match', 'possible_duplicate', 'duplicate')
                    THEN 'Reset invalid release_mbid (non-UUID); please rematch'
                    ELSE failure_reason
                END,
                updated_at = {current_ts_expr}
            WHERE {invalid_condition}
            """,
            (valid_uuid_like,),
        )
        updated_count = cursor.rowcount or 0

        conn.commit()
        conn.close()
        conn = None

        logging.info(f"[QUEUE_CLEANUP] Reset {updated_count} queue rows with invalid release_mbid values")

        return jsonify({
            "success": True,
            "dry_run": False,
            "invalid_count": invalid_count,
            "updated_count": updated_count,
            "sample": sample,
            "message": f"Reset {updated_count} queue row(s) with invalid release_mbid",
        })
    except Exception as e:
        logging.error(f"Error cleaning up invalid queue MBIDs: {e}")
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
        return jsonify({"success": False, "error": str(e)}), 500


