@app.route("/api/metadata-compare/accept-navidrome", methods=["POST"])
def accept_navidrome_data():
    """Accept Navidrome data and lock it from being overwritten by Beets"""
    try:
        data = request.json or {}
        album = data.get("album", "")
        artist = data.get("artist", "")
        
        if not artist or not album:
            return jsonify({"error": "Artist and album name required"}), 400
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Mark all tracks in this album as locked from Beets overwrites
        cursor.execute(f"""
            UPDATE tracks 
            SET metadata_locked = 1
            WHERE artist = {placeholder} AND album = {placeholder}
        """, (artist, album))
        
        conn.commit()
        conn.close()
        
        return jsonify({
            "success": True,
            "message": f"Navidrome data locked for {artist} - {album}"
        })
    except Exception as e:
        logging.error(f"Error accepting Navidrome data: {str(e)}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/metadata-compare/apply-musicbrainz", methods=["POST"])
def apply_musicbrainz_data():
    """Apply MusicBrainz data to an album - both DB and files"""
    try:
        data = request.json or {}
        album = data.get("album", "")
        artist = data.get("artist", "")
        mb_data = data.get("mb_data", {})
        
        if not artist or not album or not mb_data:
            return jsonify({"error": "Artist, album, and MusicBrainz data required"}), 400
        
        conn = get_db()
        cursor = conn.cursor()
        placeholder = "%s"
        
        # Update tracks with MusicBrainz data
        cursor.execute("""
            UPDATE tracks 
            SET 
                year = %s,
                musicbrainz_genres = %s
            WHERE artist = %s AND album = %s
            RETURNING id
        """, (
            mb_data.get("year"),
            ",".join(mb_data.get("genres", [])),
            artist,
            album
        ))
        # Get IDs of updated tracks for file sync
        updated_ids = [row[0] for row in cursor.fetchall()]
        conn.commit()
        
        # Sync tags to files
        synced_count = 0
        failed_count = 0
        if updated_ids:
            from helpers.tag_manager import sync_track_tags_to_file
            for track_id in updated_ids:
                try:
                    if sync_track_tags_to_file(track_id):
                        synced_count += 1
                    else:
                        failed_count += 1
                except Exception as e:
                    logging.warning(f"Failed to sync tags for track {track_id}: {e}")
                    failed_count += 1
        
        conn.close()
        
        message = f"Applied MusicBrainz data to {artist} - {album} ({len(updated_ids)} tracks)"
        if synced_count > 0:
            message += f". Synced {synced_count} files"
        if failed_count > 0:
            message += f", {failed_count} sync failures"
        
        return jsonify({
            "success": True,
            "message": message,
            "tracks_updated": len(updated_ids),
            "files_synced": synced_count,
            "sync_failures": failed_count
        })
    except Exception as e:
        logging.error(f"Error applying MusicBrainz data: {str(e)}")
        return jsonify({"error": str(e)}), 500


