@app.route("/api/artist/genre-recommendations", methods=["GET"])
def api_artist_genre_recommendations():
    """Fetch artist genre recommendations from MusicBrainz via backend proxy."""
    artist_name = (request.args.get("artist", "") or "").strip()
    if not artist_name:
        return jsonify({"error": "Artist name is required"}), 400

    try:
        headers = {
            "User-Agent": MUSICBRAINZ_USER_AGENT,
            "Accept": "application/json"
        }

        # Search first, then fetch artist details with tags/genres for better recommendations.
        search_params = {
            "query": f'artist:"{artist_name}"',
            "fmt": "json",
            "limit": 5,
        }

        with create_retry_session(
            user_agent=MUSICBRAINZ_USER_AGENT,
            retries=2,
            backoff=0.5,
            status_forcelist=(429, 500, 502, 503, 504),
        ) as session:
            search_response = session.get(
                "https://musicbrainz.org/ws/2/artist",
                params=search_params,
                headers=headers,
                timeout=(5, 10),
            )
            search_response.raise_for_status()
            search_data = search_response.json() or {}

            candidates = search_data.get("artists", []) or []
            if not candidates:
                return jsonify({
                    "success": True,
                    "artist": artist_name,
                    "recommendations": [],
                    "message": "No MusicBrainz artist matches found",
                })

            requested_norm = _normalize_artist_name(artist_name)

            def _candidate_rank(candidate):
                candidate_name = candidate.get("name", "")
                candidate_norm = _normalize_artist_name(candidate_name)
                try:
                    mb_score = int(candidate.get("score") or 0)
                except (TypeError, ValueError):
                    mb_score = 0
                exact_bonus = 1000 if candidate_norm == requested_norm else 0
                return exact_bonus + mb_score

            best_candidate = max(candidates, key=_candidate_rank)
            artist_mbid = best_candidate.get("id", "")

            if not artist_mbid:
                return jsonify({
                    "success": True,
                    "artist": artist_name,
                    "recommendations": [],
                    "message": "Matched artist has no MusicBrainz ID",
                })

            details_response = session.get(
                f"https://musicbrainz.org/ws/2/artist/{artist_mbid}",
                params={"fmt": "json", "inc": "genres+tags"},
                headers=headers,
                timeout=(5, 10),
            )
            details_response.raise_for_status()
            details = details_response.json() or {}

        genre_scores = {}
        for entry in (details.get("genres", []) or []):
            name = str(entry.get("name") or "").strip()
            if not name:
                continue
            count = entry.get("count") or 0
            try:
                count_val = int(count)
            except (TypeError, ValueError):
                count_val = 0
            genre_scores[name] = max(genre_scores.get(name, 0), count_val)

        for entry in (details.get("tags", []) or []):
            name = str(entry.get("name") or "").strip()
            if not name:
                continue
            count = entry.get("count") or 0
            try:
                count_val = int(count)
            except (TypeError, ValueError):
                count_val = 0
            genre_scores[name] = max(genre_scores.get(name, 0), count_val)

        recommendations = [
            name for name, _ in sorted(
                genre_scores.items(),
                key=lambda item: (-item[1], item[0].lower()),
            )
        ][:15]

        return jsonify({
            "success": True,
            "artist": artist_name,
            "musicbrainz_artist": best_candidate.get("name", artist_name),
            "musicbrainz_artist_id": artist_mbid,
            "recommendations": recommendations,
            "source": "musicbrainz",
        })

    except requests.exceptions.RequestException as e:
        logging.warning(f"[ARTIST GENRES] MusicBrainz request failed for '{artist_name}': {e}")
        return jsonify({"error": "MusicBrainz request failed"}), 503
    except Exception as e:
        logging.error(f"[ARTIST GENRES] Error fetching genre recommendations for '{artist_name}': {e}")
        return jsonify({"error": str(e)}), 500

@app.route("/api/track/musicbrainz", methods=["POST"])
def api_track_musicbrainz_lookup():
    """Lookup track on MusicBrainz for multiple matches (Picard-style) with retry logic"""
    logger = logging.getLogger('sptnr')
    try:
        data = request.get_json()
        title = data.get("title", "")
        artist = data.get("artist", "")
        
        if not title or not artist:
            return jsonify({"error": "Missing title or artist"}), 400
        
        # Search MusicBrainz for recordings with retry
        query = f'recording:"{title}" AND artist:"{artist}"'
        headers = {"User-Agent": MUSICBRAINZ_USER_AGENT}
        
        max_retries = 2
        for attempt in range(max_retries):
            try:
                resp = requests.get(
                    "https://musicbrainz.org/ws/2/recording",
                    params={"query": query, "fmt": "json", "limit": 10, "inc": "releases+artist-credits+work-level-rels+work-rels"},
                    headers=headers,
                    timeout=5
                )
                resp.raise_for_status()
                data = resp.json()
                recordings = data.get("recordings", []) or []
                
                if not recordings:
                    return jsonify({"results": [], "message": "No MusicBrainz track matches found"}), 200
                
                # Format results with similarity scores
                import difflib
                results = []
                for rec in recordings:
                    rec_id = rec.get("id", "")
                    rec_title = rec.get("title", "")
                    rec_length = rec.get("length", 0)  # in milliseconds
                    
                    # Get artist credit
                    artist_credit = rec.get("artist-credit", [])
                    rec_artist = artist_credit[0].get("name", "") if artist_credit else ""
                    
                    # Get releases (albums this appears on)
                    releases = rec.get("releases", []) or []
                    release_list = []
                    for rel in releases[:5]:
                        release_list.append({
                            "id": rel.get("id", ""),
                            "title": rel.get("title", "")
                        })

                    best_album = releases[0].get("title", "") if releases else ""
                    best_year = ""
                    for rel in releases:
                        rel_date = (rel.get("date") or "").strip()
                        if len(rel_date) >= 4 and rel_date[:4].isdigit():
                            best_year = rel_date[:4]
                            break

                    writer_names = []
                    for rel in rec.get("relations", []) or []:
                        rel_type = str(rel.get("type") or "").lower()
                        if rel_type in ("writer", "lyricist", "composer"):
                            rel_artist = (rel.get("artist") or {}).get("name")
                            if rel_artist and rel_artist not in writer_names:
                                writer_names.append(rel_artist)

                        work = rel.get("work") or {}
                        for work_rel in work.get("relations", []) or []:
                            work_rel_type = str(work_rel.get("type") or "").lower()
                            if work_rel_type in ("writer", "lyricist", "composer"):
                                work_artist = (work_rel.get("artist") or {}).get("name")
                                if work_artist and work_artist not in writer_names:
                                    writer_names.append(work_artist)
                    
                    # Calculate similarity scores
                    title_similarity = difflib.SequenceMatcher(None, title.lower(), rec_title.lower()).ratio()
                    artist_similarity = difflib.SequenceMatcher(None, artist.lower(), rec_artist.lower()).ratio()
                    overall_confidence = (title_similarity * 0.7 + artist_similarity * 0.3)
                    
                    results.append({
                        "mbid": rec_id,
                        "title": rec_title,
                        "artist": rec_artist,
                        "album": best_album,
                        "year": best_year,
                        "length": rec_length,
                        "releases": release_list,
                        "writers": writer_names,
                        "composer": ", ".join(writer_names) if writer_names else "",
                        "confidence": round(overall_confidence, 3),
                        "title_similarity": round(title_similarity, 3),
                        "artist_similarity": round(artist_similarity, 3),
                        "source": "musicbrainz"
                    })
                
                # Sort by confidence
                results.sort(key=lambda x: x["confidence"], reverse=True)
                
                return jsonify({"results": results[:10]}), 200
                
            except requests.exceptions.Timeout:
                logging.debug(f"MusicBrainz timeout (attempt {attempt+1}/{max_retries}) for {title} by {artist}")
                if attempt < max_retries - 1:
                    time.sleep(1 * (2 ** attempt))  # Exponential backoff
            except requests.exceptions.ConnectionError as e:
                logging.debug(f"MusicBrainz connection error (attempt {attempt+1}/{max_retries}): {type(e).__name__}")
                if attempt < max_retries - 1:
                    time.sleep(1 * (2 ** attempt))
            except Exception as e:
                logging.debug(f"MusicBrainz lookup error: {e}")
                if attempt == max_retries - 1:
                    return jsonify({"error": f"MusicBrainz lookup failed: {str(e)}"}), 500
                time.sleep(1)
        
        # Log at warning level for transient network issues (not critical errors)
        logger.warning(f"MusicBrainz track lookup unavailable after retries for '{title}' by '{artist}'")
        return jsonify({"error": "MusicBrainz connection failed. Try again later."}), 503
            
    except Exception as e:
        logger.error(f"MusicBrainz track lookup error: {e}")
        return jsonify({"error": str(e)}), 500

