# ============================================================================

@app.route("/api/upcoming-releases", methods=["GET"])
def api_upcoming_releases():
    """Get upcoming releases with collection/recommended artist annotations."""
    try:
        from wikipedia_releases_scraper import WikipediaReleaseScraper
        import json as _json

        def _extract_similar_names(raw_value):
            names = set()
            if not raw_value:
                return names
            try:
                parsed = _json.loads(raw_value) if isinstance(raw_value, str) else raw_value
            except Exception:
                return names
            if not isinstance(parsed, list):
                return names
            for entry in parsed:
                if isinstance(entry, str):
                    artist_name = entry.strip()
                elif isinstance(entry, dict):
                    artist_name = str(entry.get("name") or entry.get("artist") or "").strip()
                else:
                    artist_name = ""
                if artist_name:
                    names.add(artist_name.lower())
            return names
        
        filter_collection = request.args.get("collection", "false").lower() == "true"
        filter_recommended = request.args.get("recommended", "false").lower() == "true"
        include_queue = request.args.get("include_queue", "false").lower() == "true"
        
        scraper = WikipediaReleaseScraper(db_path=DB_PATH)
        releases = scraper.get_upcoming_releases(artist_in_collection=False)

        conn_flags = get_db()
        cursor_flags = conn_flags.cursor()

        # Build artist sets from local library and similar-artist cache.
        cursor_flags.execute(
            "SELECT DISTINCT LOWER(COALESCE(NULLIF(album_artist, ''), artist)) AS artist_key "
            "FROM tracks "
            "WHERE COALESCE(NULLIF(album_artist, ''), artist) IS NOT NULL"
        )
        collection_artists = {
            _row_get(row, 'artist_key', index=0)
            for row in (cursor_flags.fetchall() or [])
            if _row_get(row, 'artist_key', index=0)
        }

        recommended_artists = set()
        try:
            cursor_flags.execute(
                "SELECT similar_artists_lastfm, similar_artists_listenbrainz "
                "FROM artists "
                "WHERE similar_artists_lastfm IS NOT NULL OR similar_artists_listenbrainz IS NOT NULL"
            )
            for row in (cursor_flags.fetchall() or []):
                similar_lastfm = _row_get(row, 'similar_artists_lastfm', index=0)
                similar_listenbrainz = _row_get(row, 'similar_artists_listenbrainz', index=1)
                recommended_artists.update(_extract_similar_names(similar_lastfm))
                recommended_artists.update(_extract_similar_names(similar_listenbrainz))
        except Exception as similar_err:
            logging.warning(f"Could not load recommended-artist set for upcoming releases: {similar_err}")

        conn_flags.close()

        for release in releases:
            artist_key = (release.get("artist_name") or "").strip().lower()
            in_collection = artist_key in collection_artists
            in_recommended = artist_key in recommended_artists

            # Keep DB-sourced value if already true, but refresh from live sets.
            release["artist_in_collection"] = bool(release.get("artist_in_collection") or in_collection)
            release["artist_in_recommended"] = bool(in_recommended)

        if filter_collection:
            releases = [r for r in releases if r.get("artist_in_collection")]
        if filter_recommended:
            releases = [r for r in releases if r.get("artist_in_recommended")]

        if include_queue:
            # Optional queue annotation for views that render download-state badges.
            try:
                conn = get_db()
                cursor = conn.cursor()
                cursor.execute(
                    "SELECT LOWER(COALESCE(album_artist, artist)) AS artist_key, LOWER(album) AS album_key "
                    "FROM download_queue "
                    "WHERE import_type = 'album' "
                    "  AND status NOT IN ('completed', 'failed', 'cancelled') "
                    "  AND album IS NOT NULL"
                )
                queue_albums = set()
                for row in (cursor.fetchall() or []):
                    artist_val = _row_get(row, 'artist_key', index=0)
                    album_val = _row_get(row, 'album_key', index=1)
                    if artist_val and album_val:
                        queue_albums.add((artist_val, album_val))
                conn.close()

                for release in releases:
                    artist_key = (release.get("artist_name") or "").lower()
                    album_key = (release.get("album_name") or "").lower()
                    release["in_queue"] = (artist_key, album_key) in queue_albums
            except Exception as queue_err:
                logging.warning(f"Could not check download queue for upcoming releases: {queue_err}")
        # MBID-based collection check: if a release has a matched release_group_mbid
        # and that MBID exists in the tracks table, the album is already in the collection.
        try:
            mbid_releases = [r for r in releases if r.get("release_group_mbid")]
            if mbid_releases:
                conn_mbid = get_db()
                ph = "%s"
                mbids = list({r["release_group_mbid"] for r in mbid_releases})
                placeholders = ", ".join([ph] * len(mbids))
                cursor_mbid = conn_mbid.cursor()
                cursor_mbid.execute(
                    f"SELECT DISTINCT musicbrainz_releasegroupid FROM tracks "
                    f"WHERE musicbrainz_releasegroupid IN ({placeholders})",
                    mbids,
                )
                matched_mbids = {row[0] for row in (cursor_mbid.fetchall() or [])}
                conn_mbid.close()
                for release in releases:
                    if release.get("release_group_mbid") in matched_mbids:
                        release["album_in_collection"] = True
        except Exception as mbid_err:
            logging.warning(f"Could not perform MBID-based collection check for upcoming releases: {mbid_err}")

        # Group by month for UI display
        grouped = {}
        for release in releases:
            # Handle cases where release_date might be None
            release_date = release.get('release_date') or 'Unknown'
            month = release_date[:7] if release_date and release_date != 'Unknown' else 'Unknown'
            if month not in grouped:
                grouped[month] = []
            grouped[month].append(release)
        
        return jsonify({
            "success": True,
            "total": len(releases),
            "grouped": grouped,
            "releases": releases
        })
    except Exception as e:
        logging.error(f"Error fetching upcoming releases: {str(e)}")
        return jsonify({"error": str(e)}), 500


@app.route("/api/upcoming-releases/<int:release_id>/match", methods=["POST"])
def api_match_upcoming_release(release_id):
    """Automatically match an upcoming release to a MusicBrainz release-group or store a manual override."""
    try:
        data = request.get_json(silent=True) or {}
        release_group_mbid = (data.get("release_group_mbid") or data.get("release_group_id") or "").strip()
        source = (data.get("source") or "manual_selection").strip() or "manual_selection"

        payload, status_code = _match_upcoming_release(
            release_id,
            manual_release_group_mbid=release_group_mbid or None,
            manual_source=source,
        )
        return jsonify(payload), status_code
    except Exception as e:
        logging.error(f"Error matching upcoming release {release_id}: {e}")
        return jsonify({"success": False, "error": str(e)}), 500


